-- ==== supabase/migrations/20260810120001_project_members.sql ====
-- Project membership & isolation (M3.6). Two authorization levels now exist
-- side by side: platform role (profiles.role -- admin/curator/consultant)
-- controls what someone can administer across KB Sandbox; project role
-- (project_members.role -- owner/curator/consultant/viewer) controls what
-- they can do inside one specific project. Giving someone 'consultant'
-- access to one project must never grant access to another.
create table project_members (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  role text not null check (role in ('owner', 'curator', 'consultant', 'viewer')),
  status text not null default 'active' check (status in ('active', 'inactive')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (project_id, user_id)
);

drop trigger if exists project_members_set_updated_at on project_members;
create trigger project_members_set_updated_at before update on project_members
  for each row execute function set_updated_at();

-- The project's owner_id always has a matching 'owner' membership row --
-- enforced by trigger, not by every call site remembering to insert one.
create or replace function create_owner_membership()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.owner_id is not null then
    insert into project_members (project_id, user_id, role, status)
    values (new.id, new.owner_id, 'owner', 'active')
    on conflict (project_id, user_id) do nothing;
  end if;
  return new;
end;
$$;

drop trigger if exists projects_create_owner_membership on projects;
create trigger projects_create_owner_membership
  after insert on projects
  for each row execute function create_owner_membership();

-- One-time backfill for any project created before this migration.
insert into project_members (project_id, user_id, role, status)
select id, owner_id, 'owner', 'active' from projects where owner_id is not null
on conflict (project_id, user_id) do nothing;

-- Reusable authorization helpers -----------------------------------------------
-- Every one of these has a platform-admin bypass built in ("Platform Admin ->
-- all projects"), so it never has to be repeated in a policy body. Only
-- 'active' membership rows count -- a deactivated membership grants nothing.
create or replace function is_project_member(pid uuid, uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select is_admin(uid) or exists (
    select 1 from project_members pm where pm.project_id = pid and pm.user_id = uid and pm.status = 'active'
  );
$$;

create or replace function can_manage_project(pid uuid, uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select is_admin(uid) or exists (
    select 1 from project_members pm
    where pm.project_id = pid and pm.user_id = uid and pm.status = 'active' and pm.role = 'owner'
  );
$$;

create or replace function can_curate_project(pid uuid, uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select is_admin(uid) or exists (
    select 1 from project_members pm
    where pm.project_id = pid and pm.user_id = uid and pm.status = 'active' and pm.role in ('owner', 'curator')
  );
$$;

create or replace function can_run_project_evals(pid uuid, uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select is_admin(uid) or exists (
    select 1 from project_members pm
    where pm.project_id = pid and pm.user_id = uid and pm.status = 'active' and pm.role in ('owner', 'curator', 'consultant')
  );
$$;

-- Consistency guard: an eval_datasets row that has both a project and a
-- knowledge base must not point at a KB belonging to a *different* project.
-- Enforced here, not just in the attach actions, per the explicit gap this
-- milestone was asked to close.
create or replace function validate_eval_dataset_project_kb_consistency()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  kb_project_id uuid;
begin
  if new.knowledge_base_id is not null and new.project_id is not null then
    select project_id into kb_project_id from knowledge_bases where id = new.knowledge_base_id;
    if kb_project_id is not null and kb_project_id != new.project_id then
      raise exception 'eval_datasets.knowledge_base_id (project %) does not belong to eval_datasets.project_id (%)', kb_project_id, new.project_id;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists eval_datasets_validate_project_kb_consistency on eval_datasets;
create trigger eval_datasets_validate_project_kb_consistency
  before insert or update on eval_datasets
  for each row execute function validate_eval_dataset_project_kb_consistency();

-- project_members RLS -----------------------------------------------------------
alter table project_members enable row level security;

create policy "project_members_select_member" on project_members
  for select using (is_project_member(project_id, auth.uid()));

create policy "project_members_manage_owner" on project_members
  for all using (can_manage_project(project_id, auth.uid()))
  with check (can_manage_project(project_id, auth.uid()));

-- projects RLS: replace the "every non-anonymous user sees every project"
-- policy from 20260810100003 with real membership scoping.
drop policy "projects_select_staff_or_consultant" on projects;
create policy "projects_select_members" on projects
  for select using (is_project_member(id, auth.uid()));

drop policy "projects_update_owner_or_staff" on projects;
create policy "projects_update_managers" on projects
  for update using (can_manage_project(id, auth.uid()))
  with check (can_manage_project(id, auth.uid()));

-- knowledge_bases RLS: close the actual gap -- today ANY authenticated user
-- sees every KB, including ones scoped to a project they're not a member of.
-- Global KBs (project_id is null, e.g. fhir/vbc/grants/billing) stay visible
-- to everyone, unchanged. kb_admin_manage (platform admin, full access) is
-- untouched -- this only replaces the overly-broad select policy and adds
-- manage rights for a project's own curator/owner.
drop policy "kb_select_authenticated" on knowledge_bases;
create policy "kb_select_global_or_member" on knowledge_bases
  for select using (project_id is null or is_project_member(project_id, auth.uid()));

create policy "kb_manage_project_curator" on knowledge_bases
  for all using (project_id is not null and can_curate_project(project_id, auth.uid()))
  with check (project_id is not null and can_curate_project(project_id, auth.uid()));

-- eval_datasets / eval_cases / eval_runs / eval_results ------------------------
-- The existing platform-wide curator/admin policies from Milestone 3
-- (is_curator_or_admin-based) are intentionally left untouched -- a platform
-- curator/admin can still manage any dataset, which is what keeps the
-- platform-level "AI Engineering Wiki Benchmark" (project_id is null)
-- working exactly as before. What changes is the *consultant* policies added
-- in 20260810100004: they let ANY platform consultant see/run ANY active
-- dataset regardless of project, which is precisely what "users who are not
-- members should not see the project" (this milestone's brief) asks to
-- close. Each is dropped and recreated with a project-membership condition
-- added alongside the existing status='active' + platform-role check.
--
-- SELECT policies use is_project_member (any active role, including
-- 'viewer' -- viewers are explicitly read-only, not excluded from viewing).
-- INSERT policies (running an eval) use can_run_project_evals, which
-- excludes 'viewer' -- a viewer must never be able to trigger a run.
drop policy "eval_datasets_select_active_consultant" on eval_datasets;
create policy "eval_datasets_select_active_consultant" on eval_datasets
  for select using (
    status = 'active'
    and (project_id is null or is_project_member(project_id, auth.uid()))
    and exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'consultant' and p.is_active)
  );

drop policy "eval_cases_select_active_consultant" on eval_cases;
create policy "eval_cases_select_active_consultant" on eval_cases
  for select using (
    exists (
      select 1 from eval_datasets d where d.id = eval_cases.dataset_id and d.status = 'active'
      and (d.project_id is null or is_project_member(d.project_id, auth.uid()))
    )
    and exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'consultant' and p.is_active)
  );

drop policy "eval_runs_select_active_consultant" on eval_runs;
create policy "eval_runs_select_active_consultant" on eval_runs
  for select using (
    exists (
      select 1 from eval_datasets d where d.id = eval_runs.dataset_id and d.status = 'active'
      and (d.project_id is null or is_project_member(d.project_id, auth.uid()))
    )
    and exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'consultant' and p.is_active)
  );

drop policy "eval_runs_insert_active_consultant" on eval_runs;
create policy "eval_runs_insert_active_consultant" on eval_runs
  for insert with check (
    created_by = auth.uid()
    and exists (
      select 1 from eval_datasets d where d.id = eval_runs.dataset_id and d.status = 'active'
      and (d.project_id is null or can_run_project_evals(d.project_id, auth.uid()))
    )
    and exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'consultant' and p.is_active)
  );

drop policy "eval_results_select_active_consultant" on eval_results;
create policy "eval_results_select_active_consultant" on eval_results
  for select using (
    exists (
      select 1 from eval_runs r join eval_datasets d on d.id = r.dataset_id
      where r.id = eval_results.eval_run_id and d.status = 'active'
      and (d.project_id is null or is_project_member(d.project_id, auth.uid()))
    )
    and exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'consultant' and p.is_active)
  );

drop policy "eval_results_insert_active_consultant" on eval_results;
create policy "eval_results_insert_active_consultant" on eval_results
  for insert with check (
    exists (
      select 1 from eval_runs r join eval_datasets d on d.id = r.dataset_id
      where r.id = eval_results.eval_run_id and d.status = 'active'
      and (d.project_id is null or can_run_project_evals(d.project_id, auth.uid()))
    )
    and exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'consultant' and p.is_active)
  );

-- New, additive: project curator/owner can fully manage their own project's
-- dataset/cases even when their *platform* role is merely 'consultant' --
-- e.g. the "Senior AI Consultant" project Owner in the brief's Example 1.
create policy "eval_datasets_manage_project_curator" on eval_datasets
  for all using (project_id is not null and can_curate_project(project_id, auth.uid()))
  with check (project_id is not null and can_curate_project(project_id, auth.uid()));

create policy "eval_cases_manage_project_curator" on eval_cases
  for all using (
    exists (select 1 from eval_datasets d where d.id = eval_cases.dataset_id and d.project_id is not null and can_curate_project(d.project_id, auth.uid()))
  )
  with check (
    exists (select 1 from eval_datasets d where d.id = eval_cases.dataset_id and d.project_id is not null and can_curate_project(d.project_id, auth.uid()))
  );


-- ==== supabase/migrations/20260810120002_fix_projects_select_returning.sql ====
-- Fixes a real bug hit live: createProjectAction does
-- `.insert(...).select().single()`, and Postgres re-checks a table's SELECT
-- RLS policy against INSERT ... RETURNING output. Row-level AFTER INSERT
-- triggers (here, projects_create_owner_membership, which creates the
-- owner's project_members row) fire at the end of the statement -- AFTER the
-- RETURNING row has already been checked against the SELECT policy. So
-- is_project_member(id, auth.uid()) saw no membership row yet and rejected
-- the RETURNING of the project the caller had just created themselves.
-- owner_id = auth.uid() is checked directly against the row being inserted,
-- not through project_members, so it has no such timing dependency.
drop policy "projects_select_members" on projects;
create policy "projects_select_members" on projects
  for select using (owner_id = auth.uid() or is_project_member(id, auth.uid()));


-- ==== supabase/migrations/20260810130001_public_visibility.sql ====
-- Public/anonymous visitor experience. A visitor here is simply `auth.uid()
-- is null` -- no session, no profile row, using Supabase's plain anon API
-- key. This is a different concept from profiles.role = 'anonymous' (a real
-- Supabase Auth anonymous session, wired up in an earlier migration but
-- never actually reachable from any UI) -- that machinery is left untouched
-- and dormant; nothing here creates or depends on an 'anonymous' profile.
--
-- Governing principle: publish a curated VIEW of a project, never the
-- internal project itself. Every new RLS policy below is purely additive
-- (multiple permissive policies on one table OR together in Postgres) --
-- nothing here narrows or replaces an existing policy. Column-level safety
-- (never leaking owner_id/notes/details/published_by on projects, or
-- source_chunk_ids/created_by/approved_by on wiki_versions) is NOT
-- enforced by RLS, which is row-level only -- it's enforced by the
-- dedicated narrow-select query functions in src/lib/projects/public.ts and
-- src/lib/wiki/public.ts, which must never select('*').

-- projects: publication fields --------------------------------------------------
alter table projects add column if not exists visibility text not null default 'private'
  check (visibility in ('private', 'internal', 'public'));
alter table projects add column if not exists public_slug text unique;
alter table projects add column if not exists public_profile jsonb;
alter table projects add column if not exists published_at timestamptz;
alter table projects add column if not exists published_by uuid references profiles(id) on delete set null;

-- projects_update_managers (20260810120001, can_manage_project-gated) already
-- covers UPDATEs to these new columns since they're on the same row -- no new
-- UPDATE policy needed for publish/unpublish/save-draft.
create policy "projects_select_public" on projects
  for select using (visibility = 'public' and published_at is not null);

-- wiki_articles: separate publication flag ---------------------------------------
-- Deliberately distinct from status='approved' -- approved means "trusted
-- canonical knowledge", public means "safe for anonymous disclosure". An
-- article can be approved and still never marked public.
alter table wiki_articles add column if not exists is_public boolean not null default false;

create policy "wiki_articles_select_public" on wiki_articles
  for select using (status = 'approved' and is_public = true);

-- Reusable helper so "is this article's current version safe to show
-- anonymously" has one source of truth instead of being duplicated across
-- policies that would otherwise need to re-derive it independently.
create or replace function is_public_wiki_article(article_id uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from wiki_articles a where a.id = article_id and a.status = 'approved' and a.is_public = true
  );
$$;

-- Scoped to exactly the article's CURRENT version -- never a draft, a
-- pending review revision, or an old superseded-but-once-approved version
-- (tighter than wiki_versions_select_approved_or_staff, which the original
-- Wiki RLS migration's own comment already flags as allowing any
-- historically-approved version; that policy is untouched, staff behavior
-- doesn't change).
create policy "wiki_versions_select_public" on wiki_versions
  for select using (
    id = (select current_version_id from wiki_articles where id = wiki_versions.wiki_article_id)
    and is_public_wiki_article(wiki_article_id)
  );

-- wiki_categories: category names are non-sensitive and already visible to
-- every authenticated user regardless of role -- widen the same read to
-- anon too. No behavior change for anyone already authenticated.
drop policy "wiki_categories_select_authenticated" on wiki_categories;
create policy "wiki_categories_select_public" on wiki_categories
  for select using (true);

-- Deliberately no new RLS on wiki_sources, wiki_relations, project_members,
-- eval_datasets/eval_cases/eval_runs/eval_results, ai_operation_logs,
-- documents, or document_chunks -- none of them already leak to anon (every
-- existing policy on those tables depends on auth.uid(), which is null for
-- a sessionless request), and this milestone's public pages don't need
-- direct read access to any of them: the public project page skips a Wiki
-- cross-link/Sources section, and the public eval summary is hand-authored
-- JSON on projects.public_profile, never a live query against eval_results.


-- ==== supabase/migrations/20260811100001_graph_runtime.sql ====
-- Milestone 4: Controlled Graph Runtime. First graph-based execution
-- primitive -- STATE + NODES + EDGES + CONDITIONAL TRANSITIONS +
-- TERMINATION + TRACE, extending the M3 single-pass retrieve->generate->
-- score pipeline into a bounded retry loop. The graph controls execution
-- (deterministic transitions); the LLM only controls content generation and
-- query rewriting inside nodes -- this is NOT the Agent milestone (M5): no
-- tool-calling, no arbitrary autonomy. ai_models.supports_tools stays
-- unread by this migration's runtime.
--
-- Governing layout: graphs (stable identity) -> graph_versions (immutable
-- config snapshot) -> graph_runs (one execution) -> graph_steps (one row
-- per executed node -- the actual trace). The executable graph wiring lives
-- in TypeScript (src/lib/graph/); graph_versions.definition documents what
-- ran, it is never reconstructed from jsonb at runtime.

create table graphs (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  description text,
  graph_type text not null check (graph_type in ('rag_retry')),
  status text not null default 'draft' check (status in ('draft', 'active', 'archived')),
  -- Nullable = platform-global, same convention as knowledge_bases/eval_datasets.
  project_id uuid references projects(id) on delete cascade,
  -- Set via UPDATE (by the same manage policies below) when a version is
  -- activated -- this is the single source of truth for "what's active",
  -- which is what lets graph_versions stay strictly insert-only.
  active_version_id uuid,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger graphs_set_updated_at before update on graphs
  for each row execute function set_updated_at();

create table graph_versions (
  id uuid primary key default gen_random_uuid(),
  graph_id uuid not null references graphs(id) on delete cascade,
  version_number integer not null,
  definition jsonb not null,
  instructions_version text,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  -- Set at insert time if the version is created already-active; a version
  -- later activated via graphs.active_version_id keeps this null -- it's
  -- informational, graphs.active_version_id is authoritative.
  activated_at timestamptz,
  unique (graph_id, version_number)
);

alter table graphs add constraint graphs_active_version_id_fkey
  foreign key (active_version_id) references graph_versions(id) on delete set null;

create table graph_runs (
  id uuid primary key default gen_random_uuid(),
  graph_id uuid not null references graphs(id) on delete cascade,
  graph_version_id uuid not null references graph_versions(id) on delete cascade,
  project_id uuid references projects(id) on delete cascade,
  eval_run_id uuid references eval_runs(id) on delete set null,
  eval_case_id uuid references eval_cases(id) on delete set null,
  status text not null default 'pending' check (status in ('pending', 'running', 'completed', 'failed', 'terminated')),
  initial_input jsonb not null,
  final_output jsonb,
  iteration_count integer not null default 0,
  started_at timestamptz,
  completed_at timestamptz,
  -- Reasoning-retry (insufficient answer -> diagnose -> rewrite) and
  -- infrastructure-retry (429/timeout/network) are distinct concepts -- a
  -- thrown AIProviderError terminates the run immediately via error_code/
  -- error_message and never reaches diagnose. termination_reason (below)
  -- always records why the run stopped, success or not.
  termination_reason text check (termination_reason is null or termination_reason in (
    'success', 'unscored', 'max_iterations', 'non_retryable_failure', 'provider_error', 'invalid_configuration', 'manual_termination'
  )),
  error_code text,
  error_message text,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists graph_runs_graph_id_idx on graph_runs(graph_id);
create index if not exists graph_runs_eval_run_id_idx on graph_runs(eval_run_id);
create index if not exists graph_runs_eval_case_id_idx on graph_runs(eval_case_id);

create table graph_steps (
  id uuid primary key default gen_random_uuid(),
  graph_run_id uuid not null references graph_runs(id) on delete cascade,
  sequence_number integer not null,
  node_name text not null check (node_name in ('retrieve', 'generate', 'evaluate', 'diagnose', 'rewrite_query')),
  iteration integer not null,
  input_snapshot jsonb,
  output_snapshot jsonb,
  transition_to text,
  status text not null default 'completed' check (status in ('completed', 'failed')),
  latency_ms integer,
  ai_operation_log_id uuid,
  error_code text,
  error_message text,
  started_at timestamptz not null default now(),
  completed_at timestamptz,
  unique (graph_run_id, sequence_number)
);

create index if not exists graph_steps_graph_run_id_idx on graph_steps(graph_run_id);

-- Link AI operations (embed/generate/judge/rewrite) back to the graph
-- run/step that triggered them, mirroring exactly how eval_run_id/
-- eval_case_id were added to this same table in
-- 20260809110002_eval_runs_and_results.sql.
alter table ai_operation_logs add column if not exists graph_run_id uuid references graph_runs(id) on delete set null;
alter table ai_operation_logs add column if not exists graph_step_id uuid references graph_steps(id) on delete set null;
create index if not exists ai_operation_logs_graph_run_id_idx on ai_operation_logs(graph_run_id);

alter table graph_steps add constraint graph_steps_ai_operation_log_id_fkey
  foreign key (ai_operation_log_id) references ai_operation_logs(id) on delete set null;

-- eval_results gets a nullable link to the graph run that produced it (when
-- the eval run's execution mode was 'graph', null for single-pass), plus
-- iteration_count so the run-comparison summary can show it -- the design
-- brief explicitly asks for "iterations" as one of the compared metrics
-- alongside Hit@K/Recall@K/generation/grounding/outcome/latency/tokens/cost,
-- and neither eval_results nor the existing summary had anywhere to carry
-- it.
alter table eval_results add column if not exists graph_run_id uuid references graph_runs(id) on delete set null;
alter table eval_results add column if not exists iteration_count integer;
create index if not exists eval_results_graph_run_id_idx on eval_results(graph_run_id);

-- RLS -----------------------------------------------------------------------
alter table graphs enable row level security;
alter table graph_versions enable row level security;
alter table graph_runs enable row level security;
alter table graph_steps enable row level security;

-- graphs / graph_versions: same two-tier split knowledge_bases already uses
-- for its nullable project_id (kb_select_global_or_member /
-- kb_manage_project_curator, 20260810120001_project_members.sql) -- except
-- "manage" here is owner-only for project-scoped graphs, matching the
-- design brief's explicit "Only admin/project owner ... should change
-- active configurations."
create policy "graphs_select_global_or_member" on graphs
  for select using (project_id is null or is_project_member(project_id, auth.uid()));

create policy "graphs_manage_staff" on graphs
  for all using (project_id is null and is_curator_or_admin(auth.uid()))
  with check (project_id is null and is_curator_or_admin(auth.uid()));

create policy "graphs_manage_project_owner" on graphs
  for all using (project_id is not null and can_manage_project(project_id, auth.uid()))
  with check (project_id is not null and can_manage_project(project_id, auth.uid()));

-- graph_versions: select follows the parent graph's visibility. Insert-only
-- -- deliberately NO update policy at all, same enforcement mechanism as
-- wiki_versions (the absence of an UPDATE policy is what makes a version's
-- definition immutable once created; activation is a graphs.active_version_id
-- UPDATE instead, never a graph_versions row edit).
create policy "graph_versions_select_global_or_member" on graph_versions
  for select using (
    exists (
      select 1 from graphs g where g.id = graph_versions.graph_id
      and (g.project_id is null or is_project_member(g.project_id, auth.uid()))
    )
  );

create policy "graph_versions_insert_staff" on graph_versions
  for insert with check (
    exists (select 1 from graphs g where g.id = graph_versions.graph_id and g.project_id is null and is_curator_or_admin(auth.uid()))
  );

create policy "graph_versions_insert_project_owner" on graph_versions
  for insert with check (
    exists (select 1 from graphs g where g.id = graph_versions.graph_id and g.project_id is not null and can_manage_project(g.project_id, auth.uid()))
  );

-- graph_runs / graph_steps: mirrors eval_runs' exact select/insert shape
-- (staff unscoped + consultant project-or-global-active) -- these are
-- execution-trace rows created by the same code path that's already
-- authorized to run the eval (requireRole('consultant') + eval_runs RLS),
-- so the bar here matches eval_runs_select_staff / eval_runs_insert_active_consultant
-- rather than inventing a new authorization tier.
create policy "graph_runs_select_staff" on graph_runs
  for select using (is_curator_or_admin(auth.uid()));

create policy "graph_runs_select_consultant" on graph_runs
  for select using (
    exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'consultant' and p.is_active)
    and (project_id is null or is_project_member(project_id, auth.uid()))
  );

create policy "graph_runs_insert_staff" on graph_runs
  for insert with check (is_curator_or_admin(auth.uid()));

create policy "graph_runs_insert_consultant" on graph_runs
  for insert with check (
    created_by = auth.uid()
    and exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'consultant' and p.is_active)
    and (project_id is null or can_run_project_evals(project_id, auth.uid()))
  );

create policy "graph_steps_select_staff" on graph_steps
  for select using (is_curator_or_admin(auth.uid()));

create policy "graph_steps_select_consultant" on graph_steps
  for select using (
    exists (
      select 1 from graph_runs r
      join profiles p on p.id = auth.uid() and p.role = 'consultant' and p.is_active
      where r.id = graph_steps.graph_run_id
      and (r.project_id is null or is_project_member(r.project_id, auth.uid()))
    )
  );

create policy "graph_steps_insert_staff" on graph_steps
  for insert with check (is_curator_or_admin(auth.uid()));

create policy "graph_steps_insert_consultant" on graph_steps
  for insert with check (
    exists (
      select 1 from graph_runs r
      join profiles p on p.id = auth.uid() and p.role = 'consultant' and p.is_active
      where r.id = graph_steps.graph_run_id
      and (r.project_id is null or can_run_project_evals(r.project_id, auth.uid()))
    )
  );

-- Seed: the RAG Retry graph, platform-global, active, with its v1 config
-- snapshot -- maxIterations=2 per the design brief's default, thresholds
-- deliberately modest so the graph actually exercises its retry path on the
-- first real experiment rather than accepting everything on try 1.
insert into graphs (name, slug, description, graph_type, status, project_id)
values (
  'RAG Retry',
  'rag-retry',
  'Improves grounded answer quality when the initial retrieval/generation attempt fails evaluation: retrieve -> generate -> evaluate -> (accept -> end | retry: diagnose -> rewrite_query -> retrieve), bounded by max iterations.',
  'rag_retry',
  'active',
  null
);

insert into graph_versions (graph_id, version_number, definition, activated_at)
select
  id,
  1,
  jsonb_build_object(
    'nodes', jsonb_build_array('retrieve', 'generate', 'evaluate', 'diagnose', 'rewrite_query'),
    'edges', jsonb_build_array(
      jsonb_build_object('from', 'start', 'to', 'retrieve'),
      jsonb_build_object('from', 'retrieve', 'to', 'generate'),
      jsonb_build_object('from', 'generate', 'to', 'evaluate'),
      jsonb_build_object('from', 'diagnose', 'to', 'rewrite_query'),
      jsonb_build_object('from', 'rewrite_query', 'to', 'retrieve')
    ),
    'conditionalEdges', jsonb_build_array(
      jsonb_build_object('from', 'evaluate', 'condition', 'shouldContinue', 'accept', 'end', 'retry', 'diagnose')
    ),
    'maxIterations', 2,
    'acceptanceThresholds', jsonb_build_object(
      'requiredOutcomeScore', 0.7,
      'requiredGroundingScore', 0.7,
      'requireExpectedEvidence', false
    )
  ),
  now()
from graphs where slug = 'rag-retry';

update graphs set active_version_id = (
  select id from graph_versions where graph_id = graphs.id and version_number = 1
) where slug = 'rag-retry';


-- ==== supabase/migrations/20260811100002_fix_graph_runs_update_rls.sql ====
-- Missed in 20260811100001: runCaseViaGraph's own graph_runs status
-- transitions (pending -> running -> completed/failed, plus
-- termination_reason/error_code/final_output/iteration_count) run as UPDATE
-- statements using the caller's session -- with no UPDATE policy on
-- graph_runs at all, every one of those updates was silently blocked by
-- RLS, leaving every graph run permanently stuck at status='running' even
-- though its eval_results row (success or failure) was inserted correctly.
-- Confirmed live: a full benchmark run's graph_runs all showed
-- status='running'/completed_at=null after the eval run itself completed.
-- This is the exact same bug class already hit and fixed once this session
-- for eval_runs (20260810100005_eval_runs_update_consultant.sql) -- same
-- fix shape, mirrored for graph_runs: one policy for platform staff
-- (unrestricted, matching eval_runs_update_staff), one scoped to the
-- consultant's own run (created_by = auth.uid()), matching
-- eval_runs_update_own_consultant.
create policy "graph_runs_update_staff" on graph_runs
  for update using (is_curator_or_admin(auth.uid())) with check (is_curator_or_admin(auth.uid()));

create policy "graph_runs_update_own_consultant" on graph_runs
  for update using (
    created_by = auth.uid()
    and exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'consultant' and p.is_active)
  )
  with check (
    created_by = auth.uid()
    and exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'consultant' and p.is_active)
  );


-- ==== supabase/migrations/20260811100003_agent_framework.sql ====
-- Milestone 5A (foundation slice) + 5B: Agent Templates + RAG Answer Agent.
-- Adds the semantic layer M4 deliberately left out -- an Agent is a
-- governed configuration (Purpose + Instructions + Models + Sources + Graph
-- + Guardrails + Termination + Evaluation), never merged with a graph:
-- agents -> agent_versions (immutable) reference a graph_versions row and
-- EXECUTE THROUGH the existing M4 execution spine (graph_runs/graph_steps)
-- rather than a parallel agent_runs table -- see graph_runs.agent_id/
-- agent_version_id below, added exactly how eval_run_id/eval_case_id were
-- added in 20260811100001_graph_runtime.sql.
--
-- Agents are created FROM a template (agent_templates), not hand-authored
-- independently -- this is the M5A foundation slice: just enough schema to
-- prove "create a custom Agent from an Agent Template" honestly for one
-- concrete Agent (RAG Answer), without the amendment's full repo-scope/
-- knowledge-multi-select/OpenAPI+MCP-target wizard, which has nothing to
-- attach to yet (that arrives with the first Engineering-family template in
-- a later milestone).
--
-- Revised scope per the user's M5 re-plan: M5A Agent Templates + Custom
-- Agents (this migration, foundation slice), M5B RAG Answer Agent (this
-- migration's seed, no arbitrary tools), M5C Guardrail Templates, M5D
-- External Engineering Workbench Integration. No tool-calling/authorization
-- framework in this migration -- deferred until a concrete milestone
-- actually needs to execute a tool.

-- agent_templates -----------------------------------------------------------
-- A reusable pattern -- ordinary MUTABLE table, unlike agent_versions. A
-- template has no runs of its own; it only supplies defaults at Agent
-- *creation* time. "Template changes do not silently mutate existing Agent
-- versions" is satisfied structurally by copying these defaults into an
-- agent_versions row at creation (src/lib/agent/create.ts), not by making
-- the template itself immutable -- so ordinary staff-managed UPDATE is fine
-- here, and is exercised (not just declared) by the RLS test.
create table agent_templates (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  description text,
  agent_type text not null check (agent_type in ('knowledge', 'research', 'evaluation', 'engineering', 'governance', 'learning')),
  -- A specific immutable graph_versions snapshot, not graphs.active_version_id
  -- -- a template's recommended graph never silently drifts underneath
  -- agents already created from it.
  default_graph_version_id uuid not null references graph_versions(id),
  -- Not in the amendment's literal field list, but essential: a template
  -- with nothing to prefill defeats the point of "create from template".
  default_purpose text not null,
  default_instructions text not null,
  default_source_policy jsonb not null default '{}'::jsonb,
  default_tool_policy jsonb not null default '{}'::jsonb,
  default_guardrails jsonb not null default '{}'::jsonb,
  default_termination_policy jsonb not null default '{}'::jsonb,
  -- A recommended starting model, overridable at creation time -- nullable
  -- because a future template family may not want to prescribe one.
  default_generation_provider_id uuid references ai_providers(id),
  default_generation_model_id uuid references ai_models(id),
  default_embedding_provider_id uuid references ai_providers(id),
  default_embedding_model_id uuid references ai_models(id),
  default_evaluator_provider_id uuid references ai_providers(id),
  default_evaluator_model_id uuid references ai_models(id),
  status text not null default 'active' check (status in ('active', 'archived')),
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger agent_templates_set_updated_at before update on agent_templates
  for each row execute function set_updated_at();

-- agents ----------------------------------------------------------------
create table agents (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  description text,
  -- Agent Family taxonomy -- not RAG-specific, so the architecture doesn't
  -- stay tied to one use case as later families (engineering/governance/...)
  -- get real implementations.
  agent_type text not null check (agent_type in ('knowledge', 'research', 'evaluation', 'engineering', 'governance', 'learning')),
  -- Nullable -- "do not require every agent to have a template" (amendment,
  -- explicit). Set when the Agent was created via createAgentFromTemplate.
  template_id uuid references agent_templates(id) on delete set null,
  -- Nullable = platform-global, same convention as graphs/knowledge_bases.
  project_id uuid references projects(id) on delete cascade,
  -- Set via UPDATE (by the same manage policies below) when a version is
  -- activated -- single source of truth, same mechanism as graphs.
  active_version_id uuid,
  status text not null default 'draft' check (status in ('draft', 'active', 'archived')),
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger agents_set_updated_at before update on agents
  for each row execute function set_updated_at();

-- agent_versions ----------------------------------------------------------
-- Immutable once created -- deliberately NO update policy at all below,
-- same enforcement mechanism as graph_versions/wiki_versions. A changed
-- purpose/instructions/models/policy always means a new Agent version. This
-- is where a template's defaults land, copied at creation time.
create table agent_versions (
  id uuid primary key default gen_random_uuid(),
  agent_id uuid not null references agents(id) on delete cascade,
  version_number integer not null,
  purpose text not null,
  instructions text not null,
  graph_version_id uuid not null references graph_versions(id),
  -- Real FK columns, not folded into jsonb -- matches how EvalRunConfig
  -- always keeps generation/embedding/evaluator as three parallel typed
  -- model slots rather than an opaque bag.
  generation_provider_id uuid not null references ai_providers(id),
  generation_model_id uuid not null references ai_models(id),
  embedding_provider_id uuid not null references ai_providers(id),
  embedding_model_id uuid not null references ai_models(id),
  evaluator_provider_id uuid references ai_providers(id),
  evaluator_model_id uuid references ai_models(id),
  -- { evidenceSource: 'chunks'|'wiki'|'both', topK: number, threshold?: number }
  source_policy jsonb not null default '{}'::jsonb,
  tool_policy jsonb not null default '{}'::jsonb,
  -- { noUnsupportedClaims, projectKnowledgeBoundary, maxRetries } --
  -- documents what the underlying graph's own acceptance thresholds already
  -- enforce; this migration adds no new enforcement layer on top of the M4
  -- graph's shouldContinue(). Real runtime-enforced guardrail policy is
  -- M5C's scope.
  guardrails jsonb not null default '{}'::jsonb,
  -- { maxIterations, successTerminationReasons } -- mirrors the referenced
  -- graph version's own maxIterations so a historical Agent version stays
  -- self-describing without joining graph_versions.
  termination_policy jsonb not null default '{}'::jsonb,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  -- Informational only, same convention as graph_versions.activated_at --
  -- agents.active_version_id is authoritative.
  activated_at timestamptz,
  unique (agent_id, version_number)
);

alter table agents add constraint agents_active_version_id_fkey
  foreign key (active_version_id) references agent_versions(id) on delete set null;

-- Extend graph_runs (M4's execution spine) rather than build a parallel
-- agent_runs table -- exactly mirrors how eval_run_id/eval_case_id were
-- added in 20260811100001_graph_runtime.sql.
alter table graph_runs add column if not exists agent_id uuid references agents(id) on delete set null;
alter table graph_runs add column if not exists agent_version_id uuid references agent_versions(id) on delete set null;
create index if not exists graph_runs_agent_id_idx on graph_runs(agent_id);
create index if not exists graph_runs_agent_version_id_idx on graph_runs(agent_version_id);

-- RLS -----------------------------------------------------------------------
alter table agent_templates enable row level security;
alter table agents enable row level security;
alter table agent_versions enable row level security;

-- agent_templates: platform-global registry (no project scoping -- a
-- template is a reusable pattern, not a project artifact). Any
-- authenticated, active, non-anonymous session may see what templates exist
-- (needed to choose one when creating an Agent, same bar as ai_providers/
-- ai_models); only staff manage the catalog.
create policy "agent_templates_select_staff_or_consultant" on agent_templates
  for select using (
    exists (select 1 from profiles p where p.id = auth.uid() and p.role != 'anonymous' and p.is_active)
  );

create policy "agent_templates_manage_staff" on agent_templates
  for all using (is_curator_or_admin(auth.uid()))
  with check (is_curator_or_admin(auth.uid()));

-- agents / agent_versions: identical two-tier shape to graphs/graph_versions
-- (20260811100001) -- manage is OWNER-gated (can_manage_project), not
-- curator-gated, for project-scoped Agents.
create policy "agents_select_global_or_member" on agents
  for select using (project_id is null or is_project_member(project_id, auth.uid()));

create policy "agents_manage_staff" on agents
  for all using (project_id is null and is_curator_or_admin(auth.uid()))
  with check (project_id is null and is_curator_or_admin(auth.uid()));

create policy "agents_manage_project_owner" on agents
  for all using (project_id is not null and can_manage_project(project_id, auth.uid()))
  with check (project_id is not null and can_manage_project(project_id, auth.uid()));

create policy "agent_versions_select_global_or_member" on agent_versions
  for select using (
    exists (
      select 1 from agents a where a.id = agent_versions.agent_id
      and (a.project_id is null or is_project_member(a.project_id, auth.uid()))
    )
  );

create policy "agent_versions_insert_staff" on agent_versions
  for insert with check (
    exists (select 1 from agents a where a.id = agent_versions.agent_id and a.project_id is null and is_curator_or_admin(auth.uid()))
  );

create policy "agent_versions_insert_project_owner" on agent_versions
  for insert with check (
    exists (select 1 from agents a where a.id = agent_versions.agent_id and a.project_id is not null and can_manage_project(a.project_id, auth.uid()))
  );
-- Deliberately NO update policy on agent_versions -- immutability, same
-- mechanism as graph_versions/wiki_versions.

-- Seed: "RAG Answer" template ------------------------------------------------
insert into agent_templates (
  name, slug, description, agent_type, default_graph_version_id,
  default_purpose, default_instructions,
  default_source_policy, default_guardrails, default_termination_policy,
  default_generation_provider_id, default_generation_model_id,
  default_embedding_provider_id, default_embedding_model_id,
  default_evaluator_provider_id, default_evaluator_model_id
)
select
  'RAG Answer',
  'rag-answer',
  'Grounded question-answering over permitted KB Sandbox knowledge, maximizing traceability. Wraps the RAG Retry graph; no arbitrary tools.',
  'knowledge',
  gv.id,
  'Answer questions using permitted KB Sandbox knowledge while maximizing grounding and traceability.',
  'Answer the user''s question using only the retrieved evidence. Cite which evidence supports each claim. If the evidence does not support an answer, say so explicitly rather than guessing. Never claim knowledge outside approved project or global sources.',
  jsonb_build_object('evidenceSource', 'both', 'topK', 5),
  jsonb_build_object('noUnsupportedClaims', true, 'projectKnowledgeBoundary', true, 'maxRetries', 2),
  jsonb_build_object('maxIterations', 2, 'successTerminationReasons', jsonb_build_array('success', 'unscored')),
  gen_provider.id, gen_model.id,
  embed_provider.id, embed_model.id,
  eval_provider.id, eval_model.id
from graphs g
join graph_versions gv on gv.graph_id = g.id and gv.id = g.active_version_id
join ai_providers gen_provider on gen_provider.name = 'groq'
join ai_models gen_model on gen_model.provider_id = gen_provider.id and gen_model.model_id = 'openai/gpt-oss-20b'
join ai_providers embed_provider on embed_provider.name = 'gemini'
join ai_models embed_model on embed_model.provider_id = embed_provider.id and embed_model.model_id = 'gemini-embedding-001'
join ai_providers eval_provider on eval_provider.name = 'groq'
join ai_models eval_model on eval_model.provider_id = eval_provider.id and eval_model.model_id = 'openai/gpt-oss-20b'
where g.slug = 'rag-retry';

-- Seed: RAG Answer Agent, created FROM the template above -------------------
-- Wraps the existing RAG Retry graph as-is (no new graph_type, no new
-- nodes). Not hand-authored independently -- template_id is set, and the v1
-- agent_versions row below copies the template's defaults verbatim, exactly
-- what src/lib/agent/create.ts's createAgentFromTemplate does at runtime
-- for any future Agent created through the /agents/new UI.
insert into agents (name, slug, description, agent_type, template_id, project_id, status)
select
  'RAG Answer Agent',
  'rag-answer-agent',
  'Answers questions using permitted KB Sandbox knowledge while maximizing grounding and traceability. The first working formal Agent: a named, versioned wrapper around the RAG Retry graph, created from the RAG Answer template, no arbitrary tools.',
  'knowledge',
  t.id,
  null,
  'active'
from agent_templates t where t.slug = 'rag-answer';

insert into agent_versions (
  agent_id, version_number, purpose, instructions, graph_version_id,
  generation_provider_id, generation_model_id,
  embedding_provider_id, embedding_model_id,
  evaluator_provider_id, evaluator_model_id,
  source_policy, guardrails, termination_policy, metadata,
  activated_at
)
select
  a.id,
  1,
  t.default_purpose,
  t.default_instructions,
  t.default_graph_version_id,
  t.default_generation_provider_id, t.default_generation_model_id,
  t.default_embedding_provider_id, t.default_embedding_model_id,
  t.default_evaluator_provider_id, t.default_evaluator_model_id,
  t.default_source_policy, t.default_guardrails, t.default_termination_policy,
  jsonb_build_object('family', 'knowledge', 'createdFromTemplate', t.slug),
  now()
from agents a
join agent_templates t on t.id = a.template_id
where a.slug = 'rag-answer-agent';

update agents set active_version_id = (
  select id from agent_versions where agent_id = agents.id and version_number = 1
) where slug = 'rag-answer-agent';


-- ==== supabase/migrations/20260811100004_project_workstreams.sql ====
-- M5D (simplified): Project Workstreams & External Artifacts. KB Sandbox
-- does not execute engineering work itself -- a consultant clones a
-- standalone repo template (openapi-modernizer/mcp-modernizer, entirely
-- outside this codebase) and drives it with Claude Code against the target
-- legacy repository. A Workstream is the scope document that tells the
-- consultant what to do (repository scope, goal, a named guardrail, a
-- deliverables checklist); a workstream_artifacts row is the evidence the
-- consultant attaches when they're done (a capability inventory, a spec
-- excerpt, findings, a link to the actual PR/repo). No execution, no
-- automated scoring in this pass -- "automate the workflow after you
-- understand the workflow."
--
-- This is project-scoped, not an Agent -- unrelated to the agents/
-- agent_versions tables from 20260811100003_agent_framework.sql.

-- project_workstreams -------------------------------------------------------
-- Ordinary mutable table -- a workstream is a living scope document someone
-- edits as understanding evolves, not something executed against, so no
-- immutable-versioning is warranted (unlike graph_versions/agent_versions).
create table project_workstreams (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  name text not null,
  slug text not null,
  status text not null default 'draft' check (status in ('draft', 'active', 'completed', 'archived')),
  -- Glob patterns, e.g. 'src/onboarding/**' -- documentation for the
  -- consultant's external tooling, not enforced/read by KB Sandbox itself.
  repository_scope text[] not null default '{}',
  goal text,
  -- Free-text reference (e.g. "Safe Modernization") until M5C's
  -- guardrail_templates exists -- upgrade to a real FK then.
  guardrail text,
  -- [{label: string, completed: boolean}]
  deliverables jsonb not null default '[]',
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (project_id, slug)
);

create trigger project_workstreams_set_updated_at before update on project_workstreams
  for each row execute function set_updated_at();

-- workstream_artifacts --------------------------------------------------------
-- The evidence trail. Insert-only -- no update/delete policy below, same
-- immutability reasoning as wiki_sources: you don't edit history, you
-- attach a new finding if something changes. No file upload in this pass --
-- deliberately simpler than the Milestone 1 document pipeline: the real
-- generated artifacts (OpenAPI YAML, MCP server code) live in the
-- consultant's external repo/PR; KB Sandbox holds a link plus a text
-- summary, not the files themselves.
create table workstream_artifacts (
  id uuid primary key default gen_random_uuid(),
  workstream_id uuid not null references project_workstreams(id) on delete cascade,
  artifact_type text not null check (artifact_type in ('capability_inventory', 'openapi_spec', 'mcp_server', 'test_results', 'findings', 'other')),
  title text not null,
  -- "record external tool used", e.g. "Claude Code".
  external_tool text,
  -- Inline text/markdown -- a findings writeup, a small spec excerpt.
  content text,
  -- Link to the actual PR/branch/repo where generated files live.
  external_url text,
  notes text,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),

  constraint workstream_artifacts_evidence_required check (content is not null or external_url is not null)
);

create index if not exists workstream_artifacts_workstream_id_idx on workstream_artifacts(workstream_id);

-- RLS -----------------------------------------------------------------------
alter table project_workstreams enable row level security;
alter table workstream_artifacts enable row level security;

create policy "project_workstreams_select_member" on project_workstreams
  for select using (is_project_member(project_id, auth.uid()));

-- Owner+curator define/edit scope and mark deliverables complete -- matches
-- the eval_datasets_manage_project_curator precedent exactly (can_curate_project,
-- not can_manage_project -- a project curator, not just its owner, can run
-- this).
create policy "project_workstreams_manage_curator" on project_workstreams
  for all using (can_curate_project(project_id, auth.uid()))
  with check (can_curate_project(project_id, auth.uid()));

create policy "workstream_artifacts_select_member" on workstream_artifacts
  for select using (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_artifacts.workstream_id and is_project_member(w.project_id, auth.uid())
    )
  );

-- Broader than curator -- the consultant who did the external work is who
-- attaches the evidence, matching how graph_runs_insert_consultant/
-- eval_runs_insert_active_consultant are scoped (can_run_project_evals:
-- owner/curator/consultant, excludes viewer).
create policy "workstream_artifacts_insert_consultant" on workstream_artifacts
  for insert with check (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_artifacts.workstream_id and can_run_project_evals(w.project_id, auth.uid())
    )
  );


-- ==== supabase/migrations/20260812100001_public_wiki_kb_scoping_fix.sql ====
-- Public AI Engineering Wiki design note (see docs/CURRENT-ARCHITECTURE.md's
-- Public Wiki section): the original public-visibility migration
-- (20260810130001) never checked whether an article's knowledge_base_id
-- belongs to a project-scoped KB before allowing it to be marked public.
-- The design brief is explicit that public eligibility requires "article
-- belongs to platform/global knowledge" as its own condition -- approval +
-- is_public alone isn't enough if the article happens to sit on a
-- project/client-scoped knowledge base. No article is project-scoped today
-- (verified live), but the rule wasn't enforced, so this closes the gap
-- before it can ever matter rather than after.
--
-- wiki_articles_select_public previously duplicated its own inline
-- 'status=approved and is_public=true' condition instead of calling
-- is_public_wiki_article() -- rewritten here to call the helper instead, so
-- there's exactly one source of truth for "is this article safe to show
-- anonymously" (wiki_versions_select_public already depended on the helper
-- and picks up this fix automatically, no change needed there).
create or replace function is_public_wiki_article(article_id uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from wiki_articles a
    where a.id = article_id
    and a.status = 'approved'
    and a.is_public = true
    and (
      a.knowledge_base_id is null
      or exists (select 1 from knowledge_bases kb where kb.id = a.knowledge_base_id and kb.project_id is null)
    )
  );
$$;

drop policy "wiki_articles_select_public" on wiki_articles;
create policy "wiki_articles_select_public" on wiki_articles
  for select using (is_public_wiki_article(id));


-- ==== supabase/migrations/20260814100001_branding_storage.sql ====
-- Public storage bucket for admin-managed branding assets (logo, PWA
-- icons). Unlike the `documents` bucket, this is deliberately public --
-- the browser tab favicon, PWA manifest icons, and the site header all
-- need to fetch these with no auth. Writes stay admin-only; reads are
-- open to anyone via the bucket's own public URL regardless of these
-- policies, but the policies still govern API-level access (list/upload
-- via the Supabase client, as opposed to a bare public URL fetch).
insert into storage.buckets (id, name, public)
values ('branding', 'branding', true)
on conflict (id) do update set public = true;

create policy "branding_bucket_admin_insert" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'branding'
    and exists (
      select 1 from profiles
      where id = auth.uid() and role = 'admin' and is_active = true
    )
  );

create policy "branding_bucket_admin_update" on storage.objects
  for update to authenticated
  using (
    bucket_id = 'branding'
    and exists (
      select 1 from profiles
      where id = auth.uid() and role = 'admin' and is_active = true
    )
  );

create policy "branding_bucket_admin_delete" on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'branding'
    and exists (
      select 1 from profiles
      where id = auth.uid() and role = 'admin' and is_active = true
    )
  );

create policy "branding_bucket_public_select" on storage.objects
  for select using (bucket_id = 'branding');


-- ==== supabase/migrations/20260814100002_settings_public_branding_read.sql ====
-- settings has RLS restricting SELECT to curator/admin only
-- (settings_select_staff, 20260808190010_rls_policies.sql) -- appropriate
-- for its original purpose (internal runtime toggles like ai_provider), but
-- the new 'branding' key needs to be readable by anonymous visitors too
-- (the public site's header/favicon/manifest all read it). Multiple SELECT
-- policies on the same table are OR'd together, so this adds narrow public
-- read access to exactly that one key without loosening anything else in
-- the table.
create policy "settings_select_public_branding" on settings
  for select using (key = 'branding');


-- ==== supabase/migrations/20260814110001_trending_knowledge.sql ====
-- M5E Part A -- Trending Knowledge. Provisional external material a user
-- believes is worth examining -- deliberately NOT another Wiki category
-- ("what are we watching?" vs Wiki's "what do we currently know?"). A
-- Trending item never becomes canonical knowledge on its own; it can only
-- become one by going through the *existing* Wiki draft/review/approval
-- lifecycle via promoteTrendingToWikiAction, same as every other Wiki edit.

create table trending_items (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  source_url text not null,
  source_name text,
  -- "Why does this matter?" -- required at submission, not optional AI analysis.
  description text not null,
  tags text[] not null default '{}',
  submitted_by uuid references profiles(id) on delete set null,
  -- Nullable: platform-visibility items aren't scoped to any project.
  project_id uuid references projects(id) on delete cascade,
  visibility text not null default 'platform' check (visibility in ('platform', 'project')),
  -- Deliberately not the Wiki's draft/review/approved lifecycle -- Trending
  -- is intentionally a different kind of thing (see module comment above).
  status text not null default 'active' check (status in ('active', 'under_review', 'promoted', 'archived')),
  -- Separate axis from status, same "canonical != public" split as
  -- wiki_articles.is_public (20260810130001_public_visibility.sql) --
  -- unused until a public /trending page exists, costs nothing to have now.
  is_public boolean not null default false,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger trending_items_set_updated_at before update on trending_items
  for each row execute function set_updated_at();

create index trending_items_status_idx on trending_items(status);
create index trending_items_project_id_idx on trending_items(project_id);

-- Flat comments -- no threading, no reactions. A discussion exists to
-- evaluate the significance of the source, not to be a chat feature.
create table trending_comments (
  id uuid primary key default gen_random_uuid(),
  trending_item_id uuid not null references trending_items(id) on delete cascade,
  author_id uuid references profiles(id) on delete set null,
  body text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz
);

create index trending_comments_trending_item_id_idx on trending_comments(trending_item_id);

-- "This external development may be relevant to this existing knowledge" --
-- explicitly NOT an endorsement. A relationship table rather than an array
-- column so it carries its own audit trail (linked_by/created_at) and can
-- be queried from either direction.
create table trending_wiki_links (
  id uuid primary key default gen_random_uuid(),
  trending_item_id uuid not null references trending_items(id) on delete cascade,
  wiki_article_id uuid not null references wiki_articles(id) on delete cascade,
  linked_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (trending_item_id, wiki_article_id)
);

create index trending_wiki_links_wiki_article_id_idx on trending_wiki_links(wiki_article_id);

-- Provenance: which Trending item (if any) a Wiki version was promoted
-- from. wiki_sources' 'external' source type has no URL column to hold
-- this structurally, so a direct nullable FK is cleaner and queryable.
alter table wiki_versions add column if not exists promoted_from_trending_item_id uuid references trending_items(id) on delete set null;

-- RLS -------------------------------------------------------------------
alter table trending_items enable row level security;
alter table trending_comments enable row level security;
alter table trending_wiki_links enable row level security;

create policy "trending_items_select_visible" on trending_items
  for select using (
    visibility = 'platform'
    or (visibility = 'project' and is_project_member(project_id, auth.uid()))
    or is_public
  );

create policy "trending_items_insert_authenticated" on trending_items
  for insert to authenticated
  with check (
    submitted_by = auth.uid()
    and (project_id is null or is_project_member(project_id, auth.uid()))
  );

-- Status/is_public changes (review, archive, promote, publish) are a
-- curator/admin action, matching the doc's "Curator: review Trending;
-- archive; initiate Wiki promotion" and "public Trending publication can
-- remain Curator/Admin-controlled" (§17-18).
create policy "trending_items_manage_curator" on trending_items
  for update
  using (
    case when project_id is not null then can_curate_project(project_id, auth.uid())
    else is_curator_or_admin(auth.uid()) end
  )
  with check (
    case when project_id is not null then can_curate_project(project_id, auth.uid())
    else is_curator_or_admin(auth.uid()) end
  );

create policy "trending_comments_select_visible" on trending_comments
  for select using (
    exists (
      select 1 from trending_items t
      where t.id = trending_comments.trending_item_id
      and (t.visibility = 'platform' or (t.visibility = 'project' and is_project_member(t.project_id, auth.uid())) or t.is_public)
    )
  );

create policy "trending_comments_insert_authenticated" on trending_comments
  for insert to authenticated
  with check (
    author_id = auth.uid()
    and exists (
      select 1 from trending_items t
      where t.id = trending_comments.trending_item_id
      and (t.visibility = 'platform' or (t.visibility = 'project' and is_project_member(t.project_id, auth.uid())))
    )
  );

create policy "trending_wiki_links_select_visible" on trending_wiki_links
  for select using (
    exists (
      select 1 from trending_items t
      where t.id = trending_wiki_links.trending_item_id
      and (t.visibility = 'platform' or (t.visibility = 'project' and is_project_member(t.project_id, auth.uid())) or t.is_public)
    )
  );

-- Any consultant+ who can see the item can link a Wiki article to it
-- (doc §17: Consultant capability, not curator-only).
create policy "trending_wiki_links_insert_authenticated" on trending_wiki_links
  for insert to authenticated
  with check (
    linked_by = auth.uid()
    and exists (
      select 1 from trending_items t
      where t.id = trending_wiki_links.trending_item_id
      and (t.visibility = 'platform' or (t.visibility = 'project' and is_project_member(t.project_id, auth.uid())))
    )
  );

create policy "trending_wiki_links_delete_own_or_curator" on trending_wiki_links
  for delete using (
    linked_by = auth.uid()
    or exists (
      select 1 from trending_items t
      where t.id = trending_wiki_links.trending_item_id
      and (case when t.project_id is not null then can_curate_project(t.project_id, auth.uid()) else is_curator_or_admin(auth.uid()) end)
    )
  );


-- ==== supabase/migrations/20260814120001_project_notes.sql ====
-- M5E Part B -- Project Notes. Lightweight, resolvable notes between project
-- participants, optionally attached to a real Workbench object (an eval run,
-- a document, a workstream artifact, etc). Explicitly NOT a general inbox or
-- direct-message feature -- see docs/m5E.md sections 13-15, 22.

create table project_notes (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  author_id uuid references profiles(id) on delete set null,
  -- Who a note is addressed to. 'project_team' means every member; 'curator'
  -- and 'admin' mean any curator/admin on staff, not a specific person.
  recipient_type text not null check (recipient_type in ('user', 'project_team', 'curator', 'admin')),
  recipient_user_id uuid references profiles(id) on delete set null,
  subject text not null,
  body text not null,
  -- Polymorphic reference to the Workbench object a note is about (an eval
  -- run, a document, a workstream artifact, ...). No FK constraint -- can't
  -- FK against a union of tables; integrity is application-level, resolved
  -- per-type at read time, degrading to a plain label if unresolvable.
  context_type text,
  context_id uuid,
  status text not null default 'open' check (status in ('open', 'resolved')),
  created_at timestamptz not null default now(),
  resolved_at timestamptz,
  resolved_by uuid references profiles(id) on delete set null
);

create index project_notes_project_id_idx on project_notes(project_id);
create index project_notes_status_idx on project_notes(status);

-- Flat replies -- same "no threading" shape as trending_comments.
create table project_note_replies (
  id uuid primary key default gen_random_uuid(),
  note_id uuid not null references project_notes(id) on delete cascade,
  author_id uuid references profiles(id) on delete set null,
  body text not null,
  created_at timestamptz not null default now()
);

create index project_note_replies_note_id_idx on project_note_replies(note_id);

-- One reusable helper encapsulating who can see a note, instead of
-- duplicating the OR-chain across project_notes and project_note_replies
-- policies -- matches the is_project_member/can_curate_project convention.
create or replace function can_view_project_note(nid uuid, uid uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from project_notes n
    where n.id = nid
    and is_project_member(n.project_id, uid)
    and (
      n.recipient_type = 'project_team'
      or n.author_id = uid
      or (n.recipient_type = 'user' and n.recipient_user_id = uid)
      or (n.recipient_type = 'curator' and can_curate_project(n.project_id, uid))
      or (n.recipient_type = 'admin' and is_admin(uid))
      or can_curate_project(n.project_id, uid) -- curator/owner oversight, regardless of recipient_type
    )
  );
$$;

-- RLS -------------------------------------------------------------------
alter table project_notes enable row level security;
alter table project_note_replies enable row level security;

create policy "project_notes_select_visible" on project_notes
  for select using (can_view_project_note(id, auth.uid()));

-- Direct, subquery-free companion to the policy above -- required because
-- can_view_project_note re-queries project_notes internally, and that
-- subquery's snapshot does not see the row an INSERT ... RETURNING (i.e.
-- .insert().select()) is still in the middle of creating, so createProjectNoteAction's
-- own return value would otherwise fail RLS for the row it just inserted.
create policy "project_notes_select_own" on project_notes
  for select using (author_id = auth.uid());

create policy "project_notes_insert_member" on project_notes
  for insert to authenticated
  with check (
    author_id = auth.uid()
    and is_project_member(project_id, auth.uid())
    and (recipient_type != 'user' or is_project_member(project_id, recipient_user_id))
  );

-- Resolving is the only mutation -- author, the addressed recipient, a
-- curator, or an admin (doc section 14, literally: "who can resolve").
create policy "project_notes_resolve" on project_notes
  for update
  using (
    author_id = auth.uid()
    or (recipient_type = 'user' and recipient_user_id = auth.uid())
    or (recipient_type = 'curator' and can_curate_project(project_id, auth.uid()))
    or (recipient_type = 'admin' and is_admin(auth.uid()))
    or can_curate_project(project_id, auth.uid())
  )
  with check (
    author_id = auth.uid()
    or (recipient_type = 'user' and recipient_user_id = auth.uid())
    or (recipient_type = 'curator' and can_curate_project(project_id, auth.uid()))
    or (recipient_type = 'admin' and is_admin(auth.uid()))
    or can_curate_project(project_id, auth.uid())
  );

create policy "project_note_replies_select_visible" on project_note_replies
  for select using (can_view_project_note(note_id, auth.uid()));

create policy "project_note_replies_insert_member" on project_note_replies
  for insert to authenticated
  with check (author_id = auth.uid() and can_view_project_note(note_id, auth.uid()));


-- ==== supabase/migrations/20260814130001_workstream_artifact_types.sql ====
-- Adds endpoint_inventory and evidence_map as first-class
-- workstream_artifacts types -- previously these would have been squeezed
-- into 'other'. Purely additive: no existing value is renamed or removed,
-- so every historical row (and every other existing type) stays valid.
-- Constraint name relies on Postgres's default naming for an unnamed inline
-- check ("<table>_<column>_check"), same convention already relied on in
-- 20260810100001_role_consultant_anonymous.sql (profiles_role_check).
alter table workstream_artifacts drop constraint workstream_artifacts_artifact_type_check;
alter table workstream_artifacts add constraint workstream_artifacts_artifact_type_check
  check (artifact_type in (
    'capability_inventory', 'endpoint_inventory', 'openapi_spec', 'mcp_server',
    'evidence_map', 'test_results', 'findings', 'other'
  ));


-- ==== supabase/migrations/20260815120001_workstream_summary.sql ====
-- Adds a curator-editable outcome summary to project_workstreams, distinct
-- from `goal` (what we set out to do). Populated once artifacts/evidence
-- exist, shown at the top of the workstream page. Reuses the existing
-- project_workstreams_manage_curator policy (for all) -- no new RLS needed.
alter table project_workstreams add column if not exists summary text;


-- ==== supabase/migrations/20260816090001_project_goal.sql ====
-- A project-level goal, shared by every workstream in that project (the
-- method/approach doesn't change per workstream -- only which external tool
-- executes it does). Workstreams now link back here instead of repeating
-- the same text. No RLS change: projects_update_managers (can_manage_project)
-- already covers this column, same as `notes`.
alter table projects add column if not exists goal text;


-- ==== supabase/migrations/20260816110001_system_assessments.sql ====
-- Workstream System Understanding Assessment. A reusable capability, not
-- specific to OpenAPI/CareCall: a curator-authored, versioned set of
-- standardized questions that every "participant" (an external AI tool/
-- method, or eventually a human) answers after independently examining a
-- system -- testing whether they actually understood it, not just whether
-- they produced plausible-looking artifacts. Deliberately separate from
-- workstream_artifacts (the engineering outputs) and from any future human
-- benchmark/scoring (see design note -- ground truth stays out of the
-- participant-facing assessment).
--
-- Scope for this pass: definition + versioned questions/instructions +
-- manual response entry + question-by-question viewing. No native LLM
-- execution, no automated grading -- see docs/ design note.
--
-- project_id is denormalized onto every table (rather than the one-hop
-- join pattern workstream_artifacts uses) specifically to keep RLS shallow
-- across this 4-table chain (assessment -> version -> question/response ->
-- answer) instead of stacking 3-4 levels of EXISTS.

create table system_assessments (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  -- Soft/optional link to the workstream this assessment originated under.
  -- Not used for access control -- an assessment is a project-wide,
  -- cross-workstream comparison surface (Claude Code and ChatGPT/Codex are
  -- separate *workstreams* in this app's model, but the same assessment).
  workstream_id uuid references project_workstreams(id) on delete set null,
  name text not null,
  description text,
  -- FK added below, after system_assessment_versions exists -- same
  -- circular-reference pattern as wiki_articles.current_version_id /
  -- wiki_versions (20260808220003_wiki_versions.sql).
  current_version_id uuid,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger system_assessments_set_updated_at before update on system_assessments
  for each row execute function set_updated_at();

create index system_assessments_project_id_idx on system_assessments(project_id);

-- Two independently versioned things live here, per the design note:
-- (A) the question set, and (B) the instructions given to a participant on
-- how to answer. Both travel together as one version so a response can
-- always be traced to exactly what was asked and how.
create table system_assessment_versions (
  id uuid primary key default gen_random_uuid(),
  assessment_id uuid not null references system_assessments(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  version_number integer not null,
  instructions text not null,
  status text not null default 'draft' check (status in ('draft', 'active', 'retired')),
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),

  unique (assessment_id, version_number)
);

create index system_assessment_versions_assessment_id_idx on system_assessment_versions(assessment_id);

alter table system_assessments
  add constraint system_assessments_current_version_fk
  foreign key (current_version_id) references system_assessment_versions(id) on delete set null;

create table system_assessment_questions (
  id uuid primary key default gen_random_uuid(),
  assessment_version_id uuid not null references system_assessment_versions(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  sequence integer not null,
  title text not null,
  question text not null,
  category text,
  guidance text,

  unique (assessment_version_id, sequence)
);

create index system_assessment_questions_version_id_idx on system_assessment_questions(assessment_version_id);

-- One response per (assessment version, participant) -- "participant" is
-- descriptive metadata, not a workstream FK: a response like "Claude Code"
-- happens to correspond to a workstream of the same name in this project
-- today, but the assessment/response model doesn't assume that link always
-- holds (a future human-benchmark or a tool with no matching workstream
-- should be representable the same way).
create table assessment_responses (
  id uuid primary key default gen_random_uuid(),
  assessment_version_id uuid not null references system_assessment_versions(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  participant_label text not null,
  external_tool text,
  model text,
  repository_ref text,
  status text not null default 'in_progress' check (status in ('in_progress', 'completed')),
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  unique (assessment_version_id, participant_label)
);

create trigger assessment_responses_set_updated_at before update on assessment_responses
  for each row execute function set_updated_at();

create index assessment_responses_version_id_idx on assessment_responses(assessment_version_id);

-- One row per question per response -- deliberately not one giant Markdown
-- blob, so individual questions stay independently reviewable/scoreable
-- later (see design note section 9). Evidence stays inline free text in
-- this pass rather than a normalized evidence table.
create table assessment_answers (
  id uuid primary key default gen_random_uuid(),
  response_id uuid not null references assessment_responses(id) on delete cascade,
  question_id uuid not null references system_assessment_questions(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  answer text not null,
  classification text check (classification in ('CONFIRMED', 'INFERRED', 'UNKNOWN')),
  evidence text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  unique (response_id, question_id)
);

create trigger assessment_answers_set_updated_at before update on assessment_answers
  for each row execute function set_updated_at();

create index assessment_answers_response_id_idx on assessment_answers(response_id);

-- RLS -------------------------------------------------------------------
-- No parallel permission system -- every policy reuses is_project_member /
-- can_curate_project exactly as project_workstreams/workstream_artifacts
-- do. "Immutable once active" (design note section 5) is enforced in the
-- action layer (checking version.status = 'draft' before allowing an edit),
-- not by RLS -- same app-layer-invariant convention as this codebase's
-- other insert-only/immutable tables, since the real rule ("no edits once
-- responses exist") doesn't map cleanly onto a column-level RLS check.
alter table system_assessments enable row level security;
alter table system_assessment_versions enable row level security;
alter table system_assessment_questions enable row level security;
alter table assessment_responses enable row level security;
alter table assessment_answers enable row level security;

create policy "system_assessments_select_member" on system_assessments
  for select using (is_project_member(project_id, auth.uid()));

create policy "system_assessments_manage_curator" on system_assessments
  for all
  using (can_curate_project(project_id, auth.uid()))
  with check (can_curate_project(project_id, auth.uid()));

create policy "system_assessment_versions_select_member" on system_assessment_versions
  for select using (is_project_member(project_id, auth.uid()));

create policy "system_assessment_versions_manage_curator" on system_assessment_versions
  for all
  using (can_curate_project(project_id, auth.uid()))
  with check (can_curate_project(project_id, auth.uid()));

create policy "system_assessment_questions_select_member" on system_assessment_questions
  for select using (is_project_member(project_id, auth.uid()));

create policy "system_assessment_questions_manage_curator" on system_assessment_questions
  for all
  using (can_curate_project(project_id, auth.uid()))
  with check (can_curate_project(project_id, auth.uid()));

-- Any project member can see every participant's responses -- the entire
-- point is comparing methods side by side (design note section 11-12), not
-- hiding answers from one another the way, say, a blind eval would.
create policy "assessment_responses_select_member" on assessment_responses
  for select using (is_project_member(project_id, auth.uid()));

-- can_run_project_evals (owner/curator/consultant, excludes viewer) is the
-- closest existing helper to "Consultant / Project Member with appropriate
-- edit rights" from the design note's permission table -- a viewer must
-- not be able to submit a response, same reasoning as it excluding viewer
-- from triggering eval runs.
create policy "assessment_responses_insert_member" on assessment_responses
  for insert to authenticated
  with check (can_run_project_evals(project_id, auth.uid()) and created_by = auth.uid());

-- The response's own author can keep editing it (design note: "edit
-- responses until submitted" -- the in_progress/completed cutoff is
-- app-layer, same reasoning as version immutability above), or a curator
-- can fix/annotate any response.
create policy "assessment_responses_update_owner_or_curator" on assessment_responses
  for update
  using (created_by = auth.uid() or can_curate_project(project_id, auth.uid()))
  with check (created_by = auth.uid() or can_curate_project(project_id, auth.uid()));

create policy "assessment_answers_select_member" on assessment_answers
  for select using (is_project_member(project_id, auth.uid()));

create policy "assessment_answers_insert_response_owner" on assessment_answers
  for insert to authenticated
  with check (
    is_project_member(project_id, auth.uid())
    and exists (select 1 from assessment_responses r where r.id = response_id and r.created_by = auth.uid())
  );

create policy "assessment_answers_update_owner_or_curator" on assessment_answers
  for update
  using (
    can_curate_project(project_id, auth.uid())
    or exists (select 1 from assessment_responses r where r.id = response_id and r.created_by = auth.uid())
  )
  with check (
    can_curate_project(project_id, auth.uid())
    or exists (select 1 from assessment_responses r where r.id = response_id and r.created_by = auth.uid())
  );


-- ==== supabase/migrations/20260817120001_public_full_detail.sql ====
-- Opt-in "full data exposure" for a published project -- a second, stricter
-- gate layered on top of the existing visibility='public' publish flow
-- (20260810130001_public_visibility.sql). That flow exposes only a
-- curated, hand-authored summary (projects.public_profile) and was never
-- extended to workstreams/artifacts/assessments. This migration adds a
-- narrow, additive opt-in so a SPECIFIC project (CareCall) can expose its
-- real workstreams, artifacts, and System Understanding Assessment
-- responses to anonymous visitors, while every other already-published
-- project (e.g. the RAG vs LLM comparison) is completely unaffected --
-- public_full_detail defaults to false, and setting it true is restricted
-- to platform admins at the application layer (see
-- setPublicFullDetailAction), deliberately stricter than the owner-or-admin
-- can_manage_project gate the rest of the publish flow uses.

alter table projects add column if not exists public_full_detail boolean not null default false;

-- One helper, reused by every new policy below, so "is this project's data
-- safe to expose in full to an anonymous visitor" has one source of truth.
create or replace function is_public_full_detail_project(pid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from projects p
    where p.id = pid and p.visibility = 'public' and p.published_at is not null and p.public_full_detail = true
  );
$$;

-- project_workstreams: additive anon read -----------------------------------
-- Workstream `status` (draft/active/...) is an internal editorial field, not
-- a publish gate -- all workstreams of an opted-in project are shown; the
-- opt-in itself is the gate.
create policy "project_workstreams_select_public_full_detail" on project_workstreams
  for select using (is_public_full_detail_project(project_id));

-- workstream_artifacts: one-hop join to the parent workstream's project,
-- same shape as the existing membership policy on this table.
create policy "workstream_artifacts_select_public_full_detail" on workstream_artifacts
  for select using (
    exists (select 1 from project_workstreams w where w.id = workstream_artifacts.workstream_id and is_public_full_detail_project(w.project_id))
  );

-- System Understanding Assessment tables -------------------------------------
create policy "system_assessments_select_public_full_detail" on system_assessments
  for select using (is_public_full_detail_project(project_id));

-- Only active/retired versions -- never a draft, which may contain
-- in-progress question edits not meant for public eyes even on an
-- opted-in project.
create policy "system_assessment_versions_select_public_full_detail" on system_assessment_versions
  for select using (is_public_full_detail_project(project_id) and status in ('active', 'retired'));

create policy "system_assessment_questions_select_public_full_detail" on system_assessment_questions
  for select using (is_public_full_detail_project(project_id));

-- Only completed responses -- an in-progress draft (e.g. a half-answered
-- test response) should never surface publicly even on an opted-in project.
create policy "assessment_responses_select_public_full_detail" on assessment_responses
  for select using (is_public_full_detail_project(project_id) and status = 'completed');

create policy "assessment_answers_select_public_full_detail" on assessment_answers
  for select using (
    is_public_full_detail_project(project_id)
    and exists (select 1 from assessment_responses r where r.id = assessment_answers.response_id and r.status = 'completed')
  );

-- Deliberately no change to project_notes, trending_*, eval_*, or any other
-- table -- this migration only widens the seven tables a "full detail"
-- public workstream page actually needs to render.


-- ==== supabase/migrations/20260818090001_ai_models_structured_output_default.sql ====
-- Independent default for structured-output tasks (chunk enrichment's
-- topic/subtopic/key_concepts JSON extraction; AI-assisted Wiki draft
-- synthesis) -- separate from the plain generation default (is_default).
--
-- Mirrors is_default's shape rather than adding a fifth model_type value:
-- structured output is a CAPABILITY of a generation model
-- (supports_structured_output, already a column), not a distinct KIND of
-- model the way generation/embedding/speech/multimodal are -- a single row
-- can't simultaneously BE type 'generation' and type 'structured_output',
-- so it doesn't belong in the model_type check constraint. This lets an
-- admin pick, among generation models that support structured output,
-- a different default than whatever's used for plain prose generation
-- (e.g. Wiki synthesis) -- the same bug class as the embedding fix
-- (getActiveProvider() used for a task that actually needed a different
-- purpose-scoped default) but for a capability that hasn't caused a hard
-- failure yet, only an unconfigurable one.
alter table ai_models add column if not exists is_default_structured_output boolean not null default false;

alter table ai_models add constraint ai_models_default_structured_output_requires_capability
  check (not is_default_structured_output or supports_structured_output);

-- At most one row globally -- not scoped by model_type the way
-- ai_models_one_default_per_type is, since structured output isn't a
-- model_type value. Indexing a constant is the standard Postgres pattern
-- for "at most one row where this predicate holds."
create unique index ai_models_one_default_structured_output on ai_models ((true)) where is_default_structured_output;

-- Seed from current state so this ships with zero downtime: whichever
-- model is already the plain generation default AND already supports
-- structured output keeps doing exactly what it does today (chunk
-- enrichment and Wiki synthesis already both work) until an admin
-- deliberately picks something different via the new UI control.
update ai_models set is_default_structured_output = true
where is_default = true and model_type = 'generation' and supports_structured_output = true;


-- ==== supabase/migrations/20260818100001_workstream_artifact_type_design_note.sql ====
-- Adds design_note as a first-class workstream_artifacts type -- for
-- handoff-ready architecture/design docs (e.g. the M5F Phases A/C/D/E
-- design note), distinct from the evidence-oriented types already listed
-- (capability_inventory, findings, etc.). Purely additive: no existing
-- value is renamed or removed, so every historical row stays valid. Same
-- drop-and-recreate pattern as 20260814130001_workstream_artifact_types.sql.
alter table workstream_artifacts drop constraint workstream_artifacts_artifact_type_check;
alter table workstream_artifacts add constraint workstream_artifacts_artifact_type_check
  check (artifact_type in (
    'capability_inventory', 'endpoint_inventory', 'openapi_spec', 'mcp_server',
    'evidence_map', 'test_results', 'findings', 'design_note', 'other'
  ));


-- ==== supabase/migrations/20260818110001_wiki_handbook_category_and_artifact_sources.sql ====
-- M6A: Workbench Handbook Wiki (M5F Phase A). wiki_categories is a lookup
-- table, not a check-constraint enum (see 20260808220001_wiki_categories.sql),
-- so adding the category is a plain insert.
insert into wiki_categories (id, name, sort_order) values
  ('platform_handbook', 'Workbench Handbook', 7)
on conflict (id) do nothing;

-- wiki_sources previously had no way to cite a workstream_artifacts row as
-- evidence (only document_id/chunk_id) -- Handbook articles synthesized from
-- project self-analysis artifacts (e.g. the M5F OpenAPI Discovery output)
-- need real, queryable traceability back to that evidence, not a text note
-- stuffed into source_type='external'. Purely additive: new nullable column,
-- widened check constraints, no existing row's meaning changes. Same
-- drop-and-recreate pattern as 20260814130001_workstream_artifact_types.sql.
alter table wiki_sources add column workstream_artifact_id uuid references workstream_artifacts(id) on delete set null;

alter table wiki_sources drop constraint wiki_sources_source_type_check;
alter table wiki_sources add constraint wiki_sources_source_type_check
  check (source_type in ('document', 'chunk', 'external', 'workstream_artifact'));

alter table wiki_sources drop constraint wiki_sources_evidence_required;
alter table wiki_sources add constraint wiki_sources_evidence_required check (
  source_type = 'external' or document_id is not null or chunk_id is not null or workstream_artifact_id is not null
);


-- ==== supabase/migrations/20260818120001_chat_assistant.sql ====
-- M6D: Conversational Workbench Assistant (M5F Phase E). Personal chat
-- history between one user and the Assistant, plus provenance columns on
-- the three tables the Assistant's existing MCP tools (Phase D) actually
-- create rows in.

create table conversations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references profiles(id) on delete cascade,
  title text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index conversations_user_id_idx on conversations(user_id);

create trigger conversations_set_updated_at before update on conversations
  for each row execute function set_updated_at();

create table chat_messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references conversations(id) on delete cascade,
  -- Denormalized from conversations.user_id -- keeps RLS a direct column
  -- check on both tables instead of a subquery/join, and sidesteps the
  -- INSERT...RETURNING-visibility gotcha a security-definer helper function
  -- would otherwise hit (see project_notes_select_own's comment for why
  -- that pattern exists elsewhere in this schema).
  user_id uuid not null references profiles(id) on delete cascade,
  role text not null check (role in ('user', 'assistant', 'tool')),
  content text,
  -- Present on an assistant message that requested one or more tool calls.
  tool_calls jsonb,
  -- Present on a 'tool' role message: which call this is the result of.
  tool_call_id text,
  tool_name text,
  created_at timestamptz not null default now()
);

create index chat_messages_conversation_id_idx on chat_messages(conversation_id);

-- RLS ------------------------------------------------------------------
-- Deliberately NO is_admin(uid) OR ... bypass on either table, unlike every
-- other table in this schema -- chat history is personal enough that this
-- is an intentional exception, not an oversight. Nothing in the M5F design
-- note requires admin visibility into another user's conversations.
alter table conversations enable row level security;
alter table chat_messages enable row level security;

create policy "conversations_owner" on conversations
  for all
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create policy "chat_messages_owner" on chat_messages
  for all
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- withLogging (src/lib/ai/logging.ts) needs to record the new generateChat
-- operation. Purely additive, same drop-and-recreate pattern used elsewhere
-- in this schema for widening a check constraint.
alter table ai_operation_logs drop constraint ai_operation_logs_operation_check;
alter table ai_operation_logs add constraint ai_operation_logs_operation_check
  check (operation in ('generate_text', 'generate_structured', 'generate_chat', 'embed'));

-- Provenance -------------------------------------------------------------
-- Additive, default 'ui' so no existing row's meaning changes. Only on the
-- three tables the Assistant's write tools (create_project,
-- create_workstream, attach_workstream_artifact -- src/lib/mcp/tools.ts)
-- actually create rows in, not a speculative blanket migration.
alter table projects add column created_via text not null default 'ui';
alter table projects add column assistant_prompt_version text;
alter table projects add column assistant_conversation_id uuid references conversations(id) on delete set null;

alter table project_workstreams add column created_via text not null default 'ui';
alter table project_workstreams add column assistant_prompt_version text;
alter table project_workstreams add column assistant_conversation_id uuid references conversations(id) on delete set null;

alter table workstream_artifacts add column created_via text not null default 'ui';
alter table workstream_artifacts add column assistant_prompt_version text;
alter table workstream_artifacts add column assistant_conversation_id uuid references conversations(id) on delete set null;


-- ==== supabase/migrations/20260818130001_chat_provenance_and_handoff_artifact.sql ====
-- M6E: Assistant model identity/provenance + document-first Workbench
-- methods. Two purely additive changes:

-- 1. Per-message model provenance on chat_messages, mirroring the existing
-- plain-text-snapshot convention used by wiki_versions.ai_provider/.ai_model
-- and ai_operation_logs.provider/.model (never a live FK to ai_providers/
-- ai_models -- historical rows must stay accurate even if a model is later
-- renamed, disabled, or stops being the default). Nullable: only set on
-- assistant-role rows.
alter table chat_messages add column provider text;
alter table chat_messages add column model text;

-- 2. implementation_handoff as a first-class workstream_artifacts type --
-- the generic handoff-document concept the design note asks for (rather
-- than a new artifact type per engineering method). Same drop-and-recreate
-- pattern as 20260818100001_workstream_artifact_type_design_note.sql.
alter table workstream_artifacts drop constraint workstream_artifacts_artifact_type_check;
alter table workstream_artifacts add constraint workstream_artifacts_artifact_type_check
  check (artifact_type in (
    'capability_inventory', 'endpoint_inventory', 'openapi_spec', 'mcp_server',
    'evidence_map', 'test_results', 'findings', 'design_note', 'implementation_handoff', 'other'
  ));


-- ==== supabase/migrations/20260820120001_seed_deepseek_provider.sql ====
-- Add DeepSeek as a provider. DeepSeek's API is OpenAI-compatible (same
-- chat/completions shape as Groq), so this reuses OpenAICompatibleProvider
-- via provider_type='openai_compatible' -- no new provider class needed.
-- Neither model is made the platform default; both are enabled and
-- selectable (e.g. from the Assistant's model picker) so trying DeepSeek
-- doesn't change anyone else's default behavior.
insert into ai_providers (name, provider_type, display_name, base_url, api_key_env_var, enabled, supports_model_discovery) values
  ('deepseek', 'openai_compatible', 'DeepSeek', 'https://api.deepseek.com/v1', 'DEEPSEEK_API_KEY', true, true);

-- max_output_tokens set on both per the user's own tip ("prevents burning
-- through credits on unexpectedly long outputs") -- runAssistantTurn now
-- reads this per-model cap and passes it to every generateChat call
-- (src/lib/chat/loop.ts), not just for DeepSeek. Raise/clear it later via
-- the admin Provider Detail page if 2048 proves too tight.
insert into ai_models (provider_id, model_id, display_name, model_type, is_default, max_output_tokens, supports_structured_output, supports_tools)
select id, 'deepseek-v4-flash', 'DeepSeek V4 Flash', 'generation', false, 2048, true, true from ai_providers where name = 'deepseek';
insert into ai_models (provider_id, model_id, display_name, model_type, is_default, max_output_tokens, supports_structured_output, supports_tools)
select id, 'deepseek-v4-pro', 'DeepSeek V4 Pro', 'generation', false, 2048, true, true from ai_providers where name = 'deepseek';


-- ==== supabase/migrations/20260820130001_chat_history_and_summary.sql ====
-- Assistant Onboarding, History & Bounded Context (Stage 1 + 2).
-- Stage 1: last_message_at lets the UI list/resume conversations by recency
-- without a join against chat_messages on every render. Stage 2: a rolling
-- per-conversation summary so a long conversation's provider payload can
-- stay bounded instead of growing unboundedly with every turn.

alter table conversations add column last_message_at timestamptz;

update conversations c
set last_message_at = (
  select max(m.created_at) from chat_messages m where m.conversation_id = c.id
);

-- Kept independent of the Stage 2 summary columns below (which also update
-- this row) so "most recently active" stays accurate even on a turn whose
-- summary refresh is skipped or fails.
create or replace function set_conversation_last_message_at()
returns trigger
language plpgsql
as $$
begin
  update conversations set last_message_at = new.created_at where id = new.conversation_id;
  return new;
end;
$$;

create trigger chat_messages_set_conversation_last_message_at
  after insert on chat_messages
  for each row execute function set_conversation_last_message_at();

-- Stage 2: rolling summary. summary_through_message_id marks how much of
-- the conversation the summary already covers (set null, not cascaded,
-- if that message is ever deleted -- there is no delete UI yet, but this
-- keeps a future one from leaving a dangling reference).
alter table conversations add column summary_json jsonb;
alter table conversations add column summary_through_message_id uuid references chat_messages(id) on delete set null;
alter table conversations add column summary_updated_at timestamptz;
alter table conversations add column summary_provider text;
alter table conversations add column summary_model text;
alter table conversations add column summary_version text;


-- ==== supabase/migrations/20260821090001_seed_grok_provider.sql ====
-- Add Grok (xAI) as a provider -- distinct from Groq (the existing 'groq'
-- provider, a fast-inference host for open models like GPT-OSS). Easy to
-- confuse; they are unrelated companies/APIs. xAI's API is OpenAI-compatible
-- (same chat/completions shape), so this reuses OpenAICompatibleProvider via
-- provider_type='openai_compatible' -- no new provider class needed.
-- Not made the platform default; enabled and selectable so trying it doesn't
-- change anyone else's default behavior.
insert into ai_providers (name, provider_type, display_name, base_url, api_key_env_var, enabled, supports_model_discovery) values
  ('grok', 'openai_compatible', 'Grok (xAI)', 'https://api.x.ai/v1', 'GROK_API_KEY', true, true);

-- Grok 4.6 per the user's own account console (xAI's flagship, "built for
-- long-horizon agentic coding and real-world knowledge work", 500K context).
-- The model_id string is a best guess from the console's display name --
-- the account had no credits yet to confirm via live model discovery
-- (GET /v1/models returned 403 "no credits or licenses"). Once credits are
-- added, use Admin > Grok > "Refresh Models" to confirm/correct this row.
insert into ai_models (provider_id, model_id, display_name, model_type, is_default, context_window, max_output_tokens, supports_structured_output, supports_tools)
select id, 'grok-4.6', 'Grok 4.6', 'generation', false, 500000, 8192, true, true from ai_providers where name = 'grok';


-- ==== supabase/migrations/20260821090002_add_ai_operation_logs_error_code.sql ====
-- Mirrors the existing error_code column already on graph_runs/graph_steps
-- -- not a new convention. Lets a provider failure's already-computed
-- classification (rate_limit / quota_exceeded / model_unavailable /
-- authentication / invalid_request / unknown -- see classifyProviderError in
-- src/lib/ai/provider.ts) be queried directly instead of only living inside
-- the free-text error_message string.
alter table ai_operation_logs add column error_code text;


-- ==== supabase/migrations/20260821100001_shared_links_moderation.sql ====
-- Dashboard Shared Links: moderation audit trail + duplicate detection for
-- the existing trending_items table (no new table -- a shared link and its
-- Trending entry are the same record, see docs/dev-request-dashboard-shared-links-and-library-foundation.md).
-- No RLS changes -- the dashboard's "administrator-only Remove" is stricter
-- than the existing curator-or-admin trending_items_manage_curator policy,
-- so it's enforced in removeSharedLinkAction (requireRole('admin')) rather
-- than narrowing RLS, which would also affect the existing curator archive
-- workflow.
alter table trending_items add column archived_by uuid references profiles(id) on delete set null;
alter table trending_items add column archived_at timestamptz;
alter table trending_items add column moderation_reason text;

-- Computed application-side (normalizeUrlForDuplicateDetection in
-- src/lib/trending/url-safety.ts), not a generated column -- normalization
-- rules may evolve without a migration. Existing rows are left null; they
-- simply won't be matched as a duplicate of a new submission.
alter table trending_items add column normalized_source_url text;
create index trending_items_normalized_source_url_idx on trending_items(normalized_source_url);


-- ==== supabase/migrations/20260821110001_blog_posts.sql ====
-- Public Blog. Modeled on the Projects/Examples "just publish" pattern
-- (visibility/published_at, one Publish/Unpublish toggle -- see
-- src/app/actions/projects.ts) rather than the Wiki draft/review/approved
-- lifecycle: one admin author, no review stage.
create table blog_posts (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null,
  excerpt text,
  content text not null,
  status text not null default 'draft' check (status in ('draft', 'published')),
  author_id uuid references profiles(id) on delete set null,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger blog_posts_set_updated_at before update on blog_posts
  for each row execute function set_updated_at();

-- RLS ------------------------------------------------------------------
alter table blog_posts enable row level security;

-- No to authenticated/to anon restriction -- matches
-- wiki_articles_select_public's shape (a signed-in visitor browsing public
-- pages should see the same thing an anonymous one does).
create policy "blog_posts_select_public" on blog_posts
  for select using (status = 'published');

-- Admin-only authoring -- no curator tier, matching the "just publish"
-- pattern's single-author model rather than Wiki's multi-role review.
create policy "blog_posts_admin_all" on blog_posts
  for all using (is_admin(auth.uid())) with check (is_admin(auth.uid()));

-- Seed the first post as a DRAFT, not published -- the source document's
-- own "Publication note" says its operational details and estimates should
-- be reviewed before publication, so this is left for the user to review
-- and publish through the new admin UI, not published automatically.
insert into blog_posts (slug, title, excerpt, content, status)
values (
  'deployment-and-server-options',
  'KB Sandbox Deployment and Server Options',
  'From Vercel and managed Supabase to Azure, AWS, or a fully private deployment -- how KB Sandbox can move beyond its current hosting without slowing product development.',
  $md$## From a managed cloud service to a private enterprise deployment

KB Sandbox is currently well suited to Vercel and managed Supabase, but its architecture does not require it to remain there. The application can also be deployed to Microsoft Azure, Amazon Web Services (AWS), a customer's private cloud, or an organisation's own infrastructure.

This document explains the principal deployment choices, their trade-offs, and a recommended path for making KB Sandbox portable without slowing current product development.

## Executive summary

KB Sandbox has relatively little dependency on Vercel-specific services. It is primarily a Next.js application connected to Supabase for its database, authentication, and file storage, with external AI providers selected through configuration.

There are two levels of migration:

1. **Move only the KB Sandbox application.** Keep managed Supabase and the existing AI providers. This is a comparatively straightforward deployment change.
2. **Move the complete platform.** Deploy KB Sandbox together with a self-hosted Supabase stack. This provides greater data control and supports private or isolated installations, but transfers substantial operational responsibility to KB Sandbox or the customer.

For the present public service, Vercel and managed Supabase remain the lowest-maintenance choice. In parallel, KB Sandbox should develop and regularly test a container-based private deployment package.

## Deployment options at a glance

| Option | Best suited to | Principal advantage | Principal trade-off |
| --- | --- | --- | --- |
| Vercel with managed Supabase | Public service and rapid product development | Simplest Next.js deployment and lowest operational burden | Platform runtime limits and less infrastructure control |
| Azure with managed Supabase | Organisations already standardised on Microsoft Azure | Enterprise networking, governance, identity, and regional controls | More configuration and operational responsibility |
| AWS with managed Supabase | Organisations already standardised on AWS | Broad infrastructure choice, regions, security, and scaling controls | More infrastructure components and operational complexity |
| Azure or AWS with self-hosted Supabase | Private enterprise installations | Application and customer data can remain inside the customer's cloud boundary | KB Sandbox or the customer must operate the database platform |
| On-premises or isolated deployment | Regulated, sovereign, or disconnected environments | Maximum control over data location and external connectivity | Highest support, upgrade, backup, and availability burden |

## Option 1: Vercel and managed Supabase

Vercel provides the most direct operational experience for a Next.js application. Deployment previews, application builds, routing, image handling, and server functions require comparatively little infrastructure work.

Managed Supabase separately provides the PostgreSQL database, authentication, storage, backups, and platform administration.

This combination is a strong fit while KB Sandbox is evolving quickly because engineering effort can remain focused on product capability. Its principal limitation is that application execution remains subject to Vercel plan, memory, and duration constraints. Long-running work such as journal generation, document assessment, and AI evaluations should therefore move toward background jobs regardless of the eventual hosting platform.

## Option 2: Microsoft Azure

KB Sandbox can run as an ordinary Node.js application or as a container in Azure.

Likely services include:

- **Azure App Service** for the simplest managed Node.js or container deployment.
- **Azure Container Apps** when container scaling, private networking, managed secrets, or background workers are important.
- **Azure Database, storage, and identity services** only if a future edition replaces Supabase rather than self-hosting it.

Azure is particularly attractive when customers already use Microsoft enterprise identity, networking, governance, and security tooling. A container deployment also avoids tying the application to an Azure-specific application framework.

## Option 3: Amazon Web Services

On AWS, the application should likewise be deployed as a standard container.

Likely services include:

- **AWS App Runner** for a relatively simple managed container service.
- **Amazon ECS with Fargate** when more control over networking, scaling, and supporting services is required.
- **Amazon RDS, S3, and Cognito** only if a future edition replaces Supabase with AWS-native components.

AWS Amplify should not be the initial target for the current application without a fresh compatibility review. At the time of writing, AWS's published managed SSR support identifies Next.js versions through version 15, while KB Sandbox uses Next.js 16. A normal container deployment provides a clearer compatibility boundary.

## Option 4: A complete private KB Sandbox deployment

A private installation would package KB Sandbox and self-hosted Supabase as one deployable product while keeping them as separate services.

```text
Users
  |
Reverse proxy and HTTPS
  |-- kbsandbox.example.com --> KB Sandbox container
  `-- data.example.com ------> Supabase API gateway
                                      |
                                      |-- Authentication
                                      |-- REST API
                                      |-- Realtime
                                      |-- File storage
                                      |-- PostgreSQL
                                      `-- Administration Studio
```

The distinction is important: deployed together does not mean placed in one container. Supabase is itself a collection of cooperating services. Docker Compose is Supabase's documented self-hosting approach and provides a practical first packaging format for a single-server private installation.

This model offers:

- Control over the physical and legal location of customer data.
- Deployment within a customer's Azure or AWS account.
- Deployment on an organisation's own Linux infrastructure.
- The possibility of an isolated environment with no public application access.
- A reduced dependency on Vercel and the managed Supabase platform.
- A credible private-cloud offering for regulated organisations.

External AI providers remain a separate data-processing consideration. A fully isolated installation would require approved outbound connectivity or a compatible locally hosted AI model.

## Proposed product editions

### KB Sandbox Cloud

The public service, operated using Vercel and managed Supabase. This edition provides the lowest administration burden and supports rapid releases.

### KB Sandbox Private Cloud

KB Sandbox and a self-hosted Supabase stack deployed inside a customer's Azure or AWS account. The customer controls the cloud boundary, data region, network policies, and access to external AI providers.

### KB Sandbox Local or Isolated

The same application stack deployed on an organisation's server or approved local infrastructure. This edition may restrict internet connectivity and use locally available AI services.

The three editions should share the same application code. Environment configuration should select public URLs, Supabase endpoints, storage behaviour, AI providers, mail delivery, and optional platform capabilities.

## Self-hosted Supabase responsibilities

Self-hosting Supabase provides control, but it is not equivalent to receiving the managed Supabase service inside a Docker container. The operator becomes responsible for:

- Server provisioning and operating-system maintenance.
- PostgreSQL maintenance and version upgrades.
- Supabase service upgrades and compatibility testing.
- Database and file-storage backups.
- Point-in-time recovery or an agreed alternative.
- Restore testing and disaster recovery.
- Security hardening, firewall rules, and TLS certificates.
- Secret generation, storage, and rotation.
- Monitoring, logs, alerts, capacity, and uptime.
- High availability and scaling where required.
- Authentication email delivery and OAuth configuration.

Supabase distinguishes its development CLI stack from a production self-hosted deployment. The local development stack must not simply be exposed to the internet. Production should use the official self-hosted distribution with durable volumes, HTTPS, secure secrets, monitoring, and tested backups.

Supabase currently recommends at least four CPU cores, 8 GB of RAM, and 80 GB of SSD storage for a small-to-medium self-hosted installation. Actual KB Sandbox sizing must be established through load, document-storage, and AI-workload testing.

## Application portability work

The following work would keep KB Sandbox portable across Vercel, Azure, AWS, and private infrastructure:

1. Produce a versioned production container image using the Next.js standalone server output.
2. Add application and dependency health endpoints.
3. Maintain a deployment-independent inventory of required environment variables and secrets.
4. Keep database schema changes in repeatable, versioned migrations.
5. Move long-running journals, evaluations, and large document operations into durable background jobs.
6. Store all persistent files in Supabase Storage or another configured durable store, never in the application container.
7. Add centralised logs, metrics, and operational alerts.
8. Test authentication redirects, cookies, Server Actions, route revalidation, uploads, signed downloads, and image delivery in every supported environment.
9. Automate backups and regularly prove that both PostgreSQL data and stored files can be restored.
10. Publish a supported-version matrix for KB Sandbox, Supabase, PostgreSQL, and container images.

## Migrating the existing managed Supabase project

Moving an existing installation to self-hosted Supabase requires more than copying the database. The migration plan must cover:

- PostgreSQL schema, data, extensions, functions, and triggers.
- Row-level security policies and database permissions.
- Authentication users, identities, providers, templates, and redirect URLs.
- Storage buckets, policies, metadata, and stored files.
- Scheduled processes and database jobs.
- Application secrets, public keys, and service-role credentials.
- A reconciliation step confirming counts, ownership, and isolation after migration.

The managed deployment should remain available during migration testing. Production cutover should use a rehearsed data-freeze, final synchronisation, DNS change, validation, and rollback procedure.

## Availability profiles

A first private release can reasonably target a single Linux server, but its service level must be described honestly.

### Entry private deployment

- One server or virtual machine.
- Docker Compose application stack.
- Durable encrypted storage.
- Automated off-machine backups.
- Documented restoration and upgrade procedures.
- Planned maintenance windows.

### High-availability private deployment

- Multiple KB Sandbox application instances.
- Highly available or managed PostgreSQL architecture compatible with the chosen Supabase design.
- Replicated or durable object storage.
- Load balancing and health-based replacement.
- Centralised monitoring and alerting.
- Tested recovery objectives and operational ownership.

High availability should be a later, separately engineered profile rather than an implied property of the initial single-server package.

## Indicative migration effort

These estimates are planning assumptions, not commitments:

- Moving only the KB Sandbox application while retaining managed Supabase: **one to three days for a proof of concept**, followed by approximately **one to two weeks of production hardening**.
- Producing a supported private deployment with self-hosted Supabase: a larger product initiative requiring installation automation, migration tooling, backup and restore procedures, monitoring, security guidance, upgrade testing, and support documentation.

The private deployment should therefore be planned as a product capability rather than treated as a change of hosting address.

## Recommendation

Continue operating the public KB Sandbox service on Vercel and managed Supabase while product development remains rapid. At the same time, create a tested **KB Sandbox Private** distribution consisting of:

- A production KB Sandbox container.
- A pinned and supported self-hosted Supabase distribution.
- A reverse proxy with HTTPS.
- Durable database and storage volumes.
- Secure environment and secret templates.
- Automated off-machine backup procedures.
- Health checks, monitoring, and recovery documentation.
- A migration and validation process for existing installations.

The first target should be a single Linux server in a non-production environment. Once installation, upgrades, backup restoration, authentication, storage, and AI-provider configuration work reliably, the same package can be qualified for Azure, AWS, and customer-controlled infrastructure.

## References

- [Supabase self-hosting overview](https://supabase.com/docs/guides/self-hosting)
- [Self-hosting Supabase with Docker](https://supabase.com/docs/guides/self-hosting/docker)
- [Restoring a managed Supabase project to self-hosted Supabase](https://supabase.com/docs/guides/self-hosting/restore-from-platform)
- [Updating a self-hosted Supabase deployment](https://supabase.com/docs/guides/self-hosting/updating)
- [Configuring HTTPS for self-hosted Supabase](https://supabase.com/docs/guides/self-hosting/self-hosted-proxy-https)
- [Vercel function duration configuration](https://vercel.com/docs/functions/configuring-functions/duration)
- [Azure App Service for Node.js](https://learn.microsoft.com/en-us/azure/app-service/quickstart-nodejs)
- [Azure Container Apps overview](https://learn.microsoft.com/en-us/azure/container-apps/overview)
- [AWS Amplify support for Next.js features](https://docs.aws.amazon.com/amplify/latest/userguide/ssr-amplify-support.html)
$md$,
  'draft'
);


