-- docs/dev-request-blog-contributor-workflow-and-editorial-placeholders.md).

alter table blog_posts
  add column if not exists cover_image_path text,
  add column if not exists cover_image_alt text;

-- Mirrors wiki_relations (20260808220005_wiki_relations_and_vectors.sql)
-- exactly in shape: directional storage, symmetric display (see
-- src/lib/blog/relations.ts). RLS is deliberately stricter-on-read than
-- wiki_relations_select_authenticated -- Wiki's related-articles UI is
-- never shown to anonymous visitors, but Blog's public article page needs
-- to read relations too, so this is public-select rather than
-- authenticated-only. A relation row is just an id pair, not sensitive
-- content, even when one side is still a draft.
create table if not exists blog_relations (
  id uuid primary key default gen_random_uuid(),
  from_post_id uuid not null references blog_posts(id) on delete cascade,
  to_post_id uuid not null references blog_posts(id) on delete cascade,
  relation_type text not null default 'related',
  created_at timestamptz not null default now(),
  unique (from_post_id, to_post_id),
  constraint blog_relations_no_self_link check (from_post_id <> to_post_id)
);
create index if not exists blog_relations_from_idx on blog_relations(from_post_id);
create index if not exists blog_relations_to_idx on blog_relations(to_post_id);

alter table blog_relations enable row level security;

create policy "blog_relations_select_public" on blog_relations
  for select using (true);

create policy "blog_relations_manage_staff" on blog_relations
  for all using (is_curator_or_admin(auth.uid())) with check (is_curator_or_admin(auth.uid()));


-- ==== supabase/migrations/20260823130001_blog_media_storage.sql ====
-- Public storage bucket for Blog cover/inline images (see
-- docs/dev-request-blog-contributor-workflow-and-editorial-placeholders.md,
-- "Minimal Blog visuals"). Modeled on branding_storage
-- (20260814100001_branding_storage.sql), but curator-or-admin can write
-- (not admin-only, matching Blog's authoring permission level), and the
-- allowlist enforced at the application layer (src/lib/blog/media.ts)
-- deliberately excludes SVG -- the dev request requires preventing SVG or
-- other active content in Blog media unless a separate sanitisation
-- design is approved.
insert into storage.buckets (id, name, public)
values ('blog-media', 'blog-media', true)
on conflict (id) do update set public = true;

create policy "blog_media_bucket_staff_insert" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'blog-media' and is_curator_or_admin(auth.uid()));

create policy "blog_media_bucket_staff_update" on storage.objects
  for update to authenticated
  using (bucket_id = 'blog-media' and is_curator_or_admin(auth.uid()));

create policy "blog_media_bucket_staff_delete" on storage.objects
  for delete to authenticated
  using (bucket_id = 'blog-media' and is_curator_or_admin(auth.uid()));

create policy "blog_media_bucket_public_select" on storage.objects
  for select using (bucket_id = 'blog-media');


-- ==== supabase/migrations/20260824120001_knowledge_base_classification.sql ====
-- Separate current working knowledge bases from the four domain samples
-- inherited from Rhubarb. Stable IDs and all referenced content are retained;
-- lifecycle_status controls whether a KB is offered for new work.
alter table knowledge_bases
  add column if not exists classification text not null default 'platform'
    check (classification in ('platform', 'legacy_sample', 'project', 'partner_pilot')),
  add column if not exists lifecycle_status text not null default 'active'
    check (lifecycle_status in ('active', 'reference', 'archived')),
  add column if not exists origin text;

update knowledge_bases
set classification = 'legacy_sample',
    lifecycle_status = 'reference',
    origin = 'Rhubarb',
    description = case id
      when 'fhir' then 'Legacy Rhubarb sample: FHIR and healthcare interoperability standards.'
      when 'vbc' then 'Legacy Rhubarb sample: value-based care models and programs.'
      when 'grants' then 'Legacy Rhubarb sample: grant funding and program documentation.'
      when 'billing' then 'Legacy Rhubarb sample: healthcare billing and claims.'
      else description
    end
where id in ('fhir', 'vbc', 'grants', 'billing');

update knowledge_bases
set classification = 'partner_pilot', lifecycle_status = 'active', origin = 'Sandz'
where id = 'zadara_sandz';

insert into knowledge_bases (id, name, description, classification, lifecycle_status, origin)
values (
  'ai_engineering',
  'AI Engineering & RAG Curation',
  'Source documents and curated evidence for retrieval, RAG evaluation, agents, and AI engineering.',
  'platform',
  'active',
  'KB Sandbox'
)
on conflict (id) do update set
  name = excluded.name,
  description = excluded.description,
  classification = excluded.classification,
  lifecycle_status = excluded.lifecycle_status,
  origin = excluded.origin;

-- Remove future-facing curator assignments to the legacy samples. Accounts
-- that previously had any of the four samples receive the active AI
-- Engineering KB instead; unrelated assignments are preserved.
update profiles
set assigned_kbs = (
  select array_agg(distinct kb order by kb)
  from unnest(array_append(
    array_remove(array_remove(array_remove(array_remove(assigned_kbs, 'fhir'), 'vbc'), 'grants'), 'billing'),
    'ai_engineering'
  )) as kb
)
where assigned_kbs && array['fhir', 'vbc', 'grants', 'billing']::text[];

-- Database backstops for crafted/direct Data API writes. Existing records in
-- reference KBs remain valid and editable; only a new association (or a
-- changed association) to a non-active KB is refused.
create or replace function require_active_knowledge_base(kbid text)
returns void language plpgsql stable security definer set search_path = public as $$
begin
  if not exists (
    select 1 from knowledge_bases where id = kbid and lifecycle_status = 'active'
  ) then
    raise exception 'Knowledge base % is retained for reference and cannot be used for new work', kbid;
  end if;
end;
$$;

create or replace function validate_document_active_kb()
returns trigger language plpgsql set search_path = public as $$
begin
  perform require_active_knowledge_base(new.doc_type);
  return new;
end;
$$;

drop trigger if exists documents_require_active_kb on documents;
create trigger documents_require_active_kb
  before insert or update of doc_type on documents
  for each row execute function validate_document_active_kb();

create or replace function validate_queue_active_kb()
returns trigger language plpgsql set search_path = public as $$
begin
  perform require_active_knowledge_base(new.kb_id);
  return new;
end;
$$;

drop trigger if exists curation_queue_require_active_kb on curation_queue;
create trigger curation_queue_require_active_kb
  before insert or update of kb_id on curation_queue
  for each row execute function validate_queue_active_kb();

create or replace function validate_kb_project_attachment_active()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.project_id is not null and new.lifecycle_status <> 'active' then
    raise exception 'Reference knowledge base % cannot be attached to a project', new.id;
  end if;
  return new;
end;
$$;

drop trigger if exists knowledge_bases_active_project_attachment on knowledge_bases;
create trigger knowledge_bases_active_project_attachment
  before insert or update of project_id, lifecycle_status on knowledge_bases
  for each row execute function validate_kb_project_attachment_active();

create or replace function validate_profile_active_kb_assignments()
returns trigger language plpgsql set search_path = public as $$
declare
  kbid text;
begin
  foreach kbid in array new.assigned_kbs loop
    perform require_active_knowledge_base(kbid);
  end loop;
  return new;
end;
$$;

drop trigger if exists profiles_require_active_kb_assignments on profiles;
create trigger profiles_require_active_kb_assignments
  before insert or update of assigned_kbs on profiles
  for each row execute function validate_profile_active_kb_assignments();


-- ==== supabase/migrations/20260824130001_knowledge_sources.sql ====
-- Versioned Knowledge Source Documents (docs/dev-request-versioned-knowledge-source-documents.md),
-- Stage 1: model and safe retrieval only. `documents` stays the immutable
-- version table (every existing FK -- document_chunks, kb_vectors,
-- curation_queue, ai_operation_logs -- already points at documents.id, so
-- none of that needs to change). `knowledge_sources` is new: the stable
-- logical-source identity, mirroring wiki_articles/wiki_versions exactly
-- (current_version_id pointer, immutable versions underneath). Public
-- terminology stays "Source" and "Version", per the dev request.
create table if not exists knowledge_sources (
  id uuid primary key default gen_random_uuid(),
  knowledge_base_id text not null references knowledge_bases(id) on delete restrict,
  title text not null,
  source_url text,
  publisher text,
  current_version_id uuid, -- FK added below, once documents.knowledge_source_id exists
  lifecycle_status text not null default 'active' check (lifecycle_status in ('active', 'retired')),
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- Uniqueness on source_url now belongs at the logical-source level, not per
  -- uploaded version -- this replaces documents(doc_type, source_url) below.
  unique (knowledge_base_id, source_url)
);

create index if not exists knowledge_sources_kb_id_idx on knowledge_sources(knowledge_base_id);

drop trigger if exists knowledge_sources_set_updated_at on knowledge_sources;
create trigger knowledge_sources_set_updated_at before update on knowledge_sources
  for each row execute function set_updated_at();

-- documents becomes the immutable version table: one row per version of one
-- knowledge_source. version_number defaults to 1 for the backfill below;
-- Stage 2's "Upload new version" flow is what will ever insert version 2+.
alter table documents
  add column if not exists knowledge_source_id uuid references knowledge_sources(id) on delete cascade,
  add column if not exists version_number integer not null default 1,
  add column if not exists change_note text,
  add column if not exists superseded_at timestamptz,
  add column if not exists retired_at timestamptz;

alter table knowledge_sources
  add constraint knowledge_sources_current_version_fk
  foreign key (current_version_id) references documents(id) on delete set null;

-- Backfill: one knowledge_sources row per existing documents row, all as
-- version 1, and each immediately made current. Stage 1 never creates a
-- second version of an existing source, so "current = the only version"
-- exactly preserves today's retrieval behaviour (see match_documents below)
-- -- this is a deliberate, documented choice, not an oversight. Do not infer
-- that similarly named/dated existing documents are versions of one another;
-- that reconciliation is a deliberate Stage 3 curator action, per the dev request.
do $$
declare
  doc record;
  new_source_id uuid;
begin
  for doc in select * from documents where knowledge_source_id is null loop
    insert into knowledge_sources (knowledge_base_id, title, source_url, current_version_id, created_by, created_at)
    values (doc.doc_type, doc.original_filename, doc.source_url, null, doc.uploaded_by, doc.created_at)
    returning id into new_source_id;

    update documents set knowledge_source_id = new_source_id, version_number = 1 where id = doc.id;
    update knowledge_sources set current_version_id = doc.id where id = new_source_id;
  end loop;
end $$;

alter table documents alter column knowledge_source_id set not null;
alter table documents add constraint documents_source_version_unique unique (knowledge_source_id, version_number);

-- Superseded by the new source-level uniqueness rule above.
alter table documents drop constraint if exists documents_doc_type_source_url_key;

create index if not exists documents_knowledge_source_id_idx on documents(knowledge_source_id);

-- RLS: same staff-or-owner shape as documents itself
-- (20260808190010_rls_policies.sql), reusing the same helper functions.
alter table knowledge_sources enable row level security;

create policy "knowledge_sources_select_staff_or_owner" on knowledge_sources
  for select using (is_curator_or_admin(auth.uid()) or created_by = auth.uid());

create policy "knowledge_sources_insert_staff" on knowledge_sources
  for insert with check (is_curator_or_admin(auth.uid()));

create policy "knowledge_sources_update_staff" on knowledge_sources
  for update using (is_curator_or_admin(auth.uid())) with check (is_curator_or_admin(auth.uid()));

-- Retrieval: only chunks belonging to a source's current version are
-- eligible. Mirrors match_wiki_vectors's join through wiki_articles.current_version_id
-- exactly (20260809110003_match_wiki_vectors.sql) -- same pattern, new table.
-- Return columns are unchanged, so CREATE OR REPLACE is safe here (unlike the
-- id/chunk_id change in 20260809110005_match_documents_chunk_id.sql, which
-- needed DROP + CREATE).
create or replace function match_documents(
  query_embedding vector(1536),
  match_threshold float default 0.75,
  match_count int default 10,
  filter_doc_type text default null,
  filter_use_cases text[] default null
)
returns table (
  id uuid,
  chunk_id uuid,
  content text,
  similarity float,
  metadata jsonb
)
language sql stable as $$
  select
    kb_vectors.id,
    kb_vectors.chunk_id,
    kb_vectors.content,
    1 - (kb_vectors.embedding <=> query_embedding) as similarity,
    jsonb_build_object(
      'topic', kb_vectors.topic,
      'subtopic', kb_vectors.subtopic,
      'doc_type', kb_vectors.doc_type,
      'source_document', kb_vectors.source_document,
      'source_page', kb_vectors.source_page,
      'tags', kb_vectors.tags
    ) as metadata
  from kb_vectors
  join documents d on d.id = kb_vectors.document_id
  join knowledge_sources ks on ks.current_version_id = d.id
  where 1 - (kb_vectors.embedding <=> query_embedding) > match_threshold
    and (filter_doc_type is null or kb_vectors.doc_type = filter_doc_type)
    and (filter_use_cases is null or kb_vectors.use_cases && filter_use_cases)
  order by kb_vectors.embedding <=> query_embedding
  limit match_count;
$$;


-- ==== supabase/migrations/20260824140001_project_governance.sql ====
-- Project Approval Authorities and Governance
-- (docs/dev-request-project-approval-authorities.md), Stage 1: authority
-- planning foundation only. No approval requests/decisions tables yet --
-- those are Stage 2. Deliberately separate from platform role
-- (profiles.role) and project role (project_members.role): a policy says
-- WHAT approval a project needs; an authority assignment says WHO may make
-- that specific decision. Neither is inferred from platform admin status --
-- can_manage_project's existing is_admin bypass lets a platform admin
-- administer this shell the same way they can already manage members, but
-- that is setup, not a fabricated approval authority (there is nothing to
-- approve yet in Stage 1).

-- Business function describes why a member participates -- it routes
-- approval work but does not by itself grant authority. Bounded catalogue
-- per the dev request; 'other' pairs with function_notes for a short
-- free-text description.
alter table project_members
  add column if not exists business_function text
    check (business_function in (
      'business_development_sales', 'finance_pricing', 'legal_commercial', 'customer_support',
      'delivery_consulting', 'architecture_engineering', 'security_compliance',
      'customer_representative', 'project_governance', 'other'
    )),
  add column if not exists function_notes text;

create table if not exists project_approval_policies (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  approval_type text not null check (approval_type in (
    'technical', 'pricing', 'commercial', 'security_compliance', 'support_commitment',
    'proposal_release', 'customer_acceptance', 'knowledge_publication', 'production_change'
  )),
  requirement_status text not null default 'required'
    check (requirement_status in ('required', 'optional', 'not_applicable')),
  sequence integer,
  minimum_approvals integer not null default 1,
  approval_mode text not null default 'any_authorized' check (approval_mode in ('any_authorized', 'all_assigned')),
  allow_self_approval boolean not null default false,
  monetary_trigger numeric,
  discount_trigger_percent numeric,
  visibility_scope text not null default 'internal' check (visibility_scope in ('internal', 'customer_visible')),
  required_before_release boolean not null default false,
  notes text,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  unique (project_id, approval_type)
);

create index if not exists project_approval_policies_project_id_idx on project_approval_policies(project_id);

drop trigger if exists project_approval_policies_set_updated_at on project_approval_policies;
create trigger project_approval_policies_set_updated_at before update on project_approval_policies
  for each row execute function set_updated_at();

create table if not exists project_authority_assignments (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  business_function text
    check (business_function in (
      'business_development_sales', 'finance_pricing', 'legal_commercial', 'customer_support',
      'delivery_consulting', 'architecture_engineering', 'security_compliance',
      'customer_representative', 'project_governance', 'other'
    )),
  approval_type text not null check (approval_type in (
    'technical', 'pricing', 'commercial', 'security_compliance', 'support_commitment',
    'proposal_release', 'customer_acceptance', 'knowledge_publication', 'production_change'
  )),
  monetary_limit numeric,
  discount_limit_percent numeric,
  conditions text,
  effective_from timestamptz not null default now(),
  expires_at timestamptz,
  status text not null default 'active' check (status in ('active', 'revoked')),
  allow_self_approval boolean not null default false,
  granted_by uuid references profiles(id) on delete set null,
  granted_at timestamptz not null default now(),
  revoked_by uuid references profiles(id) on delete set null,
  revoked_at timestamptz,
  revocation_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists project_authority_assignments_project_id_idx on project_authority_assignments(project_id);
create index if not exists project_authority_assignments_user_id_idx on project_authority_assignments(user_id);

drop trigger if exists project_authority_assignments_set_updated_at on project_authority_assignments;
create trigger project_authority_assignments_set_updated_at before update on project_authority_assignments
  for each row execute function set_updated_at();

-- RLS: same shape as project_workstreams (20260811100004_project_workstreams.sql)
-- -- any active project member (including 'viewer') can see the governance
-- setup; only the project owner (or platform admin, via can_manage_project's
-- existing bypass) can change it. Stage 1 has no "governance manager" role
-- distinct from owner -- the dev request explicitly forbids inventing a new
-- global platform role, and no separate concept exists yet to delegate to.
alter table project_approval_policies enable row level security;

create policy "project_approval_policies_select_member" on project_approval_policies
  for select using (is_project_member(project_id, auth.uid()));

create policy "project_approval_policies_manage_owner" on project_approval_policies
  for all using (can_manage_project(project_id, auth.uid()))
  with check (can_manage_project(project_id, auth.uid()));

alter table project_authority_assignments enable row level security;

create policy "project_authority_assignments_select_member" on project_authority_assignments
  for select using (is_project_member(project_id, auth.uid()));

create policy "project_authority_assignments_manage_owner" on project_authority_assignments
  for all using (can_manage_project(project_id, auth.uid()))
  with check (can_manage_project(project_id, auth.uid()));


-- ==== supabase/migrations/20260824150001_project_wiki_articles_and_kb_detach.sql ====
-- Project-Aware Knowledge and Assistant Context
-- (docs/dev-request-project-aware-knowledge-and-assistant-context.md),
-- Stage 1: project associations and visibility only -- no conversation
-- binding or Assistant retrieval changes yet, those are Stage 2.
--
-- knowledge_bases.project_id already exists and already covers "a project
-- may attach a knowledge base" (one-to-one); the gap closed here is that
-- there was never a UI to attach/detach one after project creation, and
-- wiki_articles had no project-scoping concept at all.

-- Pre-existing RLS bug this feature ran straight into: kb_manage_project_curator
-- (20260810120001_project_members.sql) required project_id is not null in
-- its USING clause, which means a project curator could never target an
-- *unattached* KB in the first place -- attachKnowledgeBaseAction (and the
-- Project Wizard's own "attach an existing KB" step) has been silently
-- rejected by RLS for any non-admin caller since it was written. Fixed to
-- be symmetric: a curator may target a row that's either currently
-- unattached (to attach it) or already theirs (to edit/detach it), and the
-- result must be either detached or attached to a project they curate.
drop policy "kb_manage_project_curator" on knowledge_bases;
create policy "kb_manage_project_curator" on knowledge_bases
  for all using (project_id is null or can_curate_project(project_id, auth.uid()))
  with check (project_id is null or can_curate_project(project_id, auth.uid()));

-- A single column, not a separate wiki_article_scopes table -- matches this
-- app's existing convention for single-value-per-row config (see
-- knowledge_bases.classification/lifecycle_status). Existing articles
-- default to 'platform', matching current de facto behaviour: every
-- approved article is visible to everyone today.
alter table wiki_articles
  add column if not exists visibility_scope text not null default 'platform'
    check (visibility_scope in ('project_private', 'selected_projects', 'organization', 'platform', 'public'));

-- Serves two purposes: it's the allow-list for project_private/
-- selected_projects articles, and it's how a platform-visibility article
-- gets explicitly associated with a project's own Knowledge display without
-- copying it.
create table if not exists project_wiki_articles (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  wiki_article_id uuid not null references wiki_articles(id) on delete cascade,
  relationship text,
  attached_by uuid references profiles(id) on delete set null,
  attached_at timestamptz not null default now(),

  unique (project_id, wiki_article_id)
);

create index if not exists project_wiki_articles_project_id_idx on project_wiki_articles(project_id);
create index if not exists project_wiki_articles_wiki_article_id_idx on project_wiki_articles(wiki_article_id);

alter table project_wiki_articles enable row level security;

create policy "project_wiki_articles_select_member" on project_wiki_articles
  for select using (is_project_member(project_id, auth.uid()));

-- Same bar as workstream_artifacts_insert_consultant: project curators (not
-- just owners) can attach evidence to their own project.
create policy "project_wiki_articles_manage_curator" on project_wiki_articles
  for all using (can_curate_project(project_id, auth.uid()))
  with check (can_curate_project(project_id, auth.uid()));

-- Widen wiki_articles' select policy: an approved, platform/public-visibility
-- article stays visible to everyone (unchanged default behaviour); staff
-- keep full visibility regardless of status/scope (unchanged); a
-- project_private/selected_projects article is now visible only to a
-- member of a project it's explicitly attached to.
drop policy "wiki_articles_select_approved_or_staff" on wiki_articles;
create policy "wiki_articles_select_approved_or_staff" on wiki_articles
  for select using (
    is_curator_or_admin(auth.uid())
    or (status = 'approved' and visibility_scope in ('platform', 'public'))
    or (
      status = 'approved'
      and visibility_scope in ('project_private', 'selected_projects')
      and exists (
        select 1 from project_wiki_articles pwa
        where pwa.wiki_article_id = wiki_articles.id and is_project_member(pwa.project_id, auth.uid())
      )
    )
  );

-- wiki_versions has its own independent select policy (content, not just
-- metadata) -- widening wiki_articles alone would still leave a
-- project-private article's actual approved content directly fetchable by
-- id (e.g. `.from('wiki_versions').select('*').eq('id', ...)`), since the
-- existing policy only checked approved_at, never the parent article's
-- visibility. Joins back through wiki_articles for the same scope check.
drop policy "wiki_versions_select_approved_or_staff" on wiki_versions;
create policy "wiki_versions_select_approved_or_staff" on wiki_versions
  for select using (
    is_curator_or_admin(auth.uid())
    or (
      approved_at is not null
      and exists (
        select 1 from wiki_articles wa
        where wa.id = wiki_versions.wiki_article_id
        and (
          wa.visibility_scope in ('platform', 'public')
          or (
            wa.visibility_scope in ('project_private', 'selected_projects')
            and exists (
              select 1 from project_wiki_articles pwa
              where pwa.wiki_article_id = wa.id and is_project_member(pwa.project_id, auth.uid())
            )
          )
        )
      )
    )
  );


-- ==== supabase/migrations/20260824160001_project_knowledge_visibility_fixes.sql ====
-- Follow-up to 20260824150001_project_wiki_articles_and_kb_detach.sql, fixing
-- four issues raised in review before this feature went any further live.
-- Nothing in production depends on the shapes being changed here yet
-- (verified live: zero knowledge_bases.project_id attachments, zero
-- project_wiki_articles rows), so this is a correction, not a data migration.
--
-- 1. wiki_articles/wiki_versions' select policies gave is_curator_or_admin an
--    unconditional bypass, so any platform curator/admin could read an
--    approved project_private article regardless of project membership --
--    directly contradicting this feature's own live-verification plan
--    ("confirm a non-member curator account cannot see it") and the dev
--    request's explicit requirement that "platform Admin access does not
--    automatically constitute customer authorization." The bypass is now
--    scoped to unapproved content only (the actual reason it existed: so
--    curators can review drafts/pending versions before publication).
--    Emergency admin access to approved private content is intentionally
--    NOT built here -- it needs its own audited path, not a silent bypass.
--
-- 2. `organization` was a selectable visibility_scope value with no
--    organization/membership model behind it (this schema has no
--    organizations table at all). After fix 1 it would become a silent,
--    invisible-to-everyone dead state. Removed until an actual organization
--    boundary exists to enforce it against.
--
-- 3. project_private and selected_projects were identical labels over the
--    same project_wiki_articles junction -- nothing stopped a project_private
--    article from being attached to five projects. Enforced with triggers:
--    project_private allows at most one linked project.
--
-- 4. knowledge_bases.project_id is one-to-one, which cannot express the
--    reuse case this feature exists to support (the same Zadara/Sandz KB
--    serving more than one authorized project) -- and the dev request's own
--    suggested data model calls for project_knowledge_bases explicitly.
--    Added as a real many-to-many junction, matching project_wiki_articles.
--    The legacy column is left in place (dropping it is a separate concern)
--    but Stage 1 code no longer reads or writes it.

-- --- Fix 1: staff bypass scoped to unapproved content only ------------------

drop policy "wiki_articles_select_approved_or_staff" on wiki_articles;
create policy "wiki_articles_select_approved_or_staff" on wiki_articles
  for select using (
    (status <> 'approved' and is_curator_or_admin(auth.uid()))
    or (status = 'approved' and visibility_scope in ('platform', 'public'))
    or (
      status = 'approved'
      and visibility_scope in ('project_private', 'selected_projects')
      and exists (
        select 1 from project_wiki_articles pwa
        where pwa.wiki_article_id = wiki_articles.id and is_project_member(pwa.project_id, auth.uid())
      )
    )
  );

drop policy "wiki_versions_select_approved_or_staff" on wiki_versions;
create policy "wiki_versions_select_approved_or_staff" on wiki_versions
  for select using (
    (approved_at is null and is_curator_or_admin(auth.uid()))
    or (
      approved_at is not null
      and exists (
        select 1 from wiki_articles wa
        where wa.id = wiki_versions.wiki_article_id
        and (
          wa.visibility_scope in ('platform', 'public')
          or (
            wa.visibility_scope in ('project_private', 'selected_projects')
            and exists (
              select 1 from project_wiki_articles pwa
              where pwa.wiki_article_id = wa.id and is_project_member(pwa.project_id, auth.uid())
            )
          )
        )
      )
    )
  );

-- --- Fix 2: defer 'organization' until an org boundary actually exists -----

alter table wiki_articles drop constraint wiki_articles_visibility_scope_check;
alter table wiki_articles add constraint wiki_articles_visibility_scope_check
  check (visibility_scope in ('project_private', 'selected_projects', 'platform', 'public'));

-- --- Fix 3: project_private means exactly one associated project -----------

create or replace function validate_project_wiki_article_link_scope()
returns trigger language plpgsql set search_path = public as $$
declare
  scope text;
  existing_links int;
begin
  select visibility_scope into scope from wiki_articles where id = new.wiki_article_id;
  if scope = 'project_private' then
    select count(*) into existing_links from project_wiki_articles where wiki_article_id = new.wiki_article_id;
    if existing_links >= 1 then
      raise exception 'A project_private Wiki article may be attached to only one project -- use selected_projects to attach it to more than one';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists project_wiki_articles_validate_scope on project_wiki_articles;
create trigger project_wiki_articles_validate_scope
  before insert on project_wiki_articles
  for each row execute function validate_project_wiki_article_link_scope();

create or replace function validate_wiki_article_scope_change()
returns trigger language plpgsql set search_path = public as $$
declare
  linked_projects int;
begin
  if new.visibility_scope = 'project_private' and old.visibility_scope is distinct from new.visibility_scope then
    select count(*) into linked_projects from project_wiki_articles where wiki_article_id = new.id;
    if linked_projects > 1 then
      raise exception 'Cannot set visibility to project_private while attached to % projects -- detach down to one first', linked_projects;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists wiki_articles_validate_scope_change on wiki_articles;
create trigger wiki_articles_validate_scope_change
  before update of visibility_scope on wiki_articles
  for each row execute function validate_wiki_article_scope_change();

-- --- Fix 4: knowledge base <-> project becomes many-to-many ----------------

create table if not exists project_knowledge_bases (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  knowledge_base_id text not null references knowledge_bases(id) on delete cascade,
  purpose text,
  attached_by uuid references profiles(id) on delete set null,
  attached_at timestamptz not null default now(),

  unique (project_id, knowledge_base_id)
);

create index if not exists project_knowledge_bases_project_id_idx on project_knowledge_bases(project_id);
create index if not exists project_knowledge_bases_kb_id_idx on project_knowledge_bases(knowledge_base_id);

alter table project_knowledge_bases enable row level security;

create policy "project_knowledge_bases_select_member" on project_knowledge_bases
  for select using (is_project_member(project_id, auth.uid()));

-- Same bar as project_wiki_articles_manage_curator: project curators (not
-- just owners) can attach or detach knowledge for their own project.
create policy "project_knowledge_bases_manage_curator" on project_knowledge_bases
  for all using (can_curate_project(project_id, auth.uid()))
  with check (can_curate_project(project_id, auth.uid()));

-- Same rule as the legacy knowledge_bases_active_project_attachment trigger
-- (20260824120001_knowledge_base_classification.sql), re-enforced on the new
-- write path: only an active KB may be attached to a project.
create or replace function validate_project_kb_attachment_active()
returns trigger language plpgsql set search_path = public as $$
begin
  perform require_active_knowledge_base(new.knowledge_base_id);
  return new;
end;
$$;

drop trigger if exists project_knowledge_bases_require_active_kb on project_knowledge_bases;
create trigger project_knowledge_bases_require_active_kb
  before insert or update of knowledge_base_id on project_knowledge_bases
  for each row execute function validate_project_kb_attachment_active();

-- No-op safety net: no knowledge_bases.project_id attachment exists in
-- production as of this migration, but this keeps a future environment that
-- does have one from silently losing it.
insert into project_knowledge_bases (project_id, knowledge_base_id, attached_at)
select project_id, id, coalesce(updated_at, now())
from knowledge_bases
where project_id is not null
on conflict (project_id, knowledge_base_id) do nothing;


-- ==== supabase/migrations/20260824170001_project_wiki_strict_membership.sql ====
-- Second-order instance of the same issue fixed in
-- 20260824160001_project_knowledge_visibility_fixes.sql (fix 1): the
-- confidentiality-gating policies on wiki_articles/wiki_versions/
-- project_wiki_articles/project_knowledge_bases all check membership via
-- is_project_member(), which itself is `is_admin(uid) or <real membership>`
-- (20260810120001_project_members.sql) -- a deliberate convenience for
-- general project navigation (an admin can open any project page), but it
-- silently defeats the fix in 160001 for admins specifically: every platform
-- admin still passes as "a member" of every project, so an approved
-- project_private article stayed readable by any admin regardless of real
-- membership. Caught during this feature's own live-verification pass,
-- before testing "platform Admin without project business authority" per
-- the dev request's required test roles.
--
-- Introduces a strict membership check (real project_members row only, no
-- admin bypass) and uses it specifically where confidential content is
-- gated. can_curate_project/can_manage_project (used by the *manage*
-- policies -- attaching/detaching a KB or article) intentionally keep their
-- admin bypass: administering an association is a different, lower-stakes
-- capability than silently reading confidential content, and platform
-- admins legitimately need to manage any project's associations.

create or replace function is_project_member_strict(pid uuid, uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from project_members pm where pm.project_id = pid and pm.user_id = uid and pm.status = 'active'
  );
$$;

drop policy "project_wiki_articles_select_member" on project_wiki_articles;
create policy "project_wiki_articles_select_member" on project_wiki_articles
  for select using (is_project_member_strict(project_id, auth.uid()));

drop policy "project_knowledge_bases_select_member" on project_knowledge_bases;
create policy "project_knowledge_bases_select_member" on project_knowledge_bases
  for select using (is_project_member_strict(project_id, auth.uid()));

drop policy "wiki_articles_select_approved_or_staff" on wiki_articles;
create policy "wiki_articles_select_approved_or_staff" on wiki_articles
  for select using (
    (status <> 'approved' and is_curator_or_admin(auth.uid()))
    or (status = 'approved' and visibility_scope in ('platform', 'public'))
    or (
      status = 'approved'
      and visibility_scope in ('project_private', 'selected_projects')
      and exists (
        select 1 from project_wiki_articles pwa
        where pwa.wiki_article_id = wiki_articles.id and is_project_member_strict(pwa.project_id, auth.uid())
      )
    )
  );

drop policy "wiki_versions_select_approved_or_staff" on wiki_versions;
create policy "wiki_versions_select_approved_or_staff" on wiki_versions
  for select using (
    (approved_at is null and is_curator_or_admin(auth.uid()))
    or (
      approved_at is not null
      and exists (
        select 1 from wiki_articles wa
        where wa.id = wiki_versions.wiki_article_id
        and (
          wa.visibility_scope in ('platform', 'public')
          or (
            wa.visibility_scope in ('project_private', 'selected_projects')
            and exists (
              select 1 from project_wiki_articles pwa
              where pwa.wiki_article_id = wa.id and is_project_member_strict(pwa.project_id, auth.uid())
            )
          )
        )
      )
    )
  );


-- ==== supabase/migrations/20260824180001_project_knowledge_visibility_retrieval_fix.sql ====
-- Project-Aware Knowledge and Assistant Context, Stage 2, Migration A --
-- close two retrieval-layer leaks discovered while researching Stage 2,
-- sent standalone and first because they undermine Stage 1's confidentiality
-- work in production right now, before any new project-aware retrieval is
-- built on top of them.
--
-- 1. match_wiki_vectors (20260809110003_match_wiki_vectors.sql) is a plain
--    `language sql stable` function, not security definer, so it runs under
--    the CALLER's own RLS -- but wiki_vectors_select_consultant
--    (20260810100006_consultant_vector_read_access.sql) grants SELECT to any
--    active consultant unconditionally, with no join back to
--    wiki_articles.status/visibility_scope at all. Every authenticated user
--    defaults to role 'consultant'. Concretely: any user, via the
--    Assistant's search_wiki tool, can retrieve the full embedded content of
--    the approved "Zadara Knowledge Copilot" article right now even though
--    it's project_private and they are not a project member -- the exact
--    leak Stage 1 was built to close, one layer down. Fixed by mirroring
--    wiki_versions_select_approved_or_staff's join/visibility check exactly.
--
-- 2. kb_select_global_or_member (20260810120001_project_members.sql) reads
--    `project_id is null or is_project_member(project_id, auth.uid())` --
--    but Stage 1 stopped writing knowledge_bases.project_id in favor of the
--    new project_knowledge_bases junction, so project_id is null for every
--    knowledge base including the now-attached Zadara/Sandz one, making this
--    policy permanently permissive. kb_vectors_select_consultant has the
--    identical unconditional-consultant-access shape as
--    wiki_vectors_select_consultant. Knowledge bases have no visibility
--    concept at all today (classification is a category tag, not access
--    control). Fixed by adding knowledge_bases.visibility_scope (same
--    convention as wiki_articles.visibility_scope) and rewriting both
--    policies to check it via project_knowledge_bases + is_project_member_strict.
--
-- Also widens knowledge_sources/documents' own select policies with a
-- project-member branch -- needed so citation resolution and the Stage 2
-- source-detail page can read the row itself, not just the embedded chunk.

-- --- knowledge_bases visibility_scope --------------------------------------

alter table knowledge_bases
  add column if not exists visibility_scope text not null default 'platform'
    check (visibility_scope in ('project_private', 'selected_projects', 'platform', 'public'));

-- The one knowledge base with real customer-confidential content today;
-- every other knowledge base defaults to 'platform', matching current de
-- facto behaviour (same backfill philosophy as Stage 1's Wiki migration).
update knowledge_bases set visibility_scope = 'project_private' where id = 'zadara_sandz';

drop policy "kb_select_global_or_member" on knowledge_bases;
create policy "kb_select_global_or_member" on knowledge_bases
  for select using (
    is_admin(auth.uid())
    or visibility_scope in ('platform', 'public')
    or (
      visibility_scope in ('project_private', 'selected_projects')
      and exists (
        select 1 from project_knowledge_bases pkb
        where pkb.knowledge_base_id = knowledge_bases.id and is_project_member_strict(pkb.project_id, auth.uid())
      )
    )
  );

-- --- wiki_vectors: mirrors wiki_versions_select_approved_or_staff's join ---

drop policy "wiki_vectors_select_consultant" on wiki_vectors;
create policy "wiki_vectors_select_scoped" on wiki_vectors
  for select using (
    exists (
      select 1 from wiki_articles wa
      where wa.current_version_id = wiki_vectors.wiki_version_id
      and (
        (wa.status <> 'approved' and is_curator_or_admin(auth.uid()))
        or (wa.status = 'approved' and wa.visibility_scope in ('platform', 'public'))
        or (
          wa.status = 'approved'
          and wa.visibility_scope in ('project_private', 'selected_projects')
          and exists (
            select 1 from project_wiki_articles pwa
            where pwa.wiki_article_id = wa.id and is_project_member_strict(pwa.project_id, auth.uid())
          )
        )
      )
    )
  );

-- --- kb_vectors: same shape, joined through documents -> knowledge_sources -> knowledge_bases

drop policy "kb_vectors_select_consultant" on kb_vectors;
create policy "kb_vectors_select_scoped" on kb_vectors
  for select using (
    is_curator_or_admin(auth.uid())
    or exists (
      select 1 from documents d
      join knowledge_sources ks on ks.current_version_id = d.id
      join knowledge_bases kb on kb.id = ks.knowledge_base_id
      where d.id = kb_vectors.document_id
      and (
        kb.visibility_scope in ('platform', 'public')
        or (
          kb.visibility_scope in ('project_private', 'selected_projects')
          and exists (
            select 1 from project_knowledge_bases pkb
            where pkb.knowledge_base_id = kb.id and is_project_member_strict(pkb.project_id, auth.uid())
          )
        )
      )
    )
  );

-- --- knowledge_sources / documents: add a project-member read branch ------

drop policy "knowledge_sources_select_staff_or_owner" on knowledge_sources;
create policy "knowledge_sources_select_staff_or_owner_or_project_member" on knowledge_sources
  for select using (
    is_curator_or_admin(auth.uid())
    or created_by = auth.uid()
    or exists (
      select 1 from knowledge_bases kb
      where kb.id = knowledge_sources.knowledge_base_id
      and (
        kb.visibility_scope in ('platform', 'public')
        or (
          kb.visibility_scope in ('project_private', 'selected_projects')
          and exists (
            select 1 from project_knowledge_bases pkb
            where pkb.knowledge_base_id = kb.id and is_project_member_strict(pkb.project_id, auth.uid())
          )
        )
      )
    )
  );

drop policy "documents_select_staff_or_owner" on documents;
create policy "documents_select_staff_or_owner_or_project_member" on documents
  for select using (
    is_curator_or_admin(auth.uid())
    or uploaded_by = auth.uid()
    or exists (
      select 1 from knowledge_sources ks
      join knowledge_bases kb on kb.id = ks.knowledge_base_id
      where ks.id = documents.knowledge_source_id
      and (
        kb.visibility_scope in ('platform', 'public')
        or (
          kb.visibility_scope in ('project_private', 'selected_projects')
          and exists (
            select 1 from project_knowledge_bases pkb
            where pkb.knowledge_base_id = kb.id and is_project_member_strict(pkb.project_id, auth.uid())
          )
        )
      )
    )
  );


-- ==== supabase/migrations/20260824190001_conversations_project_binding.sql ====
-- Project-Aware Knowledge and Assistant Context, Stage 2: bind a
-- conversation to a project. Nullable -- a general/unbound conversation
-- (project_id null) keeps working exactly as today.
--
-- Immutable once set: a conversation is either general forever, or bound to
-- one project forever. "Changing project context" per the dev request means
-- starting a new conversation, not re-pointing an existing one -- so there's
-- no "transition" action to build; this trigger is the DB-level guarantee
-- that nothing can silently blend two projects' histories into one
-- conversation, by construction rather than by every caller remembering not
-- to.
--
-- conversations_owner/chat_messages_owner RLS (20260818120001_chat_assistant.sql)
-- is deliberately unchanged -- project_id is just a categorization column on
-- the user's own conversation, and nothing in this stage asks for a project
-- curator to see a teammate's chat history.

alter table conversations add column project_id uuid references projects(id) on delete set null;
create index conversations_project_id_idx on conversations(project_id);

create or replace function validate_conversation_project_id_immutable()
returns trigger language plpgsql as $$
begin
  if old.project_id is not null and new.project_id is distinct from old.project_id then
    raise exception 'conversations.project_id cannot be changed once set -- start a new conversation instead';
  end if;
  return new;
end;
$$;

create trigger conversations_project_id_immutable
  before update of project_id on conversations
  for each row execute function validate_conversation_project_id_immutable();

-- Durable "turn in progress" marker so a page refresh mid-turn doesn't lose
-- track of a pending reply -- set at turn start, cleared when the turn
-- resolves either way. Stale (old) values are treated as abandoned by the
-- client, not polled forever; see src/components/chat/ChatPanel.tsx.
alter table conversations add column pending_turn_started_at timestamptz;


-- ==== supabase/migrations/20260824200001_kb_vectors_remove_stray_bypass.sql ====
-- Follow-up to 20260824180001_project_knowledge_visibility_retrieval_fix.sql,
-- caught during this stage's own live-verification pass, before testing
-- curator/admin accounts against the Zadara private content.
--
-- kb_vectors_select_scoped was written with an unconditional
-- `is_curator_or_admin(auth.uid()) or ...` bypass -- the exact leak shape
-- this whole migration exists to close, reintroduced for the actual
-- confidential chunk content, and inconsistent with the sibling
-- wiki_vectors_select_scoped policy in the same file (which correctly
-- scopes its own staff bypass to `status <> 'approved'` only, for
-- legitimate pre-publication review). kb_vectors has no equivalent draft
-- state to justify any bypass at all: it only ever contains chunks that
-- were already curator-approved by construction (see
-- 20260810100006_consultant_vector_read_access.sql's own comment, quoted in
-- 20260824180001's header) -- so the correct policy has zero unconditional
-- branches, full stop.

drop policy "kb_vectors_select_scoped" on kb_vectors;
create policy "kb_vectors_select_scoped" on kb_vectors
  for select using (
    exists (
      select 1 from documents d
      join knowledge_sources ks on ks.current_version_id = d.id
      join knowledge_bases kb on kb.id = ks.knowledge_base_id
      where d.id = kb_vectors.document_id
      and (
        kb.visibility_scope in ('platform', 'public')
        or (
          kb.visibility_scope in ('project_private', 'selected_projects')
          and exists (
            select 1 from project_knowledge_bases pkb
            where pkb.knowledge_base_id = kb.id and is_project_member_strict(pkb.project_id, auth.uid())
          )
        )
      )
    )
  );


-- ==== supabase/migrations/20260824210001_project_junction_manage_policies_no_select_leak.sql ====
-- Caught live, testing a non-member platform admin against the new
-- /sources/[id] page (Project-Aware Knowledge and Assistant Context,
-- Stage 2): project_knowledge_bases_manage_curator and
-- project_wiki_articles_manage_curator (Stage 1,
-- 20260824150001_project_wiki_articles_and_kb_detach.sql and
-- 20260824160001_project_knowledge_visibility_fixes.sql) are both
-- `for all using (can_curate_project(project_id, auth.uid()))` -- and
-- can_curate_project has its own `is_admin(uid) or ...` bypass. Postgres
-- combines multiple permissive policies with OR, so this FOR ALL policy
-- doesn't just grant admin/curator the ability to attach/detach (its actual
-- purpose) -- it also incidentally grants them unrestricted SELECT on the
-- junction table, for any project, regardless of real membership. That
-- defeated /sources/[id]'s own access check, which relied on
-- project_knowledge_bases' default RLS-filtered SELECT as its strict-
-- membership gate: a platform admin with no real membership row could
-- still see the junction row (via the FOR ALL bypass) and reach a
-- project_private source's metadata page.
--
-- Fixed by splitting each FOR ALL policy into INSERT/DELETE only -- the
-- only two operations either write path ever performs (attach = insert,
-- detach = delete; neither table is ever updated in place) -- so SELECT is
-- governed solely by *_select_member (is_project_member_strict, no
-- bypass), exactly as intended.

drop policy "project_wiki_articles_manage_curator" on project_wiki_articles;
create policy "project_wiki_articles_insert_curator" on project_wiki_articles
  for insert with check (can_curate_project(project_id, auth.uid()));
create policy "project_wiki_articles_delete_curator" on project_wiki_articles
  for delete using (can_curate_project(project_id, auth.uid()));

drop policy "project_knowledge_bases_manage_curator" on project_knowledge_bases;
create policy "project_knowledge_bases_insert_curator" on project_knowledge_bases
  for insert with check (can_curate_project(project_id, auth.uid()));
create policy "project_knowledge_bases_delete_curator" on project_knowledge_bases
  for delete using (can_curate_project(project_id, auth.uid()));


-- ==== supabase/migrations/20260825100001_project_evidence_access_schema.sql ====
-- Project Evidence Access Controls, Stage 1
-- (docs/dev-request-project-evidence-access-controls.md). Pilot security
-- requirement: project membership currently means "can see every attached
-- source" -- too broad once a client project mixes vendor documentation
-- (whole-team readable) with customer pricing/margins/contracts (readable
-- only by specific people). This migration adds the access model itself;
-- enforcement (AND-gating it into existing retrieval RLS) is the next
-- migration, 20260825110001_project_evidence_access_enforcement.sql.
--
-- Deliberately keeps project role, business function (project_members'
-- existing column from 20260824140001_project_governance.sql), evidence
-- access (this migration), and approval authority (project_authority_
-- assignments) as four independent concepts, per the dev request's own
-- product principle: none of these should silently grant another. No
-- `lead` project role added here -- that's a separate, related change the
-- dev request explicitly doesn't require for this feature; Stage 1's access
-- model only needs the existing owner role to manage groups/grants.
--
-- Confirmed with the user before implementing: no automatic owner bypass.
-- The project owner does not silently see restricted evidence just by
-- owning the project -- they hold access the same explicit way anyone else
-- does (they can always grant themselves one, since they control grants).
-- has_evidence_access() (next migration) has zero bypass for anyone, same
-- shape as is_project_member_strict().

-- project_access_groups -----------------------------------------------------
-- No DB-seeded default rows per project (most projects will never need
-- this) -- the UI offers the dev request's suggested names
-- (sales_commercial, finance_pricing, technical_delivery,
-- security_compliance, customer_visible, named_users_only) as one-click
-- presets when a project owner creates a group, not forced rows.
create table project_access_groups (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  name text not null,
  description text,
  is_system_group boolean not null default false,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  unique (project_id, name)
);

create index if not exists project_access_groups_project_id_idx on project_access_groups(project_id);

create trigger project_access_groups_set_updated_at before update on project_access_groups
  for each row execute function set_updated_at();

-- project_access_group_members -----------------------------------------------
-- Revoking flips status + revoked_by/at/reason on the existing row (never
-- deleted) -- same convention as project_authority_assignments. Re-granting
-- after a revoke inserts a fresh row rather than reactivating the old one,
-- so the full grant/revoke history is always intact without a separate
-- audit table for this part of the model.
create table project_access_group_members (
  id uuid primary key default gen_random_uuid(),
  project_access_group_id uuid not null references project_access_groups(id) on delete cascade,
  project_member_id uuid not null references project_members(id) on delete cascade,
  effective_from timestamptz not null default now(),
  expires_at timestamptz,
  status text not null default 'active' check (status in ('active', 'revoked')),
  granted_by uuid references profiles(id) on delete set null,
  granted_at timestamptz not null default now(),
  revoked_by uuid references profiles(id) on delete set null,
  revoked_at timestamptz,
  revocation_reason text
);

create index if not exists project_access_group_members_group_id_idx on project_access_group_members(project_access_group_id);
create index if not exists project_access_group_members_member_id_idx on project_access_group_members(project_member_id);

-- resource_access_policies ---------------------------------------------------
-- A resource with NO row here behaves exactly as it does today -- the key
-- backward-compat property. "No policy row" is the implicit project_general
-- default; a row is only ever created when someone deliberately restricts
-- something, so zero migration/backfill is needed for existing content.
-- resource_id is always the *stable* identity (knowledge_sources.id, never
-- documents.id) per the dev request's own note about inheriting through the
-- stable source/version relationship rather than copying access onto every
-- chunk.
create table resource_access_policies (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  resource_type text not null check (resource_type in ('knowledge_source', 'wiki_article', 'workstream_artifact')),
  resource_id uuid not null,
  classification text not null check (classification in (
    'project_general', 'internal_confidential', 'commercial_confidential',
    'security_restricted', 'customer_confidential', 'customer_visible'
  )),
  access_steward_user_id uuid references profiles(id) on delete set null,
  review_at timestamptz,
  rationale text,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  unique (resource_type, resource_id)
);

create index if not exists resource_access_policies_project_id_idx on resource_access_policies(project_id);

create trigger resource_access_policies_set_updated_at before update on resource_access_policies
  for each row execute function set_updated_at();

-- resource_access_grants -----------------------------------------------------
-- Exactly one of project_access_group_id / project_member_id is set --
-- either a whole access group is granted, or one named user is (used
-- sparingly, per the dev request: "groups are easier to review and
-- maintain"). Same revoke-in-place / re-grant-as-new-row convention as
-- project_access_group_members.
create table resource_access_grants (
  id uuid primary key default gen_random_uuid(),
  resource_access_policy_id uuid not null references resource_access_policies(id) on delete cascade,
  project_access_group_id uuid references project_access_groups(id) on delete cascade,
  project_member_id uuid references project_members(id) on delete cascade,
  status text not null default 'active' check (status in ('active', 'revoked')),
  granted_by uuid references profiles(id) on delete set null,
  granted_at timestamptz not null default now(),
  revoked_by uuid references profiles(id) on delete set null,
  revoked_at timestamptz,
  revocation_reason text,

  constraint resource_access_grants_exactly_one_grantee check (
    (project_access_group_id is not null and project_member_id is null)
    or (project_access_group_id is null and project_member_id is not null)
  )
);

create index if not exists resource_access_grants_policy_id_idx on resource_access_grants(resource_access_policy_id);

-- resource_access_audit_log --------------------------------------------------
-- The one thing the append-only-by-convention tables above don't cover:
-- resource_access_policies.classification is a mutable field on a
-- unique-per-resource row, so reclassifying in place would otherwise lose
-- history. Insert-only, no update/delete policy at all, no client insert
-- policy either -- same "no client insert path, written via the admin
-- client from the service layer" shape as ai_operation_logs
-- (src/lib/ai/logging.ts), so RLS can't be bypassed by a forged direct
-- insert. Never stores evidence content, only which resource/who/when/what
-- classification, per the dev request's "audit access must itself be
-- restricted" and "avoid recording sensitive evidence in audit messages."
create table resource_access_audit_log (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  event_type text not null check (event_type in (
    'resource_classified', 'resource_reclassified',
    'group_created', 'group_member_granted', 'group_member_revoked',
    'resource_grant_granted', 'resource_grant_revoked'
  )),
  resource_type text,
  resource_id uuid,
  actor_id uuid references profiles(id) on delete set null,
  from_classification text,
  to_classification text,
  target_group_id uuid,
  target_member_id uuid,
  created_at timestamptz not null default now()
);

create index if not exists resource_access_audit_log_project_id_idx on resource_access_audit_log(project_id);

-- RLS -------------------------------------------------------------------------
-- All five tables: visible/manageable only by can_manage_project (project
-- owner, or platform admin via that function's existing bypass). This is
-- governance metadata *about* evidence -- which sources are restricted, to
-- whom -- not the evidence content itself, consistent with admin already
-- being able to see e.g. which knowledge bases/articles are attached to a
-- project. The content gate (has_evidence_access, next migration) has zero
-- admin bypass; this administrative visibility does not affect that.
--
-- Select and manage share the exact same authorization boundary here
-- (unlike the wiki/KB junction tables, which deliberately split a strict
-- member-only select from a bypass-allowed manage policy) -- a single FOR
-- ALL policy per table is sufficient and avoids the "combined policy leaks
-- SELECT via OR" trap from 20260824210001, since there's only one policy to
-- begin with.

alter table project_access_groups enable row level security;
create policy "project_access_groups_manage_owner" on project_access_groups
  for all using (can_manage_project(project_id, auth.uid()))
  with check (can_manage_project(project_id, auth.uid()));

alter table project_access_group_members enable row level security;
create policy "project_access_group_members_manage_owner" on project_access_group_members
  for all using (
    exists (
      select 1 from project_access_groups g
      where g.id = project_access_group_members.project_access_group_id and can_manage_project(g.project_id, auth.uid())
    )
  )
  with check (
    exists (
      select 1 from project_access_groups g
      where g.id = project_access_group_members.project_access_group_id and can_manage_project(g.project_id, auth.uid())
    )
  );

alter table resource_access_policies enable row level security;
create policy "resource_access_policies_manage_owner" on resource_access_policies
  for all using (can_manage_project(project_id, auth.uid()))
  with check (can_manage_project(project_id, auth.uid()));

alter table resource_access_grants enable row level security;
create policy "resource_access_grants_manage_owner" on resource_access_grants
  for all using (
    exists (
      select 1 from resource_access_policies p
      where p.id = resource_access_grants.resource_access_policy_id and can_manage_project(p.project_id, auth.uid())
    )
  )
  with check (
    exists (
      select 1 from resource_access_policies p
      where p.id = resource_access_grants.resource_access_policy_id and can_manage_project(p.project_id, auth.uid())
    )
  );

alter table resource_access_audit_log enable row level security;
create policy "resource_access_audit_log_select_owner" on resource_access_audit_log
  for select using (can_manage_project(project_id, auth.uid()));
-- No insert/update/delete policy -- written only via the admin client from
-- the service layer (src/lib/projects/evidence-access.ts).


-- ==== supabase/migrations/20260825110001_project_evidence_access_enforcement.sql ====
-- Project Evidence Access Controls, Stage 1 -- enforcement half. Adds
-- has_evidence_access(), the same "zero bypass for anyone" shape as
-- is_project_member_strict() (20260824170001_project_wiki_strict_membership.sql),
-- and ANDs it into every existing SELECT policy that can currently expose
-- project evidence: knowledge_sources, documents, kb_vectors, wiki_articles,
-- wiki_versions, wiki_vectors, workstream_artifacts.
--
-- has_evidence_access() returns true when a resource has NO
-- resource_access_policies row at all -- so for the 60+ existing Wiki
-- articles and every currently-attached source, this AND-gate is a no-op:
-- behavior is byte-for-byte identical to today unless someone has
-- deliberately classified a specific resource. No backfill needed.
--
-- match_documents/match_wiki_vectors (the RPCs the Assistant and eval use)
-- are plain `language sql stable` functions, not security definer, so they
-- run under the caller's own RLS -- extending kb_vectors_select_scoped and
-- wiki_vectors_select_scoped here is sufficient to filter Assistant/eval
-- retrieval "within the database query, not after text is returned" per
-- the dev request's own requirement. No application code changes needed in
-- src/lib/chat/project-knowledge-tool.ts or src/lib/eval/retrieval.ts.
--
-- This also closes the citation-navigation gap noted in
-- src/app/(app)/sources/[id]/page.tsx's own comment about
-- src/lib/chat/navigation-resolver.ts trusting knowledge_sources' RLS alone
-- for the knowledge_source case -- once RLS itself carries this gate, that
-- code path is covered with no application change.

-- `classification = 'project_general'` is treated identically to "no policy
-- row at all" in both branches below -- project_general is an explicit,
-- selectable classification (matches the dev request's suggested list), not
-- just the absence of a row, and it must mean "open to the project" either
-- way. Only a *non*-general classification ever requires an active grant.
create or replace function has_evidence_access(p_resource_type text, p_resource_id uuid, uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select not exists (
    select 1 from resource_access_policies rap
    where rap.resource_type = p_resource_type and rap.resource_id = p_resource_id
    and rap.classification <> 'project_general'
  )
  or exists (
    select 1
    from resource_access_policies rap
    join resource_access_grants g on g.resource_access_policy_id = rap.id and g.status = 'active'
    left join project_access_group_members gm
      on gm.project_access_group_id = g.project_access_group_id
      and gm.status = 'active'
      and (gm.expires_at is null or gm.expires_at > now())
    left join project_members pm_group on pm_group.id = gm.project_member_id and pm_group.status = 'active'
    left join project_members pm_named on pm_named.id = g.project_member_id and pm_named.status = 'active'
    where rap.resource_type = p_resource_type and rap.resource_id = p_resource_id
      and rap.classification <> 'project_general'
      and (pm_group.user_id = uid or pm_named.user_id = uid)
  );
$$;

-- --- knowledge_sources -------------------------------------------------------
-- Wraps the ENTIRE existing condition, including the curator/admin and
-- created_by bypass branches -- a restricted source is restricted for
-- everyone without an explicit grant, full stop, including its own
-- uploader/creator (who classifies it should grant themselves/their group
-- in the same action -- see classifyResource in
-- src/lib/projects/evidence-access.ts).

drop policy "knowledge_sources_select_staff_or_owner_or_project_member" on knowledge_sources;
create policy "knowledge_sources_select_staff_or_owner_or_project_member" on knowledge_sources
  for select using (
    has_evidence_access('knowledge_source', knowledge_sources.id, auth.uid())
    and (
      is_curator_or_admin(auth.uid())
      or created_by = auth.uid()
      or exists (
        select 1 from knowledge_bases kb
        where kb.id = knowledge_sources.knowledge_base_id
        and (
          kb.visibility_scope in ('platform', 'public')
          or (
            kb.visibility_scope in ('project_private', 'selected_projects')
            and exists (
              select 1 from project_knowledge_bases pkb
              where pkb.knowledge_base_id = kb.id and is_project_member_strict(pkb.project_id, auth.uid())
            )
          )
        )
      )
    )
  );

-- --- documents ---------------------------------------------------------------
-- resource_id is the stable knowledge_source, not the versioned document --
-- classification/grants apply to every version of a source uniformly.

drop policy "documents_select_staff_or_owner_or_project_member" on documents;
create policy "documents_select_staff_or_owner_or_project_member" on documents
  for select using (
    has_evidence_access('knowledge_source', documents.knowledge_source_id, auth.uid())
    and (
      is_curator_or_admin(auth.uid())
      or uploaded_by = auth.uid()
      or exists (
        select 1 from knowledge_sources ks
        join knowledge_bases kb on kb.id = ks.knowledge_base_id
        where ks.id = documents.knowledge_source_id
        and (
          kb.visibility_scope in ('platform', 'public')
          or (
            kb.visibility_scope in ('project_private', 'selected_projects')
            and exists (
              select 1 from project_knowledge_bases pkb
              where pkb.knowledge_base_id = kb.id and is_project_member_strict(pkb.project_id, auth.uid())
            )
          )
        )
      )
    )
  );

-- --- kb_vectors ----------------------------------------------------------------
-- Already has zero unconditional bypass (20260824200001) -- just wraps the
-- whole thing. This is the actual retrieval-time gate for the Assistant's
-- search_project_knowledge tool and eval's retrieveEvidence, via
-- match_documents.

drop policy "kb_vectors_select_scoped" on kb_vectors;
create policy "kb_vectors_select_scoped" on kb_vectors
  for select using (
    exists (
      select 1 from documents d
      join knowledge_sources ks on ks.current_version_id = d.id
      join knowledge_bases kb on kb.id = ks.knowledge_base_id
      where d.id = kb_vectors.document_id
      and has_evidence_access('knowledge_source', ks.id, auth.uid())
      and (
        kb.visibility_scope in ('platform', 'public')
        or (
          kb.visibility_scope in ('project_private', 'selected_projects')
          and exists (
            select 1 from project_knowledge_bases pkb
            where pkb.knowledge_base_id = kb.id and is_project_member_strict(pkb.project_id, auth.uid())
          )
        )
      )
    )
  );

-- --- wiki_articles / wiki_versions / wiki_vectors -----------------------------
-- Wraps the whole condition including the unapproved-draft curator/admin
-- bypass -- a restricted article stays restricted even under review.

drop policy "wiki_articles_select_approved_or_staff" on wiki_articles;
create policy "wiki_articles_select_approved_or_staff" on wiki_articles
  for select using (
    has_evidence_access('wiki_article', wiki_articles.id, auth.uid())
    and (
      (status <> 'approved' and is_curator_or_admin(auth.uid()))
      or (status = 'approved' and visibility_scope in ('platform', 'public'))
      or (
        status = 'approved'
        and visibility_scope in ('project_private', 'selected_projects')
        and exists (
          select 1 from project_wiki_articles pwa
          where pwa.wiki_article_id = wiki_articles.id and is_project_member_strict(pwa.project_id, auth.uid())
        )
      )
    )
  );

drop policy "wiki_versions_select_approved_or_staff" on wiki_versions;
create policy "wiki_versions_select_approved_or_staff" on wiki_versions
  for select using (
    has_evidence_access('wiki_article', wiki_versions.wiki_article_id, auth.uid())
    and (
      (approved_at is null and is_curator_or_admin(auth.uid()))
      or (
        approved_at is not null
        and exists (
          select 1 from wiki_articles wa
          where wa.id = wiki_versions.wiki_article_id
          and (
            wa.visibility_scope in ('platform', 'public')
            or (
              wa.visibility_scope in ('project_private', 'selected_projects')
              and exists (
                select 1 from project_wiki_articles pwa
                where pwa.wiki_article_id = wa.id and is_project_member_strict(pwa.project_id, auth.uid())
              )
            )
          )
        )
      )
    )
  );

drop policy "wiki_vectors_select_scoped" on wiki_vectors;
create policy "wiki_vectors_select_scoped" on wiki_vectors
  for select using (
    exists (
      select 1 from wiki_articles wa
      where wa.current_version_id = wiki_vectors.wiki_version_id
      and has_evidence_access('wiki_article', wa.id, auth.uid())
      and (
        (wa.status <> 'approved' and is_curator_or_admin(auth.uid()))
        or (wa.status = 'approved' and wa.visibility_scope in ('platform', 'public'))
        or (
          wa.status = 'approved'
          and wa.visibility_scope in ('project_private', 'selected_projects')
          and exists (
            select 1 from project_wiki_articles pwa
            where pwa.wiki_article_id = wa.id and is_project_member_strict(pwa.project_id, auth.uid())
          )
        )
      )
    )
  );

-- --- workstream_artifacts ------------------------------------------------------
-- Two fixes at once: swap the non-strict is_project_member (admin bypass)
-- for is_project_member_strict, closing a pre-existing inconsistency (every
-- other project-scoped table was already tightened, this one was never
-- revisited) -- and AND in has_evidence_access for the new access-group
-- gate.

drop policy "workstream_artifacts_select_member" on workstream_artifacts;
create policy "workstream_artifacts_select_member" on workstream_artifacts
  for select using (
    has_evidence_access('workstream_artifact', workstream_artifacts.id, auth.uid())
    and exists (
      select 1 from project_workstreams w
      where w.id = workstream_artifacts.workstream_id and is_project_member_strict(w.project_id, auth.uid())
    )
  );


-- ==== supabase/migrations/20260825120001_owner_feedback_board.sql ====
-- Owner Roadmap and Ember Feedback Board, Phase 1
-- (docs/dev-request-owner-roadmap-and-ember-feedback-board.md). One private
-- board where pilot users report bugs/improvements/feature requests
-- conversationally through Ember, and two specific owner identities triage
-- them -- explicitly not via the existing platform admin/curator roles.

-- platform_owners ------------------------------------------------------------
-- A new, deliberately narrow authorization concept, independent of
-- profiles.role. Seeded with the two authorized identities below; safe/
-- idempotent if either account doesn't exist yet at migration time (simply
-- not seeded -- add later the same way scripts/create-mike-admin.mjs
-- bootstraps accounts). "Design the owner allowlist so it can later move to
-- a governed owner role or membership table without rewriting board
-- records" (dev request) is satisfied by keeping this a table + function
-- checked at read/write time, never denormalized onto feedback_reports rows.
create table platform_owners (
  user_id uuid primary key references profiles(id) on delete cascade,
  email text not null,
  added_by uuid references profiles(id) on delete set null,
  added_at timestamptz not null default now()
);

insert into platform_owners (user_id, email, added_by, added_at)
select id, email, id, now() from profiles where email in ('mike.aguilar@gmail.com', 'mikecolligodata@gmail.com')
on conflict (user_id) do nothing;

-- Deliberately NO is_admin(uid) OR ... bypass, unlike every other helper
-- function in this schema -- "platform admin status alone does not grant
-- owner-board access" (dev request, Guardrails). Same shape as is_admin/
-- is_curator_or_admin (20260808190009_functions.sql) otherwise.
create or replace function is_platform_owner(uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from platform_owners where user_id = uid);
$$;

alter table platform_owners enable row level security;
create policy "platform_owners_select_owner" on platform_owners
  for select using (is_platform_owner(auth.uid()));
-- No insert/update/delete policy -- membership changes go through a future
-- migration or admin-client script, not the running application, matching
-- the dev request's "do not rely only on hidden navigation ... design the
-- owner allowlist so it can later move to a governed role."

-- conversations.kind ----------------------------------------------------------
-- Orthogonal to project_id (20260824190001_conversations_project_binding.sql)
-- -- a Feedback conversation with Ember is never resumed and never shown in
-- the normal History list, so it needs to be distinguishable from an
-- ordinary chat conversation without overloading project_id (a feedback
-- conversation may still happen to be started from a project page, but that
-- doesn't make it project-bound in the existing sense).
alter table conversations add column kind text not null default 'chat' check (kind in ('chat', 'feedback'));

-- feedback_reports -------------------------------------------------------------
create table feedback_reports (
  id uuid primary key default gen_random_uuid(),
  -- Human-friendly "FB-123" shown to the reporter -- separate from the uuid
  -- primary key, same reasoning as eval_runs/graph_runs using a uuid
  -- internally while display surfaces prefer something shorter elsewhere.
  report_number bigint generated by default as identity unique,
  reporter_id uuid not null references profiles(id) on delete cascade,
  -- The Ember conversation that produced this report, for provenance --
  -- never a pointer to a general chat conversation (kind is always
  -- 'feedback' for this column's target, though not DB-enforced across
  -- tables).
  source_conversation_id uuid references conversations(id) on delete set null,
  type text not null check (type in ('bug', 'improvement', 'feature_request', 'usability', 'documentation')),
  title text not null,
  description text not null,
  expected_result text,
  actual_result text,
  impact text,
  reproduction_steps text,
  severity text check (severity in ('critical', 'high', 'medium', 'low')),
  status text not null default 'new'
    check (status in ('new', 'triaged', 'accepted', 'deferred', 'declined', 'in_progress', 'ready_to_verify', 'resolved')),
  -- "Suspected security or privacy incidents require a confidential
  -- classification and restricted notification path rather than ordinary
  -- board visibility" (dev request) -- the restricted-visibility mechanics
  -- (RLS) are identical to 'standard' in this phase; only the label and
  -- board filterability exist yet. Actual separate notification is
  -- deliberately deferred, see the roadmap entry.
  classification text not null default 'standard' check (classification in ('standard', 'confidential_security')),
  -- Informational only -- never used to grant access to a project's
  -- underlying restricted content ("project association does not
  -- automatically expose restricted project evidence to board triagers",
  -- dev request Guardrails).
  current_page text,
  project_id uuid references projects(id) on delete set null,
  application_version text,
  environment text,
  duplicate_of uuid references feedback_reports(id) on delete set null,
  owner_decision text,
  owner_decision_rationale text,
  affected_version text,
  fixed_version text,
  deployed_version text,
  assignee_id uuid references profiles(id) on delete set null,
  -- e.g. "OR-018" once an accepted item graduates into the owner roadmap
  -- register (docs/commercial/ROADMAP.md) -- set manually by an owner, not
  -- derived.
  roadmap_ref text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index feedback_reports_reporter_id_idx on feedback_reports(reporter_id);
create index feedback_reports_status_idx on feedback_reports(status);

create trigger feedback_reports_set_updated_at before update on feedback_reports
  for each row execute function set_updated_at();

-- feedback_report_status_history -----------------------------------------------
-- Insert-only -- "preserve an auditable history of classification, status
-- and owner-decision changes" (dev request). Unlike
-- resource_access_audit_log, this is safe to gate with an ordinary RLS
-- insert policy (not an admin-client-only write) because the only actor
-- who can ever write here is already the narrowest possible role (a
-- platform owner) -- there's no lower-trust actor (e.g. a project owner)
-- this needs to be protected from.
create table feedback_report_status_history (
  id uuid primary key default gen_random_uuid(),
  feedback_report_id uuid not null references feedback_reports(id) on delete cascade,
  from_status text,
  to_status text not null,
  changed_by uuid references profiles(id) on delete set null,
  reason text,
  created_at timestamptz not null default now()
);

create index feedback_report_status_history_report_id_idx on feedback_report_status_history(feedback_report_id);

-- RLS ---------------------------------------------------------------------------
alter table feedback_reports enable row level security;

create policy "feedback_reports_select_own_or_owner" on feedback_reports
  for select using (reporter_id = auth.uid() or is_platform_owner(auth.uid()));

create policy "feedback_reports_insert_own" on feedback_reports
  for insert with check (reporter_id = auth.uid());

-- Reporters don't edit after submission -- Ember's Send is the final draft
-- ("submits only after Send", dev request). Only an owner triages.
create policy "feedback_reports_update_owner" on feedback_reports
  for update using (is_platform_owner(auth.uid())) with check (is_platform_owner(auth.uid()));

-- No delete policy -- an immutable historical record, same convention as
-- workstream_artifacts/resource_access_audit_log.

alter table feedback_report_status_history enable row level security;

create policy "feedback_report_status_history_owner" on feedback_report_status_history
  for all using (is_platform_owner(auth.uid())) with check (is_platform_owner(auth.uid()));


-- ==== supabase/migrations/20260825130001_roadmap_register.sql ====
-- Owner Roadmap register, in-app. The owner-confidential Markdown roadmap
-- (docs/commercial/ROADMAP.md, local-only, excluded from Git) explicitly
-- anticipates this: "If this roadmap later needs access from multiple
-- devices or through KB Sandbox, move it to an authenticated private
-- record ... and enforce access for the two identities above." This
-- migration does exactly that for the register TABLE specifically (the
-- tabular OR-XXX rows) -- the longer prose detail sections for individual
-- items stay in the Markdown file, which remains the narrative source of
-- record; this table is the operational, editable, exportable register.
--
-- Same authorization shape as platform_owners/feedback_reports (this
-- session's own precedent): is_platform_owner(), zero role bypass.

create table roadmap_items (
  id uuid primary key default gen_random_uuid(),
  -- The human-facing "OR-014" identifier -- stable, assigned by an owner,
  -- never renumbered (matches the Markdown register's own "Do not renumber
  -- existing methods silently"-style convention elsewhere in this repo).
  item_ref text not null unique,
  title text not null,
  item_type text not null,
  public_milestone text,
  priority text,
  status text not null default 'captured'
    check (status in ('captured', 'assessing', 'proposed', 'approved', 'in_progress', 'validate', 'done', 'deferred', 'declined', 'superseded')),
  pilot_position text,
  decision_next_action text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger roadmap_items_set_updated_at before update on roadmap_items
  for each row execute function set_updated_at();

alter table roadmap_items enable row level security;

-- Select and write share the exact same boundary here -- a single FOR ALL
-- policy is sufficient, same reasoning as project_access_groups etc.
-- (20260825100001's own comment on why this avoids the "combined policy
-- leaks SELECT via OR" trap from 20260824210001).
create policy "roadmap_items_owner" on roadmap_items
  for all using (is_platform_owner(auth.uid())) with check (is_platform_owner(auth.uid()));

-- Seed with the current register (docs/commercial/ROADMAP.md, as of this
-- migration) so the in-app view starts out matching the Markdown file
-- rather than empty. Status values map onto the check constraint above by
-- taking the FIRST listed status where a cell shows more than one (e.g.
-- "Done/Validate" -> 'done', "In progress (Stage 1 Done/Validate)" ->
-- 'in_progress') -- the full original text is preserved verbatim in
-- decision_next_action, nothing is lost, just normalized for the status
-- filter/dropdown.
insert into roadmap_items (item_ref, title, item_type, public_milestone, priority, status, pilot_position, decision_next_action) values
('OR-001', 'Project-aware knowledge and project-bound Ember conversations', 'Change', 'M2/M5', 'P0', 'done', 'Gating', 'Complete deployed regression: citations, isolation, staleness, history and recovery.'),
('OR-002', 'Project approval authorities', 'New feature', 'M7', 'P1', 'done', 'Important', 'Continue staged approval requests/decisions only when artifact versioning and pilot need justify it.'),
('OR-003', 'Project lead role and bounded member-management rights', 'Change', 'M5/M7', 'P1', 'proposed', 'Important', 'Owner/lead may add ordinary members; lead cannot replace owner or grant restricted access without separate stewardship.'),
('OR-004', 'Project evidence access controls for pricing, contracts and other restricted evidence', 'New feature', 'M1/M2/M7', 'P0 before real restricted data', 'in_progress', 'Gating only if real customer pricing/confidential evidence is used', 'Stage 1 (access model + restricted source/chunk/citation retrieval) implemented and live-verified with synthetic pricing 25 Aug 2026. Stage 2 (derived-content inheritance, sanitized release, approval-authority gap warnings) and Stage 3 (conversation/export/eval/MCP hardening) deferred -- see detailed section in the Markdown roadmap for scope and review triggers.'),
