-- ==== supabase/migrations/20260827150001_external_agent_registry.sql ====
-- External Agent Registry -- scaffolding for the Sandz Builders Programme
-- pitch (docs/commercial/KB-Sandbox-Builders-Programme-for-Sandz.docx,
-- docs/dev-request-food-outlet-ai-readiness-showcase.md). Registers agents
-- that run OUTSIDE KB Sandbox (a builder's Lunch Agent on Sandz/customer
-- infrastructure) so KB Sandbox can govern them -- distinct from the
-- existing `agents`/`agent_versions` tables (20260811100003_agent_framework.sql),
-- which are KBS-native, graph-based RAG agents Ember runs itself. Prefixed
-- external_agent_* throughout to keep the two concepts unambiguous.
--
-- Explicitly NOT covered by this migration: no Agent Gateway (nothing here
-- actually invokes a registered agent's endpoint), no real credential vault
-- (credentials_policy is a reference to where a secret lives, never the
-- secret itself), and permitted_scope is descriptive registry metadata only
-- -- not wired into RLS or any invocation path, since no invocation path
-- exists yet.

create table external_agents (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  purpose text not null,
  protocol text not null check (protocol in ('mcp', 'https')),
  endpoint_url text,                                             -- null until actually deployed
  project_id uuid references projects(id) on delete set null,    -- governing project, e.g. Food Outlet AI-Readiness Showcase
  active_version_id uuid,                                        -- FK added below once external_agent_versions exists
  status text not null default 'draft' check (status in ('draft', 'active', 'archived')),
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index external_agents_project_id_idx on external_agents(project_id);
create index external_agents_created_by_idx on external_agents(created_by);

create trigger external_agents_set_updated_at before update on external_agents
  for each row execute function set_updated_at();

-- external_agent_versions -----------------------------------------------
-- Immutable once created, same enforcement mechanism as agent_versions /
-- wiki_versions (no UPDATE policy on the version's descriptive fields --
-- only certification_status/approved_by/approved_at ever change, via a
-- dedicated curator/admin-only policy below). "Approval applies to a
-- specific version. A material code, API or permission change requires
-- reassessment" (source doc, verbatim) is why certification lives here and
-- not on the parent row -- a new version always starts back at 'experimental'.
create table external_agent_versions (
  id uuid primary key default gen_random_uuid(),
  external_agent_id uuid not null references external_agents(id) on delete cascade,
  version_number integer not null,
  skills jsonb not null default '[]'::jsonb,              -- [{name, description, provider/outlet}]
  credentials_policy jsonb not null default '{}'::jsonb,  -- references only -- {name, storage_location, notes}; NEVER a secret value
  spending_limits jsonb not null default '{}'::jsonb,     -- {perOrderMax, dailyMax, currency}
  approval_policy jsonb not null default '{}'::jsonb,     -- {requiresHumanConfirmation, confirmationFields: [...]}
  permitted_scope jsonb not null default '{}'::jsonb,     -- {projectIds:[...], userIds:[...]} -- DISPLAY ONLY, see note above
  certification_status text not null default 'experimental'
    check (certification_status in ('experimental', 'sandbox_tested', 'security_reviewed', 'outlet_accepted', 'production_approved', 'deprecated', 'suspended')),
  notes text,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  approved_by uuid references profiles(id) on delete set null,
  approved_at timestamptz,
  unique (external_agent_id, version_number)
);

create index external_agent_versions_external_agent_id_idx on external_agent_versions(external_agent_id);

alter table external_agents add constraint external_agents_active_version_id_fkey
  foreign key (active_version_id) references external_agent_versions(id) on delete set null;

-- RLS -----------------------------------------------------------------------
alter table external_agents enable row level security;
alter table external_agent_versions enable row level security;

-- Read: any authenticated, active, non-anonymous session -- same bar as
-- ai_providers/agent_templates. Needed so any Builder can browse the
-- registry, not just admins.
create policy "external_agents_select_authenticated" on external_agents
  for select using (
    exists (select 1 from profiles p where p.id = auth.uid() and p.role <> 'anonymous' and p.is_active)
  );

create policy "external_agent_versions_select_authenticated" on external_agent_versions
  for select using (
    exists (select 1 from profiles p where p.id = auth.uid() and p.role <> 'anonymous' and p.is_active)
  );

-- Insert: any authenticated non-anonymous user may register their OWN agent
-- (created_by = auth.uid()) -- this is what lets a Builder self-register,
-- matching the Programme's "Builder" tier, without requiring curator/admin
-- staff to create every entry on a builder's behalf.
create policy "external_agents_insert_own" on external_agents
  for insert with check (
    created_by = auth.uid()
    and exists (select 1 from profiles p where p.id = auth.uid() and p.role <> 'anonymous' and p.is_active)
  );

create policy "external_agent_versions_insert_own_agent" on external_agent_versions
  for insert with check (
    created_by = auth.uid()
    and exists (
      select 1 from external_agents ea
      where ea.id = external_agent_id and (ea.created_by = auth.uid() or is_curator_or_admin(auth.uid()))
    )
  );

-- Update: the parent row's own mutable fields (status, endpoint_url,
-- active_version_id) may be updated by the owning builder or curator/admin.
create policy "external_agents_update_own_or_staff" on external_agents
  for update using (created_by = auth.uid() or is_curator_or_admin(auth.uid()));

-- Certification status is staff-only -- a builder self-registers a draft,
-- but cannot self-certify it. One gate covers every tier for this first
-- pass (see plan's "explicitly not built" section for the deferred
-- per-tier permission matrix).
create policy "external_agent_versions_update_certification_staff_only" on external_agent_versions
  for update using (is_curator_or_admin(auth.uid()));


-- ==== supabase/migrations/20260828100001_project_status_pipeline.sql ====
-- Adds an explicit 'review' status value so a project can move through a
-- real Initial Draft -> Working on it -> For Approval -> Approved pipeline,
-- mirroring wiki_articles' existing draft -> review -> approved precedent
-- (supabase/migrations/20260808220002_wiki_articles.sql). 'active' already
-- existed in the check constraint but was never written by any code path
-- (confirmed by grep before this migration) -- it becomes "Working on it".
-- 'completed' is unchanged and keeps meaning "Approved" (approveProject's
-- own target value, per its existing confirm-dialog copy). Per Mike,
-- 2026-08-28: the project detail page's free-text "Status" field was a
-- naming mistake -- it's being replaced with this real, button-driven
-- pipeline; the free-text field moves to the Notes section instead.
alter table projects drop constraint projects_status_check;
alter table projects add constraint projects_status_check
  check (status = any (array['draft'::text, 'active'::text, 'review'::text, 'completed'::text, 'archived'::text]));


-- ==== supabase/migrations/20260828110001_project_status_history.sql ====
-- Tracks every status transition on a project (when created, when moved to
-- Working on it / For Approval / Approved, and back), for later analysis --
-- per Mike, 2026-08-28: "do we keep track of when something is created, set
-- to working... so later we can analyze/optimize." Mirrors
-- resource_access_audit_log's exact shape and RLS choice
-- (supabase/migrations/20260825100001_project_evidence_access_schema.sql):
-- no insert/update/delete policy at all -- written only via the admin
-- client from the service layer (src/lib/workbench/projects.ts), so
-- actor_id reflects the real acting user (ctx.user.id) rather than
-- auth.uid(), which would be null for service-role writes and is why this
-- isn't a database trigger.
create table project_status_history (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  from_status text,   -- null for the initial creation event
  to_status text not null,
  actor_id uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

create index project_status_history_project_id_idx on project_status_history(project_id);

alter table project_status_history enable row level security;

-- can_curate_project (20260810120001_project_members.sql) = platform admin,
-- or an active owner/curator member -- the same people who can trigger a
-- status change can see its history. Not open to every project member.
create policy "project_status_history_select_curator" on project_status_history
  for select using (can_curate_project(project_id, auth.uid()));


-- ==== supabase/migrations/20260828120001_knowledge_base_curator_review.sql ====
-- Curators can now create a new Knowledge Base directly from the upload
-- flow; the admin page's role shifts from creating KBs to reviewing them.
-- Mirrors wiki_articles' draft -> review -> approved precedent, collapsed
-- to two curator-visible states since creating a KB mid-upload already
-- counts as "submitting" it -- no separate draft-then-submit step. Per
-- Mike, 2026-08-28.
--
-- Orthogonal to the existing lifecycle_status (active/reference/archived,
-- a retention concept) -- a newly curator-created KB is lifecycle_status
-- 'active' (usable right away for uploads) and status 'pending' (awaiting
-- admin review) at the same time.
alter table knowledge_bases add column status text not null default 'approved'
  check (status in ('pending', 'approved', 'rejected'));

-- Existing rows are all admin-created and already trusted -- explicit
-- backfill, not relying on the column default alone, so this is auditable.
update knowledge_bases set status = 'approved';

-- kb_admin_manage's existing `for all` policy
-- (supabase/migrations/20260808190010_rls_policies.sql) already covers
-- admin update (approve/reject) and delete -- only INSERT needs a new
-- policy. Curators (and admins) may insert, but only ever as 'pending' --
-- cannot self-approve.
create policy "kb_curator_insert_pending" on knowledge_bases
  for insert with check (is_curator_or_admin(auth.uid()) and status = 'pending');


-- ==== supabase/migrations/20260828140001_product_handbook_category_and_metadata.sql ====
-- Product Handbook Wiki category, Stage 1 of the Ember Product Knowledge
-- Publishing Pipeline (docs/dev-request-ember-product-knowledge-publishing-
-- pipeline.md). Distinct from the existing platform_handbook ("Workbench
-- Handbook") category, which is already earmarked by docs/workbench-
-- handbook-*.md for external-facing AI-consulting methodology articles --
-- this one is for internal docs describing KB Sandbox's own pages, features,
-- permissions and workflows.
insert into wiki_categories (id, name, sort_order) values
  ('product_handbook', 'Product Handbook', 8)
on conflict (id) do nothing;

-- Metadata from the dev request's "each product-knowledge version should
-- retain" list. Added to wiki_versions, not wiki_articles, because that's
-- the only surface curators can already edit after creation (title/slug/
-- category are fixed at creation) -- these fields follow content through the
-- same draft-a-new-version-on-edit lifecycle as quick_help/content/
-- limitations, with no new article-level edit path needed. All nullable and
-- additive; no existing row's meaning changes.
alter table wiki_versions add column applicable_roles text[];
alter table wiki_versions add column related_routes text[];
alter table wiki_versions add column applicable_version text;


-- ==== supabase/migrations/20260828150001_product_handbook_release_notes_seed.sql ====
-- Baseline Product Handbook content, seeded at provisioning rather than
-- authored per-deployment (per Mike, 2026-08-28): every new client
-- deployment already runs the full migration set to stand up its DB, so
-- seeding here means Ember has accurate baseline product knowledge before
-- that client's own (unrelated) admin ever logs in -- no separate step, no
-- dependency on a shared source repo they'd need access to.
--
-- Deliberately not fancy (per Mike): a single, growing "Release Notes"
-- article rather than one hand-authored Handbook page per feature -- we
-- already have the roadmap for what's planned and Ember for answering
-- questions; this is just the minimal connective content between "a feature
-- shipped" and "Ember knows about it". New entries get prepended to this
-- article's content by whoever ships a user-visible change (curator/admin
-- edit -> new draft version -> approve, same as any other Wiki article).
--
-- created_by/approved_by are left null (both columns are nullable) since
-- there's no profiles row to attribute this to at fresh-provisioning time --
-- this is system-provisioned baseline content, not authored by a person.
insert into wiki_articles (slug, title, category, short_description, status)
values (
  'release-notes',
  'Release Notes',
  'product_handbook',
  'A running log of user-visible changes to KB Sandbox, newest first -- what changed, who can use it, and where to find it.',
  'approved'
)
on conflict (slug) do nothing;

insert into wiki_versions (
  wiki_article_id, version_number, quick_help, content,
  verification_status, last_verified_at, generated_by, approved_at
)
select
  wa.id, 1,
  'Release Notes is a running log of what changed in KB Sandbox and who can use it -- check here before assuming a feature works a certain way.',
  $md$## 2026-08-28 -- Product Handbook (Ember product knowledge)
Curators/admins can write and approve articles describing KB Sandbox's own pages and features (Wiki category: Product Handbook), so Ember can answer questions about the product itself, not just uploaded domain content. Who can use it: any curator can draft, any admin can approve; any signed-in user can ask Ember.

## 2026-08-28 -- Curator-created knowledge bases
Curators can create a new knowledge base directly from the Sources & Curation upload flow (previously admin-only). A new knowledge base starts pending and is usable for uploads immediately; an admin approves or rejects it from the admin page's Pending review section.

## 2026-08-28 -- Project status pipeline
Projects now move through an explicit status: Initial Draft -> Working on it -> For Approval -> Approved, shown on the project page (`/projects/[id]`), with every transition logged in a "Status history" list. A curator or the project owner can start work or submit for approval; only an admin can approve or send a project back to Working on it.

## 2026-08-28 -- Notes section gets an Add button
The Notes section on a project page previously had no way to add a note from the UI. It now has a "+ Add" link next to the existing "View all" link, matching the Status section above it.

## 2026-08-28 -- Ember chat auto-scrolls to the latest message
Opening Ember or loading a conversation with a long history used to leave you scrolled to the top, needing to scroll down to see the latest message. The chat panel now scrolls to the bottom automatically whenever it opens or a conversation loads.$md$,
  'verified', now(), 'human', now()
from wiki_articles wa
where wa.slug = 'release-notes'
  and not exists (select 1 from wiki_versions where wiki_article_id = wa.id);

update wiki_articles
set current_version_id = (
  select id from wiki_versions where wiki_article_id = wiki_articles.id order by version_number desc limit 1
)
where slug = 'release-notes' and current_version_id is null;

-- Consolidate: the standalone "Project Status Pipeline" Handbook article
-- (authored this session before we settled on the release-notes approach)
-- duplicates the entry above. Archive rather than delete -- keeps the
-- audit trail, matches the existing Archive action any curator/admin can
-- already do from the Wiki UI.
update wiki_articles set status = 'archived' where slug = 'project-status-pipeline' and status <> 'archived';


-- ==== supabase/migrations/20260828160001_decrement_approved_chunks.sql ====
-- Mirrors increment_approved_chunks (20260808190009_functions.sql). Needed
-- because a chunk can be re-reviewed and rejected after already being
-- approved (no status guard in the reviewer UI) -- rejectChunk now calls
-- this so documents.approved_chunks doesn't keep counting a chunk that's no
-- longer approved. greatest(...,0) guards against underflow if ever called
-- out of order.
create or replace function decrement_approved_chunks(doc_id uuid)
returns void
language sql security definer set search_path = public as $$
  update documents set approved_chunks = greatest(approved_chunks - 1, 0) where id = doc_id;
$$;


-- ==== supabase/migrations/20260828170001_information_sensitivity_classification.sql ====
-- Information Sensitivity Classification -- per Mike's Shadow AI blog post
-- ("Shadow AI Is Already Inside the Enterprise") and the plan discussed
-- 2026-08-28. Deliberately a NEW, separate column/table from the existing
-- Project Evidence Access Controls (resource_access_policies.classification,
-- 20260825100001) rather than repurposing it -- that system answers "which
-- humans can see this resource" (a binary access-grant gate); this one
-- answers "which AI models may process this resource's content" (a machine-
-- eligibility ceiling). Conflating the two would break the existing,
-- working access-grant feature.

-- resource_access_policies already has a unique (resource_type, resource_id)
-- constraint -- one row per resource platform-wide, not per project -- so
-- adding a column here gives a genuinely resource-global sensitivity tier,
-- matching the blog's framing that sensitivity is a property of the
-- document, not of which project happens to be viewing it. No new RLS
-- needed: the existing "resource_access_policies_manage_owner" policy
-- (can_manage_project) already covers every column on this table.
alter table resource_access_policies add column information_sensitivity text
  check (information_sensitivity in ('public', 'internal', 'confidential', 'restricted'));
-- null = not yet classified. The enforcement side (src/lib/ai/sensitivity.ts)
-- treats null as 'internal' -- a safer default than silently treating
-- unclassified content as public.

-- ai_provider_sensitivity_eligibility -----------------------------------
-- One row per AI provider: the highest sensitivity tier that provider is
-- approved to receive. A simple ordinal ceiling ('restricted' = approved for
-- everything, 'public' = public content only), not a set of allowed tiers,
-- matching the blog's own ladder framing. A provider with no row here is
-- treated as 'internal'-only by the enforcement side -- the safe default,
-- not "approved for everything" -- so this needs zero backfill for existing
-- providers to remain safe.
create table ai_provider_sensitivity_eligibility (
  provider_id uuid not null references ai_providers(id) on delete cascade,
  max_sensitivity text not null check (max_sensitivity in ('public', 'internal', 'confidential', 'restricted')),
  updated_by uuid references profiles(id) on delete set null,
  updated_at timestamptz not null default now(),

  primary key (provider_id)
);

create trigger ai_provider_sensitivity_eligibility_set_updated_at before update on ai_provider_sensitivity_eligibility
  for each row execute function set_updated_at();

alter table ai_provider_sensitivity_eligibility enable row level security;

-- Same read/write split as ai_providers/ai_models themselves (20260810110001):
-- any active, non-anonymous session may read (needed so the chat loop's
-- enforcement check works for every requesting user, not just admins);
-- only admins may set a provider's eligibility ceiling.
create policy "ai_provider_sensitivity_eligibility_select_staff_or_consultant" on ai_provider_sensitivity_eligibility
  for select using (
    exists (select 1 from profiles p where p.id = auth.uid() and p.role != 'anonymous' and p.is_active)
  );

create policy "ai_provider_sensitivity_eligibility_admin_manage" on ai_provider_sensitivity_eligibility
  for all using (is_admin(auth.uid())) with check (is_admin(auth.uid()));


-- ==== supabase/migrations/20260829120001_project_information_sensitivity.sql ====
-- Closes a gap flagged in docs/dev-request-enterprise-shadow-ai-governance-
-- later-phases.md: "Project metadata placed in system prompts must also be
-- reviewed against this rule." A project's name/goal is embedded directly
-- into the system prompt on every turn of a project-bound conversation
-- (src/lib/chat/loop.ts's buildProjectPromptAddendum), independent of
-- whether search_wiki/search_project_knowledge ever runs -- so the
-- Information Sensitivity Classification check (20260828170001) never saw
-- it, even though it's real content reaching the model.
--
-- Deliberately a plain column on projects, not a resource_access_policies
-- row keyed resource_type='project': that table's `classification` column
-- (EvidenceClassification, "which humans may see this") is mandatory on
-- every row and drives has_evidence_access() grant requirements designed
-- for knowledge_source/wiki_article/workstream_artifact -- concepts that
-- don't apply to a project's own metadata (a project's human visibility is
-- already governed by project_members/RLS, not that table). Reusing it here
-- would force a meaningless classification choice and create a policy row
-- that looks like an access restriction but silently enforces nothing
-- (has_evidence_access is never consulted by any projects RLS policy).
-- A dedicated column keeps the two concerns from ever colliding.
--
-- Same three states as resource_access_policies.information_sensitivity:
-- null = unclassified (src/lib/ai/sensitivity.ts treats this as 'internal',
-- the same conservative default used for unclassified retrieved resources).
-- No RLS change needed -- the existing "projects_update_managers" policy
-- (can_manage_project: owner or platform admin) already covers every
-- column on this table, including this one.
alter table projects add column information_sensitivity text
  check (information_sensitivity in ('public', 'internal', 'confidential', 'restricted'));


-- ==== supabase/migrations/20260829130001_chat_message_retrieved_resources.sql ====
-- Phase 2, increment 1 (docs/design-notes/ai-policy-enforcement-service-and-
-- context-manifest.md). Persists the COMPLETE per-message retrieval
-- provenance loop.ts already computes every turn (retrievedWikiArticleSlugs/
-- retrievedKnowledgeSourceIds), separately from response_payload.citations --
-- citations only capture what the model chose to cite, a subset of what was
-- actually retrieved (see envelope-resolution.ts's own citation-verification
-- comment). Reconstructing a policy manifest from citations alone would
-- understate sensitivity for anything retrieved-but-not-cited, exactly the
-- kind of silent gap this column exists to close for maybeRefreshSummary
-- (src/lib/chat/summary.ts), which resends the whole transcript to a
-- separately-resolved model and needs the FULL retrieval set, not just the
-- cited subset, to evaluate policy correctly.
--
-- Nullable, written only on 'tool' role rows that actually retrieved
-- something this call (search_wiki, search_project_knowledge) -- every
-- other row (user/assistant, or a tool call that retrieved nothing) leaves
-- this null, same as response_payload's own convention. No RLS change --
-- existing chat_messages policies already cover the whole row.
alter table chat_messages add column retrieved_resources jsonb;


-- ==== supabase/migrations/20260831100001_builder_integrations_registry.sql ====
-- Advanced Builder Integrations, Phase A (docs/design-notes/concept-paper-
-- advanced-builder-integrations.md). Generalizes the External Agent
-- Registry (20260827150001_external_agent_registry.sql) to also register
-- MCP servers, not just external agents -- the kind of registration Phase C
-- (Ember actually calling one) will need next. Renamed
-- external_agents/external_agent_versions -> builder_integrations/
-- builder_integration_versions, since "external_agents" becomes misleading
-- once MCP-server rows live in the same table.
--
-- Deliberately NOT covered by this pass: knowledge connectors (a batch-sync
-- lifecycle, not "can Ember call this tool") and webhook receivers (Phase
-- D's concern -- nothing exists yet to receive into). REST APIs are never
-- independently registered here -- they're what an MCP server or connector
-- uses underneath, per the concept paper's own "five concepts" section.
--
-- Certification ladder is UNCHANGED (still experimental -> sandbox_tested
-- -> security_reviewed -> outlet_accepted -> production_approved, plus
-- deprecated/suspended) -- it's live, tested, and matches the original
-- Sandz pitch doc's own language ("distinguish experimental, tested and
-- production-approved versions"). The concept paper's proposed 6-stage
-- ladder (Registered -> Connectivity verified -> Functionally evaluated ->
-- Security reviewed -> Customer accepted -> Production approved) maps
-- closely enough (security_reviewed/production_approved are exact matches;
-- outlet_accepted is this app's per-vertical name for Customer accepted;
-- experimental/sandbox_tested cover the earlier self-serve stages) that
-- renaming a proven ladder for cosmetic alignment wasn't worth the churn.
-- Recorded here so this isn't silently re-litigated later.

alter table external_agents rename to builder_integrations;
alter table external_agent_versions rename to builder_integration_versions;
alter table builder_integration_versions rename column external_agent_id to builder_integration_id;

-- Renaming a table does not rename its dependent indexes/trigger/explicitly-
-- named constraints in Postgres -- only auto-generated-name objects (like
-- the FKs from a bare `references` clause) are left as legacy
-- external_agent*-prefixed names, which is harmless and not worth
-- enumerating here. These are the ones worth cleaning up for anyone reading
-- \d builder_integrations later.
alter index external_agents_pkey rename to builder_integrations_pkey;
alter index external_agents_slug_key rename to builder_integrations_slug_key;
alter index external_agents_project_id_idx rename to builder_integrations_project_id_idx;
alter index external_agents_created_by_idx rename to builder_integrations_created_by_idx;
alter table builder_integrations rename constraint external_agents_active_version_id_fkey to builder_integrations_active_version_id_fkey;
alter trigger external_agents_set_updated_at on builder_integrations rename to builder_integrations_set_updated_at;

alter index external_agent_versions_pkey rename to builder_integration_versions_pkey;
alter index external_agent_versions_external_agent_id_version_number_key rename to builder_integration_versions_integration_id_version_key;
alter index external_agent_versions_external_agent_id_idx rename to builder_integration_versions_integration_id_idx;

-- Policy renames are purely cosmetic (a policy's name never has to match
-- its table), but worth doing while every other name is moving -- Postgres
-- auto-updates the policy bodies' internal references to the renamed
-- table/column above, so only the names below need touching, not the SQL.
alter policy "external_agents_select_authenticated" on builder_integrations rename to "builder_integrations_select_authenticated";
alter policy "external_agents_insert_own" on builder_integrations rename to "builder_integrations_insert_own";
alter policy "external_agents_update_own_or_staff" on builder_integrations rename to "builder_integrations_update_own_or_staff";
alter policy "external_agent_versions_select_authenticated" on builder_integration_versions rename to "builder_integration_versions_select_authenticated";
alter policy "external_agent_versions_insert_own_agent" on builder_integration_versions rename to "builder_integration_versions_insert_own";
alter policy "external_agent_versions_update_certification_staff_only" on builder_integration_versions rename to "builder_integration_versions_update_certification_staff_only";

-- kind: what's being registered. Existing rows are genuinely all external
-- agents, so the temporary default backfills them correctly; dropped
-- immediately after so every future insert must specify kind explicitly,
-- matching this table's existing convention for `protocol` (no default,
-- always stated).
alter table builder_integrations
  add column kind text not null default 'external_agent' check (kind in ('external_agent', 'mcp_server'));
alter table builder_integrations alter column kind drop default;

-- risk_classification / auth_method: version-level, not integration-level,
-- since risk can change between versions (a v2 might add a write capability
-- a v1 didn't have). risk_classification operationalizes the concept
-- paper's "treat read and write differently" principle and is what Phase C
-- will gate tool exposure on -- unlike kind/protocol, it keeps a permanent
-- default: 'read_only' is the deliberately safe assumption for a version
-- that never stated otherwise. auth_method is descriptive only for now,
-- same "reference, not enforcement" posture credentials_policy already has.
alter table builder_integration_versions
  add column risk_classification text not null default 'read_only'
    check (risk_classification in ('read_only', 'reversible_write', 'consequential_write', 'administrative')),
  add column auth_method text;

-- Project availability -- replaces permitted_scope.projectIds (inert JSON;
-- nothing has ever read it, per the original migration's own comment) as
-- the REAL mechanism. Phase C's "Ember discovers only tools permitted for
-- the current Project" needs a real join to query, not a JSON blob.
-- permitted_scope itself is untouched (still holds userIds and whatever
-- else isn't modeled as a real table yet).
create table builder_integration_project_availability (
  id uuid primary key default gen_random_uuid(),
  builder_integration_id uuid not null references builder_integrations(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  granted_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (builder_integration_id, project_id)
);

create index builder_integration_project_availability_integration_id_idx
  on builder_integration_project_availability(builder_integration_id);
create index builder_integration_project_availability_project_id_idx
  on builder_integration_project_availability(project_id);

alter table builder_integration_project_availability enable row level security;

-- Visible to: the integration's own registering builder, curator/admin
-- staff, or any active member of the referenced project -- so a Project
-- owner can see what's available to their own Project without needing
-- platform staff role.
create policy "builder_integration_project_availability_select" on builder_integration_project_availability
  for select using (
    is_project_member(project_id, auth.uid())
    or is_curator_or_admin(auth.uid())
    or exists (select 1 from builder_integrations bi where bi.id = builder_integration_id and bi.created_by = auth.uid())
  );

-- Manage (grant/revoke): the registering builder or curator/admin -- same
-- bar createExternalAgentVersion already uses for adding a new version.
create policy "builder_integration_project_availability_manage" on builder_integration_project_availability
  for all using (
    is_curator_or_admin(auth.uid())
    or exists (select 1 from builder_integrations bi where bi.id = builder_integration_id and bi.created_by = auth.uid())
  )
  with check (
    is_curator_or_admin(auth.uid())
    or exists (select 1 from builder_integrations bi where bi.id = builder_integration_id and bi.created_by = auth.uid())
  );


-- ==== supabase/migrations/20260831110001_builder_integration_invocations.sql ====
-- Agent Gateway, Milestone 1 (Advanced Builder Integrations Phase C):
-- Ember can now actually call a registered, certified, Project-available
-- MCP server's tools -- not just register/certify it (Phase A). This table
-- is both the audit trail ("recorded evaluation" the dev request asks for)
-- and the pending-confirmation state machine for write-risk tool calls,
-- following this repo's existing convention (resource_access_audit_log,
-- project_status_history): one append-only-ish row per attempt, a status
-- column IS the state machine, no separate pending table.
--
-- Read-only tool calls (see src/lib/mcp-gateway/risk.ts) go straight from
-- nothing to a single 'executed' row -- matching how every other read tool
-- in src/lib/mcp/tools.ts already works today (call, get result, done).
-- Gated (reversible_write/consequential_write/administrative) tool calls
-- insert a 'proposed' row first; a human must explicitly confirm via
-- src/app/actions/gateway-invocations.ts before the external call ever
-- happens -- this is the first code-level "propose, then confirm, then
-- execute" gate anywhere in the app (every other tool today only has a
-- prompt-level confirmation instruction, per project-note-tool.ts's own
-- comment).
create table builder_integration_invocations (
  id uuid primary key default gen_random_uuid(),
  builder_integration_id uuid not null references builder_integrations(id) on delete cascade,
  builder_integration_version_id uuid not null references builder_integration_versions(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  conversation_id uuid references conversations(id) on delete set null,
  actor_id uuid references profiles(id) on delete set null,
  tool_name text not null,
  -- Snapshotted at call time from the version's own risk_classification /
  -- src/lib/mcp-gateway/risk.ts's name-prefix heuristic -- a later version
  -- change must never silently reclassify a historical row.
  risk_classification text not null
    check (risk_classification in ('read_only', 'reversible_write', 'consequential_write', 'administrative')),
  input jsonb not null default '{}'::jsonb,
  output jsonb,
  status text not null default 'proposed'
    check (status in ('proposed', 'confirmed', 'executed', 'failed', 'cancelled')),
  error text,
  -- Best-effort numeric amount correlated for spending_limits enforcement
  -- (see src/lib/mcp-gateway/spending.ts) -- populated when this row's own
  -- tool result contains a total/amount-shaped field, or copied forward
  -- from a prior row sharing an id-shaped field (e.g. orderId) when this
  -- row is a gated write proposal being checked against perOrderMax/dailyMax.
  correlated_amount numeric,
  created_at timestamptz not null default now(),
  confirmed_at timestamptz,
  confirmed_by uuid references profiles(id) on delete set null,
  executed_at timestamptz
);

create index builder_integration_invocations_project_id_idx on builder_integration_invocations(project_id);
create index builder_integration_invocations_integration_id_idx on builder_integration_invocations(builder_integration_id);
create index builder_integration_invocations_status_idx on builder_integration_invocations(status);

alter table builder_integration_invocations enable row level security;

-- Visible to: project members, curator/admin staff, or the integration's
-- own registering builder -- identical shape to
-- builder_integration_project_availability_select.
create policy "builder_integration_invocations_select" on builder_integration_invocations
  for select using (
    is_project_member(project_id, auth.uid())
    or is_curator_or_admin(auth.uid())
    or exists (select 1 from builder_integrations bi where bi.id = builder_integration_id and bi.created_by = auth.uid())
  );

-- No client insert/update policy at all, deliberately -- same "no client
-- insert path" posture as resource_access_audit_log and ai_operation_logs.
-- Every write (propose, confirm, execute, cancel) goes through the admin
-- client from src/lib/chat/loop.ts / src/app/actions/gateway-invocations.ts,
-- each already gated by an explicit application-level authorization check
-- before the write happens -- RLS on this table exists only to bound reads.


-- ==== supabase/migrations/20260831120001_member_role.sql ====
-- OL-007 (docs/test-reports/2026-08-31-orderlunch-builder-journey.md): a new
-- least-privileged platform role, 'member', below 'consultant'. An ordinary
-- employee should be able to sign in, see their own Projects, use Ember
-- within them, read approved Wiki/knowledge, and participate in permitted
-- Project interactions (notes) -- without being able to create Projects,
-- self-register Builder integrations, or do anything else a plain
-- consultant today can already do that a member shouldn't.
--
-- Audit (this session, three parallel investigations) found the real
-- security-relevant surface for this change is much smaller than "every
-- role != 'anonymous' check": everything that creates/curates content
-- (Workstreams, KBs, Wiki drafts, eval datasets, agent/graph management,
-- KB/Wiki-to-project attach) is already gated by is_curator_or_admin/
-- can_curate_project/can_manage_project, none of which a member (like a
-- plain consultant today) would ever satisfy -- no RLS change needed there.
-- Eval/graph run creation uses a *literal* role = 'consultant' allowlist,
-- which already excludes a member correctly. project_notes insert has no
-- profiles.role check at all -- already matches the intended member
-- capability with zero changes. Only two write policies checked merely
-- "any non-anonymous role", which a member would incorrectly satisfy:
-- projects_insert_self and builder_integrations_insert_own. Tightened below.

alter table profiles drop constraint profiles_role_check;
alter table profiles add constraint profiles_role_check
  check (role in ('anonymous', 'member', 'consultant', 'curator', 'admin'));

-- Mirrors is_curator_or_admin's exact shape (20260808190009_functions.sql).
create or replace function is_consultant_or_above(uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from profiles where id = uid and role in ('consultant', 'curator', 'admin') and is_active = true
  );
$$;

alter policy "projects_insert_self" on projects
  with check (owner_id = auth.uid() and is_consultant_or_above(auth.uid()));

alter policy "builder_integrations_insert_own" on builder_integrations
  with check (created_by = auth.uid() and is_consultant_or_above(auth.uid()));


-- ==== supabase/migrations/20260831130001_workstream_artifact_status.sql ====
-- OL-010 (docs/test-reports/2026-08-31-orderlunch-builder-journey.md):
-- attach_workstream_artifact's "successfully attached" never implied the
-- content satisfied its requested acceptance criteria. workstream_artifacts
-- was deliberately insert-only (no UPDATE policy existed at all -- "you
-- don't edit history, you attach a new finding if something changes", per
-- 20260811100004_project_workstreams.sql's own comment). This adds a status
-- column following the Builder Registry's certification-ladder precedent
-- (builder_integration_versions.certification_status, immutable descriptive
-- fields + a narrowly-scoped staff-gated status column) rather than the
-- chunk-review precedent (mutates one row's status in place) -- an artifact
-- attempt's own recorded content must stay exactly as submitted even after
-- a later attempt supersedes it.

alter table workstream_artifacts
  add column status text not null default 'draft'
    check (status in ('draft', 'validation_failed', 'ready_for_review', 'approved', 'rejected')),
  add column validation_notes text,
  add column reviewed_by uuid references profiles(id) on delete set null,
  add column reviewed_at timestamptz;

-- Same authorization bar as workstream creation/curation (can_curate_project
-- -- Project owner/curator, or admin). Only the app-layer reviewArtifact()
-- function (src/lib/workbench/workstreams.ts) ever calls this update, and it
-- only ever sends status/validation_notes/reviewed_by/reviewed_at -- same
-- "one trusted call path, no column-level RLS needed" posture already
-- established for builder_integration_versions_update_certification_staff_only.
create policy "workstream_artifacts_update_review_curator" on workstream_artifacts
  for update using (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_artifacts.workstream_id and can_curate_project(w.project_id, auth.uid())
    )
  );


-- ==== supabase/migrations/20260901120001_project_notes_request_membership.sql ====
-- "Request membership" on the Organization Portfolio (/projects/portfolio).
-- A curator viewing that page can see a project's safe metadata but, unlike
-- an admin, has no RLS bypass into its actual content -- they need an
-- explicit project_members row first. project_notes_insert_member
-- (20260814120001_project_notes.sql) requires the author to already be a
-- project member, which is exactly what a membership *request* can't
-- satisfy. Rather than weakening that policy, add a second, narrowly-scoped
-- insert policy: any curator/admin may author a note on a project they are
-- not yet a member of, same as they already have oversight visibility into
-- via can_curate_project elsewhere. Postgres OR's multiple permissive
-- policies for the same command, so project_notes_insert_member is
-- untouched -- ordinary members still can't note projects they're not on.
create policy "project_notes_insert_curator_or_admin" on project_notes
  for insert to authenticated
  with check (
    author_id = auth.uid()
    and is_curator_or_admin(auth.uid())
    and (recipient_type != 'user' or is_project_member(project_id, recipient_user_id))
  );


-- ==== supabase/migrations/20260901130001_resource_access_requests.sql ====
-- Locked sources for restricted project members, with a request/approve/
-- reject flow. Project Evidence Access Controls (20260825100001,
-- 20260825110001) already restricts a source to specific groups/members via
-- has_evidence_access, but a locked-out member has no way to even learn a
-- restricted source exists, let alone ask for it. This table is the
-- request/decision record; the notification itself reuses project_notes
-- (context_type = 'resource_access_request', context_id = this row's id) --
-- no new project_notes RLS policy needed, since the requester is always
-- already a project member (project_notes_insert_member already covers it).
create table resource_access_requests (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  resource_type text not null check (resource_type in ('knowledge_source', 'wiki_article', 'workstream_artifact')),
  resource_id uuid not null,
  requester_id uuid not null references profiles(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'approved', 'denied')),
  note_id uuid references project_notes(id) on delete set null,
  outcome_note_id uuid references project_notes(id) on delete set null,
  decided_by uuid references profiles(id) on delete set null,
  decision_reason text,
  decided_at timestamptz,
  created_at timestamptz not null default now()
);

create index resource_access_requests_project_id_idx on resource_access_requests(project_id);
create index resource_access_requests_resource_idx on resource_access_requests(resource_type, resource_id);
create index resource_access_requests_requester_id_idx on resource_access_requests(requester_id);

alter table resource_access_requests enable row level security;

-- Any active project member of any role can request -- same is_project_member
-- gate as project_notes_insert_member, not can_manage_project.
create policy "resource_access_requests_insert_member" on resource_access_requests
  for insert to authenticated
  with check (
    requester_id = auth.uid()
    and is_project_member(project_id, auth.uid())
  );

-- The requester sees their own requests (so the UI can seed "already
-- requested" state); the decision-maker (owner/admin, can_manage_project --
-- same boundary as resource_access_grants itself) sees every request for
-- their project.
create policy "resource_access_requests_select_own_or_manager" on resource_access_requests
  for select using (
    requester_id = auth.uid()
    or can_manage_project(project_id, auth.uid())
  );

-- Only the decision-maker can move a request out of pending.
create policy "resource_access_requests_update_manager" on resource_access_requests
  for update
  using (can_manage_project(project_id, auth.uid()))
  with check (can_manage_project(project_id, auth.uid()));


-- ==== supabase/migrations/20260903100001_curator_manages_project_members.sql ====
-- Curator = department head (or their assistant) running their own team's
-- project, confirmed by Mike 2026-09-03: they know their staff and what
-- those staff are working on, and need to invite them into the project
-- directly rather than bouncing every invite through the project owner or
-- a platform admin. project_members_manage_owner (20260810120001) only let
-- 'owner' (or platform admin) touch project_members at all -- too narrow
-- for that.
--
-- Additive policy (OR'd with project_members_manage_owner): a curator can
-- manage any member row EXCEPT the owner's own row, and can never set a
-- row's role to 'owner' -- both directions of ownership stay exclusively
-- an owner/admin action (see transferOwnershipAction in
-- src/lib/workbench/projects.ts), never something a curator can grant to
-- themselves or anyone else.
create policy "project_members_curate" on project_members
  for all using (can_curate_project(project_id, auth.uid()) and role <> 'owner')
  with check (can_curate_project(project_id, auth.uid()) and role <> 'owner');


-- ==== supabase/migrations/20260904100001_project_source_submissions.sql ====
-- Member-submitted knowledge sources, with project-curator approval.
-- Adding anything to a knowledge base has always required *platform*
-- curator/admin role (is_curator_or_admin, e.g. documents_insert_staff) --
-- project role was never consulted, so a Project owner whose platform role
-- is merely 'member'/'consultant' could not add anything to their own
-- project's KB, and an ordinary member had no way to propose a source at
-- all. This table is the propose/decide record, modeled on
-- resource_access_requests (20260901130001) but deliberately gated on
-- can_curate_project (owner-or-curator) rather than can_manage_project
-- (owner-only) -- the confirmed model is that a project's curator is the
-- department head who decides what enters their own team's knowledge, the
-- same authority already extended to project-membership management in
-- 20260903100001_curator_manages_project_members.sql.
--
-- Deliberately does NOT touch RLS on documents/knowledge_sources/
-- document_chunks/kb_vectors -- those stay is_curator_or_admin-only,
-- unchanged. Every privilege-crossing write this table's workflow needs
-- (a member with no RLS path into those tables at all; a project curator
-- without platform-curator standing) goes through an explicitly-checked
-- service-role code path instead (src/lib/workbench/source-submissions.ts),
-- same pattern as createAndAddProjectMember.
create table project_source_submissions (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  knowledge_base_id text not null references knowledge_bases(id) on delete cascade,
  source_kind text not null check (source_kind in ('file', 'artifact')),
  title text not null,
  -- file-kind: set at submission time (the document/knowledge_source is
  -- created immediately, left unparsed, so a file is only ever uploaded to
  -- storage once -- see submitFileSource). artifact-kind: left null until
  -- approval, since an approved workstream artifact's content is copied
  -- into a new document only when a decision is made.
  document_id uuid references documents(id) on delete set null,
  -- artifact-kind only -- the already-approved workstream artifact this
  -- submission is proposing to copy into the project's KB.
  workstream_artifact_id uuid references workstream_artifacts(id) on delete set null,
  submitted_by uuid not null references profiles(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  decision_reason text,
  decided_by uuid references profiles(id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  check (
    (source_kind = 'file' and workstream_artifact_id is null)
    or (source_kind = 'artifact' and workstream_artifact_id is not null)
  )
);

create index project_source_submissions_project_id_idx on project_source_submissions(project_id);
create index project_source_submissions_status_idx on project_source_submissions(project_id, status);

alter table project_source_submissions enable row level security;

-- Any active project member of any role can submit -- same is_project_member
-- gate as resource_access_requests_insert_member.
create policy "project_source_submissions_insert_member" on project_source_submissions
  for insert to authenticated
  with check (
    submitted_by = auth.uid()
    and is_project_member(project_id, auth.uid())
  );

-- The submitter sees their own submissions (so the UI can show status); the
-- project's owner/curator/admin (can_curate_project) sees every submission
-- for their project -- deliberately curator-inclusive, unlike
-- resource_access_requests' owner-only can_manage_project.
create policy "project_source_submissions_select_own_or_curator" on project_source_submissions
  for select using (
    submitted_by = auth.uid()
    or can_curate_project(project_id, auth.uid())
  );

-- Only the project's owner/curator/admin can move a submission out of
-- pending.
create policy "project_source_submissions_decide_curator" on project_source_submissions
  for update
  using (can_curate_project(project_id, auth.uid()))
  with check (can_curate_project(project_id, auth.uid()));


-- ==== supabase/migrations/20260904110001_project_starter_prompt.sql ====
-- Per-project starter prompt for Ember (2026-09-04). The Sandz Pilot
-- Meeting Brief's suggested onboarding pattern (docs/commercial/Sandz-
-- Pilot-Meeting-Brief-and-Follow-Up-QA.docx, section 6) explicitly asks
-- for "a visible starter prompt" on a Project's Q&A/feedback experience --
-- generic across the whole platform, not something a curator can set for
-- their own Project today (ChatPanel.tsx's STARTER_PROMPTS is one hardcoded
-- global list). No RLS needed here: updateProjectStarterPrompt
-- (src/lib/workbench/projects.ts) writes it via the admin client after an
-- explicit owner/curator/admin check, same pattern as
-- createAndAddProjectMember and approveSourceSubmission -- deliberately not
-- relying on projects_update_managers (can_manage_project, owner-only),
-- since a project curator should be able to set this for their own team's
-- Project.
alter table projects add column starter_prompt text;


-- ==== supabase/migrations/20260904120001_project_portfolio_category.sql ====
-- Projects list declutter (2026-09-04, Mike): "My Projects" grouped into
-- three buckets -- Foundational (product/general AI R&D), Project-specific
-- (a named client/programme), Others -- instead of one flat grid.
--
-- Deliberately a new, explicit column rather than a relabeling of
-- project_type: the two axes don't line up. "KB Sandbox -- API Discovery"
-- is project_type='transformation' but is clearly foundational (it's about
-- the product itself, not a client); "CareCall -- API Modernization
-- Assessment" and "OrderLunch Agent" are project_type='experiment' but are
-- specific named case-study clients, not general AI experiments. A straight
-- type->bucket mapping would misclassify both live today.
--
-- default 'other' so every new project starts in the safe, always-correct
-- bucket rather than a guessed one. RLS: no new policy needed --
-- updateProjectPortfolioCategory (src/lib/workbench/projects.ts) writes it
-- via the admin client after an explicit owner/curator/admin check, same
-- pattern as starter_prompt (20260904110001) and for the same reason: a
-- project curator should be able to tag their own team's Project, not just
-- its owner (projects_update_managers/can_manage_project is owner-only).
alter table projects add column portfolio_category text not null default 'other'
  check (portfolio_category in ('foundational', 'project_specific', 'other'));

-- One-time best-guess backfill for the 44 projects that existed before this
-- column did, so the split isn't "44 things dumped in Others" on day one.
-- Exact-name-matched, not a fuzzy/pattern rule (so it can never mis-tag a
-- future project with a similar name) -- Mike reviews/corrects these once
-- via the new per-project selector, they are not meant to be authoritative
-- forever. Two clear signals only, everything else stays the safe 'other'
-- default:
--   1. A named real-world client/case-study in the title (Sandz, Zadara,
--      CareCall, KABATONE, OrderLunch, the Food Outlet showcase) ->
--      project_specific.
--   2. A clearly generic, no-named-client AI/methodology R&D exercise, or
--      the product's own dogfooding (KB Sandbox itself) -> foundational.
update projects set portfolio_category = 'project_specific' where name in (
  'Sandz–Zadara Pilot — Governance and Evaluation',
  'Sandz–Zadara Pilot — Call Center Support',
  'Sandz–Zadara Pilot — Sales Proposals',
  'Sandz HR Knowledge Base',
  'Sandz Pilot Feedback and Q&A',
  'CareCall — API Modernization Assessment',
  'KABATONE Visual/Edge AI',
  'Food Outlet AI-Readiness Showcase',
  'OrderLunch Agent (Lunch Agent)'
);

update projects set portfolio_category = 'foundational' where name in (
  'RAG Retrieval Exercise',
  'RAG vs Raw Chunk Retrieval',
  'Single Pass vs. Graph Retry',
  'Vendor/Product Evaluation',
  'AI Model Selection',
  'Code Review',
  'AI Infrastructure Benchmark',
  'AI Governance Exercise',
  'KB Sandbox — API Discovery'
);


