-- ==== supabase/migrations/20260904140001_project_join_requests.sql ====
-- Organization Home Project, Project directory, and join requests (OR-036).
-- Mike couldn't find "Sandz General" (it's a knowledge base, not a project)
-- and a colleague independently filed a dev request for the same real gap
-- at scale (docs/dev-request-organization-home-project-directory-and-join-
-- requests.md). This migration adds the two new project-level columns, the
-- join-request table, and seeds the real Sandz Organization Home project.
--
-- Deliberately reuses 'platform' (not a new 'organization' value) for
-- discoverability -- wiki_articles.visibility_scope briefly had an
-- 'organization' value and it was removed (20260824160001) because this
-- schema has no organizations/tenant table; a single-tenant deployment's
-- "everyone in this instance" is already what 'platform' means elsewhere
-- (knowledge_bases.visibility_scope, wiki_articles.visibility_scope).
--
-- No change to projects_select_members RLS (is_project_member -- active
-- member of any role, or platform admin). A genuinely new user still can't
-- SELECT a discoverable project's row through the normal RLS-scoped client;
-- that's served the same way /projects/portfolio already serves org-wide
-- safe metadata to non-members -- an explicit-check-then-admin-client-query
-- service function (listDiscoverableProjects), never a broadened policy.
alter table projects add column discoverability text not null default 'members_only'
  check (discoverability in ('platform', 'members_only'));
alter table projects add column is_organization_home boolean not null default false;

-- Mirrors resource_access_requests (20260901130001) almost exactly -- same
-- status/decision-audit shape, same service-function split (request/decide),
-- same notify-via-project_notes side channel. The one deliberate difference
-- is the insert policy below: resource_access_requests_insert_member
-- requires the requester already be a project member (that feature is for
-- members locked out of a restricted resource); this feature is for people
-- who are NOT project members yet, so insert is gated on the project being
-- either already visible to them or explicitly discoverable instead.
create table project_join_requests (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  requester_id uuid not null references profiles(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'approved', 'declined', 'cancelled')),
  note_id uuid references project_notes(id) on delete set null,
  outcome_note_id uuid references project_notes(id) on delete set null,
  decided_by uuid references profiles(id) on delete set null,
  decision_reason text,
  decided_at timestamptz,
  created_at timestamptz not null default now()
);

create index project_join_requests_project_id_idx on project_join_requests(project_id);
create index project_join_requests_requester_id_idx on project_join_requests(requester_id);

alter table project_join_requests enable row level security;

-- A real DB-level guarantee (not just an app-layer check) that a join
-- request can only ever be filed for a project the requester can already
-- see, or one that's explicitly discoverable -- directly satisfies the dev
-- request's "A user cannot request access to a non-discoverable Project
-- they cannot already see."
create policy "project_join_requests_insert_self" on project_join_requests
  for insert to authenticated
  with check (
    requester_id = auth.uid()
    and (
      is_project_member(project_id, auth.uid())
      or exists (select 1 from projects p where p.id = project_id and p.discoverability = 'platform')
    )
  );

-- Requester sees their own (so the UI can seed "request pending" state);
-- the decision-maker sees every request for their Project. can_curate_project
-- (owner or curator), not can_manage_project (owner-only) -- the dev request
-- explicitly says "Project owner or a Project curator may approve or
-- decline."
create policy "project_join_requests_select_own_or_manager" on project_join_requests
  for select using (
    requester_id = auth.uid()
    or can_curate_project(project_id, auth.uid())
  );

create policy "project_join_requests_update_manager" on project_join_requests
  for update
  using (can_curate_project(project_id, auth.uid()))
  with check (can_curate_project(project_id, auth.uid()));

-- Seed the real Sandz Organization Home project so the feature is live for
-- the actual pilot, not just a code path nobody has used yet. Content per
-- the dev request's own "Suggested organization-home content" section.
-- projects has no unique constraint on name (duplicate-named seed/example
-- rows already exist elsewhere), so idempotency here is a where-not-exists
-- guard, not on conflict.
insert into projects (name, project_type, objective, status, owner_id, discoverability, is_organization_home, starter_prompt, details)
select
  'Sandz — Organization Home',
  'transformation',
  'The main governed entry point for Sandz users: explains what Sandz does, how Sandz uses KB Sandbox, how Projects and Knowledge Bases relate, who owns or curates each discoverable Project, and how to request access or ask for a missing Project/FAQ.',
  'active',
  p.id,
  'platform',
  true,
  'Ask about Sandz, find the right Project, or request access to a team workspace.',
  '{}'::jsonb
from profiles p
where p.email = 'mikecolligodata@gmail.com'
  and not exists (select 1 from projects existing where existing.is_organization_home = true);

-- Attach the Sandz General knowledge base to it -- the KB stays a KB, the
-- Project is the real entry point, per the dev request's explicit "the
-- Project -- not the KB -- provides the directory and membership request
-- experience."
insert into project_knowledge_bases (project_id, knowledge_base_id, attached_by)
select proj.id, 'sandz-general', proj.owner_id
from projects proj
where proj.is_organization_home = true and proj.name = 'Sandz — Organization Home'
on conflict do nothing;

-- The pilot-facing Projects the dev request names as safe to discover --
-- everything else keeps the safe 'members_only' default.
update projects set discoverability = 'platform' where name in (
  'Sandz Pilot Feedback and Q&A',
  'Sandz HR Knowledge Base',
  'Sandz–Zadara Pilot — Sales Proposals',
  'Sandz–Zadara Pilot — Governance and Evaluation',
  'Sandz–Zadara Pilot — Call Center Support'
);


-- ==== supabase/migrations/20260904150001_fix_project_join_requests_insert_rls.sql ====
-- Fix for a real bug caught live 2026-09-04: project_join_requests_insert_self
-- (20260904140001) checked discoverability with a raw
-- `exists (select 1 from projects p where p.id = project_id and
-- p.discoverability = 'platform')` subquery -- but that subquery runs under
-- the CALLER's own RLS on `projects` (projects_select_members: active member
-- of any role, or platform admin), not bypassing it. A genuinely new,
-- non-member user -- exactly who this feature is for -- can never see that
-- project's row through their own RLS, so the subquery always came back
-- empty and every join-request insert failed with a raw Postgres 42501
-- (insufficient_privilege), caught live attempting to request to join
-- "Sandz Pilot Feedback and Q&A" as a fresh test account.
--
-- Same fix shape as is_project_member/can_manage_project/can_curate_project
-- themselves (20260810120001_project_members.sql): a `security definer`
-- helper function bypasses RLS for this one narrow, already-safe check
-- (discoverability is meant to be checkable by definition -- that's the
-- entire point of the column) rather than widening any RLS policy.
create or replace function is_project_discoverable(pid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from projects p where p.id = pid and p.discoverability = 'platform');
$$;

drop policy "project_join_requests_insert_self" on project_join_requests;
create policy "project_join_requests_insert_self" on project_join_requests
  for insert to authenticated
  with check (
    requester_id = auth.uid()
    and (
      is_project_member(project_id, auth.uid())
      or is_project_discoverable(project_id)
    )
  );


-- ==== supabase/migrations/20260904160001_workstream_artifact_type_research_dossier.sql ====
-- Adds research_dossier as a first-class workstream_artifacts type -- Ember's
-- web-research findings (via the search_web tool), proposed for human
-- curator review before becoming real project knowledge. Purely additive:
-- no existing value is renamed or removed, so every historical row stays
-- valid. Same drop-and-recreate pattern as
-- 20260818100001_workstream_artifact_type_design_note.sql.
alter table workstream_artifacts drop constraint workstream_artifacts_artifact_type_check;
alter table workstream_artifacts add constraint workstream_artifacts_artifact_type_check
  check (artifact_type in (
    'capability_inventory', 'endpoint_inventory', 'openapi_spec', 'mcp_server',
    'evidence_map', 'test_results', 'findings', 'design_note', 'implementation_handoff',
    'research_dossier', 'other'
  ));


-- ==== supabase/migrations/20260905100001_working_knowledge_schema.sql ====
-- Working Knowledge & Research Notebooks, Stage 1+2
-- (docs/dev-request-project-scoped-working-knowledge-and-research-notebooks.md).
-- A persistent, Project-scoped research/notes layer Ember can save findings
-- to and later retrieve for conversational continuity -- distinct from
-- approved Wiki/knowledge-base evidence, and never presented as such. Not
-- merged into the Ember role-directed shell work -- its own schema/RLS/tests
-- per the dev request's own instruction.
--
-- No working_knowledge_promotions table -- that's Stage 3 (curation
-- promotion), explicitly deferred; nothing here builds submission/freeze/
-- snapshot logic. trust_status's full six-value domain is still declared now
-- (cheap, forward-compatible) even though only 'working'/'archived'/
-- 'superseded' are reachable via app logic this increment.

create table working_knowledge_items (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  owner_id uuid not null references profiles(id) on delete cascade,
  type text not null check (type in ('research_notebook', 'working_note')),
  title text not null,
  objective text,
  content text not null,
  -- 'shared_selected' means specific named recipients via
  -- working_knowledge_shares below; 'shared_project' is a single flag on the
  -- item itself (every active Project member), not a share row per member --
  -- simpler than a literal "Project-wide share marker" row for the same
  -- effective behavior.
  visibility text not null default 'private' check (visibility in ('private', 'shared_selected', 'shared_project')),
  trust_status text not null default 'working' check (trust_status in ('working', 'submitted', 'returned', 'promoted', 'superseded', 'archived')),
  source_conversation_id uuid references conversations(id) on delete set null,
  source_workstream_id uuid references project_workstreams(id) on delete set null,
  source_artifact_id uuid references workstream_artifacts(id) on delete set null,
  synthesis_provider text,
  synthesis_model text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  last_used_at timestamptz,
  refresh_after timestamptz,
  archived_at timestamptz
);

create index working_knowledge_items_project_id_idx on working_knowledge_items(project_id);
create index working_knowledge_items_owner_id_idx on working_knowledge_items(owner_id);

create trigger working_knowledge_items_set_updated_at before update on working_knowledge_items
  for each row execute function set_updated_at();

-- One row per cited web source on a notebook -- bounded excerpt/fingerprint
-- only, never a full page mirror, matching the dev request's copyright/
-- retention guidance.
create table working_knowledge_sources (
  id uuid primary key default gen_random_uuid(),
  item_id uuid not null references working_knowledge_items(id) on delete cascade,
  url text not null,
  domain text,
  title text,
  published_date date,
  retrieved_at timestamptz not null default now(),
  excerpt text,
  content_fingerprint text,
  claim_status text check (claim_status in ('unconfirmed', 'corroborated', 'conflicting', 'customer_confirmed')),
  created_at timestamptz not null default now()
);

create index working_knowledge_sources_item_id_idx on working_knowledge_sources(item_id);

-- Named-recipient shares only (visibility='shared_selected'). Revoking flips
-- status + revoked_by/at/reason in place (never deleted); re-sharing after a
-- revoke inserts a fresh row -- same convention as resource_access_grants
-- (20260825100001_project_evidence_access_schema.sql:112-128).
create table working_knowledge_shares (
  id uuid primary key default gen_random_uuid(),
  item_id uuid not null references working_knowledge_items(id) on delete cascade,
  recipient_user_id uuid not null references profiles(id) on delete cascade,
  status text not null default 'active' check (status in ('active', 'revoked')),
  granted_by uuid references profiles(id) on delete set null,
  granted_at timestamptz not null default now(),
  revoked_by uuid references profiles(id) on delete set null,
  revoked_at timestamptz,
  revocation_reason text
);

create index working_knowledge_shares_item_id_idx on working_knowledge_shares(item_id);
create index working_knowledge_shares_recipient_idx on working_knowledge_shares(recipient_user_id);

-- The one subtle, acceptance-criteria-critical point: the viewer must be a
-- CURRENTLY ACTIVE Project member on every branch, including the owner's own
-- notebook -- removing the creator's own membership must immediately revoke
-- their own access too (dev request acceptance criterion 7), not just other
-- people's. Uses is_project_member_strict (no is_admin bypass), never plain
-- is_project_member (which silently grants any admin true) -- a platform
-- admin must never see private/shared_project content just by holding that
-- role (acceptance criteria 3, 6).
create or replace function can_view_working_knowledge_item(p_item_id uuid, p_uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from working_knowledge_items i
    where i.id = p_item_id
      and is_project_member_strict(i.project_id, p_uid)
      and (
        i.owner_id = p_uid
        or i.visibility = 'shared_project'
        or exists (
          select 1 from working_knowledge_shares s
          where s.item_id = i.id and s.recipient_user_id = p_uid and s.status = 'active'
        )
      )
  );
$$;

alter table working_knowledge_items enable row level security;
alter table working_knowledge_sources enable row level security;
alter table working_knowledge_shares enable row level security;

create policy "working_knowledge_items_select_visible" on working_knowledge_items
  for select using (can_view_working_knowledge_item(id, auth.uid()));

-- Subquery-free companion, same reason project_notes_select_own exists
-- (20260814120001_project_notes.sql:74-80): can_view_working_knowledge_item
-- re-queries this table internally, whose subquery snapshot doesn't see a
-- row still mid-INSERT, so a plain .insert().select() would otherwise fail
-- RLS for the row it just created.
create policy "working_knowledge_items_select_own" on working_knowledge_items
  for select using (owner_id = auth.uid());

create policy "working_knowledge_items_insert_owner" on working_knowledge_items
  for insert to authenticated
  with check (owner_id = auth.uid() and is_project_member_strict(project_id, auth.uid()));

-- Owner-only edits -- "Project-shared notebooks may initially be
-- owner-editable and read-only to recipients" per the dev request.
create policy "working_knowledge_items_update_owner" on working_knowledge_items
  for update using (owner_id = auth.uid()) with check (owner_id = auth.uid());

create policy "working_knowledge_sources_select_visible" on working_knowledge_sources
  for select using (can_view_working_knowledge_item(item_id, auth.uid()));

create policy "working_knowledge_sources_manage_owner" on working_knowledge_sources
  for all using (
    exists (select 1 from working_knowledge_items i where i.id = working_knowledge_sources.item_id and i.owner_id = auth.uid())
  )
  with check (
    exists (select 1 from working_knowledge_items i where i.id = working_knowledge_sources.item_id and i.owner_id = auth.uid())
  );

-- A recipient can see their own grant (so "shared with me" is listable); only
-- the parent item's owner can create/revoke shares.
create policy "working_knowledge_shares_select_owner_or_recipient" on working_knowledge_shares
  for select using (
    recipient_user_id = auth.uid()
    or exists (select 1 from working_knowledge_items i where i.id = working_knowledge_shares.item_id and i.owner_id = auth.uid())
  );

create policy "working_knowledge_shares_manage_owner" on working_knowledge_shares
  for insert to authenticated
  with check (
    granted_by = auth.uid()
    and exists (select 1 from working_knowledge_items i where i.id = working_knowledge_shares.item_id and i.owner_id = auth.uid())
  );

create policy "working_knowledge_shares_revoke_owner" on working_knowledge_shares
  for update using (
    exists (select 1 from working_knowledge_items i where i.id = working_knowledge_shares.item_id and i.owner_id = auth.uid())
  )
  with check (
    exists (select 1 from working_knowledge_items i where i.id = working_knowledge_shares.item_id and i.owner_id = auth.uid())
  );


-- ==== supabase/migrations/20260905100002_working_knowledge_shares_recipient_membership.sql ====
-- Strengthens working_knowledge_shares_manage_owner: the recipient must be a
-- currently active member of the item's own Project, enforced in RLS itself
-- (not just app-layer), matching project_notes_insert_member's exact
-- "recipient must be a Project member" precedent
-- (20260814120001_project_notes.sql:82-88) -- dev request invariant 5,
-- "Sharing is explicit, revocable and restricted to active members of the
-- same Project."
drop policy "working_knowledge_shares_manage_owner" on working_knowledge_shares;
create policy "working_knowledge_shares_manage_owner" on working_knowledge_shares
  for insert to authenticated
  with check (
    granted_by = auth.uid()
    and exists (
      select 1 from working_knowledge_items i
      where i.id = working_knowledge_shares.item_id
        and i.owner_id = auth.uid()
        and is_project_member_strict(i.project_id, recipient_user_id)
    )
  );


-- ==== supabase/migrations/20260905100003_working_knowledge_owner_policies_require_active_membership.sql ====
-- Closes a live-verified gap in every owner-only policy across all three
-- Working Knowledge tables: each checked only owner_id/granted_by = auth.uid(),
-- never whether that owner is STILL a currently active member of the item's
-- own Project. Since RLS SELECT/UPDATE policies are ORed together, this let
-- an owner who has been removed from the Project keep reading, editing,
-- archiving, and managing sources/shares on their own now-orphaned notebook
-- via these owner-branch policies -- even though can_view_working_knowledge_item
-- (the *_select_visible policies) already correctly requires
-- is_project_member_strict on every branch. Live-verified against the real
-- database (not just the SQL-shape unit tests) with a disposable Project:
-- demoting the owner's own project_members row to 'inactive' left them still
-- able to select their own item until this fix. Dev request acceptance
-- criterion 7: "Removing the creator's Project membership prevents Ember
-- retrieval and direct access immediately" -- "immediately" and "direct
-- access" cover every one of these five policies, not only Ember's own
-- retrieval tools (which already went through working_knowledge_items_select_own).

drop policy "working_knowledge_items_select_own" on working_knowledge_items;
create policy "working_knowledge_items_select_own" on working_knowledge_items
  for select using (owner_id = auth.uid() and is_project_member_strict(project_id, auth.uid()));

drop policy "working_knowledge_items_update_owner" on working_knowledge_items;
create policy "working_knowledge_items_update_owner" on working_knowledge_items
  for update
  using (owner_id = auth.uid() and is_project_member_strict(project_id, auth.uid()))
  with check (owner_id = auth.uid() and is_project_member_strict(project_id, auth.uid()));

drop policy "working_knowledge_sources_manage_owner" on working_knowledge_sources;
create policy "working_knowledge_sources_manage_owner" on working_knowledge_sources
  for all using (
    exists (
      select 1 from working_knowledge_items i
      where i.id = working_knowledge_sources.item_id and i.owner_id = auth.uid() and is_project_member_strict(i.project_id, auth.uid())
    )
  )
  with check (
    exists (
      select 1 from working_knowledge_items i
      where i.id = working_knowledge_sources.item_id and i.owner_id = auth.uid() and is_project_member_strict(i.project_id, auth.uid())
    )
  );

drop policy "working_knowledge_shares_manage_owner" on working_knowledge_shares;
create policy "working_knowledge_shares_manage_owner" on working_knowledge_shares
  for insert to authenticated
  with check (
    granted_by = auth.uid()
    and exists (
      select 1 from working_knowledge_items i
      where i.id = working_knowledge_shares.item_id
        and i.owner_id = auth.uid()
        and is_project_member_strict(i.project_id, auth.uid())
        and is_project_member_strict(i.project_id, recipient_user_id)
    )
  );

drop policy "working_knowledge_shares_revoke_owner" on working_knowledge_shares;
create policy "working_knowledge_shares_revoke_owner" on working_knowledge_shares
  for update using (
    exists (
      select 1 from working_knowledge_items i
      where i.id = working_knowledge_shares.item_id and i.owner_id = auth.uid() and is_project_member_strict(i.project_id, auth.uid())
    )
  )
  with check (
    exists (
      select 1 from working_knowledge_items i
      where i.id = working_knowledge_shares.item_id and i.owner_id = auth.uid() and is_project_member_strict(i.project_id, auth.uid())
    )
  );


-- ==== supabase/migrations/20260905100004_project_notes_author_policies_require_active_membership.sql ====
-- Same owner-fallback gap just found and fixed in Working Knowledge
-- (20260905100003), confirmed present here too: project_notes_select_own and
-- project_notes_resolve's author_id branch check only author_id = auth.uid(),
-- never whether that author is STILL a currently active Project member.
-- Since Postgres OR-combines permissive RLS policies, an author removed from
-- the Project could keep reading and resolving their own note via these
-- fallback branches, even though project_notes_select_visible's
-- can_view_project_note helper already requires is_project_member on every
-- other branch. docs/dev-request-role-aware-project-views-and-ember-first-
-- workspace.md is explicit and general, not Working-Knowledge-specific:
-- "Revoking or suspending membership must remove the Project from the
-- user's view and prevent further project-bound retrieval immediately"
-- (line 74) and acceptance criterion 9, "Revoking membership immediately
-- removes listing, page and Ember access."
--
-- Deliberately NOT touching can_view_project_note itself or the other
-- project_notes_resolve branches (recipient_type = 'curator'/'admin' via
-- can_curate_project/is_admin) -- those already encode intentional
-- curator/admin oversight regardless of membership ("curator/owner oversight,
-- regardless of recipient_type", the function's own comment), a different,
-- deliberate design from the author-only fallback this migration closes.
-- Uses is_project_member_strict (never plain is_project_member, which has
-- its own admin bypass) so this holds even for an author who happens to also
-- be a platform admin -- matching the Working Knowledge fix's precedent.

drop policy "project_notes_select_own" on project_notes;
create policy "project_notes_select_own" on project_notes
  for select using (author_id = auth.uid() and is_project_member_strict(project_id, auth.uid()));

drop policy "project_notes_resolve" on project_notes;
create policy "project_notes_resolve" on project_notes
  for update
  using (
    (author_id = auth.uid() and is_project_member_strict(project_id, auth.uid()))
    or (recipient_type = 'user' and recipient_user_id = auth.uid())
    or (recipient_type = 'curator' and can_curate_project(project_id, auth.uid()))
    or (recipient_type = 'admin' and is_admin(auth.uid()))
    or can_curate_project(project_id, auth.uid())
  )
  with check (
    (author_id = auth.uid() and is_project_member_strict(project_id, auth.uid()))
    or (recipient_type = 'user' and recipient_user_id = auth.uid())
    or (recipient_type = 'curator' and can_curate_project(project_id, auth.uid()))
    or (recipient_type = 'admin' and is_admin(auth.uid()))
    or can_curate_project(project_id, auth.uid())
  );


-- ==== supabase/migrations/20260905110001_source_submissions_working_knowledge_kind.sql ====
-- KB Sandbox Builder MVP (docs/dev-request-kb-sandbox-builder-product.md):
-- lets a builder submit a Working Knowledge notebook for curator review
-- into a Knowledge Base -- most concretely, the operator's Organization Home
-- Project KB (docs/dev-request-organization-home-project-directory-and-
-- join-requests.md), the shared destination every builder auto-enrolls
-- into as a viewer. Mirrors the existing 'artifact' source_kind exactly
-- (20260904100001_project_source_submissions.sql): content is snapshotted
-- only at approval time, not at submission time, same as an artifact.

alter table project_source_submissions
  add column working_knowledge_item_id uuid references working_knowledge_items(id) on delete set null;

alter table project_source_submissions drop constraint project_source_submissions_source_kind_check;
alter table project_source_submissions add constraint project_source_submissions_source_kind_check
  check (source_kind = any (array['file', 'artifact', 'working_knowledge']));

alter table project_source_submissions drop constraint project_source_submissions_check;
alter table project_source_submissions add constraint project_source_submissions_check
  check (
    (source_kind = 'file' and workstream_artifact_id is null and working_knowledge_item_id is null)
    or (source_kind = 'artifact' and workstream_artifact_id is not null and working_knowledge_item_id is null)
    or (source_kind = 'working_knowledge' and workstream_artifact_id is null and working_knowledge_item_id is not null)
  );


-- ==== supabase/migrations/20260906100001_workstream_promotions_schema.sql ====
-- KB Sandbox Builder: workstream promotion (business-process handoff, not
-- docs/dev-request-builder-capability-promotion-evaluation-templates.md's
-- separate technical certification ladder). A builder submits a completed
-- Workstream for review; on approval, a new customer-facing Project is
-- created rather than the builder's own private Project being exposed.
--
-- The one genuinely new RLS shape here (see can_curate_project everywhere
-- else in this codebase): deciding a promotion must be gated on
-- is_curator_or_admin (platform-level, 20260808190009_functions.sql), never
-- can_curate_project -- a builder IS the owner of their own Project, so
-- can_curate_project would let them approve their own promotion.
create table workstream_promotions (
  id uuid primary key default gen_random_uuid(),
  workstream_id uuid not null references project_workstreams(id) on delete cascade,
  submitted_by uuid not null references profiles(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  decision_reason text,
  decided_by uuid references profiles(id) on delete set null,
  decided_at timestamptz,
  created_project_id uuid references projects(id) on delete set null,
  created_at timestamptz not null default now()
);

create index workstream_promotions_workstream_id_idx on workstream_promotions(workstream_id);
create index workstream_promotions_status_idx on workstream_promotions(status);

alter table workstream_promotions enable row level security;

-- Only the workstream's own Project owner (the builder) may submit --
-- mirrors project_source_submissions_insert_member's "submitted_by = self"
-- shape, but scoped to can_manage_project (owner-only) rather than
-- is_project_member (any role), since only the sole builder-owner should
-- ever be proposing their own graduation.
create policy "workstream_promotions_insert_owner" on workstream_promotions
  for insert to authenticated
  with check (
    submitted_by = auth.uid()
    and exists (
      select 1 from project_workstreams w
      where w.id = workstream_id and can_manage_project(w.project_id, auth.uid())
    )
  );

-- The submitter sees their own submissions; is_curator_or_admin (platform-
-- level, not project-scoped) sees every pending promotion across every
-- builder -- the review queue is necessarily cross-Project.
create policy "workstream_promotions_select_own_or_operator" on workstream_promotions
  for select using (
    submitted_by = auth.uid()
    or is_curator_or_admin(auth.uid())
  );

create policy "workstream_promotions_decide_operator" on workstream_promotions
  for update
  using (is_curator_or_admin(auth.uid()))
  with check (is_curator_or_admin(auth.uid()));


-- ==== supabase/migrations/20260906100002_workstream_promotions_generalize.sql ====
-- Generalizes Workstream Promotion (20260906100001) beyond Builder mode.
-- The original version scoped insert to the workstream's Project *owner*
-- and decide to platform-level is_curator_or_admin -- both correct for a
-- Builder's single-member Project, both wrong for an ordinary Enterprise
-- team Project (e.g. an HR Manager who is a project-level `curator` but
-- platform role merely `consultant`, with staff who are plain `member`/
-- `consultant` submitting the work, never the Project owner). /admin
-- itself is platform-admin-only, so is_curator_or_admin excluded that HR
-- Manager from ever reviewing at all.
--
-- The generalized, still-safe rule: decide requires can_curate_project
-- (project owner-or-curator, or platform admin via its own bypass) AND
-- submitted_by != auth.uid() -- this still blocks a Builder from
-- self-approving (they're both owner and submitter), still lets a platform
-- admin decide a Builder's solo-Project promotion, and now also lets any
-- team Project's real curator decide their own team's promotions.

drop policy "workstream_promotions_insert_owner" on workstream_promotions;
create policy "workstream_promotions_insert_member" on workstream_promotions
  for insert to authenticated
  with check (
    submitted_by = auth.uid()
    and exists (select 1 from project_workstreams w where w.id = workstream_id and is_project_member(w.project_id, auth.uid()))
  );

drop policy "workstream_promotions_select_own_or_operator" on workstream_promotions;
create policy "workstream_promotions_select_own_or_curator" on workstream_promotions
  for select using (
    submitted_by = auth.uid()
    or exists (select 1 from project_workstreams w where w.id = workstream_id and can_curate_project(w.project_id, auth.uid()))
  );

drop policy "workstream_promotions_decide_operator" on workstream_promotions;
create policy "workstream_promotions_decide_curator" on workstream_promotions
  for update
  using (
    submitted_by != auth.uid()
    and exists (select 1 from project_workstreams w where w.id = workstream_id and can_curate_project(w.project_id, auth.uid()))
  )
  with check (
    submitted_by != auth.uid()
    and exists (select 1 from project_workstreams w where w.id = workstream_id and can_curate_project(w.project_id, auth.uid()))
  );


-- ==== supabase/migrations/20260906110001_capability_evaluations_schema.sql ====
-- Builder Capability Promotion (docs/dev-request-builder-capability-
-- promotion-evaluation-templates.md): before a builder-produced capability
-- (MCP server/connector/agent) reaches a customer, it must pass
-- proportionate evidence-based evaluation. Distinct from Workstream
-- Promotion (business-process handoff) -- this certifies the *artifact*,
-- reusing the existing Builder Registry (builder_integration_versions,
-- 20260827150001_external_agent_registry.sql) and its live certification
-- ladder. The ladder itself is unchanged -- see that migration's own
-- rename comment for why 'outlet_accepted' stays the DB value for what
-- this doc calls "Customer Accepted."
--
-- One evidence row per template per version (confirmed with Mike --
-- combined evidence note, not itemized per-check tracking): the builder
-- writes one evidence_notes writeup covering the doc's own listed checks
-- for that template; a reviewer records one pass/conditional_pass/fail/
-- not_applicable decision + rationale for the whole template. Mirrors
-- workstream_artifacts.status's own draft -> ready_for_review ->
-- approved/rejected shape almost exactly (20260831130001).
create table capability_evaluations (
  id uuid primary key default gen_random_uuid(),
  builder_integration_version_id uuid not null references builder_integration_versions(id) on delete cascade,
  template_id text not null check (template_id in (
    'scope_evidence', 'functional_contract', 'identity_permissions',
    'human_decision', 'customer_acceptance', 'production_readiness'
  )),
  status text not null default 'draft'
    check (status in ('draft', 'ready_for_review', 'pass', 'conditional_pass', 'fail', 'not_applicable')),
  evidence_notes text,
  rationale text,
  reviewed_by uuid references profiles(id) on delete set null,
  reviewed_at timestamptz,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (builder_integration_version_id, template_id)
);

create index capability_evaluations_version_id_idx on capability_evaluations(builder_integration_version_id);

create trigger capability_evaluations_set_updated_at before update on capability_evaluations
  for each row execute function set_updated_at();

alter table capability_evaluations enable row level security;

-- Same "any Builder can browse the registry" bar as builder_integration_versions_select_authenticated.
create policy "capability_evaluations_select_authenticated" on capability_evaluations
  for select using (
    exists (select 1 from profiles p where p.id = auth.uid() and p.role <> 'anonymous' and p.is_active)
  );

-- Insert is the registering builder (of the parent integration) or staff --
-- same authorization shape as requireIntegrationManager in registry.ts.
create policy "capability_evaluations_insert_owner_or_staff" on capability_evaluations
  for insert to authenticated
  with check (
    created_by = auth.uid()
    and (
      is_curator_or_admin(auth.uid())
      or exists (
        select 1 from builder_integration_versions v
        join builder_integrations bi on bi.id = v.builder_integration_id
        where v.id = builder_integration_version_id and bi.created_by = auth.uid()
      )
    )
  );

-- The registering builder may edit their own evidence -- but the WITH CHECK
-- restricts status to the two non-terminal values, so even a raw API call
-- (not just the UI) cannot self-decide a gate. This is genuine RLS
-- enforcement, not just an app-layer convention -- Postgres has no
-- column-level RLS, so the terminal states must be excluded at the row
-- level for this policy specifically, leaving them reachable only via the
-- separate staff-only policy below.
create policy "capability_evaluations_update_owner_evidence" on capability_evaluations
  for update
  using (
    exists (
      select 1 from builder_integration_versions v
      join builder_integrations bi on bi.id = v.builder_integration_id
      where v.id = builder_integration_version_id and bi.created_by = auth.uid()
    )
  )
  with check (
    status in ('draft', 'ready_for_review')
    and exists (
      select 1 from builder_integration_versions v
      join builder_integrations bi on bi.id = v.builder_integration_id
      where v.id = builder_integration_version_id and bi.created_by = auth.uid()
    )
  );

-- Terminal decisions (pass/conditional_pass/fail/not_applicable) plus
-- rationale/reviewed_by/reviewed_at are staff-only -- matches
-- updateCertificationStatus's own "curator/admin only" bar exactly. A
-- Builder's platform role is always 'consultant', so this already excludes
-- them from ever deciding their own evaluation, by construction.
create policy "capability_evaluations_decide_staff" on capability_evaluations
  for update
  using (is_curator_or_admin(auth.uid()))
  with check (is_curator_or_admin(auth.uid()));


-- ==== supabase/migrations/20260906120001_builder_progress_updates_schema.sql ====
-- Builder Operations and Progress Updates (docs/dev-request-builder-
-- operations-and-progress-updates.md): a Builder explicitly drafts,
-- reviews and submits a progress update on one of their Workstreams; the
-- operator's Builder Operations view (platform curator/admin) reads these
-- alongside basic account/activity metadata. Never automatic -- nothing
-- here reads a private Working Knowledge notebook or Ember conversation.
--
-- One row per Workstream (not a history table) -- "replace" updates this
-- same row in place (matches "a Builder may replace or withdraw their
-- update until it becomes milestone evidence"); "withdraw" flips status
-- rather than deleting, so a withdrawn update stays auditable.
create table builder_progress_updates (
  id uuid primary key default gen_random_uuid(),
  workstream_id uuid not null references project_workstreams(id) on delete cascade,
  submitted_by uuid not null references profiles(id) on delete cascade,
  current_stage text not null,
  opportunity_label text,
  progress text not null,
  next_step text not null,
  help_requested text,
  confidence text not null check (confidence in ('on_track', 'at_risk', 'blocked')),
  status text not null default 'active' check (status in ('active', 'withdrawn')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workstream_id)
);

create trigger builder_progress_updates_set_updated_at before update on builder_progress_updates
  for each row execute function set_updated_at();

alter table builder_progress_updates enable row level security;

-- Insert/update restricted to the workstream's own Project owner (the
-- Builder -- in Builder mode there is only ever one member anyway, so
-- owner-only and any-active-member are equivalent in practice here; this
-- feature is deliberately not generalized to Enterprise team Projects the
-- way Workstream Promotion was, see that migration's own comment for why).
create policy "builder_progress_updates_insert_owner" on builder_progress_updates
  for insert to authenticated
  with check (
    submitted_by = auth.uid()
    and exists (select 1 from project_workstreams w where w.id = workstream_id and can_manage_project(w.project_id, auth.uid()))
  );

create policy "builder_progress_updates_update_owner" on builder_progress_updates
  for update
  using (
    exists (select 1 from project_workstreams w where w.id = workstream_id and can_manage_project(w.project_id, auth.uid()))
  )
  with check (
    exists (select 1 from project_workstreams w where w.id = workstream_id and can_manage_project(w.project_id, auth.uid()))
  );

-- An update is an explicitly shared, consent-based artifact (the whole
-- point of Share Builder Update) -- select for the submitter's own rows or
-- is_curator_or_admin (platform-level operator), not a leak.
create policy "builder_progress_updates_select_own_or_operator" on builder_progress_updates
  for select using (
    submitted_by = auth.uid()
    or is_curator_or_admin(auth.uid())
  );


-- ==== supabase/migrations/20260907100001_builder_ai_metering_schema.sql ====
-- Builder AI Usage Metering + Bring-Your-Own-LLM (BYOLLM). Closes the
-- "credits used and remaining" gap listBuilderOperationsRows
-- (src/lib/workbench/builder-progress-updates.ts) deliberately left blank --
-- "no metering infrastructure exists yet". Implements the "Credits and
-- metering" section of docs/dev-request-kb-sandbox-builder-product.md:
-- per-call cost, monthly allowance, manually-granted credit top-ups, and a
-- configurable stop threshold. Deliberately NOT the 5-milestone-triggered
-- automatic credit awards from that same doc -- the milestones themselves
-- don't exist yet, same deferral already on record for this whole
-- initiative.
--
-- BYOLLM lets a builder opt out of being metered entirely by supplying their
-- own provider credentials (or a local, keyless OpenAI-compatible server
-- like Ollama/LM Studio) -- this is the first table in this codebase to
-- store a real secret value (encrypted application-side; see
-- src/lib/ai/credential-crypto.ts). Every other "external credential"
-- pattern here (ai_providers.api_key_env_var, builder_integration_versions.
-- credentials_policy/auth_method) is deliberately reference-only.

alter table ai_operation_logs
  add column project_id uuid references projects(id) on delete set null,
  add column estimated_cost_usd numeric,
  add column is_byo_llm boolean not null default false;

create index ai_operation_logs_project_id_idx on ai_operation_logs(project_id);

-- One row per builder -- current allowance config. A missing row means "use
-- the platform-wide default" (a constant in application code, not a seeded
-- row per builder) -- same "don't fabricate a value" posture
-- listBuilderOperationsRows already uses for the fields it omits today.
create table builder_ai_allowances (
  builder_id uuid primary key references profiles(id) on delete cascade,
  monthly_allowance_usd numeric not null default 20,
  warning_threshold_pct numeric not null default 80 check (warning_threshold_pct between 0 and 100),
  stop_at_allowance boolean not null default true,
  current_period_start date not null default date_trunc('month', now())::date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger builder_ai_allowances_set_updated_at before update on builder_ai_allowances
  for each row execute function set_updated_at();

alter table builder_ai_allowances enable row level security;

-- A builder sees only their own allowance; platform curator/admin sees any --
-- same shape as builder_progress_updates_select_own_or_operator.
create policy "builder_ai_allowances_select_own_or_operator" on builder_ai_allowances
  for select using (builder_id = auth.uid() or is_curator_or_admin(auth.uid()));

-- Only staff ever sets/adjusts an allowance -- a builder cannot raise their
-- own cap.
create policy "builder_ai_allowances_manage_staff" on builder_ai_allowances
  for all using (is_curator_or_admin(auth.uid())) with check (is_curator_or_admin(auth.uid()));

-- Append-only ledger of manually-granted top-ups -- balance is always
-- computed as sum(amount_usd), never a stored mutable balance, same
-- audit-trail posture as builder_progress_updates' status-flip-not-delete
-- (nothing here is ever updated or deleted, only inserted).
create table builder_credit_grants (
  id uuid primary key default gen_random_uuid(),
  builder_id uuid not null references profiles(id) on delete cascade,
  amount_usd numeric not null check (amount_usd > 0),
  reason text not null,
  granted_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

create index builder_credit_grants_builder_id_idx on builder_credit_grants(builder_id);

alter table builder_credit_grants enable row level security;

create policy "builder_credit_grants_select_own_or_operator" on builder_credit_grants
  for select using (builder_id = auth.uid() or is_curator_or_admin(auth.uid()));

create policy "builder_credit_grants_insert_staff" on builder_credit_grants
  for insert to authenticated
  with check (granted_by = auth.uid() and is_curator_or_admin(auth.uid()));

-- One active BYOLLM configuration per builder (one row, not a history table
-- -- matches the existing "builder gets exactly one Project" simplicity
-- precedent). base_url is required for provider_type='openai_compatible'
-- (this is also how a local server like Ollama/LM Studio/vLLM is
-- configured -- OpenAICompatibleProvider already exists and already names
-- these as a future case). encrypted_api_key is nullable -- a local server
-- may need no key at all.
create table builder_llm_credentials (
  builder_id uuid primary key references profiles(id) on delete cascade,
  provider_type text not null check (provider_type in ('openai', 'gemini', 'groq', 'openai_compatible')),
  base_url text,
  model_id text not null,
  encrypted_api_key text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint builder_llm_credentials_base_url_required_for_compatible
    check (provider_type != 'openai_compatible' or base_url is not null)
);

create trigger builder_llm_credentials_set_updated_at before update on builder_llm_credentials
  for each row execute function set_updated_at();

alter table builder_llm_credentials enable row level security;

-- A builder managing only their own row reading back their own ciphertext is
-- not a leak: it's their own key, encrypted with a server-only key
-- (BUILDER_CREDENTIAL_ENCRYPTION_KEY) they never have access to, so the
-- stored ciphertext is useless to them even if read back -- the real trust
-- boundary is the encryption key, not this row. This keeps the policy as
-- simple as builder_progress_updates' own shape instead of splitting into a
-- second service-role-only secrets table for no real security gain.
create policy "builder_llm_credentials_select_own_or_operator" on builder_llm_credentials
  for select using (builder_id = auth.uid() or is_curator_or_admin(auth.uid()));

create policy "builder_llm_credentials_manage_own_or_staff" on builder_llm_credentials
  for all
  using (builder_id = auth.uid() or is_curator_or_admin(auth.uid()))
  with check (builder_id = auth.uid() or is_curator_or_admin(auth.uid()));


-- ==== supabase/migrations/20260925100001_project_objects_and_workstream_structure.sql ====
-- Builder Ontology, Part A (docs/kbs-ontology-dev-req-3.md): per-project
-- domain-object ontology (project_objects, a self-referencing tree -- e.g.
-- Plane/Route for an airline client, Sensor/AnomalyEvent for a
-- riverbank-monitoring client) plus richer Workstream structure (nesting,
-- lifecycle stage, operational status, planned/actual duration) and two
-- relationship tables (workstream_object_links: which objects a workstream
-- reads/writes/creates; workstream_flow: pipeline ordering between
-- workstreams). This is the instance-graph layer later Methods/cloning
-- features read -- nothing here executes anything. Single shared database,
-- one operator, many builders, isolated from each other by RLS -- NOT
-- per-client physical database separation (see the doc's own §1.1
-- correction from an earlier draft).

alter table project_workstreams
  add column parent_workstream_id uuid references project_workstreams(id) on delete cascade,
  -- Commercial/engagement lifecycle stage -- a different axis than `status`
  -- (draft/active/completed/archived). Nullable: existing rows and non-
  -- Builder-programme projects may never set this.
  add column lifecycle_stage text check (lifecycle_stage in ('presales', 'deployment', 'management_maintenance')),
  add column operational_status text not null default 'open' check (operational_status in ('open', 'concluded')),
  add column planned_duration interval,
  add column actual_duration interval;

create index if not exists project_workstreams_parent_workstream_id_idx on project_workstreams(parent_workstream_id);

-- Connecting infrastructure for the doc's own §9 (Evals section workstream
-- list) and a later comparison view -- neither can join a run back to a
-- workstream without this.
alter table eval_runs add column workstream_id uuid references project_workstreams(id) on delete set null;
create index if not exists eval_runs_workstream_id_idx on eval_runs(workstream_id);

-- Cycle guard for parent_workstream_id -- Postgres/RLS can't declaratively
-- forbid "no cycles" on a self-referencing adjacency list. This trigger is
-- the real enforcement (fires for every writer, not just the service
-- layer); the service layer additionally pre-checks the same thing so a
-- caller gets a clear message instead of a raw trigger exception (same
-- defense-in-depth shape as createWorkstream's own OL-002 role preflight).
create or replace function prevent_workstream_cycle()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  cursor_id uuid;
begin
  if new.parent_workstream_id is null then
    return new;
  end if;
  if new.parent_workstream_id = new.id then
    raise exception 'project_workstreams: a workstream cannot be its own parent';
  end if;
  cursor_id := new.parent_workstream_id;
  while cursor_id is not null loop
    if cursor_id = new.id then
      raise exception 'project_workstreams: parent_workstream_id would create a cycle';
    end if;
    select parent_workstream_id into cursor_id from project_workstreams where id = cursor_id;
  end loop;
  return new;
end;
$$;

create trigger project_workstreams_prevent_cycle before insert or update of parent_workstream_id on project_workstreams
  for each row execute function prevent_workstream_cycle();

-- project_objects ------------------------------------------------------------
-- Per-project domain-object ontology. A self-referencing tree of the domain
-- object *types* that matter for this specific builder's business -- not a
-- platform-wide taxonomy, and not instances of those types. Ordinary
-- mutable table, same reasoning as project_workstreams: a living definition
-- someone edits as understanding evolves, not something executed against.
create table project_objects (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  parent_object_id uuid references project_objects(id) on delete cascade,
  name text not null,
  slug text not null,
  description text,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (project_id, slug)
);

create index if not exists project_objects_project_id_idx on project_objects(project_id);
create index if not exists project_objects_parent_object_id_idx on project_objects(parent_object_id);

create trigger project_objects_set_updated_at before update on project_objects
  for each row execute function set_updated_at();

create or replace function prevent_project_object_cycle()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  cursor_id uuid;
begin
  if new.parent_object_id is null then
    return new;
  end if;
  if new.parent_object_id = new.id then
    raise exception 'project_objects: an object cannot be its own parent';
  end if;
  cursor_id := new.parent_object_id;
  while cursor_id is not null loop
    if cursor_id = new.id then
      raise exception 'project_objects: parent_object_id would create a cycle';
    end if;
    select parent_object_id into cursor_id from project_objects where id = cursor_id;
  end loop;
  return new;
end;
$$;

create trigger project_objects_prevent_cycle before insert or update of parent_object_id on project_objects
  for each row execute function prevent_project_object_cycle();

-- workstream_object_links -----------------------------------------------------
-- Which objects a workstream reads/writes/creates. One row per
-- (workstream_id, object_id) pair with an access_modes array -- reuses the
-- repository_scope text[] precedent already on project_workstreams itself,
-- rather than three near-duplicate rows per relation.
create table workstream_object_links (
  id uuid primary key default gen_random_uuid(),
  workstream_id uuid not null references project_workstreams(id) on delete cascade,
  object_id uuid not null references project_objects(id) on delete cascade,
  access_modes text[] not null default '{}',
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workstream_id, object_id),
  constraint workstream_object_links_access_modes_valid check (access_modes <@ array['reads', 'writes', 'creates']::text[])
);

create index if not exists workstream_object_links_workstream_id_idx on workstream_object_links(workstream_id);
create index if not exists workstream_object_links_object_id_idx on workstream_object_links(object_id);

create trigger workstream_object_links_set_updated_at before update on workstream_object_links
  for each row execute function set_updated_at();

-- A link's workstream and object must belong to the same project, or a
-- builder could wire another builder's object into their own workstream
-- despite both individually passing RLS on their own project.
create or replace function validate_workstream_object_link_project_match()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  ws_project_id uuid;
  obj_project_id uuid;
begin
  select project_id into ws_project_id from project_workstreams where id = new.workstream_id;
  select project_id into obj_project_id from project_objects where id = new.object_id;
  if ws_project_id is null or obj_project_id is null or ws_project_id != obj_project_id then
    raise exception 'workstream_object_links: workstream and object must belong to the same project';
  end if;
  return new;
end;
$$;

create trigger workstream_object_links_validate_project_match before insert or update on workstream_object_links
  for each row execute function validate_workstream_object_link_project_match();

-- workstream_flow --------------------------------------------------------------
-- Pipeline ordering between workstreams (a DAG, not a simple tree -- a
-- workstream can have multiple upstream/downstream neighbors).
create table workstream_flow (
  id uuid primary key default gen_random_uuid(),
  upstream_workstream_id uuid not null references project_workstreams(id) on delete cascade,
  downstream_workstream_id uuid not null references project_workstreams(id) on delete cascade,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (upstream_workstream_id, downstream_workstream_id),
  constraint workstream_flow_no_self_loop check (upstream_workstream_id != downstream_workstream_id)
);

create index if not exists workstream_flow_upstream_idx on workstream_flow(upstream_workstream_id);
create index if not exists workstream_flow_downstream_idx on workstream_flow(downstream_workstream_id);

create or replace function validate_workstream_flow_project_match()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  up_project_id uuid;
  down_project_id uuid;
begin
  select project_id into up_project_id from project_workstreams where id = new.upstream_workstream_id;
  select project_id into down_project_id from project_workstreams where id = new.downstream_workstream_id;
  if up_project_id is null or down_project_id is null or up_project_id != down_project_id then
    raise exception 'workstream_flow: both workstreams must belong to the same project';
  end if;
  return new;
end;
$$;

create trigger workstream_flow_validate_project_match before insert or update on workstream_flow
  for each row execute function validate_workstream_flow_project_match();

-- Cycle guard for the flow DAG: does a path already exist from the new
-- edge's downstream node back to its upstream node? If so this edge would
-- close a cycle. Recursive CTE, not a simple parent-walk loop, since this
-- is a general graph, not a tree.
create or replace function prevent_workstream_flow_cycle()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  reaches_upstream boolean;
begin
  with recursive downstream_closure(id) as (
    select new.downstream_workstream_id
    union
    select wf.downstream_workstream_id
    from workstream_flow wf
    join downstream_closure dc on wf.upstream_workstream_id = dc.id
  )
  select exists (select 1 from downstream_closure where id = new.upstream_workstream_id) into reaches_upstream;

  if reaches_upstream then
    raise exception 'workstream_flow: this edge would create a cycle in the workstream pipeline';
  end if;
  return new;
end;
$$;

create trigger workstream_flow_prevent_cycle before insert on workstream_flow
  for each row execute function prevent_workstream_flow_cycle();

-- RLS -----------------------------------------------------------------------
alter table project_objects enable row level security;
alter table workstream_object_links enable row level security;
alter table workstream_flow enable row level security;

-- project_objects: direct child of project, same shape as project_workstreams
-- itself (is_project_member for select, can_curate_project for manage).
create policy "project_objects_select_member" on project_objects
  for select using (is_project_member(project_id, auth.uid()));

create policy "project_objects_manage_curator" on project_objects
  for all using (can_curate_project(project_id, auth.uid()))
  with check (can_curate_project(project_id, auth.uid()));

-- workstream_object_links: child of workstream via subquery, same shape as
-- workstream_artifacts_select_member/workstream_artifacts_insert_consultant
-- (no denormalized project_id column -- always join through
-- project_workstreams). Curator-level gate for manage: this is a structural
-- definition of the workstream's scope, same authorization bar as the
-- workstream's own repository_scope/goal/guardrail fields
-- (project_workstreams_manage_curator), not the broader consultant-evidence
-- bar workstream_artifacts uses.
create policy "workstream_object_links_select_member" on workstream_object_links
  for select using (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_object_links.workstream_id and is_project_member(w.project_id, auth.uid())
    )
  );

create policy "workstream_object_links_manage_curator" on workstream_object_links
  for all using (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_object_links.workstream_id and can_curate_project(w.project_id, auth.uid())
    )
  )
  with check (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_object_links.workstream_id and can_curate_project(w.project_id, auth.uid())
    )
  );

-- workstream_flow: child of workstream via subquery, same shape as above --
-- checking the upstream side is sufficient for using/select (the trigger
-- above already guarantees both sides share a project); with check verifies
-- both sides so a caller can't wire in a workstream from a project they
-- can't curate.
create policy "workstream_flow_select_member" on workstream_flow
  for select using (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_flow.upstream_workstream_id and is_project_member(w.project_id, auth.uid())
    )
  );

create policy "workstream_flow_manage_curator" on workstream_flow
  for all using (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_flow.upstream_workstream_id and can_curate_project(w.project_id, auth.uid())
    )
  )
  with check (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_flow.upstream_workstream_id and can_curate_project(w.project_id, auth.uid())
    )
    and exists (
      select 1 from project_workstreams w2
      where w2.id = workstream_flow.downstream_workstream_id and can_curate_project(w2.project_id, auth.uid())
    )
  );


-- ==== supabase/migrations/20260926100001_project_workstream_cloning.sql ====
-- Builder Ontology, Part B (docs/kbs-ontology-dev-req-3.md, Part B of the
-- implementation plan): lets a builder duplicate a Project or a Workstream
-- (with its own subtree) to compare two options side by side under
-- otherwise-identical conditions -- e.g. two VLM training partners run as
-- siblings, each with its own fresh run history. Provenance-only columns:
-- cloning itself is a service-layer deep copy (project-cloning.ts), nothing
-- here executes or cascades automatically. No new RLS -- both columns land
-- on tables already fully covered by existing policies (projects_*,
-- project_workstreams_*).

alter table projects add column cloned_from_project_id uuid references projects(id) on delete set null;
create index if not exists projects_cloned_from_project_id_idx on projects(cloned_from_project_id);

alter table project_workstreams add column cloned_from_workstream_id uuid references project_workstreams(id) on delete set null;
create index if not exists project_workstreams_cloned_from_workstream_id_idx on project_workstreams(cloned_from_workstream_id);


-- ==== supabase/migrations/20260927100001_methods_schema.sql ====
-- Builder Ontology, Part C (docs/kbs-ontology-dev-req-3.md, Part C of the
-- implementation plan): a structured Method a builder can promote from a
-- workstream that worked -- reusable process/guardrails other builders can
-- browse and instantiate into a fresh workstream of their own. Deliberately
-- narrowed scope for this pass: ships the table, promotion-from-workstream,
-- and instantiation. Deferred: Ember checking published Methods before
-- proposing a new workstream tree during the wizard's own "Domain objects &
-- workstreams" step (a loop.ts/context-retrieval change, separate work from
-- the schema+CRUD here) -- the applied_method_id column below is added now
-- anyway (cheap, foundational) even though nothing populates it live yet.
--
-- requirements/evidence/deliverables/guardrails/review_points are plain
-- text, not jsonb -- this codebase's own "no template engine" convention
-- (see projects.details' own comment) for free-form curator-authored
-- content rendered as Markdown, same as project_workstreams.guardrail/
-- summary/goal. Nothing in this pass parses them as structured data.

create table methods (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  description text,
  -- The workstream a Method was promoted from -- not null (every Method has
  -- a real, demonstrated origin), so its own delete cascades here too,
  -- matching workstream_promotions.workstream_id's identical not-null +
  -- cascade shape (20260906100001_workstream_promotions_schema.sql) rather
  -- than the "set null" that would violate this column's own not-null
  -- constraint.
  derived_from_workstream_id uuid not null references project_workstreams(id) on delete cascade,
  derived_from_wiki_article_id uuid references wiki_articles(id) on delete set null,
  requirements text,
  evidence text,
  deliverables text,
  guardrails text,
  review_points text,
  status text not null default 'draft' check (status in ('draft', 'published')),
  published_by uuid references profiles(id) on delete set null,
  published_at timestamptz,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index methods_derived_from_workstream_id_idx on methods(derived_from_workstream_id);
create index methods_status_idx on methods(status);

create trigger methods_set_updated_at before update on methods
  for each row execute function set_updated_at();

alter table project_workstreams add column derived_from_method_id uuid references methods(id) on delete set null;
create index project_workstreams_derived_from_method_id_idx on project_workstreams(derived_from_method_id);

-- Runtime-evidence column for the deferred design-time integration (see
-- header comment) -- not populated by anything in this pass.
alter table ai_operation_logs add column applied_method_id uuid references methods(id) on delete set null;

alter table methods enable row level security;

-- Published is cross-builder visible (the whole point of a Method); a draft
-- is visible only to the originating builder (whoever can curate the source
-- workstream's project) or platform staff.
create policy "methods_select_published_or_own_draft" on methods
  for select using (
    status = 'published'
    or is_curator_or_admin(auth.uid())
    or exists (
      select 1 from project_workstreams w
      where w.id = derived_from_workstream_id and can_curate_project(w.project_id, auth.uid())
    )
  );

create policy "methods_insert_own" on methods
  for insert to authenticated
  with check (
    created_by = auth.uid()
    and exists (
      select 1 from project_workstreams w
      where w.id = derived_from_workstream_id and can_curate_project(w.project_id, auth.uid())
    )
  );

-- Same two-policy split as capability_evaluations
-- (20260906110001_capability_evaluations_schema.sql), this session's own
-- precedent: the originating builder can edit their own Method, but the
-- WITH CHECK keeps status in ('draft'), so even a raw API call can't
-- self-publish -- publishing is a separate staff-only policy below.
-- Postgres has no column-level RLS, so the terminal state is excluded at
-- the row level for the owner's own policy specifically.
create policy "methods_manage_own_draft" on methods
  for update
  using (
    exists (
      select 1 from project_workstreams w
      where w.id = derived_from_workstream_id and can_curate_project(w.project_id, auth.uid())
    )
  )
  with check (
    status = 'draft'
    and exists (
      select 1 from project_workstreams w
      where w.id = derived_from_workstream_id and can_curate_project(w.project_id, auth.uid())
    )
  );

create policy "methods_publish_staff" on methods
  for update
  using (is_curator_or_admin(auth.uid()))
  with check (is_curator_or_admin(auth.uid()));


-- ==== supabase/migrations/20260928100001_workstream_knowledge_bases.sql ====
-- Builder Ontology, Part D (docs/kbs-ontology-dev-req-3.md, Part D of the
-- implementation plan): today a knowledge_bases attachment is project-
-- scoped only (project_knowledge_bases) -- there's no way for one
-- Workstream to have its own scoped KB distinct from its Project's (e.g. a
-- client-specific reference set that shouldn't be visible to every other
-- workstream in the same builder-agency Project). Independent of Parts
-- A/B/C. Exact structural mirror of project_knowledge_bases' own final,
-- hardened shape (20260824160001_project_knowledge_visibility_fixes.sql +
-- 20260824170001_project_wiki_strict_membership.sql +
-- 20260824210001_project_junction_manage_policies_no_select_leak.sql):
-- strict membership for select (is_project_member_strict, no admin-bypass
-- leak on content-visibility-adjacent data), curator-gated insert/delete
-- only (can_curate_project, which does keep its admin bypass -- managing an
-- association is a different, lower-stakes capability than reading
-- confidential content), no update policy (only ever inserted or deleted,
-- never updated in place).

create table workstream_knowledge_bases (
  id uuid primary key default gen_random_uuid(),
  workstream_id uuid not null references project_workstreams(id) on delete cascade,
  knowledge_base_id text not null references knowledge_bases(id) on delete cascade,
  purpose text,
  attached_by uuid references profiles(id) on delete set null,
  attached_at timestamptz not null default now(),
  unique (workstream_id, knowledge_base_id)
);

create index workstream_knowledge_bases_workstream_id_idx on workstream_knowledge_bases(workstream_id);
create index workstream_knowledge_bases_kb_id_idx on workstream_knowledge_bases(knowledge_base_id);

alter table workstream_knowledge_bases enable row level security;

create policy "workstream_knowledge_bases_select_member" on workstream_knowledge_bases
  for select using (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_knowledge_bases.workstream_id and is_project_member_strict(w.project_id, auth.uid())
    )
  );

create policy "workstream_knowledge_bases_insert_curator" on workstream_knowledge_bases
  for insert with check (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_knowledge_bases.workstream_id and can_curate_project(w.project_id, auth.uid())
    )
  );

create policy "workstream_knowledge_bases_delete_curator" on workstream_knowledge_bases
  for delete using (
    exists (
      select 1 from project_workstreams w
      where w.id = workstream_knowledge_bases.workstream_id and can_curate_project(w.project_id, auth.uid())
    )
  );


-- ==== supabase/migrations/20260930100001_workstream_presentations.sql ====
-- Workstream Presentation & Review, Part A (docs/Workstream Presentation &
-- Customer Review.docx): lets a builder turn a completed Workstream into a
-- slide-based proposal that goes through structured review -- slide-level
-- comments, exactly one builder reply each, Ember-assisted classification,
-- and a structured Action Register -- before a curator approval gate.
-- Same reconciliation this session already applied to the Builder Ontology
-- doc: reuse existing schema shapes rather than inventing new ones.
--
-- One presentation per Workstream (nullable 1:1 -- most Workstreams never
-- get one). status is the review-period state machine (doc §11); actual
-- content lives in presentation_versions, never here -- this row is just
-- the stable identity + current pointer + review state, exactly the
-- wiki_articles/system_assessments "parent row, versioned children" shape.
create table presentations (
  id uuid primary key default gen_random_uuid(),
  workstream_id uuid not null unique references project_workstreams(id) on delete cascade,
  status text not null default 'draft' check (status in (
    'draft', 'review_open', 'review_closed', 'builder_revision', 'curator_review', 'approved'
  )),
  review_deadline timestamptz,
  current_version_id uuid, -- FK added below once presentation_versions exists (chicken-and-egg, same as wiki_articles.current_version_id)
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger presentations_set_updated_at before update on presentations for each row execute function set_updated_at();

-- Insert-only, immutable once written (wiki_versions' own shape) -- a new
-- "Generate Presentation" call always creates a new version, never edits
-- slide content of an existing one. slides is an ordered array of
-- {id, type, title, body, items?} -- id is a short stable string (e.g.
-- "slide-3") a comment's slide_id references; no separate slides table,
-- same "jsonb for structured content nobody queries by field" convention
-- as project_workstreams.deliverables.
create table presentation_versions (
  id uuid primary key default gen_random_uuid(),
  presentation_id uuid not null references presentations(id) on delete cascade,
  version_number integer not null,
  slides jsonb not null,
  generated_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (presentation_id, version_number)
);
alter table presentations add constraint presentations_current_version_id_fkey
  foreign key (current_version_id) references presentation_versions(id) on delete set null;

create table presentation_status_history (
  id uuid primary key default gen_random_uuid(),
  presentation_id uuid not null references presentations(id) on delete cascade,
  from_status text,
  to_status text not null,
  actor_id uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

-- slide_id is a polymorphic pointer into presentation_versions.slides'
-- jsonb array, not a real FK -- same convention as project_notes.context_id.
-- builder_reply* are plain nullable columns directly on the comment row
-- (not a child table) so "one reply" is a structural fact, not a business
-- rule layered on an unbounded table.
create table presentation_slide_comments (
  id uuid primary key default gen_random_uuid(),
  presentation_version_id uuid not null references presentation_versions(id) on delete cascade,
  slide_id text not null,
  author_id uuid references profiles(id) on delete set null,
  comment_text text not null,
  classification text check (classification in (
    'question', 'evaluation_candidate', 'action', 'security_review',
    'requirement_gap', 'approval_signal', 'scope_change', 'risk_concern', 'customer_requirement'
  )),
  builder_reply text,
  builder_reply_by uuid references profiles(id) on delete set null,
  builder_reply_at timestamptz,
  created_at timestamptz not null default now()
);

create table presentation_actions (
  id uuid primary key default gen_random_uuid(),
  presentation_id uuid not null references presentations(id) on delete cascade,
  source_comment_id uuid references presentation_slide_comments(id) on delete set null,
  action_text text not null,
  owner_id uuid references profiles(id) on delete set null,
  type text not null check (type in ('action', 'evaluation', 'security', 'requirement')),
  status text not null default 'open' check (status in ('open', 'in_progress', 'complete')),
  evidence text,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger presentation_actions_set_updated_at before update on presentation_actions for each row execute function set_updated_at();

create index presentation_versions_presentation_id_idx on presentation_versions(presentation_id);
create index presentation_slide_comments_version_id_idx on presentation_slide_comments(presentation_version_id);
create index presentation_actions_presentation_id_idx on presentation_actions(presentation_id);

alter table presentations enable row level security;
alter table presentation_versions enable row level security;
alter table presentation_status_history enable row level security;
alter table presentation_slide_comments enable row level security;
alter table presentation_actions enable row level security;

-- select: any project member, via the workstream's own project_id (join
-- through project_workstreams, exactly workstream_object_links' own
-- subquery shape). manage (insert/generate): curator+ only.
create policy "presentations_select_member" on presentations
  for select using (
    exists (select 1 from project_workstreams w where w.id = workstream_id and is_project_member(w.project_id, auth.uid()))
  );
create policy "presentations_insert_curator" on presentations
  for insert with check (
    exists (select 1 from project_workstreams w where w.id = workstream_id and can_curate_project(w.project_id, auth.uid()))
  );
-- Status transitions all go through this one policy; self-approval into
-- 'approved' is blocked in the SERVICE layer (curator_review -> approved
-- requires the actor to not be the presentation's own creator), same
-- reasoning workstream_promotions uses at the RLS layer -- kept here at
-- the service layer instead since every other transition on this same
-- column is curator-only anyway, so a single extra RLS policy would be
-- redundant with the check already required for every transition.
create policy "presentations_update_curator" on presentations
  for update
  using (exists (select 1 from project_workstreams w where w.id = workstream_id and can_curate_project(w.project_id, auth.uid())))
  with check (exists (select 1 from project_workstreams w where w.id = workstream_id and can_curate_project(w.project_id, auth.uid())));

create policy "presentation_versions_select_member" on presentation_versions
  for select using (
    exists (
      select 1 from presentations p join project_workstreams w on w.id = p.workstream_id
      where p.id = presentation_id and is_project_member(w.project_id, auth.uid())
    )
  );
create policy "presentation_versions_insert_curator" on presentation_versions
  for insert with check (
    exists (
      select 1 from presentations p join project_workstreams w on w.id = p.workstream_id
      where p.id = presentation_id and can_curate_project(w.project_id, auth.uid())
    )
  );
-- No update/delete policy at all -- immutable once written, same as wiki_versions.

create policy "presentation_status_history_select_member" on presentation_status_history
  for select using (
    exists (
      select 1 from presentations p join project_workstreams w on w.id = p.workstream_id
      where p.id = presentation_id and is_project_member(w.project_id, auth.uid())
    )
  );
-- No insert policy -- written only via the admin client from the service
-- layer, same as project_status_history.

create policy "presentation_slide_comments_select_member" on presentation_slide_comments
  for select using (
    exists (
      select 1 from presentation_versions v join presentations p on p.id = v.presentation_id
      join project_workstreams w on w.id = p.workstream_id
      where v.id = presentation_version_id and is_project_member(w.project_id, auth.uid())
    )
  );
create policy "presentation_slide_comments_insert_member" on presentation_slide_comments
  for insert with check (
    author_id = auth.uid()
    and exists (
      select 1 from presentation_versions v join presentations p on p.id = v.presentation_id
      join project_workstreams w on w.id = p.workstream_id
      where v.id = presentation_version_id and is_project_member(w.project_id, auth.uid())
    )
  );
-- The real one-reply enforcement: USING requires builder_reply IS NULL, so
-- a second update attempt on an already-replied row matches zero rows
-- (same "zero rows = no permission" convention as reviewArtifact) -- not
-- just a service-layer check.
create policy "presentation_slide_comments_reply_curator" on presentation_slide_comments
  for update
  using (
    builder_reply is null
    and exists (
      select 1 from presentation_versions v join presentations p on p.id = v.presentation_id
      join project_workstreams w on w.id = p.workstream_id
      where v.id = presentation_version_id and can_curate_project(w.project_id, auth.uid())
    )
  )
  with check (builder_reply is not null);

create policy "presentation_actions_select_member" on presentation_actions
  for select using (
    exists (select 1 from presentations p join project_workstreams w on w.id = p.workstream_id where p.id = presentation_id and is_project_member(w.project_id, auth.uid()))
  );
create policy "presentation_actions_insert_curator" on presentation_actions
  for insert with check (
    exists (select 1 from presentations p join project_workstreams w on w.id = p.workstream_id where p.id = presentation_id and can_curate_project(w.project_id, auth.uid()))
  );
-- status/evidence updates: curator, OR the action's own owner marking their
-- own work done -- same "builder updates their own thing" bar as
-- toggleDeliverable.
create policy "presentation_actions_update_owner_or_curator" on presentation_actions
  for update using (
    owner_id = auth.uid()
    or exists (select 1 from presentations p join project_workstreams w on w.id = p.workstream_id where p.id = presentation_id and can_curate_project(w.project_id, auth.uid()))
  );


-- ==== supabase/migrations/20261001100001_presentation_scheduled_open.sql ====
-- A curator can schedule a presentation review to open automatically at a
-- future date/time (draft -> review_open) instead of clicking "Open for
-- review" that day. Nullable -- most presentations are opened manually and
-- never set this. review_deadline (existing column) can be set together
-- with this at schedule time; it just sits on the row until the cron job
-- flips status, same as it already does for a manual open.
alter table presentations add column if not exists scheduled_open_at timestamptz;

create index if not exists presentations_scheduled_open_at_idx on presentations(scheduled_open_at) where scheduled_open_at is not null;


-- ==== supabase/migrations/20261002100001_openai_default_embedding.sql ====
-- Default embedding model: OpenAI text-embedding-3-small (1536 dimensions,
-- same as every vector(1536) column). Replaces the seed's gemini-embedding-001
-- default (20260810110002_seed_ai_providers.sql), and the RAG Answer agent
-- template's pinned embedding default (20260811100003_agent_framework.sql), so
-- knowledge vectors and the queries searched against them come from the same
-- model. The embedding default stays admin-changeable from the "Model
-- assignments" summary on the AI Config tab.
--
-- Vectors from different embedding models are not comparable, so this only
-- switches while no kb_vectors/wiki_vectors row was embedded by another model
-- -- an environment already running on a different embedding model keeps it
-- until an admin changes it deliberately (and re-embeds).
do $$
declare
  v_provider uuid;
  v_model uuid;
begin
  select m.provider_id, m.id into v_provider, v_model
  from ai_models m
  join ai_providers p on p.id = m.provider_id
  where p.name = 'openai' and m.model_id = 'text-embedding-3-small' and m.model_type = 'embedding';

  if v_model is null then
    return;
  end if;
  -- Re-run safe: only replace the original seed default (or no default),
  -- never an embedding model an admin has chosen since.
  if exists (
    select 1 from ai_models m
    where m.model_type = 'embedding' and m.is_default and m.id <> v_model and m.model_id <> 'gemini-embedding-001'
  ) then
    return;
  end if;
  if exists (select 1 from kb_vectors where embedding_model is distinct from 'text-embedding-3-small')
     or exists (select 1 from wiki_vectors where embedding_model is distinct from 'text-embedding-3-small') then
    return;
  end if;

  update ai_models set is_default = false where model_type = 'embedding' and is_default and id <> v_model;
  update ai_models set is_default = true, enabled = true where id = v_model;

  update agent_templates
  set default_embedding_provider_id = v_provider, default_embedding_model_id = v_model
  where default_embedding_model_id is not null and default_embedding_model_id <> v_model;
end $$;


-- ==== supabase/migrations/20261003100001_agency_builders.sql ====
-- Builder agencies (2026-10-01, Mike): in Ember Builder the platform owner
-- is the admin, each builder agency is a curator account, and each builder
-- is a consultant account. This roster says which agency a builder works
-- under, so the agency dashboard (/agency) shows a curator only their own
-- builders, and the admin sees every agency's.
--
-- One agency per builder (builder_id is the primary key). The admin assigns
-- builders; the service layer (src/lib/workbench/agency-dashboard.ts)
-- checks that the agency is a curator and the builder a consultant, so the
-- table itself only enforces the shape.
create table if not exists agency_builders (
  builder_id uuid primary key references profiles(id) on delete cascade,
  agency_id uuid not null references profiles(id) on delete cascade,
  assigned_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (builder_id <> agency_id)
);

create index if not exists agency_builders_agency_id_idx on agency_builders(agency_id);

drop trigger if exists agency_builders_set_updated_at on agency_builders;
create trigger agency_builders_set_updated_at before update on agency_builders
  for each row execute function set_updated_at();

alter table agency_builders enable row level security;

-- An agency sees its own roster, a builder sees which agency they're under,
-- the admin sees everything.
drop policy if exists "agency_builders_select_own_or_admin" on agency_builders;
create policy "agency_builders_select_own_or_admin" on agency_builders
  for select using (
    agency_id = auth.uid()
    or builder_id = auth.uid()
    or is_admin(auth.uid())
  );

drop policy if exists "agency_builders_admin_write" on agency_builders;
create policy "agency_builders_admin_write" on agency_builders
  for all using (is_admin(auth.uid())) with check (is_admin(auth.uid()));


-- ==== supabase/migrations/20261003100002_builder_proposal_promotions.sql ====
-- Builder proposals become client Projects (2026-10-01, Mike). A builder
-- keeps one workspace Project; each client proposal is a Workstream on it.
-- Once the client accepts, the builder submits the workstream for promotion
-- with the client's email addresses, and the builder's agency (curator, via
-- agency_builders) or the platform admin approves it. Approval creates the
-- client Project, owned by the builder, with the agency as curator and the
-- client as viewers (src/lib/workbench/workstream-promotions.ts). Each
-- approved promotion (decided_at, created_project_id) is the billable
-- "client project created" event the agency dashboard counts.
alter table workstream_promotions add column if not exists client_emails text[] not null default '{}';

-- An agency is not a member of its builders' private workspaces, so
-- can_curate_project alone never lets it decide their promotions.
create or replace function is_builder_agency(builder uuid, uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from agency_builders ab
    join profiles p on p.id = ab.agency_id
    where ab.builder_id = builder and ab.agency_id = uid and p.role = 'curator' and p.is_active = true
  );
$$;

drop policy if exists "workstream_promotions_select_own_or_curator" on workstream_promotions;
drop policy if exists "workstream_promotions_select_own_curator_or_agency" on workstream_promotions;
create policy "workstream_promotions_select_own_curator_or_agency" on workstream_promotions
  for select using (
    submitted_by = auth.uid()
    or exists (select 1 from project_workstreams w where w.id = workstream_id and can_curate_project(w.project_id, auth.uid()))
    or is_builder_agency(submitted_by, auth.uid())
  );

drop policy if exists "workstream_promotions_decide_curator" on workstream_promotions;
drop policy if exists "workstream_promotions_decide_curator_or_agency" on workstream_promotions;
create policy "workstream_promotions_decide_curator_or_agency" on workstream_promotions
  for update
  using (
    submitted_by != auth.uid()
    and (
      exists (select 1 from project_workstreams w where w.id = workstream_id and can_curate_project(w.project_id, auth.uid()))
      or is_builder_agency(submitted_by, auth.uid())
    )
  )
  with check (
    submitted_by != auth.uid()
    and (
      exists (select 1 from project_workstreams w where w.id = workstream_id and can_curate_project(w.project_id, auth.uid()))
      or is_builder_agency(submitted_by, auth.uid())
    )
  );


-- ==== supabase/migrations/20261003100003_client_project_fees.sql ====
-- Client maintenance fees and the platform's share (2026-10-01, Mike).
-- A builder charges each client a maintenance fee (PHP or USD, monthly or
-- annual); the platform owner takes a percentage of it -- 10% by default,
-- set per deployment in settings.builder_billing (a dev house running its
-- own Ember sets its own). Ember doesn't collect payments: these figures
-- are for invoicing builders.
--
-- The builder proposes the fee when requesting the client Project
-- (workstream_promotions.proposed_fee_*); approval records it in
-- client_project_fees with the platform rate in force at that moment, so a
-- later rate change never rewrites what was already agreed. The agency or
-- admin can correct a fee afterwards; that keeps the recorded rate.

alter table workstream_promotions drop constraint if exists workstream_promotions_proposed_fee_complete;
alter table workstream_promotions
  add column if not exists proposed_fee_amount numeric(12, 2) check (proposed_fee_amount >= 0),
  add column if not exists proposed_fee_currency text check (proposed_fee_currency in ('PHP', 'USD')),
  add column if not exists proposed_fee_period text check (proposed_fee_period in ('monthly', 'annual')),
  add constraint workstream_promotions_proposed_fee_complete check (
    (proposed_fee_amount is null and proposed_fee_currency is null and proposed_fee_period is null)
    or (proposed_fee_amount is not null and proposed_fee_currency is not null and proposed_fee_period is not null)
  );

create table if not exists client_project_fees (
  project_id uuid primary key references projects(id) on delete cascade,
  amount numeric(12, 2) not null check (amount >= 0),
  currency text not null check (currency in ('PHP', 'USD')),
  billing_period text not null check (billing_period in ('monthly', 'annual')),
  platform_rate_pct numeric(5, 2) not null check (platform_rate_pct >= 0 and platform_rate_pct <= 100),
  set_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

drop trigger if exists client_project_fees_set_updated_at on client_project_fees;
create trigger client_project_fees_set_updated_at before update on client_project_fees
  for each row execute function set_updated_at();

-- The platform owner (admin) can be an agency too -- e.g. the owner
-- running the first agency themselves before selling to dev houses.
create or replace function is_builder_agency(builder uuid, uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from agency_builders ab
    join profiles p on p.id = ab.agency_id
    where ab.builder_id = builder and ab.agency_id = uid and p.role in ('curator', 'admin') and p.is_active = true
  );
$$;

alter table client_project_fees enable row level security;

-- The builder sees the fee on their own client Project; their agency and
-- the admin see and set it.
drop policy if exists "client_project_fees_select_owner_agency_or_admin" on client_project_fees;
create policy "client_project_fees_select_owner_agency_or_admin" on client_project_fees
  for select using (
    is_admin(auth.uid())
    or exists (
      select 1 from projects p
      where p.id = project_id and (p.owner_id = auth.uid() or is_builder_agency(p.owner_id, auth.uid()))
    )
  );

drop policy if exists "client_project_fees_write_agency_or_admin" on client_project_fees;
create policy "client_project_fees_write_agency_or_admin" on client_project_fees
  for all
  using (
    is_admin(auth.uid())
    or exists (select 1 from projects p where p.id = project_id and is_builder_agency(p.owner_id, auth.uid()))
  )
  with check (
    is_admin(auth.uid())
    or exists (select 1 from projects p where p.id = project_id and is_builder_agency(p.owner_id, auth.uid()))
  );


-- ==== supabase/migrations/20261004100001_project_creation_approval.sql ====
-- Project creation approval (2026-10-02, Mike). A Project created by a
-- consultant/builder (anyone below platform curator) starts as
-- approval_status 'pending': the creator can work on it fully, but nobody
-- else is let in until a platform admin or a curator approves it -- any
-- curator in Enterprise mode, only the creator's own agency curator
-- (agency_builders) in Builder mode (src/lib/workbench/project-approval.ts).
-- Projects created by a curator/admin, or by the service role
-- (provisionBuilderProject, workstream promotions, seeds), are 'approved'
-- straight away, and every existing Project is backfilled 'approved' by the
-- column default.
--
-- Separate axis from projects.status (draft/active/review/completed) --
-- that's the team's own working lifecycle, which the creator keeps driving
-- while this is pending.
alter table projects add column if not exists approval_status text not null default 'approved'
  check (approval_status in ('pending', 'approved', 'rejected'));
alter table projects add column if not exists approval_decided_by uuid references profiles(id) on delete set null;
alter table projects add column if not exists approval_decided_at timestamptz;
alter table projects add column if not exists approval_decision_reason text;
-- Team members picked in the new-project wizard ({user_id, role}[]) --
-- held here, not in project_members, until approval adds them.
alter table projects add column if not exists pending_members jsonb not null default '[]'::jsonb;

create index if not exists projects_approval_status_pending_idx on projects(owner_id) where approval_status = 'pending';

-- One trigger is the real gate for every write path (RLS-scoped client,
-- service role, and any future one):
--   * a signed-in caller below curator always inserts 'pending', whatever
--     the client sent;
--   * a signed-in caller can never change approval_* themselves -- only the
--     service layer (auth.uid() is null under the service role), after its
--     own agency-curator/admin check, decides;
--   * while not approved the project stays private and members-only, so it
--     can't reach anyone through publication or the platform directory.
create or replace function enforce_project_approval()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null and not is_curator_or_admin(auth.uid()) then
      new.approval_status := 'pending';
      new.approval_decided_by := null;
      new.approval_decided_at := null;
      new.approval_decision_reason := null;
    end if;
  elsif auth.uid() is not null and (
    new.approval_status is distinct from old.approval_status
    or new.approval_decided_by is distinct from old.approval_decided_by
    or new.approval_decided_at is distinct from old.approval_decided_at
    or new.approval_decision_reason is distinct from old.approval_decision_reason
    or new.pending_members is distinct from old.pending_members
  ) then
    raise exception 'Only a curator or platform admin can approve this project';
  end if;

  if new.approval_status <> 'approved' and (new.visibility <> 'private' or new.discoverability <> 'members_only') then
    raise exception 'This project is awaiting approval -- it stays private until a curator or admin approves it';
  end if;
  return new;
end;
$$;

drop trigger if exists projects_enforce_approval on projects;
create trigger projects_enforce_approval
  before insert or update on projects
  for each row execute function enforce_project_approval();

-- Creator only while pending: no active membership for anyone but the
-- owner until the project is approved (approval itself flips the status
-- first, then adds pending_members).
create or replace function enforce_project_approval_membership()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  p record;
begin
  if new.status <> 'active' then
    return new;
  end if;
  select approval_status, owner_id into p from projects where id = new.project_id;
  if found and p.approval_status <> 'approved' and new.user_id is distinct from p.owner_id then
    raise exception 'This project is awaiting approval -- members can be added once a curator or admin approves it';
  end if;
  return new;
end;
$$;

drop trigger if exists project_members_enforce_approval on project_members;
create trigger project_members_enforce_approval
  before insert or update on project_members
  for each row execute function enforce_project_approval_membership();


-- ==== supabase/migrations/20261004100002_project_live_status.sql ====
-- Live status (2026-10-02, Mike). After a project is Approved ('completed')
-- it waits for the client's approval -- normally given through the
-- workstream presentation -- and then goes Live: in production and in
-- maintenance. Pipeline: draft -> active -> review -> completed -> live.
-- A Live project stays Live: bug fixes and new features are new workstreams
-- inside it. An Approved project can be reopened to Working on it. Safe to re-run.
alter table projects drop constraint if exists projects_status_check;
alter table projects add constraint projects_status_check
  check (status = any (array['draft'::text, 'active'::text, 'review'::text, 'completed'::text, 'live'::text, 'archived'::text]));


-- ==== supabase/migrations/20261005100001_external_mcp_access.sql ====
-- External MCP server (docs/dev-request-ember-external-mcp-server.md):
-- builders ask their own AI chatbot (Claude, ChatGPT) about their Ember
-- projects. The chatbot signs in through Supabase Auth's OAuth 2.1 server,
-- so every token it holds is an ordinary Supabase user JWT carrying a
-- `client_id` claim. This migration adds:
--
--   1. mcp_access_users           who may connect a chatbot at all (admin-managed)
--   2. mcp_approved_clients       which chatbots, by exact OAuth redirect URI,
--                                 and the highest sensitivity tier each may receive
--   3. mcp_access_log             one row per MCP call, including denied ones
--   4. mcp_rate_counters          per user+client call counters (serverless-safe)
--   5. read-only enforcement      a RESTRICTIVE insert/update/delete policy on
--                                 every public table and storage.objects that
--                                 fails for any token with a client_id claim --
--                                 so a leaked chatbot token is read-only even
--                                 when sent straight to PostgREST, not just
--                                 through Ember's own read-only tools
--   6. guards on the three writing SECURITY DEFINER RPCs (they bypass RLS)

-- 1. Allowlist ---------------------------------------------------------------
create table if not exists mcp_access_users (
  user_id uuid primary key references profiles(id) on delete cascade,
  note text,
  added_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

alter table mcp_access_users enable row level security;

drop policy if exists "mcp_access_users_select_self_or_admin" on mcp_access_users;
create policy "mcp_access_users_select_self_or_admin" on mcp_access_users
  for select to authenticated using (user_id = auth.uid() or is_admin(auth.uid()));
drop policy if exists "mcp_access_users_admin_insert" on mcp_access_users;
create policy "mcp_access_users_admin_insert" on mcp_access_users
  for insert to authenticated with check (is_admin(auth.uid()));
drop policy if exists "mcp_access_users_admin_delete" on mcp_access_users;
create policy "mcp_access_users_admin_delete" on mcp_access_users
  for delete to authenticated using (is_admin(auth.uid()));

-- 2. Approved chatbot clients --------------------------------------------------
-- Dynamic client registration lets anyone register an OAuth client, so the
-- consent page only approves a client whose redirect URI is listed here
-- (exact match). max_sensitivity caps what that chatbot's provider may be
-- sent -- same tiers as ai_provider_sensitivity_eligibility, and never
-- 'restricted'.
create table if not exists mcp_approved_clients (
  redirect_uri text primary key check (redirect_uri ~ '^https://' or redirect_uri ~ '^http://(localhost|127\.0\.0\.1)(:[0-9]+)?/'),
  label text not null check (length(label) between 1 and 80),
  max_sensitivity text not null default 'internal' check (max_sensitivity in ('public', 'internal', 'confidential')),
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

alter table mcp_approved_clients enable row level security;

-- Readable by any signed-in user: the consent page shows the label, and a
-- redirect URI is not a secret.
drop policy if exists "mcp_approved_clients_select_authenticated" on mcp_approved_clients;
create policy "mcp_approved_clients_select_authenticated" on mcp_approved_clients
  for select to authenticated using (true);
drop policy if exists "mcp_approved_clients_admin_insert" on mcp_approved_clients;
create policy "mcp_approved_clients_admin_insert" on mcp_approved_clients
  for insert to authenticated with check (is_admin(auth.uid()));
drop policy if exists "mcp_approved_clients_admin_update" on mcp_approved_clients;
create policy "mcp_approved_clients_admin_update" on mcp_approved_clients
  for update to authenticated using (is_admin(auth.uid())) with check (is_admin(auth.uid()));
drop policy if exists "mcp_approved_clients_admin_delete" on mcp_approved_clients;
create policy "mcp_approved_clients_admin_delete" on mcp_approved_clients
  for delete to authenticated using (is_admin(auth.uid()));

insert into mcp_approved_clients (redirect_uri, label, max_sensitivity) values
  ('https://claude.ai/api/mcp/auth_callback', 'Claude', 'internal'),
  ('https://claude.com/api/mcp/auth_callback', 'Claude', 'internal'),
  ('https://chatgpt.com/connector_platform_oauth_redirect', 'ChatGPT', 'internal')
on conflict (redirect_uri) do nothing;

-- 3. Audit log -----------------------------------------------------------------
-- No client insert policy: written only by the service-role client in
-- src/lib/mcp/access.ts, same shape as ai_operation_logs.
create table if not exists mcp_access_log (
  id bigint generated always as identity primary key,
  user_id uuid references profiles(id) on delete set null,
  client_id text,
  method text not null,
  tool text,
  project_id uuid,
  args_summary text,
  result_count integer,
  withheld_count integer,
  status text not null check (status in ('ok', 'denied', 'rate_limited', 'error')),
  error text,
  latency_ms integer,
  user_agent text,
  created_at timestamptz not null default now()
);

create index if not exists mcp_access_log_user_created_idx on mcp_access_log (user_id, created_at desc);
create index if not exists mcp_access_log_created_idx on mcp_access_log (created_at desc);

alter table mcp_access_log enable row level security;

drop policy if exists "mcp_access_log_select_self_or_admin" on mcp_access_log;
create policy "mcp_access_log_select_self_or_admin" on mcp_access_log
  for select to authenticated using (user_id = auth.uid() or is_admin(auth.uid()));

-- 4. Rate counters ---------------------------------------------------------------
create table if not exists mcp_rate_counters (
  user_id uuid not null references profiles(id) on delete cascade,
  client_id text not null,
  window_kind text not null check (window_kind in ('minute', 'day')),
  window_start timestamptz not null,
  hits integer not null default 0,
  primary key (user_id, client_id, window_kind, window_start)
);

alter table mcp_rate_counters enable row level security;
-- No policies: service role only.

-- Counts this call against both windows and reports whether it is within
-- both limits. One atomic upsert per window, so concurrent serverless
-- instances can't under-count. Service role only.
create or replace function mcp_rate_hit(p_user_id uuid, p_client_id text, p_minute_limit integer, p_day_limit integer)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_minute integer;
  v_day integer;
begin
  insert into mcp_rate_counters (user_id, client_id, window_kind, window_start, hits)
  values (p_user_id, p_client_id, 'minute', date_trunc('minute', now()), 1)
  on conflict (user_id, client_id, window_kind, window_start) do update set hits = mcp_rate_counters.hits + 1
  returning hits into v_minute;

  insert into mcp_rate_counters (user_id, client_id, window_kind, window_start, hits)
  values (p_user_id, p_client_id, 'day', date_trunc('day', now()), 1)
  on conflict (user_id, client_id, window_kind, window_start) do update set hits = mcp_rate_counters.hits + 1
  returning hits into v_day;

  delete from mcp_rate_counters where window_start < now() - interval '2 days';

  return v_minute <= p_minute_limit and v_day <= p_day_limit;
end;
$$;

revoke all on function mcp_rate_hit(uuid, text, integer, integer) from public, anon, authenticated;
grant execute on function mcp_rate_hit(uuid, text, integer, integer) to service_role;

-- 5. Read-only enforcement for OAuth-issued tokens ------------------------------
-- A RESTRICTIVE policy is ANDed with every permissive one, so browser sessions
-- (no client_id claim) are unaffected while any OAuth client token fails every
-- insert, update and delete. Idempotent: creates only the policies a table is
-- missing. Any future migration that creates a table must end with
--   select apply_oauth_read_only_policies();
-- (src/lib/mcp/read-only-migrations.test.ts fails otherwise).
create or replace function apply_oauth_read_only_policies()
returns void
language plpgsql
set search_path = public
as $$
declare
  t record;
begin
  for t in
    select c.relname as table_name
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity
  loop
    if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = t.table_name and policyname = 'oauth_clients_no_insert') then
      execute format(
        'create policy oauth_clients_no_insert on public.%I as restrictive for insert to public with check ((auth.jwt() ->> ''client_id'') is null)',
        t.table_name
      );
    end if;
    if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = t.table_name and policyname = 'oauth_clients_no_update') then
      execute format(
        'create policy oauth_clients_no_update on public.%I as restrictive for update to public using ((auth.jwt() ->> ''client_id'') is null) with check ((auth.jwt() ->> ''client_id'') is null)',
        t.table_name
      );
    end if;
    if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = t.table_name and policyname = 'oauth_clients_no_delete') then
      execute format(
        'create policy oauth_clients_no_delete on public.%I as restrictive for delete to public using ((auth.jwt() ->> ''client_id'') is null)',
        t.table_name
      );
    end if;
  end loop;
end;
$$;

revoke all on function apply_oauth_read_only_policies() from public, anon, authenticated;

select apply_oauth_read_only_policies();

drop policy if exists "oauth_clients_no_insert" on storage.objects;
create policy "oauth_clients_no_insert" on storage.objects
  as restrictive for insert to public with check ((auth.jwt() ->> 'client_id') is null);
drop policy if exists "oauth_clients_no_update" on storage.objects;
create policy "oauth_clients_no_update" on storage.objects
  as restrictive for update to public using ((auth.jwt() ->> 'client_id') is null) with check ((auth.jwt() ->> 'client_id') is null);
drop policy if exists "oauth_clients_no_delete" on storage.objects;
create policy "oauth_clients_no_delete" on storage.objects
  as restrictive for delete to public using ((auth.jwt() ->> 'client_id') is null);

-- 6. Writing SECURITY DEFINER RPCs bypass RLS, so guard them directly.
-- Same bodies as 20260808190009_functions.sql / 20260828160001, plus the guard.
create or replace function increment_approved_chunks(doc_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if (auth.jwt() ->> 'client_id') is not null then
    raise exception 'OAuth client tokens are read-only' using errcode = '42501';
  end if;
  update documents set approved_chunks = approved_chunks + 1 where id = doc_id;
end;
$$;

create or replace function increment_rejected_chunks(doc_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if (auth.jwt() ->> 'client_id') is not null then
    raise exception 'OAuth client tokens are read-only' using errcode = '42501';
  end if;
  update documents set rejected_chunks = rejected_chunks + 1 where id = doc_id;
end;
$$;

create or replace function decrement_approved_chunks(doc_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if (auth.jwt() ->> 'client_id') is not null then
    raise exception 'OAuth client tokens are read-only' using errcode = '42501';
  end if;
  update documents set approved_chunks = greatest(approved_chunks - 1, 0) where id = doc_id;
end;
$$;


-- ==== supabase/migrations/20261006100001_ai_provider_self_hosted.sql ====
-- Sandz-hosted AI for Live client Projects (Builder mode).
--
-- Marks a provider as running on Sandz infrastructure (for example the vLLM
-- server on the Zadara GPU VM, docs/guides/ember-self-hosted-llm-integration.md).
-- In Builder mode, a contracted client Project -- one with a
-- client_project_fees row, created when an accepted proposal is promoted --
-- may use only these providers for content calls once it is Live
-- (src/lib/ai/hosting-policy.ts). Presales work, pre-live client Projects
-- and internal/foundation Projects are unrestricted.
--
-- Default false: a provider is external until an admin says otherwise. Set
-- from Admin -> AI Config; existing ai_providers RLS (admin-only writes,
-- read by any active non-anonymous session) already covers the column.
alter table ai_providers add column if not exists is_self_hosted boolean not null default false;

comment on column ai_providers.is_self_hosted is
  'Runs on Sandz infrastructure. Live client Projects in Builder mode may use only these providers for content AI calls.';


-- ==== supabase/migrations/20261007100001_agency_scoped_builder_budgets.sql ====
-- Agencies see and control their own builders' AI budgets (2026-10-04,
-- Mike). With the Builder/Enterprise modes merged, an enterprise running its
-- own Ember is the agency and wants the same control over its employees'
-- AI spend that a builder agency has over its builders.
--
-- Until now any curator could read or change any builder's allowance,
-- credit grants and BYOLLM credential (is_curator_or_admin), so on a
-- deployment shared by several agencies one agency could manage another's
-- builders. Scope all three to the builder themselves, their own agency
-- (agency_builders, via is_builder_agency) and the platform admin. A
-- builder on no agency's roster is managed by the admin alone -- same set
-- the agency dashboard (/agency) shows each viewer.
create or replace function can_manage_builder_budget(builder uuid, uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select is_admin(uid) or is_builder_agency(builder, uid);
$$;

drop policy if exists "builder_ai_allowances_select_own_or_operator" on builder_ai_allowances;
drop policy if exists "builder_ai_allowances_select_own_agency_or_admin" on builder_ai_allowances;
create policy "builder_ai_allowances_select_own_agency_or_admin" on builder_ai_allowances
  for select using (builder_id = auth.uid() or can_manage_builder_budget(builder_id, auth.uid()));

-- A builder still cannot raise their own cap.
drop policy if exists "builder_ai_allowances_manage_staff" on builder_ai_allowances;
drop policy if exists "builder_ai_allowances_manage_agency_or_admin" on builder_ai_allowances;
create policy "builder_ai_allowances_manage_agency_or_admin" on builder_ai_allowances
  for all
  using (can_manage_builder_budget(builder_id, auth.uid()))
  with check (can_manage_builder_budget(builder_id, auth.uid()));

drop policy if exists "builder_credit_grants_select_own_or_operator" on builder_credit_grants;
drop policy if exists "builder_credit_grants_select_own_agency_or_admin" on builder_credit_grants;
create policy "builder_credit_grants_select_own_agency_or_admin" on builder_credit_grants
  for select using (builder_id = auth.uid() or can_manage_builder_budget(builder_id, auth.uid()));

drop policy if exists "builder_credit_grants_insert_staff" on builder_credit_grants;
drop policy if exists "builder_credit_grants_insert_agency_or_admin" on builder_credit_grants;
create policy "builder_credit_grants_insert_agency_or_admin" on builder_credit_grants
  for insert to authenticated
  with check (granted_by = auth.uid() and can_manage_builder_budget(builder_id, auth.uid()));

drop policy if exists "builder_llm_credentials_select_own_or_operator" on builder_llm_credentials;
drop policy if exists "builder_llm_credentials_select_own_agency_or_admin" on builder_llm_credentials;
create policy "builder_llm_credentials_select_own_agency_or_admin" on builder_llm_credentials
  for select using (builder_id = auth.uid() or can_manage_builder_budget(builder_id, auth.uid()));

drop policy if exists "builder_llm_credentials_manage_own_or_staff" on builder_llm_credentials;
drop policy if exists "builder_llm_credentials_manage_own_agency_or_admin" on builder_llm_credentials;
create policy "builder_llm_credentials_manage_own_agency_or_admin" on builder_llm_credentials
  for all
  using (builder_id = auth.uid() or can_manage_builder_budget(builder_id, auth.uid()))
  with check (builder_id = auth.uid() or can_manage_builder_budget(builder_id, auth.uid()));


-- ==== supabase/migrations/20261008100001_live_handover_and_builder_share.sql ====
-- Live hand-over and the builder's share of client fees (2026-10-04, Mike).
--
-- When a builder's Project goes Live, the agency takes ownership: Ember is
-- then used for maintenance and feature requests, and the agency protects
-- the client relationship even for a solo builder. The builder stays on
-- the Project as curator and keeps working on it
-- (src/lib/workbench/projects.ts, handOverLiveProjectToAgency).
--
-- projects.builder_id records the builder of record -- the builder who
-- built it -- so the hand-over doesn't lose who earns the maintenance
-- bonus, whose AI budget their work counts against, or which builder card
-- the agency dashboard shows the Project on. Set only by the service layer
-- (promotion, hand-over) or a platform admin.
--
-- client_project_fees.builder_share_pct is the builder's share of the
-- maintenance fee -- for an employee, a bonus on top of salary (10% by
-- default, settings.builder_billing.builderSharePct). Recorded per fee like
-- platform_rate_pct, so changing the default never rewrites an agreed fee;
-- the agency or admin can adjust it per Project.

alter table projects add column if not exists builder_id uuid references profiles(id) on delete set null;
create index if not exists projects_builder_id_idx on projects(builder_id) where builder_id is not null;

-- Every existing client Project is still owned by its builder.
update projects p set builder_id = p.owner_id
where p.builder_id is null and exists (select 1 from client_project_fees f where f.project_id = p.id);

create or replace function enforce_project_builder_id()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null and not is_admin(auth.uid()) and (
    (tg_op = 'INSERT' and new.builder_id is not null)
    or (tg_op = 'UPDATE' and new.builder_id is distinct from old.builder_id)
  ) then
    raise exception 'Only a platform admin can change a project''s builder of record';
  end if;
  return new;
end;
$$;

drop trigger if exists projects_enforce_builder_id on projects;
create trigger projects_enforce_builder_id
  before insert or update on projects
  for each row execute function enforce_project_builder_id();

alter table client_project_fees
  add column if not exists builder_share_pct numeric(5, 2) not null default 0
    check (builder_share_pct >= 0 and builder_share_pct <= 100);

-- The builder of record sees their own fee and share; their agency (by the
-- builder, whoever owns the Project now) and the admin see and set it.
drop policy if exists "client_project_fees_select_owner_agency_or_admin" on client_project_fees;
drop policy if exists "client_project_fees_select_builder_agency_or_admin" on client_project_fees;
create policy "client_project_fees_select_builder_agency_or_admin" on client_project_fees
  for select using (
    is_admin(auth.uid())
    or exists (
      select 1 from projects p
      where p.id = project_id
        and (
          p.owner_id = auth.uid()
          or p.builder_id = auth.uid()
          or is_builder_agency(p.owner_id, auth.uid())
          or is_builder_agency(p.builder_id, auth.uid())
        )
    )
  );

drop policy if exists "client_project_fees_write_agency_or_admin" on client_project_fees;
create policy "client_project_fees_write_agency_or_admin" on client_project_fees
  for all
  using (
    is_admin(auth.uid())
    or exists (
      select 1 from projects p
      where p.id = project_id and (is_builder_agency(p.owner_id, auth.uid()) or is_builder_agency(p.builder_id, auth.uid()))
    )
  )
  with check (
    is_admin(auth.uid())
    or exists (
      select 1 from projects p
      where p.id = project_id and (is_builder_agency(p.owner_id, auth.uid()) or is_builder_agency(p.builder_id, auth.uid()))
    )
  );

-- After the hand-over the builder is no longer the owner, but still shares
-- progress updates on the Project they maintain.
drop policy if exists "builder_progress_updates_insert_owner" on builder_progress_updates;
drop policy if exists "builder_progress_updates_insert_owner_or_builder" on builder_progress_updates;
create policy "builder_progress_updates_insert_owner_or_builder" on builder_progress_updates
  for insert to authenticated
  with check (
    submitted_by = auth.uid()
    and exists (
      select 1 from project_workstreams w join projects p on p.id = w.project_id
      where w.id = workstream_id and (can_manage_project(w.project_id, auth.uid()) or p.builder_id = auth.uid())
    )
  );

drop policy if exists "builder_progress_updates_update_owner" on builder_progress_updates;
drop policy if exists "builder_progress_updates_update_owner_or_builder" on builder_progress_updates;
create policy "builder_progress_updates_update_owner_or_builder" on builder_progress_updates
  for update
  using (
    exists (
      select 1 from project_workstreams w join projects p on p.id = w.project_id
      where w.id = workstream_id and (can_manage_project(w.project_id, auth.uid()) or p.builder_id = auth.uid())
    )
  )
  with check (
    exists (
      select 1 from project_workstreams w join projects p on p.id = w.project_id
      where w.id = workstream_id and (can_manage_project(w.project_id, auth.uid()) or p.builder_id = auth.uid())
    )
  );


-- ==== supabase/migrations/20261009100001_disable_self_registration.sql ====
-- Self-registration off (2026-10-04, Mike). /register already redirects to
-- /login and accounts are created by an admin (createUserAction), which
-- writes the profile itself. But a sign-up made straight against Supabase
-- Auth (the anon key is public) could still give itself a consultant
-- profile on first login through this policy -- a builder account with
-- Ember access nobody approved. Drop it, so the only way to a non-anonymous
-- profile is the service role. Re-add a reviewed path when self-registration
-- is ready (e.g. as 'member', pending an agency's acceptance).
--
-- profiles_insert_self_anonymous stays: it only ever yields the dormant
-- 'anonymous' role.
drop policy if exists "profiles_insert_self_consultant" on profiles;


-- ==== supabase/migrations/20261010100001_ai_operation_logs_task.sql ====
-- Cost per task (2026-10-04, Mike). Every AI call records what it was for
-- (src/lib/ai/tasks.ts) and how much of its input the provider served from
-- its prompt cache. Groundwork for an admin cost report by task and for
-- choosing a model per task.
--
-- task is text, not a check constraint: the list lives in code and grows
-- with new features. Rows logged before this migration stay null and read
-- as "unattributed".
--
-- cached_input_tokens is the part of input_tokens served from the
-- provider's prompt cache (OpenAI/Groq/xAI prompt_tokens_details.
-- cached_tokens, DeepSeek prompt_cache_hit_tokens, Gemini
-- cachedContentTokenCount); null when the provider doesn't report it.
alter table ai_operation_logs add column if not exists task text;
alter table ai_operation_logs add column if not exists cached_input_tokens integer
  check (cached_input_tokens is null or cached_input_tokens >= 0);

create index if not exists ai_operation_logs_task_created_at_idx on ai_operation_logs(task, created_at desc);


-- ==== supabase/migrations/20261011100001_ai_cost_report.sql ====
-- AI cost report and cached-token pricing (2026-10-04, Mike).
--
-- ai_models.cached_input_cost_per_million: what the provider charges for
-- input tokens served from its prompt cache (OpenAI, Gemini and DeepSeek
-- all discount them). Null means "not set": cached tokens are then charged
-- at the full input price, so cost is never understated
-- (src/lib/ai/metering.ts computeCost).
alter table ai_models add column if not exists cached_input_cost_per_million numeric
  check (cached_input_cost_per_million is null or cached_input_cost_per_million >= 0);

-- Daily totals per task, provider, model and kind of call, for the admin
-- cost report (src/lib/workbench/ai-cost-report.ts). security_invoker, so
-- ai_operation_logs' own RLS (admin-only select) applies to whoever reads it.
-- Calls logged before 20261010100001 have no task and read as
-- 'unattributed'.
create or replace view ai_cost_daily with (security_invoker = true) as
select
  (created_at at time zone 'utc')::date as day,
  coalesce(task, 'unattributed') as task,
  provider,
  model,
  operation,
  count(*)::integer as calls,
  (count(*) filter (where not success))::integer as failed_calls,
  -- Succeeded, not the builder's own LLM, and no price configured.
  (count(*) filter (where success and not is_byo_llm and estimated_cost_usd is null))::integer as unpriced_calls,
  (count(*) filter (where is_byo_llm))::integer as byo_llm_calls,
  coalesce(sum(input_tokens), 0)::bigint as input_tokens,
  coalesce(sum(cached_input_tokens), 0)::bigint as cached_input_tokens,
  -- Input tokens on calls whose provider reported a cache figure, so the
  -- cached share isn't diluted by providers that report none.
  coalesce(sum(input_tokens) filter (where cached_input_tokens is not null), 0)::bigint as cache_reported_input_tokens,
  coalesce(sum(output_tokens), 0)::bigint as output_tokens,
  coalesce(sum(estimated_cost_usd), 0)::numeric as cost_usd
from ai_operation_logs
group by 1, 2, 3, 4, 5;

grant select on ai_cost_daily to authenticated;


-- ==== supabase/migrations/20261012100001_eval_operations_admin_only.sql ====
-- Ember Readiness, Stage 1 (docs/dev-request-ember-readiness-and-knowledge-
-- gaps.md): running evaluations, marking a baseline and recording human
-- review become platform-admin work. AI evaluation is evidence that Ember
-- understands a Project before it suggests anything -- a platform decision,
-- alongside choosing the default model -- so it moves to the admin
-- dashboard.
--
-- What changes:
--   eval_runs     insert/update: curator/admin + own-run consultant -> admin
--   eval_results  insert/update: curator/admin + consultant          -> admin
--
-- What deliberately does NOT change:
--   * eval_datasets / eval_cases: platform curators and Project curators
--     still create datasets and author draft cases -- they know the correct
--     answers for their Project. Draft-only case mutation stays enforced by
--     20260809110004_eval_rls.sql.
--   * Every select policy: reading runs and results is unchanged here; the
--     run pages themselves are admin-only in the app. Stage 2's readiness
--     section shows the measured score to Project members.
--   * graph_runs / graph_steps: Agents' "Ask a question" still creates
--     graph_runs as consultants; an admin's graph-mode eval run is already
--     covered by graph_runs_insert_staff.

drop policy if exists "eval_runs_insert_staff" on eval_runs;
drop policy if exists "eval_runs_update_staff" on eval_runs;
drop policy if exists "eval_runs_insert_active_consultant" on eval_runs;
drop policy if exists "eval_runs_update_own_consultant" on eval_runs;

create policy "eval_runs_insert_admin" on eval_runs
  for insert with check (is_admin(auth.uid()));

-- executeEvalRun's status transitions and markBaselineAction both update
-- eval_runs in the caller's session.
create policy "eval_runs_update_admin" on eval_runs
  for update using (is_admin(auth.uid())) with check (is_admin(auth.uid()));

drop policy if exists "eval_results_insert_staff" on eval_results;
drop policy if exists "eval_results_update_staff" on eval_results;
drop policy if exists "eval_results_insert_active_consultant" on eval_results;

create policy "eval_results_insert_admin" on eval_results
  for insert with check (is_admin(auth.uid()));

-- Human review (human_* columns) is the only in-place update of a result.
create policy "eval_results_update_admin" on eval_results
  for update using (is_admin(auth.uid())) with check (is_admin(auth.uid()));


-- ==== supabase/migrations/20261013100001_project_ember_readiness.sql ====
-- Ember Readiness, Stage 2 (docs/dev-request-ember-readiness-and-knowledge-
-- gaps.md): a per-Project readiness section showing how ready Ember is for
-- this Project. Two signals stay visibly separate:
--
--   * curator confidence -- a percentage, verdict and rationale a Project
--     curator or platform admin sets (project_ember_readiness, append-only
--     history; the newest row is current);
--   * measured score -- the latest completed admin eval run on the
--     Project's dataset, as "questions passed of questions asked".
--
-- Project members (viewers included) can read both, but most of them cannot
-- read eval_runs / eval_results (Stage 1 left those to staff), so the
-- measured score and knowledge coverage come from a SECURITY DEFINER
-- function that returns counts only, and only for Projects the caller is a
-- member of.

-- Measured score ---------------------------------------------------------------
-- A question passes when a human reviewer accepted it; with no review, when
-- nothing contradicts it and at least one signal supports it: the expected
-- evidence was retrieved (retrieval_hit is not false) and either the LLM
-- judge's outcome score is at least 0.7 or, with no judge, the expected
-- evidence was retrieved. Human review always wins over the automated
-- signals. Internal helper: no auth check, so not executable by clients.
create or replace function project_measured_score(pid uuid)
returns table (run_id uuid, dataset_name text, completed_at timestamptz, question_count integer, passed_count integer)
language sql stable security definer set search_path = public as $$
  with latest as (
    select r.id, d.name, r.completed_at
    from eval_runs r
    join eval_datasets d on d.id = r.dataset_id
    where d.project_id = pid and d.status <> 'archived' and r.status = 'completed'
    order by r.completed_at desc nulls last, r.created_at desc
    limit 1
  )
  select
    l.id,
    l.name,
    l.completed_at,
    count(res.id)::integer,
    (count(res.id) filter (
      where res.status = 'completed'
        and coalesce(
          res.human_accepted,
          (res.retrieval_hit is distinct from false)
            and (res.outcome_score >= 0.7 or (res.outcome_score is null and res.retrieval_hit is true))
        )
    ))::integer
  from latest l
  left join eval_results res on res.eval_run_id = l.id
  group by l.id, l.name, l.completed_at;
$$;

revoke execute on function project_measured_score(uuid) from public, anon, authenticated;

-- Readiness signals for the caller's own Projects ----------------------------------
-- One row per requested Project the caller is a member of (is_project_member
-- carries the platform-admin bypass). Counts only -- never source titles or
-- content -- so a restricted source still counts toward coverage without
-- being revealed.
create or replace function project_ember_readiness_signals(pids uuid[])
returns table (
  project_id uuid,
  measured_run_id uuid,
  measured_dataset_name text,
  measured_at timestamptz,
  measured_questions integer,
  measured_passed integer,
  source_count integer,
  searchable_source_count integer,
  wiki_article_count integer,
  last_source_added_at timestamptz
)
language sql stable security definer set search_path = public as $$
  with allowed as (
    select distinct p.id from unnest(pids) as p(id) where is_project_member(p.id, auth.uid())
  ),
  project_kbs as (
    select kb.project_id, kb.id as kb_id from knowledge_bases kb join allowed a on a.id = kb.project_id
    union
    select pkb.project_id, pkb.knowledge_base_id from project_knowledge_bases pkb join allowed a on a.id = pkb.project_id
  ),
  sources as (
    select pk.project_id, ks.id, ks.created_at, ks.current_version_id
    from project_kbs pk
    join knowledge_sources ks on ks.knowledge_base_id = pk.kb_id
    where ks.lifecycle_status = 'active'
  ),
  articles as (
    select pwa.project_id, w.id
    from project_wiki_articles pwa
    join allowed a on a.id = pwa.project_id
    join wiki_articles w on w.id = pwa.wiki_article_id
    where w.status = 'approved'
    union
    select pk.project_id, w.id
    from project_kbs pk
    join wiki_articles w on w.knowledge_base_id = pk.kb_id
    where w.status = 'approved'
  )
  select
    a.id,
    m.run_id,
    m.dataset_name,
    m.completed_at,
    m.question_count,
    m.passed_count,
    (select count(distinct s.id) from sources s where s.project_id = a.id)::integer,
    (select count(distinct s.id) from sources s
      where s.project_id = a.id
        and exists (select 1 from document_chunks dc where dc.document_id = s.current_version_id and dc.review_status = 'approved'))::integer,
    (select count(distinct ar.id) from articles ar where ar.project_id = a.id)::integer,
    (select max(s.created_at) from sources s where s.project_id = a.id)
  from allowed a
  left join lateral project_measured_score(a.id) m on true;
$$;

revoke execute on function project_ember_readiness_signals(uuid[]) from public, anon;
grant execute on function project_ember_readiness_signals(uuid[]) to authenticated;

-- Curator confidence and verdict (append-only history) ------------------------------
create table project_ember_readiness (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  confidence_percent integer not null check (confidence_percent between 0 and 100),
  verdict text not null check (verdict in ('ready', 'needs_more_sources')),
  rationale text not null check (length(trim(rationale)) > 0),
  -- When this judgement should be looked at again. After it, the section
  -- shows "review due".
  review_due_at timestamptz not null,
  -- The measured score (0..1) when this was set, so a later drop can mark
  -- the judgement for review. Filled by the trigger below, never by the
  -- client; null when no eval run existed yet.
  measured_score_at_set numeric,
  set_by uuid references profiles(id) on delete set null,
  set_at timestamptz not null default now()
);

create index project_ember_readiness_project_set_at_idx on project_ember_readiness(project_id, set_at desc);

create or replace function project_ember_readiness_before_insert()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_questions integer;
  v_passed integer;
begin
  new.set_at := now();
  if new.review_due_at <= now() then
    raise exception 'project_ember_readiness: review_due_at must be in the future';
  end if;
  if new.review_due_at > now() + interval '366 days' then
    raise exception 'project_ember_readiness: review_due_at must be within a year';
  end if;
  select question_count, passed_count into v_questions, v_passed from project_measured_score(new.project_id);
  new.measured_score_at_set := case when v_questions > 0 then v_passed::numeric / v_questions else null end;
  return new;
end;
$$;

create trigger project_ember_readiness_before_insert before insert on project_ember_readiness
  for each row execute function project_ember_readiness_before_insert();

alter table project_ember_readiness enable row level security;

create policy "project_ember_readiness_select_member" on project_ember_readiness
  for select using (is_project_member(project_id, auth.uid()));

-- Project owner/curator or platform admin (can_curate_project), recorded
-- as themselves. No update or delete policy: history is append-only; a
-- change is a new row.
create policy "project_ember_readiness_insert_curator" on project_ember_readiness
  for insert with check (can_curate_project(project_id, auth.uid()) and set_by = auth.uid());

-- External MCP read-only guarantee: an OAuth client token can never write
-- the new table (20261005100001_external_mcp_access.sql). Guarded so this
-- migration also applies to a database where that one hasn't run yet: when
-- it does run, its own apply_oauth_read_only_policies() call covers every
-- RLS table that exists by then, this one included.
do $$
begin
  if to_regprocedure('public.apply_oauth_read_only_policies()') is not null then
    perform apply_oauth_read_only_policies();
  end if;
end;
$$;


-- ==== supabase/migrations/20261014100001_project_knowledge_gaps.sql ====
-- Ember Readiness, Stage 3 (docs/dev-request-ember-readiness-and-knowledge-
-- gaps.md): failure reports and the curator's knowledge-gap queue.
--
-- A Project member reports that Ember got something wrong (from an Ember
-- answer, or typed into the Project's readiness section). The report lands
-- in the Project's knowledge-gap queue for its curators, who triage it,
-- resolve it by linking the source or Wiki article that now covers it,
-- record whether Ember now answers it, and can turn it into a draft test
-- question. Stage 4 adds automatically detected gaps (origin =
-- 'automatic') to the same table.
--
-- Failure reports are Project-scoped and never reach the platform-owner
-- feedback board unless a curator converts one (feedback_report_id).

create table project_knowledge_gaps (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  origin text not null default 'failure_report' check (origin in ('failure_report', 'automatic')),

  -- What the reporter saw. Fixed once reported (see the update trigger).
  question text not null check (length(trim(question)) > 0),
  ember_answer text,
  failure_kind text check (failure_kind in ('wrong', 'incomplete', 'outdated', 'wrong_source', 'could_not_answer')),
  details text,
  correct_answer text,
  suggested_source text,
  -- Stage 4: Ember's own description of what is missing.
  missing_topic text,
  conversation_id uuid references conversations(id) on delete set null,
  message_id uuid references chat_messages(id) on delete set null,
  answer_provider text,
  answer_model text,
  -- The answer's verified citations at report time: [{label, sourceType, sourceId}].
  cited_sources jsonb,
  reported_by uuid references profiles(id) on delete set null,

  -- Curator workflow.
  status text not null default 'new'
    check (status in ('new', 'needs_source', 'wiki_needed', 'resolved', 'out_of_scope', 'product_issue', 'duplicate')),
  triage_note text,
  duplicate_of uuid references project_knowledge_gaps(id) on delete set null,
  resolving_source_id uuid references knowledge_sources(id) on delete set null,
  resolving_article_id uuid references wiki_articles(id) on delete set null,
  resolution_note text,
  -- Whether Ember answered the question correctly when re-asked after the
  -- fix, as recorded by the curator.
  verified_answers boolean,
  verified_by uuid references profiles(id) on delete set null,
  verified_at timestamptz,
  eval_case_id uuid references eval_cases(id) on delete set null,
  feedback_report_id uuid references feedback_reports(id) on delete set null,
  resolved_by uuid references profiles(id) on delete set null,
  resolved_at timestamptz,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index project_knowledge_gaps_project_status_idx on project_knowledge_gaps(project_id, status);
create index project_knowledge_gaps_reported_by_idx on project_knowledge_gaps(reported_by);

create trigger project_knowledge_gaps_set_updated_at before update on project_knowledge_gaps
  for each row execute function set_updated_at();

-- Insert guard: a new report always starts untriaged, and a report tied to
-- a conversation must come from the reporter's own conversation bound to
-- this Project.
create or replace function project_knowledge_gaps_before_insert()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.status := 'new';
  new.triage_note := null;
  new.duplicate_of := null;
  new.resolving_source_id := null;
  new.resolving_article_id := null;
  new.resolution_note := null;
  new.verified_answers := null;
  new.verified_by := null;
  new.verified_at := null;
  new.eval_case_id := null;
  new.feedback_report_id := null;
  new.resolved_by := null;
  new.resolved_at := null;
  new.created_at := now();

  if new.conversation_id is not null and not exists (
    select 1 from conversations c
    where c.id = new.conversation_id and c.project_id = new.project_id and c.user_id = new.reported_by
  ) then
    raise exception 'project_knowledge_gaps: the conversation must be the reporter''s own, bound to this Project';
  end if;
  if new.message_id is not null and not exists (
    select 1 from chat_messages m where m.id = new.message_id and m.conversation_id = new.conversation_id and m.role = 'assistant'
  ) then
    raise exception 'project_knowledge_gaps: the message must be an Ember answer in that conversation';
  end if;
  return new;
end;
$$;

create trigger project_knowledge_gaps_before_insert before insert on project_knowledge_gaps
  for each row execute function project_knowledge_gaps_before_insert();

-- Update guard: curators work the queue but never rewrite what was reported.
create or replace function project_knowledge_gaps_before_update()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.project_id is distinct from old.project_id
    or new.origin is distinct from old.origin
    or new.question is distinct from old.question
    or new.ember_answer is distinct from old.ember_answer
    or new.failure_kind is distinct from old.failure_kind
    or new.details is distinct from old.details
    or new.correct_answer is distinct from old.correct_answer
    or new.suggested_source is distinct from old.suggested_source
    or new.missing_topic is distinct from old.missing_topic
    or new.conversation_id is distinct from old.conversation_id
    or new.message_id is distinct from old.message_id
    or new.answer_provider is distinct from old.answer_provider
    or new.answer_model is distinct from old.answer_model
    or new.cited_sources is distinct from old.cited_sources
    or new.reported_by is distinct from old.reported_by
    or new.created_at is distinct from old.created_at
  then
    raise exception 'project_knowledge_gaps: what was reported cannot be changed';
  end if;
  return new;
end;
$$;

create trigger project_knowledge_gaps_before_update before update on project_knowledge_gaps
  for each row execute function project_knowledge_gaps_before_update();

alter table project_knowledge_gaps enable row level security;

-- The reporter sees their own reports (and how they were resolved); the
-- Project's owner/curators and platform admins see the whole queue. Other
-- members see only the open count, through project_ember_readiness_signals.
create policy "project_knowledge_gaps_select_reporter_or_curator" on project_knowledge_gaps
  for select using (reported_by = auth.uid() or can_curate_project(project_id, auth.uid()));

create policy "project_knowledge_gaps_insert_member" on project_knowledge_gaps
  for insert with check (reported_by = auth.uid() and is_project_member(project_id, auth.uid()));

create policy "project_knowledge_gaps_update_curator" on project_knowledge_gaps
  for update using (can_curate_project(project_id, auth.uid())) with check (can_curate_project(project_id, auth.uid()));

-- No delete policy: a gap is closed (resolved, out of scope, duplicate,
-- product issue), never removed.

-- Readiness signals gain the open-gap count ---------------------------------------
-- Open = new, needs_source or wiki_needed. The return type changes, so the
-- function is dropped and recreated (create or replace cannot change it).
drop function if exists project_ember_readiness_signals(uuid[]);

create function project_ember_readiness_signals(pids uuid[])
returns table (
  project_id uuid,
  measured_run_id uuid,
  measured_dataset_name text,
  measured_at timestamptz,
  measured_questions integer,
  measured_passed integer,
  source_count integer,
  searchable_source_count integer,
  wiki_article_count integer,
  last_source_added_at timestamptz,
  open_gap_count integer
)
language sql stable security definer set search_path = public as $$
  with allowed as (
    select distinct p.id from unnest(pids) as p(id) where is_project_member(p.id, auth.uid())
  ),
  project_kbs as (
    select kb.project_id, kb.id as kb_id from knowledge_bases kb join allowed a on a.id = kb.project_id
    union
    select pkb.project_id, pkb.knowledge_base_id from project_knowledge_bases pkb join allowed a on a.id = pkb.project_id
  ),
  sources as (
    select pk.project_id, ks.id, ks.created_at, ks.current_version_id
    from project_kbs pk
    join knowledge_sources ks on ks.knowledge_base_id = pk.kb_id
    where ks.lifecycle_status = 'active'
  ),
  articles as (
    select pwa.project_id, w.id
    from project_wiki_articles pwa
    join allowed a on a.id = pwa.project_id
    join wiki_articles w on w.id = pwa.wiki_article_id
    where w.status = 'approved'
    union
    select pk.project_id, w.id
    from project_kbs pk
    join wiki_articles w on w.knowledge_base_id = pk.kb_id
    where w.status = 'approved'
  )
  select
    a.id,
    m.run_id,
    m.dataset_name,
    m.completed_at,
    m.question_count,
    m.passed_count,
    (select count(distinct s.id) from sources s where s.project_id = a.id)::integer,
    (select count(distinct s.id) from sources s
      where s.project_id = a.id
        and exists (select 1 from document_chunks dc where dc.document_id = s.current_version_id and dc.review_status = 'approved'))::integer,
    (select count(distinct ar.id) from articles ar where ar.project_id = a.id)::integer,
    (select max(s.created_at) from sources s where s.project_id = a.id),
    (select count(*) from project_knowledge_gaps g
      where g.project_id = a.id and g.status in ('new', 'needs_source', 'wiki_needed'))::integer
  from allowed a
  left join lateral project_measured_score(a.id) m on true;
$$;

revoke execute on function project_ember_readiness_signals(uuid[]) from public, anon;
grant execute on function project_ember_readiness_signals(uuid[]) to authenticated;

