-- RLS table that exists by then, this one included.
do $$
begin
  if to_regprocedure('public.apply_oauth_read_only_policies()') is not null then
    perform apply_oauth_read_only_policies();
  end if;
end;
$$;


-- ==== supabase/migrations/20261015100001_knowledge_gap_detection.sql ====
-- Ember Readiness, Stage 4 (docs/dev-request-ember-readiness-and-knowledge-
-- gaps.md): Ember detects its own knowledge gaps in Project-bound chat and
-- files them for the Project's curators.
--
-- When a Project conversation's answer is not grounded in the Project's
-- knowledge (Ember says so in its response envelope, or the Project search
-- found nothing relevant and Ember gave no coverage declaration), the app
-- calls record_automatic_knowledge_gap(). Similar questions are grouped into
-- one open gap with an occurrence count, so ten people asking the same thing
-- produce one gap, not ten. The person who asked sees that a gap was sent
-- and can add details or withdraw it.

-- Grouping counts -----------------------------------------------------------------
-- occurrence_count is how many times the question has come up: 1 for a new
-- gap (failure report or detection), +1 for each grouped detection.
alter table project_knowledge_gaps
  add column occurrence_count integer not null default 1 check (occurrence_count >= 0),
  add column last_occurred_at timestamptz not null default now();

-- One row per detection, including the one that created an automatic gap.
create table project_knowledge_gap_occurrences (
  id uuid primary key default gen_random_uuid(),
  gap_id uuid not null references project_knowledge_gaps(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  conversation_id uuid references conversations(id) on delete set null,
  message_id uuid references chat_messages(id) on delete set null,
  question text not null,
  missing_topic text,
  -- declared: Ember said the answer was partial or not in Project knowledge.
  -- no_project_evidence: the Project search found nothing relevant and
  -- Ember made no coverage declaration.
  signal text not null check (signal in ('declared', 'no_project_evidence')),
  -- Added by the person who asked, after the fact ("Add details").
  note text,
  suggested_source text,
  created_at timestamptz not null default now(),
  unique (message_id)
);

create index project_knowledge_gap_occurrences_gap_idx on project_knowledge_gap_occurrences(gap_id);
create index project_knowledge_gap_occurrences_project_idx on project_knowledge_gap_occurrences(project_id);

-- The person who asked may only add a note or a suggested source. Runs with
-- the caller's role (not SECURITY DEFINER), so it binds API callers while
-- withdraw_knowledge_gap_occurrence(), running as the owner, can still move
-- detections onto a re-created gap.
create or replace function project_knowledge_gap_occurrences_before_update()
returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if new.gap_id is distinct from old.gap_id
    or new.project_id is distinct from old.project_id
    or new.user_id is distinct from old.user_id
    or new.conversation_id is distinct from old.conversation_id
    or new.message_id is distinct from old.message_id
    or new.question is distinct from old.question
    or new.missing_topic is distinct from old.missing_topic
    or new.signal is distinct from old.signal
    or new.created_at is distinct from old.created_at
  then
    raise exception 'project_knowledge_gap_occurrences: only the note and suggested source can be changed';
  end if;
  return new;
end;
$$;

create trigger project_knowledge_gap_occurrences_before_update before update on project_knowledge_gap_occurrences
  for each row execute function project_knowledge_gap_occurrences_before_update();

alter table project_knowledge_gap_occurrences enable row level security;

-- Same visibility as the gaps themselves: the person who asked, and the
-- Project's owner/curators and platform admins. Inserts and deletes only
-- happen through the functions below.
create policy "project_knowledge_gap_occurrences_select_own_or_curator" on project_knowledge_gap_occurrences
  for select using (user_id = auth.uid() or can_curate_project(project_id, auth.uid()));

create policy "project_knowledge_gap_occurrences_update_own" on project_knowledge_gap_occurrences
  for update using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Similarity for grouping -----------------------------------------------------------
-- Word overlap (Jaccard) over lower-cased words, ignoring common question
-- words, with a light suffix trim (configure/configured/configuring and
-- trunk/trunks/trunking match) and words of three or more letters kept.
-- Deterministic and needs no AI call or extension; good enough to group
-- rephrasings of the same question.
create or replace function knowledge_gap_similarity(a text, b text)
returns numeric
language sql immutable set search_path = public as $$
  with stop(w) as (
    select unnest(array[
      'the', 'and', 'for', 'are', 'but', 'not', 'you', 'all', 'any', 'can', 'how', 'what', 'when', 'where',
      'which', 'who', 'why', 'does', 'did', 'with', 'this', 'that', 'from', 'our', 'your', 'have', 'has',
      'was', 'were', 'will', 'would', 'should', 'could', 'into', 'about', 'there', 'their', 'they', 'them',
      'its', 'tell', 'please', 'know', 'need', 'use', 'used', 'using', 'get'
    ])
  ),
  ta as (
    select distinct regexp_replace(w, '(ing|ed|es|e|s)$', '') as w
    from regexp_split_to_table(lower(coalesce(a, '')), '[^a-z0-9]+') as w
    where length(w) >= 3 and w not in (select w from stop)
  ),
  tb as (
    select distinct regexp_replace(w, '(ing|ed|es|e|s)$', '') as w
    from regexp_split_to_table(lower(coalesce(b, '')), '[^a-z0-9]+') as w
    where length(w) >= 3 and w not in (select w from stop)
  ),
  u as (select w from ta union select w from tb)
  select case
    when (select count(*) from u) = 0 then 0
    else (select count(*) from ta join tb using (w))::numeric / (select count(*) from u)
  end;
$$;

-- Record a detected gap ----------------------------------------------------------
-- Called by the app, in the asking user's session, right after an Ember
-- answer in a Project conversation. SECURITY DEFINER so it can group with
-- open gaps the caller cannot read (other members' reports) without ever
-- returning their content. Idempotent per answer.
create or replace function record_automatic_knowledge_gap(
  p_message_id uuid,
  p_question text,
  p_missing_topic text,
  p_signal text
)
returns table (gap_id uuid, occurrence_id uuid, is_new boolean, occurrence_count integer)
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_message chat_messages%rowtype;
  v_project_id uuid;
  v_question text := left(trim(coalesce(p_question, '')), 2000);
  v_topic text := nullif(left(trim(coalesce(p_missing_topic, '')), 300), '');
  v_text text;
  v_existing project_knowledge_gap_occurrences%rowtype;
  v_gap_id uuid;
  v_count integer;
  v_new boolean := false;
  v_occurrence_id uuid;
begin
  if v_uid is null then
    raise exception 'record_automatic_knowledge_gap: not signed in';
  end if;
  if p_signal not in ('declared', 'no_project_evidence') then
    raise exception 'record_automatic_knowledge_gap: unknown signal';
  end if;
  if v_question = '' then
    raise exception 'record_automatic_knowledge_gap: question is required';
  end if;

  select * into v_message from chat_messages where id = p_message_id and role = 'assistant';
  if not found then
    raise exception 'record_automatic_knowledge_gap: not an Ember answer';
  end if;

  -- Only the caller's own Project chat conversation (never feedback, never
  -- unbound), and only while they are a member.
  select c.project_id into v_project_id
  from conversations c
  where c.id = v_message.conversation_id and c.user_id = v_uid and c.project_id is not null and c.kind = 'chat';
  if v_project_id is null or not is_project_member(v_project_id, v_uid) then
    raise exception 'record_automatic_knowledge_gap: not a Project conversation of yours';
  end if;

  select * into v_existing from project_knowledge_gap_occurrences o where o.message_id = p_message_id;
  if found then
    select g.occurrence_count into v_count from project_knowledge_gaps g where g.id = v_existing.gap_id;
    return query select v_existing.gap_id, v_existing.id, false, coalesce(v_count, 0);
    return;
  end if;

  v_text := coalesce(v_topic, '') || ' ' || v_question;

  select g.id into v_gap_id
  from project_knowledge_gaps g
  where g.project_id = v_project_id
    and g.status in ('new', 'needs_source', 'wiki_needed')
    -- 0.65: rephrasings of one question scored 0.67-0.80 in testing; two
    -- different questions about the same system ("who owns the CCDRRMO radio
    -- network" vs "what protocol does it use") scored 0.60.
    and knowledge_gap_similarity(coalesce(g.missing_topic, '') || ' ' || g.question, v_text) >= 0.65
  order by knowledge_gap_similarity(coalesce(g.missing_topic, '') || ' ' || g.question, v_text) desc, g.created_at
  limit 1;

  if v_gap_id is not null then
    update project_knowledge_gaps g
    set occurrence_count = g.occurrence_count + 1, last_occurred_at = now()
    where g.id = v_gap_id
    returning g.occurrence_count into v_count;
  else
    insert into project_knowledge_gaps (
      project_id, origin, question, ember_answer, failure_kind, missing_topic,
      conversation_id, message_id, answer_provider, answer_model, reported_by
    ) values (
      v_project_id, 'automatic', v_question, left(v_message.content, 8000), 'could_not_answer', v_topic,
      v_message.conversation_id, v_message.id, v_message.provider, v_message.model, v_uid
    )
    returning id, project_knowledge_gaps.occurrence_count into v_gap_id, v_count;
    v_new := true;
  end if;

  insert into project_knowledge_gap_occurrences (gap_id, project_id, user_id, conversation_id, message_id, question, missing_topic, signal)
  values (v_gap_id, v_project_id, v_uid, v_message.conversation_id, v_message.id, v_question, v_topic, p_signal)
  returning id into v_occurrence_id;

  return query select v_gap_id, v_occurrence_id, v_new, v_count;
end;
$$;

revoke execute on function record_automatic_knowledge_gap(uuid, text, text, text) from public, anon;
grant execute on function record_automatic_knowledge_gap(uuid, text, text, text) to authenticated;

-- "Don't send" ------------------------------------------------------------------
-- The person who asked withdraws their detection within a day.
--   * A grouped detection (someone else's question started the gap): the
--     count drops by one.
--   * The detection that started an untriaged automatic gap: the asker's
--     question must not stay on it, so the gap is removed, or, if others
--     have since asked the same thing, re-created from the next person's
--     question with their detections moved onto it.
--   * The detection that started a gap a curator is already working on:
--     refused -- the curator's work is not discarded.
create or replace function withdraw_knowledge_gap_occurrence(p_occurrence_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_occurrence project_knowledge_gap_occurrences%rowtype;
  v_gap project_knowledge_gaps%rowtype;
  v_next project_knowledge_gap_occurrences%rowtype;
  v_next_message chat_messages%rowtype;
  v_new_gap_id uuid;
begin
  select * into v_occurrence from project_knowledge_gap_occurrences
  where id = p_occurrence_id and user_id = auth.uid() and created_at > now() - interval '1 day';
  if not found then
    raise exception 'withdraw_knowledge_gap_occurrence: nothing to withdraw';
  end if;

  select * into v_gap from project_knowledge_gaps where id = v_occurrence.gap_id;

  if v_gap.origin <> 'automatic' or v_gap.message_id is distinct from v_occurrence.message_id then
    delete from project_knowledge_gap_occurrences where id = v_occurrence.id;
    update project_knowledge_gaps set occurrence_count = greatest(occurrence_count - 1, 0) where id = v_gap.id;
    return;
  end if;

  if v_gap.status <> 'new' then
    raise exception 'withdraw_knowledge_gap_occurrence: a curator is already working on this gap';
  end if;

  delete from project_knowledge_gap_occurrences where id = v_occurrence.id;

  select * into v_next from project_knowledge_gap_occurrences where gap_id = v_gap.id order by created_at limit 1;
  if found then
    select * into v_next_message from chat_messages where id = v_next.message_id;
    insert into project_knowledge_gaps (
      project_id, origin, question, ember_answer, failure_kind, missing_topic,
      conversation_id, message_id, answer_provider, answer_model, reported_by
    ) values (
      v_gap.project_id, 'automatic', v_next.question, left(v_next_message.content, 8000), 'could_not_answer', v_next.missing_topic,
      v_next.conversation_id, v_next.message_id, v_next_message.provider, v_next_message.model, v_next.user_id
    )
    returning id into v_new_gap_id;
    update project_knowledge_gap_occurrences set gap_id = v_new_gap_id where gap_id = v_gap.id;
    update project_knowledge_gaps
    set occurrence_count = (select count(*) from project_knowledge_gap_occurrences where gap_id = v_new_gap_id)
    where id = v_new_gap_id;
  end if;

  delete from project_knowledge_gaps where id = v_gap.id;
end;
$$;

revoke execute on function withdraw_knowledge_gap_occurrence(uuid) from public, anon;
grant execute on function withdraw_knowledge_gap_occurrence(uuid) to authenticated;

-- External MCP read-only guarantee: an OAuth client token can never write
-- the new table (20261005100001_external_mcp_access.sql). Guarded so this
-- migration also applies to a database where that migration has not run
-- yet. When it does run, its own call covers every RLS table that exists by
-- then, this one included.
do $$
begin
  if to_regprocedure('public.apply_oauth_read_only_policies()') is not null then
    perform apply_oauth_read_only_policies();
  end if;
end;
$$;


-- ==== supabase/migrations/20261016100001_workstream_knowledge_in_project_search.sql ====
-- Workstream knowledge counts as Project knowledge, and readiness coverage
-- counts exactly what Ember searches (docs/dev-request-ember-readiness-and-
-- knowledge-gaps.md, follow-up).
--
-- 1. A knowledge base attached to one of a Project's workstreams
--    (workstream_knowledge_bases) is now readable by that Project's members
--    the same way a Project-attached one is, and Ember's Project search
--    treats its approved chunks as Project evidence. Until now the read
--    policies only recognised project_knowledge_bases, so a private
--    workstream knowledge base was invisible to Ember (and to members).
--    Curation is unchanged: only approved chunks are embedded, and
--    has_evidence_access() still restricts individual sources.
-- 2. project_ember_readiness_signals() counts sources in exactly the
--    knowledge bases Project search uses (attached to the Project or to one
--    of its workstreams) and only Wiki articles attached to the Project --
--    not the legacy knowledge_bases.project_id link or Wiki articles that
--    merely sit in a Project knowledge base, which search treats as
--    platform evidence.

-- Membership path to a non-public knowledge base: attached to a Project the
-- caller belongs to, or to a workstream of one. Strict membership (no admin
-- bypass), same as the policies it replaces inline.
create or replace function knowledge_base_readable_via_project(p_kb_id text, uid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from project_knowledge_bases pkb
    where pkb.knowledge_base_id = p_kb_id and is_project_member_strict(pkb.project_id, uid)
  ) or exists (
    select 1 from workstream_knowledge_bases wkb
    join project_workstreams w on w.id = wkb.workstream_id
    where wkb.knowledge_base_id = p_kb_id and is_project_member_strict(w.project_id, uid)
  );
$$;

-- The three read policies from 20260825110001_project_evidence_access_
-- enforcement.sql, unchanged except that the project_knowledge_bases-only
-- check becomes knowledge_base_readable_via_project().

drop policy "knowledge_sources_select_staff_or_owner_or_project_member" on knowledge_sources;
create policy "knowledge_sources_select_staff_or_owner_or_project_member" on knowledge_sources
  for select using (
    has_evidence_access('knowledge_source', knowledge_sources.id, auth.uid())
    and (
      is_curator_or_admin(auth.uid())
      or created_by = auth.uid()
      or exists (
        select 1 from knowledge_bases kb
        where kb.id = knowledge_sources.knowledge_base_id
        and (
          kb.visibility_scope in ('platform', 'public')
          or (
            kb.visibility_scope in ('project_private', 'selected_projects')
            and knowledge_base_readable_via_project(kb.id, auth.uid())
          )
        )
      )
    )
  );

drop policy "documents_select_staff_or_owner_or_project_member" on documents;
create policy "documents_select_staff_or_owner_or_project_member" on documents
  for select using (
    has_evidence_access('knowledge_source', documents.knowledge_source_id, auth.uid())
    and (
      is_curator_or_admin(auth.uid())
      or uploaded_by = auth.uid()
      or exists (
        select 1 from knowledge_sources ks
        join knowledge_bases kb on kb.id = ks.knowledge_base_id
        where ks.id = documents.knowledge_source_id
        and (
          kb.visibility_scope in ('platform', 'public')
          or (
            kb.visibility_scope in ('project_private', 'selected_projects')
            and knowledge_base_readable_via_project(kb.id, auth.uid())
          )
        )
      )
    )
  );

drop policy "kb_vectors_select_scoped" on kb_vectors;
create policy "kb_vectors_select_scoped" on kb_vectors
  for select using (
    exists (
      select 1 from documents d
      join knowledge_sources ks on ks.current_version_id = d.id
      join knowledge_bases kb on kb.id = ks.knowledge_base_id
      where d.id = kb_vectors.document_id
      and has_evidence_access('knowledge_source', ks.id, auth.uid())
      and (
        kb.visibility_scope in ('platform', 'public')
        or (
          kb.visibility_scope in ('project_private', 'selected_projects')
          and knowledge_base_readable_via_project(kb.id, auth.uid())
        )
      )
    )
  );

-- Readiness coverage = Project search scope -----------------------------------------
-- Same return type as 20261014100001, so create or replace is enough.
create or replace function project_ember_readiness_signals(pids uuid[])
returns table (
  project_id uuid,
  measured_run_id uuid,
  measured_dataset_name text,
  measured_at timestamptz,
  measured_questions integer,
  measured_passed integer,
  source_count integer,
  searchable_source_count integer,
  wiki_article_count integer,
  last_source_added_at timestamptz,
  open_gap_count integer
)
language sql stable security definer set search_path = public as $$
  with allowed as (
    select distinct p.id from unnest(pids) as p(id) where is_project_member(p.id, auth.uid())
  ),
  project_kbs as (
    select pkb.project_id, pkb.knowledge_base_id as kb_id
    from project_knowledge_bases pkb join allowed a on a.id = pkb.project_id
    union
    select w.project_id, wkb.knowledge_base_id
    from workstream_knowledge_bases wkb
    join project_workstreams w on w.id = wkb.workstream_id
    join allowed a on a.id = w.project_id
  ),
  sources as (
    select pk.project_id, ks.id, ks.created_at, ks.current_version_id
    from project_kbs pk
    join knowledge_sources ks on ks.knowledge_base_id = pk.kb_id
    where ks.lifecycle_status = 'active'
  ),
  articles as (
    select pwa.project_id, w.id
    from project_wiki_articles pwa
    join allowed a on a.id = pwa.project_id
    join wiki_articles w on w.id = pwa.wiki_article_id
    where w.status = 'approved'
  )
  select
    a.id,
    m.run_id,
    m.dataset_name,
    m.completed_at,
    m.question_count,
    m.passed_count,
    (select count(distinct s.id) from sources s where s.project_id = a.id)::integer,
    (select count(distinct s.id) from sources s
      where s.project_id = a.id
        and exists (select 1 from document_chunks dc where dc.document_id = s.current_version_id and dc.review_status = 'approved'))::integer,
    (select count(distinct ar.id) from articles ar where ar.project_id = a.id)::integer,
    (select max(s.created_at) from sources s where s.project_id = a.id),
    (select count(*) from project_knowledge_gaps g
      where g.project_id = a.id and g.status in ('new', 'needs_source', 'wiki_needed'))::integer
  from allowed a
  left join lateral project_measured_score(a.id) m on true;
$$;

revoke execute on function project_ember_readiness_signals(uuid[]) from public, anon;
grant execute on function project_ember_readiness_signals(uuid[]) to authenticated;


-- ==== supabase/migrations/20261017100001_solution_requirements.sql ====
-- Solution conformance and acceptance evaluation, Stage 1: the requirements
-- register (docs/dev-request-solution-conformance-and-acceptance-
-- evaluation.md).
--
-- A requirement is one verifiable statement the Project's delivered
-- solution must satisfy, traced to where it came from (a standard clause,
-- regulation, contract term, customer need or vendor claim), scoped to the
-- workstreams and Project objects it concerns, and given one or more
-- verification methods with explicit pass criteria. Later stages add
-- verification records, frozen baselines with conformance decisions, and
-- re-verification triggers.
--
-- Editing: a requirement and its sources, scope and methods can be changed
-- only while it is a draft. Once baselined (Stage 3) its content is fixed;
-- it can only be withdrawn or superseded by a new requirement.

create table solution_requirements (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  code text not null check (length(trim(code)) > 0),
  title text not null check (length(trim(title)) > 0),
  statement text not null check (length(trim(statement)) > 0),
  rationale text,
  category text not null
    check (category in ('functional', 'interface', 'performance', 'security', 'privacy', 'operational', 'regulatory', 'contractual')),
  priority text not null default 'must' check (priority in ('must', 'should', 'could')),
  applies_from text not null default 'deployment' check (applies_from in ('presales', 'deployment', 'management_maintenance')),
  status text not null default 'draft' check (status in ('draft', 'baselined', 'superseded', 'withdrawn')),
  superseded_by uuid references solution_requirements(id) on delete set null,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (project_id, code)
);

create index solution_requirements_project_idx on solution_requirements(project_id, status);

create trigger solution_requirements_set_updated_at before update on solution_requirements
  for each row execute function set_updated_at();

-- Content is fixed once a requirement leaves draft: only the status (to
-- withdrawn or superseded) and superseded_by may change.
create or replace function solution_requirements_before_update()
returns trigger
language plpgsql set search_path = public as $$
begin
  if new.project_id is distinct from old.project_id or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'solution_requirements: project and author cannot change';
  end if;
  if old.status <> 'draft' and (
    new.code is distinct from old.code
    or new.title is distinct from old.title
    or new.statement is distinct from old.statement
    or new.rationale is distinct from old.rationale
    or new.category is distinct from old.category
    or new.priority is distinct from old.priority
    or new.applies_from is distinct from old.applies_from
  ) then
    raise exception 'solution_requirements: only a draft requirement can be edited -- withdraw it or supersede it with a new one';
  end if;
  if old.status in ('superseded', 'withdrawn') and new.status is distinct from old.status then
    raise exception 'solution_requirements: a superseded or withdrawn requirement cannot be reopened';
  end if;
  return new;
end;
$$;

create trigger solution_requirements_before_update before update on solution_requirements
  for each row execute function solution_requirements_before_update();

-- Whether a requirement can still be edited (draft). Used by the child
-- tables' write policies.
create or replace function solution_requirement_is_draft(p_requirement_id uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from solution_requirements r where r.id = p_requirement_id and r.status = 'draft');
$$;

-- Sources ---------------------------------------------------------------------------
create table solution_requirement_sources (
  id uuid primary key default gen_random_uuid(),
  requirement_id uuid not null references solution_requirements(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  kind text not null check (kind in ('standard', 'regulation', 'contract', 'customer_need', 'vendor_claim')),
  -- Where it lives in the knowledge, when it does. document_version_id is
  -- the source's version at the time it was cited (set by the trigger), so
  -- a later version can mark the requirement for review (Stage 4).
  knowledge_source_id uuid references knowledge_sources(id) on delete set null,
  document_version_id uuid references documents(id) on delete set null,
  wiki_article_id uuid references wiki_articles(id) on delete set null,
  -- Human-readable clause locator: section, table, page, clause number.
  locator text,
  -- Who asked, for a customer need.
  requester text,
  note text,
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  check (kind <> 'customer_need' or length(trim(coalesce(requester, ''))) > 0)
);

create index solution_requirement_sources_requirement_idx on solution_requirement_sources(requirement_id);
create index solution_requirement_sources_knowledge_source_idx on solution_requirement_sources(knowledge_source_id);

-- Scope -----------------------------------------------------------------------------
create table solution_requirement_scope_links (
  id uuid primary key default gen_random_uuid(),
  requirement_id uuid not null references solution_requirements(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  workstream_id uuid references project_workstreams(id) on delete cascade,
  project_object_id uuid references project_objects(id) on delete cascade,
  created_at timestamptz not null default now(),
  check ((workstream_id is null) <> (project_object_id is null))
);

create unique index solution_requirement_scope_links_workstream_uniq
  on solution_requirement_scope_links(requirement_id, workstream_id) where workstream_id is not null;
create unique index solution_requirement_scope_links_object_uniq
  on solution_requirement_scope_links(requirement_id, project_object_id) where project_object_id is not null;
create index solution_requirement_scope_links_workstream_idx on solution_requirement_scope_links(workstream_id);

-- Verification methods --------------------------------------------------------------
create table solution_verification_methods (
  id uuid primary key default gen_random_uuid(),
  requirement_id uuid not null references solution_requirements(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  method text not null
    check (method in ('test', 'demonstration', 'inspection', 'analysis', 'vendor_evidence', 'operational_measure')),
  procedure text,
  pass_criteria text not null check (length(trim(pass_criteria)) > 0),
  -- Required for an operational measure: the threshold and the window it
  -- is measured over (e.g. ">= 90% answered within 15 s", "monthly").
  threshold text,
  measure_window text,
  performed_by text not null default 'integrator'
    check (performed_by in ('vendor', 'integrator', 'customer', 'independent_tester', 'project_team')),
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (method <> 'operational_measure' or (length(trim(coalesce(threshold, ''))) > 0 and length(trim(coalesce(measure_window, ''))) > 0))
);

create index solution_verification_methods_requirement_idx on solution_verification_methods(requirement_id);

create trigger solution_verification_methods_set_updated_at before update on solution_verification_methods
  for each row execute function set_updated_at();

-- Consistency: a child row belongs to its requirement's Project; a scope link
-- points inside that Project; a cited source records its current version.
create or replace function solution_requirement_child_before_write()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_project_id uuid;
begin
  select project_id into v_project_id from solution_requirements where id = new.requirement_id;
  if v_project_id is null or new.project_id is distinct from v_project_id then
    raise exception '%: must belong to its requirement''s Project', tg_table_name;
  end if;

  if tg_table_name = 'solution_requirement_scope_links' then
    if new.workstream_id is not null and not exists (select 1 from project_workstreams w where w.id = new.workstream_id and w.project_id = v_project_id) then
      raise exception 'solution_requirement_scope_links: the workstream must be in this Project';
    end if;
    if new.project_object_id is not null and not exists (select 1 from project_objects o where o.id = new.project_object_id and o.project_id = v_project_id) then
      raise exception 'solution_requirement_scope_links: the Project object must be in this Project';
    end if;
  end if;

  -- Nested, not one "and": PL/pgSQL resolves new.<field> even when an
  -- earlier condition is false, and only the sources table has it.
  if tg_table_name = 'solution_requirement_sources' and tg_op = 'INSERT' then
    if new.knowledge_source_id is not null then
      select current_version_id into new.document_version_id from knowledge_sources where id = new.knowledge_source_id;
    end if;
  end if;
  return new;
end;
$$;

create trigger solution_requirement_sources_before_write before insert or update on solution_requirement_sources
  for each row execute function solution_requirement_child_before_write();
create trigger solution_requirement_scope_links_before_write before insert or update on solution_requirement_scope_links
  for each row execute function solution_requirement_child_before_write();
create trigger solution_verification_methods_before_write before insert or update on solution_verification_methods
  for each row execute function solution_requirement_child_before_write();

-- RLS ---------------------------------------------------------------------------------
-- Every Project member reads the register; the Project's owner/curators and
-- platform admins write it (can_curate_project). Children are writable only
-- while their requirement is a draft. A source restricted by evidence access
-- is hidden from members without a grant -- curators included, so the write
-- policies are split by command (a "for all" policy would also grant select
-- and bypass that check).

alter table solution_requirements enable row level security;
alter table solution_requirement_sources enable row level security;
alter table solution_requirement_scope_links enable row level security;
alter table solution_verification_methods enable row level security;

create policy "solution_requirements_select_member" on solution_requirements
  for select using (is_project_member(project_id, auth.uid()));
create policy "solution_requirements_insert_curator" on solution_requirements
  for insert with check (can_curate_project(project_id, auth.uid()) and created_by = auth.uid() and status = 'draft');
create policy "solution_requirements_update_curator" on solution_requirements
  for update using (can_curate_project(project_id, auth.uid())) with check (can_curate_project(project_id, auth.uid()));
create policy "solution_requirements_delete_curator_draft" on solution_requirements
  for delete using (can_curate_project(project_id, auth.uid()) and status = 'draft');

create policy "solution_requirement_sources_select_member" on solution_requirement_sources
  for select using (
    is_project_member(project_id, auth.uid())
    and (knowledge_source_id is null or has_evidence_access('knowledge_source', knowledge_source_id, auth.uid()))
    and (wiki_article_id is null or has_evidence_access('wiki_article', wiki_article_id, auth.uid()))
  );
create policy "solution_requirement_sources_insert_curator_draft" on solution_requirement_sources
  for insert with check (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id));
create policy "solution_requirement_sources_update_curator_draft" on solution_requirement_sources
  for update using (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id))
  with check (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id));
create policy "solution_requirement_sources_delete_curator_draft" on solution_requirement_sources
  for delete using (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id));

create policy "solution_requirement_scope_links_select_member" on solution_requirement_scope_links
  for select using (is_project_member(project_id, auth.uid()));
create policy "solution_requirement_scope_links_insert_curator_draft" on solution_requirement_scope_links
  for insert with check (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id));
create policy "solution_requirement_scope_links_update_curator_draft" on solution_requirement_scope_links
  for update using (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id))
  with check (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id));
create policy "solution_requirement_scope_links_delete_curator_draft" on solution_requirement_scope_links
  for delete using (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id));

create policy "solution_verification_methods_select_member" on solution_verification_methods
  for select using (is_project_member(project_id, auth.uid()));
create policy "solution_verification_methods_insert_curator_draft" on solution_verification_methods
  for insert with check (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id));
create policy "solution_verification_methods_update_curator_draft" on solution_verification_methods
  for update using (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id))
  with check (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id));
create policy "solution_verification_methods_delete_curator_draft" on solution_verification_methods
  for delete using (can_curate_project(project_id, auth.uid()) and solution_requirement_is_draft(requirement_id));

-- External MCP read-only guarantee: an OAuth client token can never write
-- these tables (20261005100001_external_mcp_access.sql). Guarded so this
-- migration also applies to a database where that migration has not run
-- yet. When it does run, its own call covers every RLS table that exists by
-- then, these included.
do $$
begin
  if to_regprocedure('public.apply_oauth_read_only_policies()') is not null then
    perform apply_oauth_read_only_policies();
  end if;
end;
$$;


-- ==== supabase/migrations/20261018100001_knowledge_gap_semantic_grouping.sql ====
-- Ember Readiness follow-up: AI-based (embedding) grouping of knowledge gaps
-- (docs/dev-request-ember-readiness-and-knowledge-gaps.md).
--
-- Stage 4 grouped repeated questions by word overlap. Gaps now carry an
-- embedding of their missing topic and question, made with the platform's
-- default embedding model, and a new detection joins the open gap whose
-- embedding is most similar (cosine similarity at or above the threshold the
-- app passes in). Word overlap remains the fallback: for a detection the app
-- could not embed (no embedding model, AI policy gate, provider error), and
-- for gaps without a comparable embedding (made before this migration, or by
-- a different embedding model).

create extension if not exists vector;

-- embedding_model is "<model>/<dimensions>": vectors are only ever compared
-- with vectors from the same model and size.
-- "if not exists" so the migration can be re-run safely after a partial run.
alter table project_knowledge_gaps
  add column if not exists embedding vector,
  add column if not exists embedding_model text;

alter table project_knowledge_gap_occurrences
  add column if not exists embedding vector,
  add column if not exists embedding_model text;

-- The asker may still only change note and suggested_source on their
-- detection; the embedding columns join the frozen list.
create or replace function project_knowledge_gap_occurrences_before_update()
returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if new.gap_id is distinct from old.gap_id
    or new.project_id is distinct from old.project_id
    or new.user_id is distinct from old.user_id
    or new.conversation_id is distinct from old.conversation_id
    or new.message_id is distinct from old.message_id
    or new.question is distinct from old.question
    or new.missing_topic is distinct from old.missing_topic
    or new.signal is distinct from old.signal
    or new.created_at is distinct from old.created_at
    or new.embedding is distinct from old.embedding
    or new.embedding_model is distinct from old.embedding_model
  then
    raise exception 'project_knowledge_gap_occurrences: only the note and suggested source can be changed';
  end if;
  return new;
end;
$$;

-- record_automatic_knowledge_gap gains the embedding; its argument list
-- changes, so the old one is dropped first.
drop function if exists record_automatic_knowledge_gap(uuid, text, text, text);
drop function if exists record_automatic_knowledge_gap(uuid, text, text, text, vector, text, double precision);

create function record_automatic_knowledge_gap(
  p_message_id uuid,
  p_question text,
  p_missing_topic text,
  p_signal text,
  p_embedding vector default null,
  p_embedding_model text default null,
  p_min_similarity double precision default 0.82
)
returns table (gap_id uuid, occurrence_id uuid, is_new boolean, occurrence_count integer)
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_message chat_messages%rowtype;
  v_project_id uuid;
  v_question text := left(trim(coalesce(p_question, '')), 2000);
  v_topic text := nullif(left(trim(coalesce(p_missing_topic, '')), 300), '');
  v_text text;
  v_existing project_knowledge_gap_occurrences%rowtype;
  v_gap_id uuid;
  v_count integer;
  v_new boolean := false;
  v_occurrence_id uuid;
  v_embedding vector := case when p_embedding is not null and p_embedding_model is not null then p_embedding end;
begin
  if v_uid is null then
    raise exception 'record_automatic_knowledge_gap: not signed in';
  end if;
  if p_signal not in ('declared', 'no_project_evidence') then
    raise exception 'record_automatic_knowledge_gap: unknown signal';
  end if;
  if v_question = '' then
    raise exception 'record_automatic_knowledge_gap: question is required';
  end if;
  if p_min_similarity is null or p_min_similarity < 0.5 or p_min_similarity > 1 then
    raise exception 'record_automatic_knowledge_gap: similarity threshold must be between 0.5 and 1';
  end if;

  select * into v_message from chat_messages where id = p_message_id and role = 'assistant';
  if not found then
    raise exception 'record_automatic_knowledge_gap: not an Ember answer';
  end if;

  -- Only the caller's own Project chat conversation (never feedback, never
  -- unbound), and only while they are a member.
  select c.project_id into v_project_id
  from conversations c
  where c.id = v_message.conversation_id and c.user_id = v_uid and c.project_id is not null and c.kind = 'chat';
  if v_project_id is null or not is_project_member(v_project_id, v_uid) then
    raise exception 'record_automatic_knowledge_gap: not a Project conversation of yours';
  end if;

  select * into v_existing from project_knowledge_gap_occurrences o where o.message_id = p_message_id;
  if found then
    select g.occurrence_count into v_count from project_knowledge_gaps g where g.id = v_existing.gap_id;
    return query select v_existing.gap_id, v_existing.id, false, coalesce(v_count, 0);
    return;
  end if;

  -- 1. Semantic match: the most similar open gap embedded by the same model.
  if v_embedding is not null then
    select g.id into v_gap_id
    from project_knowledge_gaps g
    where g.project_id = v_project_id
      and g.status in ('new', 'needs_source', 'wiki_needed')
      and g.embedding is not null
      and g.embedding_model = p_embedding_model
      and 1 - (g.embedding <=> v_embedding) >= p_min_similarity
    order by g.embedding <=> v_embedding, g.created_at
    limit 1;
  end if;

  -- 2. Word-overlap fallback, only against gaps the semantic match could not
  --    compare (or all open gaps when this detection has no embedding).
  if v_gap_id is null then
    v_text := coalesce(v_topic, '') || ' ' || v_question;
    select g.id into v_gap_id
    from project_knowledge_gaps g
    where g.project_id = v_project_id
      and g.status in ('new', 'needs_source', 'wiki_needed')
      and (v_embedding is null or g.embedding is null or g.embedding_model is distinct from p_embedding_model)
      and knowledge_gap_similarity(coalesce(g.missing_topic, '') || ' ' || g.question, v_text) >= 0.65
    order by knowledge_gap_similarity(coalesce(g.missing_topic, '') || ' ' || g.question, v_text) desc, g.created_at
    limit 1;
  end if;

  if v_gap_id is not null then
    update project_knowledge_gaps g
    set occurrence_count = g.occurrence_count + 1, last_occurred_at = now()
    where g.id = v_gap_id
    returning g.occurrence_count into v_count;
  else
    insert into project_knowledge_gaps (
      project_id, origin, question, ember_answer, failure_kind, missing_topic,
      conversation_id, message_id, answer_provider, answer_model, reported_by, embedding, embedding_model
    ) values (
      v_project_id, 'automatic', v_question, left(v_message.content, 8000), 'could_not_answer', v_topic,
      v_message.conversation_id, v_message.id, v_message.provider, v_message.model, v_uid,
      v_embedding, case when v_embedding is not null then p_embedding_model end
    )
    returning id, project_knowledge_gaps.occurrence_count into v_gap_id, v_count;
    v_new := true;
  end if;

  insert into project_knowledge_gap_occurrences (gap_id, project_id, user_id, conversation_id, message_id, question, missing_topic, signal, embedding, embedding_model)
  values (
    v_gap_id, v_project_id, v_uid, v_message.conversation_id, v_message.id, v_question, v_topic, p_signal,
    v_embedding, case when v_embedding is not null then p_embedding_model end
  )
  returning id into v_occurrence_id;

  return query select v_gap_id, v_occurrence_id, v_new, v_count;
end;
$$;

revoke execute on function record_automatic_knowledge_gap(uuid, text, text, text, vector, text, double precision) from public, anon;
grant execute on function record_automatic_knowledge_gap(uuid, text, text, text, vector, text, double precision) to authenticated;

-- "Don't send": unchanged rules (20261015100001), except that a gap
-- re-created from the next person's question takes that detection's
-- embedding, so it keeps grouping semantically.
create or replace function withdraw_knowledge_gap_occurrence(p_occurrence_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_occurrence project_knowledge_gap_occurrences%rowtype;
  v_gap project_knowledge_gaps%rowtype;
  v_next project_knowledge_gap_occurrences%rowtype;
  v_next_message chat_messages%rowtype;
  v_new_gap_id uuid;
begin
  select * into v_occurrence from project_knowledge_gap_occurrences
  where id = p_occurrence_id and user_id = auth.uid() and created_at > now() - interval '1 day';
  if not found then
    raise exception 'withdraw_knowledge_gap_occurrence: nothing to withdraw';
  end if;

  select * into v_gap from project_knowledge_gaps where id = v_occurrence.gap_id;

  if v_gap.origin <> 'automatic' or v_gap.message_id is distinct from v_occurrence.message_id then
    delete from project_knowledge_gap_occurrences where id = v_occurrence.id;
    update project_knowledge_gaps set occurrence_count = greatest(occurrence_count - 1, 0) where id = v_gap.id;
    return;
  end if;

  if v_gap.status <> 'new' then
    raise exception 'withdraw_knowledge_gap_occurrence: a curator is already working on this gap';
  end if;

  delete from project_knowledge_gap_occurrences where id = v_occurrence.id;

  select * into v_next from project_knowledge_gap_occurrences where gap_id = v_gap.id order by created_at limit 1;
  if found then
    select * into v_next_message from chat_messages where id = v_next.message_id;
    insert into project_knowledge_gaps (
      project_id, origin, question, ember_answer, failure_kind, missing_topic,
      conversation_id, message_id, answer_provider, answer_model, reported_by, embedding, embedding_model
    ) values (
      v_gap.project_id, 'automatic', v_next.question, left(v_next_message.content, 8000), 'could_not_answer', v_next.missing_topic,
      v_next.conversation_id, v_next.message_id, v_next_message.provider, v_next_message.model, v_next.user_id,
      v_next.embedding, v_next.embedding_model
    )
    returning id into v_new_gap_id;
    update project_knowledge_gap_occurrences set gap_id = v_new_gap_id where gap_id = v_gap.id;
    update project_knowledge_gaps
    set occurrence_count = (select count(*) from project_knowledge_gap_occurrences where gap_id = v_new_gap_id)
    where id = v_new_gap_id;
  end if;

  delete from project_knowledge_gaps where id = v_gap.id;
end;
$$;

revoke execute on function withdraw_knowledge_gap_occurrence(uuid) from public, anon;
grant execute on function withdraw_knowledge_gap_occurrence(uuid) to authenticated;


-- ==== supabase/migrations/20261019100001_solution_verification_records.sql ====
-- Solution conformance and acceptance evaluation, Stage 2: verification
-- records (docs/dev-request-solution-conformance-and-acceptance-
-- evaluation.md).
--
-- A verification record is one execution of a requirement's verification
-- method against an identified solution state (environment, build or
-- component versions, configuration, date), with a result and the
-- workstream artifacts that evidence it. A narrative assertion alone is not
-- evidence: a pass or conditional pass needs at least one artifact.
--
-- Records are append-only. Nobody edits or deletes one; a correction is a
-- new record that supersedes it, and the history stays readable. Each record
-- copies the method and pass criteria it was judged against, so editing a
-- draft requirement's method later never rewrites what a result meant.
-- Writes go only through record_solution_verification(), which saves the
-- record and its evidence together.
--
-- Safe to re-run (if not exists / drop ... if exists throughout).

create table if not exists solution_verification_records (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  -- No cascade: a requirement with verification records can't be deleted
  -- (withdraw it instead). Deleting the Project still removes both.
  requirement_id uuid not null references solution_requirements(id),
  method_id uuid references solution_verification_methods(id) on delete set null,
  -- What the result was judged against, copied from the method.
  method_kind text not null
    check (method_kind in ('test', 'demonstration', 'inspection', 'analysis', 'vendor_evidence', 'operational_measure')),
  pass_criteria text not null,
  threshold text,
  measure_window text,
  result text not null check (result in ('pass', 'fail', 'conditional_pass', 'not_run', 'not_applicable')),
  conditions text,
  rationale text,
  -- The observed value, for an operational measure.
  measured_value text,
  -- The solution state it was run against.
  environment text not null check (environment in ('lab', 'factory', 'staging', 'site', 'production', 'vendor', 'other')),
  solution_reference text not null check (length(trim(solution_reference)) > 0),
  configuration_reference text,
  performed_on date not null,
  observations text,
  defect_reference text,
  supersedes_id uuid references solution_verification_records(id),
  recorded_by uuid references profiles(id) on delete set null,
  recorded_at timestamptz not null default now(),
  check (result <> 'conditional_pass' or length(trim(coalesce(conditions, ''))) > 0),
  check (result <> 'not_applicable' or length(trim(coalesce(rationale, ''))) > 0)
);

create index if not exists solution_verification_records_requirement_idx on solution_verification_records(requirement_id, performed_on desc);
create index if not exists solution_verification_records_project_idx on solution_verification_records(project_id);
-- A record is superseded at most once: corrections form a chain, not a fork.
create unique index if not exists solution_verification_records_supersedes_uniq on solution_verification_records(supersedes_id) where supersedes_id is not null;

create table if not exists solution_verification_evidence (
  id uuid primary key default gen_random_uuid(),
  record_id uuid not null references solution_verification_records(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  workstream_artifact_id uuid references workstream_artifacts(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (record_id, workstream_artifact_id)
);

create index if not exists solution_verification_evidence_record_idx on solution_verification_evidence(record_id);
create index if not exists solution_verification_evidence_artifact_idx on solution_verification_evidence(workstream_artifact_id);

-- Append-only, even for the definer function and the service role. The one
-- change allowed is the method link clearing when a draft's method is
-- removed (the copied method fields keep what it was judged against).
create or replace function solution_verification_records_before_update()
returns trigger
language plpgsql set search_path = public as $$
begin
  if new.method_id is null and old.method_id is not null
    and (to_jsonb(new) - 'method_id') = (to_jsonb(old) - 'method_id') then
    return new;
  end if;
  raise exception 'solution_verification_records: records are append-only -- record a correction that supersedes it';
end;
$$;

drop trigger if exists solution_verification_records_before_update on solution_verification_records;
create trigger solution_verification_records_before_update before update on solution_verification_records
  for each row execute function solution_verification_records_before_update();

-- Recording ------------------------------------------------------------------------
-- The Project's owner, curators and consultants (and platform admins) record
-- results -- the same bar as attaching workstream evidence
-- (can_run_project_evals); viewers read. Only an open requirement (draft or
-- baselined) takes new results; a withdrawn or superseded one keeps its
-- history. Every evidence artifact must be in one of this Project's
-- workstreams and visible to the recorder.
create or replace function record_solution_verification(
  p_requirement_id uuid,
  p_method_id uuid,
  p_result text,
  p_environment text,
  p_solution_reference text,
  p_performed_on date,
  p_artifact_ids uuid[],
  p_configuration_reference text default null,
  p_conditions text default null,
  p_rationale text default null,
  p_measured_value text default null,
  p_observations text default null,
  p_defect_reference text default null,
  p_supersedes_id uuid default null
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_requirement solution_requirements%rowtype;
  v_method solution_verification_methods%rowtype;
  v_superseded solution_verification_records%rowtype;
  v_artifact_ids uuid[] := array(select distinct a from unnest(coalesce(p_artifact_ids, '{}'::uuid[])) a where a is not null);
  v_artifact_id uuid;
  v_record_id uuid;
begin
  if v_uid is null then
    raise exception 'record_solution_verification: not signed in';
  end if;

  select * into v_requirement from solution_requirements where id = p_requirement_id;
  if not found or not can_run_project_evals(v_requirement.project_id, v_uid) then
    raise exception 'record_solution_verification: only this Project''s owner, curators and consultants can record verification results';
  end if;
  if v_requirement.status not in ('draft', 'baselined') then
    raise exception 'record_solution_verification: this requirement is closed -- it no longer takes verification results';
  end if;

  select * into v_method from solution_verification_methods where id = p_method_id and requirement_id = p_requirement_id;
  if not found then
    raise exception 'record_solution_verification: choose one of this requirement''s verification methods';
  end if;

  if p_result is null or p_result not in ('pass', 'fail', 'conditional_pass', 'not_run', 'not_applicable') then
    raise exception 'record_solution_verification: unknown result';
  end if;
  if p_result = 'conditional_pass' and length(trim(coalesce(p_conditions, ''))) = 0 then
    raise exception 'record_solution_verification: a conditional pass needs its conditions';
  end if;
  if p_result = 'not_applicable' and length(trim(coalesce(p_rationale, ''))) = 0 then
    raise exception 'record_solution_verification: not applicable needs a rationale';
  end if;
  if p_environment is null or p_environment not in ('lab', 'factory', 'staging', 'site', 'production', 'vendor', 'other') then
    raise exception 'record_solution_verification: choose the environment it was run in';
  end if;
  if length(trim(coalesce(p_solution_reference, ''))) = 0 then
    raise exception 'record_solution_verification: identify the solution state -- build or component versions';
  end if;
  if p_performed_on is null or p_performed_on > current_date + 1 then
    raise exception 'record_solution_verification: the date it was performed can''t be in the future';
  end if;
  if p_result in ('pass', 'conditional_pass') and cardinality(v_artifact_ids) = 0 then
    raise exception 'record_solution_verification: a pass needs at least one evidence artifact -- a narrative assertion alone is not evidence';
  end if;
  if v_method.method = 'operational_measure' and p_result in ('pass', 'fail', 'conditional_pass')
    and length(trim(coalesce(p_measured_value, ''))) = 0 then
    raise exception 'record_solution_verification: an operational measure needs the measured value';
  end if;

  if p_supersedes_id is not null then
    select * into v_superseded from solution_verification_records where id = p_supersedes_id;
    if not found or v_superseded.requirement_id <> p_requirement_id then
      raise exception 'record_solution_verification: a correction must supersede a record of the same requirement';
    end if;
    if exists (select 1 from solution_verification_records r where r.supersedes_id = p_supersedes_id) then
      raise exception 'record_solution_verification: that record has already been corrected';
    end if;
  end if;

  foreach v_artifact_id in array v_artifact_ids loop
    if not exists (
      select 1 from workstream_artifacts a
      join project_workstreams w on w.id = a.workstream_id
      where a.id = v_artifact_id
        and w.project_id = v_requirement.project_id
        and has_evidence_access('workstream_artifact', a.id, v_uid)
    ) then
      raise exception 'record_solution_verification: evidence must be an artifact in one of this Project''s workstreams that you can see';
    end if;
  end loop;

  insert into solution_verification_records (
    project_id, requirement_id, method_id, method_kind, pass_criteria, threshold, measure_window,
    result, conditions, rationale, measured_value, environment, solution_reference, configuration_reference,
    performed_on, observations, defect_reference, supersedes_id, recorded_by
  ) values (
    v_requirement.project_id, p_requirement_id, v_method.id, v_method.method, v_method.pass_criteria, v_method.threshold, v_method.measure_window,
    p_result, nullif(trim(p_conditions), ''), nullif(trim(p_rationale), ''), nullif(trim(p_measured_value), ''),
    p_environment, trim(p_solution_reference), nullif(trim(p_configuration_reference), ''),
    p_performed_on, nullif(trim(p_observations), ''), nullif(trim(p_defect_reference), ''), p_supersedes_id, v_uid
  )
  returning id into v_record_id;

  insert into solution_verification_evidence (record_id, project_id, workstream_artifact_id)
  select v_record_id, v_requirement.project_id, a from unnest(v_artifact_ids) a;

  return v_record_id;
end;
$$;

revoke execute on function record_solution_verification(uuid, uuid, text, text, text, date, uuid[], text, text, text, text, text, text, uuid) from public, anon;
grant execute on function record_solution_verification(uuid, uuid, text, text, text, date, uuid[], text, text, text, text, text, text, uuid) to authenticated;

-- RLS ---------------------------------------------------------------------------------
-- Read-only through RLS: every Project member reads the records; evidence
-- citing a restricted artifact is hidden from anyone without a grant. No
-- insert, update or delete policies -- writes go through the function above.

alter table solution_verification_records enable row level security;
alter table solution_verification_evidence enable row level security;

drop policy if exists "solution_verification_records_select_member" on solution_verification_records;
create policy "solution_verification_records_select_member" on solution_verification_records
  for select using (is_project_member(project_id, auth.uid()));

drop policy if exists "solution_verification_evidence_select_member" on solution_verification_evidence;
create policy "solution_verification_evidence_select_member" on solution_verification_evidence
  for select using (
    is_project_member(project_id, auth.uid())
    and (workstream_artifact_id is null or has_evidence_access('workstream_artifact', workstream_artifact_id, auth.uid()))
  );

-- External MCP read-only guarantee (20261005100001_external_mcp_access.sql),
-- guarded so this migration also applies before that one has run.
do $$
begin
  if to_regprocedure('public.apply_oauth_read_only_policies()') is not null then
    perform apply_oauth_read_only_policies();
  end if;
end;
$$;


-- ==== supabase/migrations/20261020100001_solution_baselines_and_decisions.sql ====
-- Solution conformance and acceptance evaluation, Stage 3: evaluation
-- baselines, waivers and conformance decisions (docs/dev-request-solution-
-- conformance-and-acceptance-evaluation.md).
--
-- A baseline is a named, versioned set of requirements for a purpose and
-- stage (e.g. "Cebu NG911 Phase 1 Site Acceptance"). While it is a draft,
-- curators add and remove requirements; activating it freezes it and moves
-- its requirements to 'baselined', which fixes their content, sources, scope
-- and verification methods (20261017100001). Changing scope means a new
-- version; activating the new version supersedes the old one.
--
-- A conformance decision is a human decision over an active baseline (site
-- acceptance, customer acceptance, go-live, ...). Who may approve it comes
-- from the Project's approval policies and authority assignments
-- (20260824140001_project_governance.sql): only an active holder of the
-- decision's approval type, never platform admin status by itself, and not
-- the requester or anyone who recorded the evidence unless both the policy
-- and the assignment allow self-approval. When it is decided, the decision
-- keeps a snapshot of exactly which (immutable) verification records and
-- waivers it rested on.
--
-- A waiver (or deviation) accepts a requirement as not met, or met
-- differently, for one baseline. It needs a rationale and is approved the
-- same way; approved waivers appear in every later roll-up of that baseline.
--
-- Waivers and decisions are written only through the functions below.
-- Safe to re-run (if not exists / drop ... if exists / create or replace).

-- Authority ---------------------------------------------------------------------------
-- Whether a user currently holds an approval authority in a Project: an
-- active, in-date assignment, while an active member. No admin bypass --
-- authority is assigned, never inferred.
create or replace function holds_project_authority(p_project_id uuid, p_uid uuid, p_approval_type text)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1
    from project_authority_assignments a
    join project_members pm on pm.project_id = a.project_id and pm.user_id = a.user_id and pm.status = 'active'
    where a.project_id = p_project_id and a.user_id = p_uid and a.approval_type = p_approval_type
      and a.status = 'active' and a.effective_from <= now() and (a.expires_at is null or a.expires_at > now())
  );
$$;

-- Self-approval is allowed only when both the Project's policy for the
-- approval type and the approver's own assignment allow it.
create or replace function project_self_approval_allowed(p_project_id uuid, p_uid uuid, p_approval_type text)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select p.allow_self_approval from project_approval_policies p where p.project_id = p_project_id and p.approval_type = p_approval_type), false)
    and exists (
      select 1 from project_authority_assignments a
      where a.project_id = p_project_id and a.user_id = p_uid and a.approval_type = p_approval_type
        and a.status = 'active' and a.allow_self_approval
        and a.effective_from <= now() and (a.expires_at is null or a.expires_at > now())
    );
$$;

-- Baselines ---------------------------------------------------------------------------
create table if not exists solution_evaluation_baselines (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  name text not null check (length(trim(name)) > 0),
  purpose text not null
    check (purpose in ('presales_claim_validation', 'factory_acceptance', 'site_acceptance', 'customer_acceptance', 'go_live', 'post_change_reverification')),
  lifecycle_stage text not null default 'deployment' check (lifecycle_stage in ('presales', 'deployment', 'management_maintenance')),
  description text,
  version integer not null default 1 check (version >= 1),
  previous_baseline_id uuid references solution_evaluation_baselines(id),
  status text not null default 'draft' check (status in ('draft', 'active', 'superseded')),
  created_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  activated_by uuid references profiles(id) on delete set null,
  activated_at timestamptz,
  unique (project_id, name, version)
);

create index if not exists solution_evaluation_baselines_project_idx on solution_evaluation_baselines(project_id, status);

drop trigger if exists solution_evaluation_baselines_set_updated_at on solution_evaluation_baselines;
create trigger solution_evaluation_baselines_set_updated_at before update on solution_evaluation_baselines
  for each row execute function set_updated_at();

-- A draft's name, purpose, stage and description can change; nothing else
-- ever does, and once active only the move to superseded is allowed (made by
-- activating the next version).
create or replace function solution_evaluation_baselines_before_update()
returns trigger
language plpgsql set search_path = public as $$
begin
  if new.project_id is distinct from old.project_id or new.version is distinct from old.version
    or new.previous_baseline_id is distinct from old.previous_baseline_id
    or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception 'solution_evaluation_baselines: project, version and author cannot change';
  end if;
  if old.status <> 'draft' and (
    new.name is distinct from old.name or new.purpose is distinct from old.purpose
    or new.lifecycle_stage is distinct from old.lifecycle_stage or new.description is distinct from old.description
  ) then
    raise exception 'solution_evaluation_baselines: an active baseline is frozen -- create a new version to change it';
  end if;
  if new.status is distinct from old.status
    and not (old.status = 'draft' and new.status = 'active') and not (old.status = 'active' and new.status = 'superseded') then
    raise exception 'solution_evaluation_baselines: a baseline only moves from draft to active to superseded';
  end if;
  return new;
end;
$$;

drop trigger if exists solution_evaluation_baselines_before_update on solution_evaluation_baselines;
create trigger solution_evaluation_baselines_before_update before update on solution_evaluation_baselines
  for each row execute function solution_evaluation_baselines_before_update();

create or replace function solution_baseline_is_draft(p_baseline_id uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from solution_evaluation_baselines b where b.id = p_baseline_id and b.status = 'draft');
$$;

create table if not exists solution_evaluation_baseline_items (
  id uuid primary key default gen_random_uuid(),
  baseline_id uuid not null references solution_evaluation_baselines(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  -- Only a draft requirement can be deleted, and a requirement in an active
  -- baseline is baselined, so this only ever removes draft-baseline items.
  requirement_id uuid not null references solution_requirements(id) on delete cascade,
  added_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (baseline_id, requirement_id)
);

create index if not exists solution_evaluation_baseline_items_requirement_idx on solution_evaluation_baseline_items(requirement_id);

-- An item belongs to its baseline's Project, cites an open requirement of
-- that Project, and only changes while the baseline is a draft (the RLS
-- policies say the same; this also holds for definer and service paths).
create or replace function solution_evaluation_baseline_items_before_write()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_baseline solution_evaluation_baselines%rowtype;
begin
  if tg_op = 'DELETE' then
    -- Deleting the baseline or the Project removes items with it.
    if pg_trigger_depth() = 1 and exists (select 1 from solution_evaluation_baselines b where b.id = old.baseline_id and b.status <> 'draft') then
      raise exception 'solution_evaluation_baseline_items: an active baseline is frozen -- create a new version to change it';
    end if;
    return old;
  end if;
  if tg_op = 'UPDATE' then
    raise exception 'solution_evaluation_baseline_items: items are added or removed, never changed';
  end if;
  select * into v_baseline from solution_evaluation_baselines where id = new.baseline_id;
  if not found or v_baseline.project_id is distinct from new.project_id then
    raise exception 'solution_evaluation_baseline_items: must belong to its baseline''s Project';
  end if;
  if v_baseline.status <> 'draft' then
    raise exception 'solution_evaluation_baseline_items: an active baseline is frozen -- create a new version to change it';
  end if;
  if not exists (
    select 1 from solution_requirements r
    where r.id = new.requirement_id and r.project_id = v_baseline.project_id and r.status in ('draft', 'baselined')
  ) then
    raise exception 'solution_evaluation_baseline_items: only an open requirement of this Project can be baselined';
  end if;
  return new;
end;
$$;

drop trigger if exists solution_evaluation_baseline_items_before_write on solution_evaluation_baseline_items;
create trigger solution_evaluation_baseline_items_before_write before insert or update or delete on solution_evaluation_baseline_items
  for each row execute function solution_evaluation_baseline_items_before_write();

-- Activating a baseline: a curator; at least one requirement, each still
-- open and with a verification method. Its requirements become baselined
-- (content fixed), and the version it replaces is superseded.
create or replace function activate_solution_baseline(p_baseline_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_baseline solution_evaluation_baselines%rowtype;
begin
  select * into v_baseline from solution_evaluation_baselines where id = p_baseline_id for update;
  if not found or v_uid is null or not can_curate_project(v_baseline.project_id, v_uid) then
    raise exception 'activate_solution_baseline: only this Project''s owner and curators can activate a baseline';
  end if;
  if v_baseline.status <> 'draft' then
    raise exception 'activate_solution_baseline: only a draft baseline can be activated';
  end if;
  if not exists (select 1 from solution_evaluation_baseline_items i where i.baseline_id = p_baseline_id) then
    raise exception 'activate_solution_baseline: add at least one requirement first';
  end if;
  if exists (
    select 1 from solution_evaluation_baseline_items i join solution_requirements r on r.id = i.requirement_id
    where i.baseline_id = p_baseline_id and r.status not in ('draft', 'baselined')
  ) then
    raise exception 'activate_solution_baseline: remove withdrawn or superseded requirements first';
  end if;
  if exists (
    select 1 from solution_evaluation_baseline_items i
    where i.baseline_id = p_baseline_id
      and not exists (select 1 from solution_verification_methods m where m.requirement_id = i.requirement_id)
  ) then
    raise exception 'activate_solution_baseline: every requirement needs a verification method first';
  end if;

  update solution_requirements r set status = 'baselined'
  from solution_evaluation_baseline_items i
  where i.baseline_id = p_baseline_id and r.id = i.requirement_id and r.status = 'draft';

  if v_baseline.previous_baseline_id is not null then
    update solution_evaluation_baselines set status = 'superseded'
    where id = v_baseline.previous_baseline_id and status = 'active';
  end if;

  update solution_evaluation_baselines set status = 'active', activated_by = v_uid, activated_at = now() where id = p_baseline_id;
end;
$$;

-- A new version of an active or superseded baseline: a draft copy with the
-- next version number. A requirement that has since been superseded is
-- carried over as its replacement; withdrawn ones are left out.
create or replace function new_solution_baseline_version(p_baseline_id uuid)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_baseline solution_evaluation_baselines%rowtype;
  v_new_id uuid;
begin
  select * into v_baseline from solution_evaluation_baselines where id = p_baseline_id;
  if not found or v_uid is null or not can_curate_project(v_baseline.project_id, v_uid) then
    raise exception 'new_solution_baseline_version: only this Project''s owner and curators can version a baseline';
  end if;
  if v_baseline.status = 'draft' then
    raise exception 'new_solution_baseline_version: a draft can still be edited -- activate it first';
  end if;
  if exists (
    select 1 from solution_evaluation_baselines b
    where b.project_id = v_baseline.project_id and b.name = v_baseline.name and b.status = 'draft'
  ) then
    raise exception 'new_solution_baseline_version: a draft version of this baseline already exists';
  end if;

  insert into solution_evaluation_baselines (project_id, name, purpose, lifecycle_stage, description, version, previous_baseline_id, created_by)
  select v_baseline.project_id, v_baseline.name, v_baseline.purpose, v_baseline.lifecycle_stage, v_baseline.description,
    (select max(b.version) + 1 from solution_evaluation_baselines b where b.project_id = v_baseline.project_id and b.name = v_baseline.name),
    v_baseline.id, v_uid
  returning id into v_new_id;

  insert into solution_evaluation_baseline_items (baseline_id, project_id, requirement_id, added_by)
  select distinct v_new_id, v_baseline.project_id, coalesce(replacement.id, r.id), v_uid
  from solution_evaluation_baseline_items i
  join solution_requirements r on r.id = i.requirement_id
  left join solution_requirements replacement on replacement.id = r.superseded_by and replacement.status in ('draft', 'baselined')
  where i.baseline_id = p_baseline_id
    and (r.status in ('draft', 'baselined') or replacement.id is not null);

  return v_new_id;
end;
$$;

-- Waivers -----------------------------------------------------------------------------
create table if not exists solution_waivers (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  baseline_id uuid not null references solution_evaluation_baselines(id) on delete cascade,
  requirement_id uuid not null references solution_requirements(id),
  kind text not null check (kind in ('waiver', 'deviation')),
  rationale text not null check (length(trim(rationale)) > 0),
  conditions text,
  approval_type text not null check (approval_type in ('technical', 'security_compliance', 'customer_acceptance', 'production_change')),
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'withdrawn')),
  requested_by uuid references profiles(id) on delete set null,
  requested_at timestamptz not null default now(),
  decided_by uuid references profiles(id) on delete set null,
  decided_at timestamptz,
  decision_note text
);

create index if not exists solution_waivers_baseline_idx on solution_waivers(baseline_id);
-- One live waiver per requirement per baseline.
create unique index if not exists solution_waivers_live_uniq on solution_waivers(baseline_id, requirement_id) where status in ('pending', 'approved');

create or replace function request_solution_waiver(
  p_baseline_id uuid,
  p_requirement_id uuid,
  p_kind text,
  p_rationale text,
  p_approval_type text,
  p_conditions text default null
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_baseline solution_evaluation_baselines%rowtype;
  v_id uuid;
begin
  select * into v_baseline from solution_evaluation_baselines where id = p_baseline_id;
  if not found or v_uid is null or not can_run_project_evals(v_baseline.project_id, v_uid) then
    raise exception 'request_solution_waiver: only this Project''s owner, curators and consultants can request a waiver';
  end if;
  if v_baseline.status <> 'active' then
    raise exception 'request_solution_waiver: waivers apply to an active baseline';
  end if;
  if not exists (select 1 from solution_evaluation_baseline_items i where i.baseline_id = p_baseline_id and i.requirement_id = p_requirement_id) then
    raise exception 'request_solution_waiver: the requirement is not in this baseline';
  end if;
  if p_kind is null or p_kind not in ('waiver', 'deviation') then
    raise exception 'request_solution_waiver: choose waiver or deviation';
  end if;
  if length(trim(coalesce(p_rationale, ''))) = 0 then
    raise exception 'request_solution_waiver: a waiver needs a rationale';
  end if;
  if p_approval_type is null or p_approval_type not in ('technical', 'security_compliance', 'customer_acceptance', 'production_change') then
    raise exception 'request_solution_waiver: choose who must approve it';
  end if;
  if exists (select 1 from solution_waivers w where w.baseline_id = p_baseline_id and w.requirement_id = p_requirement_id and w.status in ('pending', 'approved')) then
    raise exception 'request_solution_waiver: this requirement already has a pending or approved waiver in this baseline';
  end if;

  insert into solution_waivers (project_id, baseline_id, requirement_id, kind, rationale, conditions, approval_type, requested_by)
  values (v_baseline.project_id, p_baseline_id, p_requirement_id, p_kind, trim(p_rationale), nullif(trim(p_conditions), ''), p_approval_type, v_uid)
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function decide_solution_waiver(p_waiver_id uuid, p_approve boolean, p_note text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_waiver solution_waivers%rowtype;
begin
  select * into v_waiver from solution_waivers where id = p_waiver_id for update;
  if not found or v_uid is null or not holds_project_authority(v_waiver.project_id, v_uid, v_waiver.approval_type) then
    raise exception 'decide_solution_waiver: only a holder of the required approval authority can decide this waiver';
  end if;
  if v_waiver.status <> 'pending' then
    raise exception 'decide_solution_waiver: this waiver has already been decided';
  end if;
  if v_waiver.requested_by = v_uid and not project_self_approval_allowed(v_waiver.project_id, v_uid, v_waiver.approval_type) then
    raise exception 'decide_solution_waiver: you requested this waiver, and this Project does not allow self-approval';
  end if;
  update solution_waivers
  set status = case when p_approve then 'approved' else 'rejected' end,
      decided_by = v_uid, decided_at = now(), decision_note = nullif(trim(p_note), '')
  where id = p_waiver_id;
end;
$$;

create or replace function withdraw_solution_waiver(p_waiver_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_waiver solution_waivers%rowtype;
begin
  select * into v_waiver from solution_waivers where id = p_waiver_id for update;
  if not found or v_uid is null or not (v_waiver.requested_by = v_uid or can_curate_project(v_waiver.project_id, v_uid)) then
    raise exception 'withdraw_solution_waiver: only the requester or a curator can withdraw a waiver';
  end if;
  if v_waiver.status <> 'pending' then
    raise exception 'withdraw_solution_waiver: only a pending waiver can be withdrawn';
  end if;
  update solution_waivers set status = 'withdrawn', decided_by = v_uid, decided_at = now() where id = p_waiver_id;
end;
$$;

-- Conformance decisions ---------------------------------------------------------------
create table if not exists solution_conformance_decisions (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  baseline_id uuid not null references solution_evaluation_baselines(id) on delete cascade,
  decision_type text not null
    check (decision_type in ('presales_claim_validation', 'factory_acceptance', 'site_acceptance', 'customer_acceptance', 'go_live', 'post_change_reverification')),
  approval_type text not null check (approval_type in ('technical', 'security_compliance', 'customer_acceptance', 'production_change')),
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'withdrawn')),
  request_note text,
  -- Approvals needed, fixed from the policy when requested.
  required_approvals integer not null default 1 check (required_approvals >= 1),
  approval_mode text not null default 'any_authorized' check (approval_mode in ('any_authorized', 'all_assigned')),
  requested_by uuid references profiles(id) on delete set null,
  requested_at timestamptz not null default now(),
  decided_at timestamptz,
  -- What the decision rested on, taken when it was decided: per requirement,
  -- its methods, the verification records in effect and any approved waiver.
  snapshot jsonb
);

create index if not exists solution_conformance_decisions_baseline_idx on solution_conformance_decisions(baseline_id);
-- One pending decision of each kind per baseline.
create unique index if not exists solution_conformance_decisions_pending_uniq
  on solution_conformance_decisions(baseline_id, decision_type) where status = 'pending';

create table if not exists solution_conformance_decision_approvals (
  id uuid primary key default gen_random_uuid(),
  decision_id uuid not null references solution_conformance_decisions(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  approver_id uuid references profiles(id) on delete set null,
  verdict text not null check (verdict in ('approve', 'reject')),
  note text,
  conditions text,
  created_at timestamptz not null default now(),
  unique (decision_id, approver_id)
);

create index if not exists solution_conformance_decision_approvals_decision_idx on solution_conformance_decision_approvals(decision_id);

create or replace function solution_baseline_snapshot(p_baseline_id uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'taken_at', now(),
    'baseline_version', (select b.version from solution_evaluation_baselines b where b.id = p_baseline_id),
    'requirements', coalesce((
      select jsonb_agg(jsonb_build_object(
        'requirement_id', i.requirement_id,
        'method_ids', coalesce((
          select jsonb_agg(m.id order by m.created_at) from solution_verification_methods m where m.requirement_id = i.requirement_id
        ), '[]'::jsonb),
        'record_ids', coalesce((
          select jsonb_agg(x.id) from (
            select distinct on (r.method_id) r.id
            from solution_verification_records r
            where r.requirement_id = i.requirement_id and r.method_id is not null
              and not exists (select 1 from solution_verification_records s where s.supersedes_id = r.id)
            order by r.method_id, r.performed_on desc, r.recorded_at desc
          ) x
        ), '[]'::jsonb),
        'waiver_id', (
          select w.id from solution_waivers w
          where w.baseline_id = p_baseline_id and w.requirement_id = i.requirement_id and w.status = 'approved'
          limit 1
        )
      ) order by i.created_at)
      from solution_evaluation_baseline_items i where i.baseline_id = p_baseline_id
    ), '[]'::jsonb)
  );
$$;

create or replace function request_solution_conformance_decision(
  p_baseline_id uuid,
  p_decision_type text,
  p_approval_type text,
  p_note text default null
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_baseline solution_evaluation_baselines%rowtype;
  v_policy project_approval_policies%rowtype;
  v_id uuid;
begin
  select * into v_baseline from solution_evaluation_baselines where id = p_baseline_id;
  if not found or v_uid is null or not can_curate_project(v_baseline.project_id, v_uid) then
    raise exception 'request_solution_conformance_decision: only this Project''s owner and curators can request a decision';
  end if;
  if v_baseline.status <> 'active' then
    raise exception 'request_solution_conformance_decision: decisions are made over an active baseline';
  end if;
  if p_decision_type is null or p_decision_type not in ('presales_claim_validation', 'factory_acceptance', 'site_acceptance', 'customer_acceptance', 'go_live', 'post_change_reverification') then
    raise exception 'request_solution_conformance_decision: choose the kind of decision';
  end if;
  if p_approval_type is null or p_approval_type not in ('technical', 'security_compliance', 'customer_acceptance', 'production_change') then
    raise exception 'request_solution_conformance_decision: choose who must approve it';
  end if;
  select * into v_policy from project_approval_policies where project_id = v_baseline.project_id and approval_type = p_approval_type;
  if found and v_policy.requirement_status = 'not_applicable' then
    raise exception 'request_solution_conformance_decision: this Project''s approval policy marks that approval type as not applicable';
  end if;
  if exists (select 1 from solution_conformance_decisions d where d.baseline_id = p_baseline_id and d.decision_type = p_decision_type and d.status = 'pending') then
    raise exception 'request_solution_conformance_decision: a decision of this kind is already pending for this baseline';
  end if;

  insert into solution_conformance_decisions (project_id, baseline_id, decision_type, approval_type, request_note, required_approvals, approval_mode, requested_by)
  values (
    v_baseline.project_id, p_baseline_id, p_decision_type, p_approval_type, nullif(trim(p_note), ''),
    greatest(coalesce(v_policy.minimum_approvals, 1), 1), coalesce(v_policy.approval_mode, 'any_authorized'), v_uid
  )
  returning id into v_id;
  return v_id;
end;
$$;

-- One approver's verdict. A reject decides it at once; otherwise it is
-- approved when enough authorized approvers agree (the policy's minimum, or
-- every current holder for 'all_assigned').
create or replace function decide_solution_conformance_decision(
  p_decision_id uuid,
  p_approve boolean,
  p_note text default null,
  p_conditions text default null
)
returns text
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_decision solution_conformance_decisions%rowtype;
  v_is_self boolean;
  v_approvals integer;
  v_needed integer;
begin
  select * into v_decision from solution_conformance_decisions where id = p_decision_id for update;
  if not found or v_uid is null or not holds_project_authority(v_decision.project_id, v_uid, v_decision.approval_type) then
    raise exception 'decide_solution_conformance_decision: only a holder of the required approval authority can decide this';
  end if;
  if v_decision.status <> 'pending' then
    raise exception 'decide_solution_conformance_decision: this decision has already been made';
  end if;
  if exists (select 1 from solution_conformance_decision_approvals a where a.decision_id = p_decision_id and a.approver_id = v_uid) then
    raise exception 'decide_solution_conformance_decision: you have already given your verdict';
  end if;

  -- Self-approval: the requester, or anyone who recorded evidence in effect
  -- for this baseline's requirements.
  v_is_self := v_decision.requested_by = v_uid or exists (
    select 1
    from solution_evaluation_baseline_items i
    join solution_verification_records r on r.requirement_id = i.requirement_id
    where i.baseline_id = v_decision.baseline_id and r.recorded_by = v_uid
      and not exists (select 1 from solution_verification_records s where s.supersedes_id = r.id)
  );
  if v_is_self and not project_self_approval_allowed(v_decision.project_id, v_uid, v_decision.approval_type) then
    raise exception 'decide_solution_conformance_decision: you requested this decision or recorded its evidence, and this Project does not allow self-approval';
  end if;

  insert into solution_conformance_decision_approvals (decision_id, project_id, approver_id, verdict, note, conditions)
  values (p_decision_id, v_decision.project_id, v_uid, case when p_approve then 'approve' else 'reject' end, nullif(trim(p_note), ''), nullif(trim(p_conditions), ''));

  if not p_approve then
    update solution_conformance_decisions set status = 'rejected', decided_at = now(), snapshot = solution_baseline_snapshot(v_decision.baseline_id)
    where id = p_decision_id;
    return 'rejected';
  end if;

  select count(*) into v_approvals from solution_conformance_decision_approvals a where a.decision_id = p_decision_id and a.verdict = 'approve';
  if v_decision.approval_mode = 'all_assigned' then
    select count(distinct a.user_id) into v_needed
    from project_authority_assignments a
    where a.project_id = v_decision.project_id and holds_project_authority(v_decision.project_id, a.user_id, v_decision.approval_type);
    v_needed := greatest(v_needed, v_decision.required_approvals);
  else
    v_needed := v_decision.required_approvals;
  end if;

  if v_approvals >= v_needed then
    update solution_conformance_decisions set status = 'approved', decided_at = now(), snapshot = solution_baseline_snapshot(v_decision.baseline_id)
    where id = p_decision_id;
    return 'approved';
  end if;
  return 'pending';
end;
$$;

create or replace function withdraw_solution_conformance_decision(p_decision_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_decision solution_conformance_decisions%rowtype;
begin
  select * into v_decision from solution_conformance_decisions where id = p_decision_id for update;
  if not found or v_uid is null or not (v_decision.requested_by = v_uid or can_curate_project(v_decision.project_id, v_uid)) then
    raise exception 'withdraw_solution_conformance_decision: only the requester or a curator can withdraw a decision request';
  end if;
  if v_decision.status <> 'pending' then
    raise exception 'withdraw_solution_conformance_decision: only a pending decision can be withdrawn';
  end if;
  update solution_conformance_decisions set status = 'withdrawn', decided_at = now() where id = p_decision_id;
end;
$$;

-- Decided waivers and decisions are fixed (the functions above are the only
-- writers; this also holds for the service role).
create or replace function solution_decided_row_before_update()
returns trigger
language plpgsql set search_path = public as $$
begin
  if old.status <> 'pending' then
    raise exception '%: a decided record cannot change', tg_table_name;
  end if;
  return new;
end;
$$;

drop trigger if exists solution_waivers_before_update on solution_waivers;
create trigger solution_waivers_before_update before update on solution_waivers
  for each row execute function solution_decided_row_before_update();
drop trigger if exists solution_conformance_decisions_before_update on solution_conformance_decisions;
create trigger solution_conformance_decisions_before_update before update on solution_conformance_decisions
  for each row execute function solution_decided_row_before_update();

do $$
declare
  fn text;
begin
  foreach fn in array array[
    'holds_project_authority(uuid, uuid, text)',
    'project_self_approval_allowed(uuid, uuid, text)',
    'solution_baseline_is_draft(uuid)',
    'activate_solution_baseline(uuid)',
    'new_solution_baseline_version(uuid)',
    'request_solution_waiver(uuid, uuid, text, text, text, text)',
    'decide_solution_waiver(uuid, boolean, text)',
    'withdraw_solution_waiver(uuid)',
    'solution_baseline_snapshot(uuid)',
    'request_solution_conformance_decision(uuid, text, text, text)',
    'decide_solution_conformance_decision(uuid, boolean, text, text)',
    'withdraw_solution_conformance_decision(uuid)'
  ] loop
    execute format('revoke execute on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated', fn);
  end loop;
end;
$$;

-- RLS ---------------------------------------------------------------------------------
-- Members read everything here. Curators write draft baselines and their
-- items directly (split per command); waivers, decisions and approvals have
-- no write policies -- the functions above are the only writers.

alter table solution_evaluation_baselines enable row level security;
alter table solution_evaluation_baseline_items enable row level security;
alter table solution_waivers enable row level security;
alter table solution_conformance_decisions enable row level security;
alter table solution_conformance_decision_approvals enable row level security;

drop policy if exists "solution_evaluation_baselines_select_member" on solution_evaluation_baselines;
create policy "solution_evaluation_baselines_select_member" on solution_evaluation_baselines
  for select using (is_project_member(project_id, auth.uid()));
drop policy if exists "solution_evaluation_baselines_insert_curator" on solution_evaluation_baselines;
create policy "solution_evaluation_baselines_insert_curator" on solution_evaluation_baselines
  for insert with check (
    can_curate_project(project_id, auth.uid()) and created_by = auth.uid() and status = 'draft' and version = 1 and previous_baseline_id is null
  );
drop policy if exists "solution_evaluation_baselines_update_curator_draft" on solution_evaluation_baselines;
create policy "solution_evaluation_baselines_update_curator_draft" on solution_evaluation_baselines
  for update using (can_curate_project(project_id, auth.uid()) and status = 'draft')
  with check (can_curate_project(project_id, auth.uid()) and status = 'draft');
drop policy if exists "solution_evaluation_baselines_delete_curator_draft" on solution_evaluation_baselines;
create policy "solution_evaluation_baselines_delete_curator_draft" on solution_evaluation_baselines
  for delete using (can_curate_project(project_id, auth.uid()) and status = 'draft');

drop policy if exists "solution_evaluation_baseline_items_select_member" on solution_evaluation_baseline_items;
create policy "solution_evaluation_baseline_items_select_member" on solution_evaluation_baseline_items
  for select using (is_project_member(project_id, auth.uid()));
drop policy if exists "solution_evaluation_baseline_items_insert_curator_draft" on solution_evaluation_baseline_items;
create policy "solution_evaluation_baseline_items_insert_curator_draft" on solution_evaluation_baseline_items
  for insert with check (can_curate_project(project_id, auth.uid()) and solution_baseline_is_draft(baseline_id) and added_by = auth.uid());
drop policy if exists "solution_evaluation_baseline_items_delete_curator_draft" on solution_evaluation_baseline_items;
create policy "solution_evaluation_baseline_items_delete_curator_draft" on solution_evaluation_baseline_items
  for delete using (can_curate_project(project_id, auth.uid()) and solution_baseline_is_draft(baseline_id));

drop policy if exists "solution_waivers_select_member" on solution_waivers;
create policy "solution_waivers_select_member" on solution_waivers
  for select using (is_project_member(project_id, auth.uid()));
drop policy if exists "solution_conformance_decisions_select_member" on solution_conformance_decisions;
create policy "solution_conformance_decisions_select_member" on solution_conformance_decisions
  for select using (is_project_member(project_id, auth.uid()));
drop policy if exists "solution_conformance_decision_approvals_select_member" on solution_conformance_decision_approvals;
create policy "solution_conformance_decision_approvals_select_member" on solution_conformance_decision_approvals
  for select using (is_project_member(project_id, auth.uid()));

-- External MCP read-only guarantee (20261005100001_external_mcp_access.sql),
-- guarded so this migration also applies before that one has run.
do $$
begin
  if to_regprocedure('public.apply_oauth_read_only_policies()') is not null then
    perform apply_oauth_read_only_policies();
  end if;
end;
$$;


-- ==== supabase/migrations/20261021100001_solution_reverification.sql ====
-- Solution conformance and acceptance evaluation, Stage 4: re-verification
-- triggers (docs/dev-request-solution-conformance-and-acceptance-
-- evaluation.md).
--
-- In management and maintenance a decision is a point-in-time statement.
-- These events mark the affected requirements "re-verification due" while
-- keeping every past record, baseline and decision readable:
--   * a component, firmware or configuration change recorded on the Project
--     (or any other change the team records), naming the requirements it
--     affects;
--   * a new version of a knowledge source a requirement cites (automatic);
--   * an operational measure recorded as a fail -- outside its threshold
--     (automatic);
--   * a review interval passing since the requirement was last verified.
-- An event stays open for a requirement until every one of its verification
-- methods has a new result (other than "not run") recorded after the event,
-- or a curator resolves it with a note (e.g. "reviewed, no impact"). While
-- any requirement in a baseline is due, a production-change decision over it
-- can't be approved.
--
-- Safe to re-run.

-- How often a requirement must be re-verified, if at all. Operational, so
-- it stays editable after baselining (not in the frozen-field list).
alter table solution_requirements
  add column if not exists review_interval_months integer check (review_interval_months between 1 and 120);

create table if not exists solution_reverification_events (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  kind text not null check (kind in ('component_change', 'source_revision', 'threshold_breach', 'other')),
  summary text not null check (length(trim(summary)) > 0),
  detail text,
  -- e.g. "K-Dispatch 4.2.1 -> 4.3.0"
  change_reference text,
  project_object_id uuid references project_objects(id) on delete set null,
  workstream_id uuid references project_workstreams(id) on delete set null,
  knowledge_source_id uuid references knowledge_sources(id) on delete set null,
  document_version_id uuid references documents(id) on delete set null,
  record_id uuid references solution_verification_records(id) on delete set null,
  -- Null for the automatic kinds.
  recorded_by uuid references profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists solution_reverification_events_project_idx on solution_reverification_events(project_id, created_at desc);

create table if not exists solution_reverification_event_requirements (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references solution_reverification_events(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  requirement_id uuid not null references solution_requirements(id) on delete cascade,
  resolved_by uuid references profiles(id) on delete set null,
  resolved_at timestamptz,
  resolution_note text,
  created_at timestamptz not null default now(),
  unique (event_id, requirement_id),
  check (resolved_at is null or length(trim(coalesce(resolution_note, ''))) > 0)
);

create index if not exists solution_reverification_event_requirements_requirement_idx on solution_reverification_event_requirements(requirement_id);

-- The one definition of "re-verification due" -------------------------------------
-- Open events: unresolved, and some current method (or the requirement has
-- none) has no result other than "not run" recorded after the event.
create or replace function solution_requirement_open_events(p_requirement_id uuid)
returns uuid[]
language sql stable security definer set search_path = public as $$
  select coalesce(array_agg(distinct e.id), '{}'::uuid[])
  from solution_reverification_event_requirements l
  join solution_reverification_events e on e.id = l.event_id
  where l.requirement_id = p_requirement_id and l.resolved_at is null
    and (
      not exists (select 1 from solution_verification_methods m where m.requirement_id = p_requirement_id)
      or exists (
        select 1 from solution_verification_methods m
        where m.requirement_id = p_requirement_id
          and not exists (
            select 1 from solution_verification_records r
            where r.method_id = m.id and r.result <> 'not_run' and r.recorded_at > e.created_at
          )
      )
    );
$$;

-- Review due: a baselined requirement with a review interval whose least
-- recently verified method was last performed longer ago than that.
create or replace function solution_requirement_review_due(p_requirement_id uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select r.review_interval_months is not null and r.status = 'baselined'
      and (
        select min(x.latest) from (
          select max(rec.performed_on) as latest
          from solution_verification_methods m
          join solution_verification_records rec on rec.method_id = m.id and rec.result <> 'not_run'
          where m.requirement_id = r.id
          group by m.id
        ) x
      ) + make_interval(months => r.review_interval_months) < current_date
    from solution_requirements r where r.id = p_requirement_id
  ), false);
$$;

-- For the app: every open requirement in a Project that is due, and why.
create or replace function project_reverification_due(p_project_id uuid)
returns table (requirement_id uuid, open_event_ids uuid[], review_due boolean)
language sql stable security definer set search_path = public as $$
  select x.id, x.open_events, x.review_due
  from (
    select r.id, solution_requirement_open_events(r.id) as open_events, solution_requirement_review_due(r.id) as review_due
    from solution_requirements r
    where r.project_id = p_project_id and r.status in ('draft', 'baselined')
      and is_project_member(p_project_id, auth.uid())
  ) x
  where cardinality(x.open_events) > 0 or x.review_due;
$$;

-- Recording a change ------------------------------------------------------------------
-- The Project's owner, curators and consultants (and platform admins) record
-- a change and the open requirements of this Project it affects.
create or replace function record_solution_reverification_event(
  p_project_id uuid,
  p_kind text,
  p_summary text,
  p_requirement_ids uuid[],
  p_change_reference text default null,
  p_detail text default null,
  p_project_object_id uuid default null,
  p_workstream_id uuid default null
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_ids uuid[] := array(select distinct a from unnest(coalesce(p_requirement_ids, '{}'::uuid[])) a where a is not null);
  v_id uuid;
begin
  if v_uid is null or not can_run_project_evals(p_project_id, v_uid) then
    raise exception 'record_solution_reverification_event: only this Project''s owner, curators and consultants can record a change';
  end if;
  if p_kind is null or p_kind not in ('component_change', 'other') then
    raise exception 'record_solution_reverification_event: choose the kind of change';
  end if;
  if length(trim(coalesce(p_summary, ''))) = 0 then
    raise exception 'record_solution_reverification_event: describe the change';
  end if;
  if cardinality(v_ids) = 0 then
    raise exception 'record_solution_reverification_event: choose at least one affected requirement';
  end if;
  if exists (
    select 1 from unnest(v_ids) a
    where not exists (select 1 from solution_requirements r where r.id = a and r.project_id = p_project_id and r.status in ('draft', 'baselined'))
  ) then
    raise exception 'record_solution_reverification_event: affected requirements must be open requirements of this Project';
  end if;
  if p_project_object_id is not null and not exists (select 1 from project_objects o where o.id = p_project_object_id and o.project_id = p_project_id) then
    raise exception 'record_solution_reverification_event: the component must be in this Project';
  end if;
  if p_workstream_id is not null and not exists (select 1 from project_workstreams w where w.id = p_workstream_id and w.project_id = p_project_id) then
    raise exception 'record_solution_reverification_event: the workstream must be in this Project';
  end if;

  insert into solution_reverification_events (project_id, kind, summary, detail, change_reference, project_object_id, workstream_id, recorded_by)
  values (p_project_id, p_kind, trim(p_summary), nullif(trim(p_detail), ''), nullif(trim(p_change_reference), ''), p_project_object_id, p_workstream_id, v_uid)
  returning id into v_id;

  insert into solution_reverification_event_requirements (event_id, project_id, requirement_id)
  select v_id, p_project_id, a from unnest(v_ids) a;
  return v_id;
end;
$$;

-- A curator closes an event for one requirement without re-verifying it,
-- with a note (e.g. "reviewed the revised clause -- no impact").
create or replace function resolve_solution_reverification(p_link_id uuid, p_note text)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_link solution_reverification_event_requirements%rowtype;
begin
  select * into v_link from solution_reverification_event_requirements where id = p_link_id for update;
  if not found or v_uid is null or not can_curate_project(v_link.project_id, v_uid) then
    raise exception 'resolve_solution_reverification: only this Project''s owner and curators can resolve it';
  end if;
  if v_link.resolved_at is not null then
    raise exception 'resolve_solution_reverification: this has already been resolved';
  end if;
  if length(trim(coalesce(p_note, ''))) = 0 then
    raise exception 'resolve_solution_reverification: say why no re-verification is needed';
  end if;
  update solution_reverification_event_requirements
  set resolved_by = v_uid, resolved_at = now(), resolution_note = trim(p_note)
  where id = p_link_id;
end;
$$;

-- Automatic: a new version of a cited knowledge source --------------------------------
-- Flags each open requirement citing an earlier version, one event per
-- Project. Never blocks the upload: a failure here is only a warning.
create or replace function solution_flag_source_revision()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_project record;
  v_event_id uuid;
begin
  begin
    for v_project in
      select distinct s.project_id
      from solution_requirement_sources s
      join solution_requirements r on r.id = s.requirement_id and r.status in ('draft', 'baselined')
      where s.knowledge_source_id = new.id and s.document_version_id is distinct from new.current_version_id
    loop
      insert into solution_reverification_events (project_id, kind, summary, knowledge_source_id, document_version_id)
      values (v_project.project_id, 'source_revision', 'New version of a cited source: ' || coalesce(new.title, 'untitled'), new.id, new.current_version_id)
      returning id into v_event_id;

      insert into solution_reverification_event_requirements (event_id, project_id, requirement_id)
      select distinct v_event_id, v_project.project_id, s.requirement_id
      from solution_requirement_sources s
      join solution_requirements r on r.id = s.requirement_id and r.status in ('draft', 'baselined')
      where s.knowledge_source_id = new.id and s.project_id = v_project.project_id
        and s.document_version_id is distinct from new.current_version_id;
    end loop;
  exception when others then
    raise warning 'solution_flag_source_revision: %', sqlerrm;
  end;
  return null;
end;
$$;

drop trigger if exists knowledge_sources_flag_solution_revision on knowledge_sources;
create trigger knowledge_sources_flag_solution_revision
  after update of current_version_id on knowledge_sources
  for each row
  when (old.current_version_id is not null and new.current_version_id is distinct from old.current_version_id)
  execute function solution_flag_source_revision();

-- Automatic: an operational measure recorded as a fail ---------------------------------
create or replace function solution_flag_threshold_breach()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_event_id uuid;
begin
  if new.method_kind = 'operational_measure' and new.result = 'fail' then
    insert into solution_reverification_events (project_id, kind, summary, detail, record_id, recorded_by)
    values (
      new.project_id, 'threshold_breach', 'Operational measure outside its threshold',
      concat_ws(' · ', 'Measured: ' || new.measured_value, 'Threshold: ' || new.threshold, 'Window: ' || new.measure_window),
      new.id, new.recorded_by
    )
    returning id into v_event_id;
    insert into solution_reverification_event_requirements (event_id, project_id, requirement_id)
    values (v_event_id, new.project_id, new.requirement_id);
  end if;
  return null;
end;
$$;

drop trigger if exists solution_verification_records_flag_threshold on solution_verification_records;
create trigger solution_verification_records_flag_threshold
  after insert on solution_verification_records
  for each row execute function solution_flag_threshold_breach();

-- Production changes wait for re-verification ----------------------------------------
-- decide_solution_conformance_decision() from 20261020100001, unchanged except
-- for the production-change check before the verdict is recorded.
create or replace function decide_solution_conformance_decision(
  p_decision_id uuid,
  p_approve boolean,
  p_note text default null,
  p_conditions text default null
)
returns text
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_decision solution_conformance_decisions%rowtype;
  v_is_self boolean;
  v_approvals integer;
  v_needed integer;
begin
  select * into v_decision from solution_conformance_decisions where id = p_decision_id for update;
  if not found or v_uid is null or not holds_project_authority(v_decision.project_id, v_uid, v_decision.approval_type) then
    raise exception 'decide_solution_conformance_decision: only a holder of the required approval authority can decide this';
  end if;
  if v_decision.status <> 'pending' then
    raise exception 'decide_solution_conformance_decision: this decision has already been made';
  end if;
  if exists (select 1 from solution_conformance_decision_approvals a where a.decision_id = p_decision_id and a.approver_id = v_uid) then
    raise exception 'decide_solution_conformance_decision: you have already given your verdict';
  end if;

  -- Self-approval: the requester, or anyone who recorded evidence in effect
  -- for this baseline's requirements.
  v_is_self := v_decision.requested_by = v_uid or exists (
    select 1
    from solution_evaluation_baseline_items i
    join solution_verification_records r on r.requirement_id = i.requirement_id
    where i.baseline_id = v_decision.baseline_id and r.recorded_by = v_uid
      and not exists (select 1 from solution_verification_records s where s.supersedes_id = r.id)
  );
  if v_is_self and not project_self_approval_allowed(v_decision.project_id, v_uid, v_decision.approval_type) then
    raise exception 'decide_solution_conformance_decision: you requested this decision or recorded its evidence, and this Project does not allow self-approval';
  end if;

  -- Stage 4: a production change can't be approved while any requirement
  -- in the baseline needs re-verification.
  if p_approve and v_decision.approval_type = 'production_change' and exists (
    select 1 from solution_evaluation_baseline_items i
    where i.baseline_id = v_decision.baseline_id
      and (cardinality(solution_requirement_open_events(i.requirement_id)) > 0 or solution_requirement_review_due(i.requirement_id))
  ) then
    raise exception 'decide_solution_conformance_decision: requirements in this baseline need re-verification before a production change can be approved';
  end if;

  insert into solution_conformance_decision_approvals (decision_id, project_id, approver_id, verdict, note, conditions)
  values (p_decision_id, v_decision.project_id, v_uid, case when p_approve then 'approve' else 'reject' end, nullif(trim(p_note), ''), nullif(trim(p_conditions), ''));

  if not p_approve then
    update solution_conformance_decisions set status = 'rejected', decided_at = now(), snapshot = solution_baseline_snapshot(v_decision.baseline_id)
    where id = p_decision_id;
    return 'rejected';
  end if;

  select count(*) into v_approvals from solution_conformance_decision_approvals a where a.decision_id = p_decision_id and a.verdict = 'approve';
  if v_decision.approval_mode = 'all_assigned' then
    select count(distinct a.user_id) into v_needed
    from project_authority_assignments a
    where a.project_id = v_decision.project_id and holds_project_authority(v_decision.project_id, a.user_id, v_decision.approval_type);
    v_needed := greatest(v_needed, v_decision.required_approvals);
  else
    v_needed := v_decision.required_approvals;
  end if;

  if v_approvals >= v_needed then
    update solution_conformance_decisions set status = 'approved', decided_at = now(), snapshot = solution_baseline_snapshot(v_decision.baseline_id)
    where id = p_decision_id;
    return 'approved';
  end if;
  return 'pending';
end;
$$;


-- Grants ------------------------------------------------------------------------------
-- The per-requirement helpers are internal (used by the functions above);
-- the app reads project_reverification_due(), which checks membership.
do $$
declare
  fn text;
begin
  foreach fn in array array[
    'solution_requirement_open_events(uuid)',
    'solution_requirement_review_due(uuid)',
    'solution_flag_source_revision()',
    'solution_flag_threshold_breach()'
  ] loop
    execute format('revoke execute on function %s from public, anon, authenticated', fn);
  end loop;
  foreach fn in array array[
    'project_reverification_due(uuid)',
    'record_solution_reverification_event(uuid, text, text, uuid[], text, text, uuid, uuid)',
    'resolve_solution_reverification(uuid, text)',
    'decide_solution_conformance_decision(uuid, boolean, text, text)'
  ] loop
    execute format('revoke execute on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated', fn);
  end loop;
end;
$$;

-- RLS ---------------------------------------------------------------------------------
-- Members read the history; the functions above are the only writers.
alter table solution_reverification_events enable row level security;
alter table solution_reverification_event_requirements enable row level security;

drop policy if exists "solution_reverification_events_select_member" on solution_reverification_events;
create policy "solution_reverification_events_select_member" on solution_reverification_events
  for select using (is_project_member(project_id, auth.uid()));
drop policy if exists "solution_reverification_event_requirements_select_member" on solution_reverification_event_requirements;
create policy "solution_reverification_event_requirements_select_member" on solution_reverification_event_requirements
  for select using (is_project_member(project_id, auth.uid()));

-- External MCP read-only guarantee (20261005100001_external_mcp_access.sql),
-- guarded so this migration also applies before that one has run.
do $$
begin
  if to_regprocedure('public.apply_oauth_read_only_policies()') is not null then
    perform apply_oauth_read_only_policies();
  end if;
end;
$$;


-- ==== supabase/migrations/20261022100001_ember_drafted_requirements.sql ====
-- Solution conformance and acceptance evaluation, Stage 5: Ember tools
-- (docs/dev-request-solution-conformance-and-acceptance-evaluation.md).
--
-- Ember can draft requirements (and verification methods) from the
-- Project's knowledge when a curator asks and confirms. A requirement Ember
-- drafted is marked as such and is "awaiting acceptance": it can't be added
-- to a baseline until a curator explicitly accepts it, which records who
-- accepted it and when. Ember never records results, waives, baselines or
-- approves -- none of those are reachable from its tools.
--
-- Safe to re-run.

alter table solution_requirements
  add column if not exists created_via text not null default 'ui' check (created_via in ('ui', 'assistant')),
  add column if not exists assistant_conversation_id uuid references conversations(id) on delete set null,
  add column if not exists awaiting_acceptance boolean not null default false,
  add column if not exists accepted_by uuid references profiles(id) on delete set null,
  add column if not exists accepted_at timestamptz;

alter table solution_verification_methods
  add column if not exists created_via text not null default 'ui' check (created_via in ('ui', 'assistant'));

-- An Ember draft always starts awaiting acceptance; acceptance only goes one
-- way and is stamped with the accepting user; the origin never changes.
create or replace function solution_requirements_acceptance_guard()
returns trigger
language plpgsql set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.created_via = 'assistant' then
      new.awaiting_acceptance := true;
    end if;
    new.accepted_by := null;
    new.accepted_at := null;
    return new;
  end if;
  if new.created_via is distinct from old.created_via or new.assistant_conversation_id is distinct from old.assistant_conversation_id then
    raise exception 'solution_requirements: where a requirement came from cannot change';
  end if;
  if new.awaiting_acceptance and not old.awaiting_acceptance then
    raise exception 'solution_requirements: an accepted requirement cannot go back to awaiting acceptance';
  end if;
  if old.awaiting_acceptance and not new.awaiting_acceptance then
    if old.status <> 'draft' then
      raise exception 'solution_requirements: only a draft can be accepted';
    end if;
    new.accepted_by := auth.uid();
    new.accepted_at := now();
  else
    new.accepted_by := old.accepted_by;
    new.accepted_at := old.accepted_at;
  end if;
  return new;
end;
$$;

drop trigger if exists solution_requirements_acceptance_guard on solution_requirements;
create trigger solution_requirements_acceptance_guard before insert or update on solution_requirements
  for each row execute function solution_requirements_acceptance_guard();

-- A requirement awaiting acceptance can't be baselined: the item trigger from
-- 20261020100001 gains that check (otherwise unchanged).
create or replace function solution_evaluation_baseline_items_before_write()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_baseline solution_evaluation_baselines%rowtype;
begin
  if tg_op = 'DELETE' then
    -- Deleting the baseline or the Project removes items with it.
    if pg_trigger_depth() = 1 and exists (select 1 from solution_evaluation_baselines b where b.id = old.baseline_id and b.status <> 'draft') then
      raise exception 'solution_evaluation_baseline_items: an active baseline is frozen -- create a new version to change it';
    end if;
    return old;
  end if;
  if tg_op = 'UPDATE' then
    raise exception 'solution_evaluation_baseline_items: items are added or removed, never changed';
  end if;
  select * into v_baseline from solution_evaluation_baselines where id = new.baseline_id;
  if not found or v_baseline.project_id is distinct from new.project_id then
    raise exception 'solution_evaluation_baseline_items: must belong to its baseline''s Project';
  end if;
  if v_baseline.status <> 'draft' then
    raise exception 'solution_evaluation_baseline_items: an active baseline is frozen -- create a new version to change it';
  end if;
  if not exists (
    select 1 from solution_requirements r
    where r.id = new.requirement_id and r.project_id = v_baseline.project_id and r.status in ('draft', 'baselined')
  ) then
    raise exception 'solution_evaluation_baseline_items: only an open requirement of this Project can be baselined';
  end if;
  if exists (select 1 from solution_requirements r where r.id = new.requirement_id and r.awaiting_acceptance) then
    raise exception 'solution_evaluation_baseline_items: a requirement Ember drafted must be accepted by a curator before it can be baselined';
  end if;
  return new;
end;
$$;

-- External MCP read-only guarantee (20261005100001_external_mcp_access.sql),
-- guarded so this migration also applies before that one has run.
do $$
begin
  if to_regprocedure('public.apply_oauth_read_only_policies()') is not null then
    perform apply_oauth_read_only_policies();
  end if;
end;
$$;


-- ==== supabase/migrations/20261023100001_collaboration_sessions.sql ====
-- Shared workspace sessions, Phase 1: session foundation
-- (docs/dev-request-shared-workspace-sessions.md).
--
-- Two active members of the same Project work in one live session: both
-- browsers show the Project or Workstream page the controller is on, either
-- can ask for control, the host can take it back, and the shared
-- conversation stays in both people's history afterwards. Phase 1 shares
-- navigation only -- shared form drafts are Phase 2 and shared Ember chat is
-- Phase 3, so the conversation here is a shell (participants and sessions).
--
-- Authority lives in these tables and the functions below, never in the
-- browser: every call resolves the caller from auth.uid(), re-checks that
-- BOTH people are still active members of the Project (no admin bypass),
-- locks the session row, and validates the caller's browser tab
-- (connection) and the control generation. A command from a tab that lost
-- control, or that was issued before a handover, is rejected.
--
-- No client reads or writes the tables directly; RLS is on with no
-- policies and grants are revoked. Clients call the security-definer
-- functions, which return minimal DTOs (never connection ids).
--
-- Nothing here deletes a row: sessions and invitations end or expire by
-- status. Safe to re-run.

-- Shared conversation: a fixed pair in one Project, persisting across live
-- sessions. user_a < user_b so the pair has one spelling.
create table if not exists collaboration_conversations (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  user_a uuid not null references profiles(id) on delete cascade,
  user_b uuid not null references profiles(id) on delete cascade,
  created_by uuid not null references profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  last_activity_at timestamptz not null default now(),
  check (user_a < user_b),
  check (created_by in (user_a, user_b))
);

create index if not exists collaboration_conversations_user_a_idx on collaboration_conversations(user_a, last_activity_at desc);
create index if not exists collaboration_conversations_user_b_idx on collaboration_conversations(user_b, last_activity_at desc);

-- Invitation to a live session: a new conversation, or (conversation_id set
-- at creation) resuming an existing one. Admission only -- never grants
-- Project membership or evidence access. Expires; only the invitee can
-- accept, so a forwarded link grants nothing.
create table if not exists collaboration_invitations (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  conversation_id uuid references collaboration_conversations(id) on delete cascade,
  inviter_id uuid not null references profiles(id) on delete cascade,
  invitee_id uuid not null references profiles(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'cancelled')),
  created_via text not null default 'ui' check (created_via in ('ui', 'assistant')),
  assistant_conversation_id uuid references conversations(id) on delete set null,
  expires_at timestamptz not null,
  responded_at timestamptz,
  created_at timestamptz not null default now(),
  check (inviter_id <> invitee_id)
);

create index if not exists collaboration_invitations_invitee_idx on collaboration_invitations(invitee_id, status, expires_at);
create index if not exists collaboration_invitations_inviter_idx on collaboration_invitations(inviter_id, status, expires_at);

-- Live session. The inviter is host and starts in control. Control moves
-- only by a recorded grant, reclaim, or the controller explicitly leaving;
-- never because someone disconnected. control_generation increases on
-- every change of controller or of the controller's tab, and on end.
-- state_revision increases on any visible change, so a poll can skip
-- unchanged snapshots. location_workstream_id null = the Project page.
create table if not exists collaboration_sessions (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references collaboration_conversations(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  host_id uuid not null references profiles(id) on delete cascade,
  guest_id uuid not null references profiles(id) on delete cascade,
  status text not null default 'active' check (status in ('active', 'ended')),
  end_reason text check (end_reason in ('ended_by_host', 'everyone_left', 'inactive', 'participant_inactive', 'expired', 'access_revoked')),
  ended_by uuid references profiles(id) on delete set null,
  controller_id uuid not null references profiles(id) on delete cascade,
  control_generation integer not null default 1,
  state_revision integer not null default 1,
  control_requested_by uuid references profiles(id) on delete set null,
  control_requested_at timestamptz,
  location_workstream_id uuid references project_workstreams(id) on delete set null,
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  check (host_id <> guest_id),
  check (controller_id in (host_id, guest_id)),
  check ((status = 'ended') = (ended_at is not null))
);

create unique index if not exists collaboration_sessions_one_live_idx on collaboration_sessions(conversation_id) where status = 'active';
create index if not exists collaboration_sessions_conversation_idx on collaboration_sessions(conversation_id, started_at desc);

alter table collaboration_invitations
  add column if not exists session_id uuid references collaboration_sessions(id) on delete set null;

-- One row per person per session. connection_id is the one browser tab
-- that currently speaks for this person; last_seen_at is that tab's
-- presence (it polls); last_active_at is the last time the person actually
-- did something in it (input, or a session command) -- "away" and the
-- inactivity end come from that.
create table if not exists collaboration_participants (
  session_id uuid not null references collaboration_sessions(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  role text not null check (role in ('host', 'guest')),
  connection_id uuid,
  last_seen_at timestamptz,
  last_active_at timestamptz,
  joined_at timestamptz,
  left_at timestamptz,
  primary key (session_id, user_id)
);

create index if not exists collaboration_participants_user_idx on collaboration_participants(user_id);

-- Minimal, server-attributed audit: invitations, joins, leaves, control
-- changes and ends. No navigation trail, no content.
create table if not exists collaboration_events (
  id bigint generated always as identity primary key,
  session_id uuid references collaboration_sessions(id) on delete cascade,
  conversation_id uuid references collaboration_conversations(id) on delete cascade,
  invitation_id uuid references collaboration_invitations(id) on delete cascade,
  actor_id uuid references profiles(id) on delete set null,
  -- Who the event was about, when that isn't the actor (an added viewer).
  subject_id uuid references profiles(id) on delete set null,
  event text not null,
  control_generation integer,
  created_at timestamptz not null default now()
);

create index if not exists collaboration_events_session_idx on collaboration_events(session_id, created_at);

-- Viewers of a shared conversation: other active members of the Project
-- that either person in the pair has added. Phase 1: they see the
-- conversation in their own history and its page, read-only, and are
-- listed in the session bar -- they don't watch live sessions (no polling)
-- and can't join, control or resume one. Phase 3: they read a recap of the
-- shared Ember chat and can post to it. Removing a viewer only changes
-- status.
create table if not exists collaboration_viewers (
  conversation_id uuid not null references collaboration_conversations(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  status text not null default 'active' check (status in ('active', 'removed')),
  added_by uuid references profiles(id) on delete set null,
  added_at timestamptz not null default now(),
  removed_by uuid references profiles(id) on delete set null,
  removed_at timestamptz,
  primary key (conversation_id, user_id),
  check ((status = 'removed') = (removed_at is not null))
);

create index if not exists collaboration_viewers_user_idx on collaboration_viewers(user_id, status);

-- A viewer watching a live session in one tab (they chose Watch): their tab
-- follows the controller like the guest's, with no controls. Separate from
-- collaboration_participants so watchers never count for the pair's rules
-- (one live session per person, deadlines, "everyone left"). A watcher's
-- poll writes only their own row here -- it never locks the session.
create table if not exists collaboration_watchers (
  session_id uuid not null references collaboration_sessions(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  connection_id uuid,
  last_seen_at timestamptz,
  started_at timestamptz not null default now(),
  stopped_at timestamptz,
  primary key (session_id, user_id)
);

alter table collaboration_conversations enable row level security;
alter table collaboration_invitations enable row level security;
alter table collaboration_sessions enable row level security;
alter table collaboration_participants enable row level security;
alter table collaboration_events enable row level security;
alter table collaboration_viewers enable row level security;
alter table collaboration_watchers enable row level security;
revoke all on collaboration_conversations, collaboration_invitations, collaboration_sessions,
  collaboration_participants, collaboration_events, collaboration_viewers, collaboration_watchers from anon, authenticated;

-- Internal helpers -----------------------------------------------------------------
-- Errors meant for the person use SQLSTATE class EC (EC001 general, EC002
-- "open in another tab", EC003 "out of date -- refresh"); the app shows
-- those messages and hides anything else.

-- Timings, in one place:
--   presence window: how long a tab counts as connected without polling.
--     Browsers slow timers in background tabs to about once a minute, so
--     this is long enough that switching tabs never reads as "not
--     connected"; a closed tab says so straight away (collaboration_disconnect).
--   away after: no input or command for this long shows a person as away.
--   inactive limit: the session ends when nobody has been active this long.
--   participant inactive limit: ...or when either person has been inactive
--     this long (one person alone isn't collaborating).
--   max duration: the session ends regardless after this long.
create or replace function collaboration_presence_window() returns interval
language sql immutable as $$ select interval '90 seconds' $$;
create or replace function collaboration_invitation_lifetime() returns interval
language sql immutable as $$ select interval '1 hour' $$;
create or replace function collaboration_away_after() returns interval
language sql immutable as $$ select interval '10 minutes' $$;
create or replace function collaboration_inactive_limit() returns interval
language sql immutable as $$ select interval '30 minutes' $$;
create or replace function collaboration_participant_inactive_limit() returns interval
language sql immutable as $$ select interval '60 minutes' $$;
create or replace function collaboration_max_duration() returns interval
language sql immutable as $$ select interval '12 hours' $$;

-- Actual active membership with an active profile. Deliberately no admin
-- bypass: admission needs real membership for both people.
create or replace function collaboration_has_access(p_project uuid, p_user uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from project_members m join profiles p on p.id = m.user_id
    where m.project_id = p_project and m.user_id = p_user and m.status = 'active' and p.is_active
  );
$$;

create or replace function collaboration_display_name(p_user uuid)
returns text
language sql stable security definer set search_path = public as $$
  select coalesce(nullif(trim(full_name), ''), email, 'Project member') from profiles where id = p_user;
$$;

-- The signed-in caller, with an active profile.
create or replace function collaboration_actor()
returns uuid
language plpgsql stable security definer set search_path = public as $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null or not exists (select 1 from profiles where id = v_actor and is_active) then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  return v_actor;
end;
$$;

-- Same, for anything that writes: an external MCP client token
-- (20261005100001_external_mcp_access.sql) is read-only, and these
-- functions run as their owner, past its restrictive policies.
create or replace function collaboration_writer()
returns uuid
language plpgsql stable security definer set search_path = public as $$
begin
  if (auth.jwt() ->> 'client_id') is not null then
    raise exception 'An external client cannot change collaboration sessions' using errcode = '42501';
  end if;
  return collaboration_actor();
end;
$$;

create or replace function collaboration_is_present(p collaboration_participants)
returns boolean
language sql stable as $$
  select p.left_at is null and p.connection_id is not null
    and p.last_seen_at is not null and p.last_seen_at > now() - collaboration_presence_window();
$$;

-- When the person last did something: their last input or command, else
-- when they joined, else when the session started.
create or replace function collaboration_last_active(p collaboration_participants, p_started_at timestamptz)
returns timestamptz
language sql stable as $$
  select coalesce(p.last_active_at, p.joined_at, p_started_at);
$$;

create or replace function collaboration_is_away(p collaboration_participants, p_started_at timestamptz)
returns boolean
language sql stable as $$
  select collaboration_last_active(p, p_started_at) < now() - collaboration_away_after();
$$;

-- When a live session will end on its own, and why: nobody active for the
-- inactive limit, either person inactive for the participant limit, or the
-- maximum duration -- whichever comes first.
create or replace function collaboration_deadline(p_session uuid, out ends_at timestamptz, out reason text)
language plpgsql stable security definer set search_path = public as $$
declare
  s collaboration_sessions;
  h collaboration_participants;
  g collaboration_participants;
  v_host timestamptz;
  v_guest timestamptz;
  v_candidate timestamptz;
begin
  select * into s from collaboration_sessions where id = p_session;
  select * into h from collaboration_participants where session_id = s.id and user_id = s.host_id;
  select * into g from collaboration_participants where session_id = s.id and user_id = s.guest_id;
  v_host := collaboration_last_active(h, s.started_at);
  v_guest := collaboration_last_active(g, s.started_at);
  ends_at := s.started_at + collaboration_max_duration();
  reason := 'expired';
  v_candidate := least(v_host, v_guest) + collaboration_participant_inactive_limit();
  if v_candidate < ends_at then
    ends_at := v_candidate;
    reason := 'participant_inactive';
  end if;
  v_candidate := greatest(v_host, v_guest) + collaboration_inactive_limit();
  if v_candidate <= ends_at then
    ends_at := v_candidate;
    reason := 'inactive';
  end if;
end;
$$;

-- Ends a session (status only -- nothing is deleted).
create or replace function collaboration_end_session(p_session uuid, p_reason text, p_actor uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  update collaboration_sessions
    set status = 'ended', end_reason = p_reason, ended_by = p_actor, ended_at = now(),
        control_requested_by = null, control_requested_at = null,
        control_generation = control_generation + 1, state_revision = state_revision + 1
    where id = p_session and status = 'active';
  if found then
    update collaboration_conversations set last_activity_at = now()
      where id = (select conversation_id from collaboration_sessions where id = p_session);
    insert into collaboration_events(session_id, actor_id, event, control_generation)
      select id, p_actor, 'ended:' || p_reason, control_generation from collaboration_sessions where id = p_session;
  end if;
end;
$$;

-- Ends a live session that has lost a participant's access or passed its
-- deadline (inactivity or maximum duration), and drops a control request
-- whose requester has since gone away. Called with the session row locked;
-- returns true if the session ended.
create or replace function collaboration_settle(p_session uuid)
returns boolean
language plpgsql security definer set search_path = public as $$
declare
  s collaboration_sessions;
  d record;
  r collaboration_participants;
begin
  select * into s from collaboration_sessions where id = p_session;
  if not found or s.status <> 'active' then
    return false;
  end if;
  if not collaboration_has_access(s.project_id, s.host_id) or not collaboration_has_access(s.project_id, s.guest_id) then
    perform collaboration_end_session(s.id, 'access_revoked', null);
    return true;
  end if;
  select * into d from collaboration_deadline(s.id);
  if d.ends_at <= now() then
    perform collaboration_end_session(s.id, d.reason, null);
    return true;
  end if;
  if s.control_requested_by is not null then
    select * into r from collaboration_participants where session_id = s.id and user_id = s.control_requested_by;
    if collaboration_is_away(r, s.started_at) or r.left_at is not null then
      update collaboration_sessions set control_requested_by = null, control_requested_at = null, state_revision = state_revision + 1
        where id = s.id;
    end if;
  end if;
  return false;
end;
$$;

-- Ends any of this person's live sessions that have expired or lost access,
-- so a stale one never blocks a new invitation.
create or replace function collaboration_settle_user(p_user uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_session uuid;
begin
  for v_session in
    select s.id from collaboration_sessions s join collaboration_participants p on p.session_id = s.id
    where p.user_id = p_user and s.status = 'active'
    order by s.id
    for update of s
  loop
    perform collaboration_settle(v_session);
  end loop;
end;
$$;

create or replace function collaboration_in_live_session(p_user uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from collaboration_sessions s join collaboration_participants p on p.session_id = s.id
    where p.user_id = p_user and s.status = 'active' and p.left_at is null
  );
$$;

-- Locks the session for a command from the caller. Requires the caller to
-- be a participant with access; with p_connection, also that this tab is
-- the caller's current, present tab in a live session.
create or replace function collaboration_lock(p_session uuid, p_connection uuid, p_actor uuid)
returns collaboration_sessions
language plpgsql security definer set search_path = public as $$
declare
  s collaboration_sessions;
  me collaboration_participants;
begin
  select * into s from collaboration_sessions where id = p_session for update;
  if not found or p_actor not in (s.host_id, s.guest_id) or not collaboration_has_access(s.project_id, p_actor) then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  if collaboration_settle(s.id) then
    select * into s from collaboration_sessions where id = p_session;
  end if;
  if s.status <> 'active' then
    raise exception 'This live session has ended' using errcode = 'EC001';
  end if;
  if p_connection is not null then
    select * into me from collaboration_participants where session_id = s.id and user_id = p_actor;
    if me.connection_id is distinct from p_connection or not coalesce(collaboration_is_present(me), false) then
      raise exception 'This tab is no longer connected to the live session -- rejoin to continue' using errcode = 'EC003';
    end if;
    -- A command is activity.
    update collaboration_participants set last_active_at = now(), last_seen_at = now() where session_id = s.id and user_id = p_actor;
  end if;
  return s;
end;
$$;

create or replace function collaboration_log(s collaboration_sessions, p_actor uuid, p_event text)
returns void
language sql security definer set search_path = public as $$
  insert into collaboration_events(session_id, conversation_id, actor_id, event, control_generation)
  values (s.id, s.conversation_id, p_actor, p_event, s.control_generation);
$$;

-- The conversation's current viewers who still have access to its Project.
create or replace function collaboration_viewers_json(p_conversation uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('userId', v.user_id, 'name', collaboration_display_name(v.user_id),
           'addedByName', collaboration_display_name(v.added_by), 'addedAt', v.added_at)
           order by v.added_at), '[]'::jsonb)
  from collaboration_viewers v join collaboration_conversations c on c.id = v.conversation_id
  where v.conversation_id = p_conversation and v.status = 'active' and collaboration_has_access(c.project_id, v.user_id);
$$;

-- The caller's role in a conversation they can open: 'participant' (one of
-- the pair), 'viewer', or null. Both of the pair, and a viewer, need
-- current access to the Project.
create or replace function collaboration_conversation_role(c collaboration_conversations, p_user uuid)
returns text
language sql stable security definer set search_path = public as $$
  select case
    when not collaboration_has_access(c.project_id, c.user_a) or not collaboration_has_access(c.project_id, c.user_b) then null
    when p_user in (c.user_a, c.user_b) then 'participant'
    when exists (select 1 from collaboration_viewers v where v.conversation_id = c.id and v.user_id = p_user and v.status = 'active')
         and collaboration_has_access(c.project_id, p_user) then 'viewer'
  end;
$$;

-- Viewers watching a session right now (polled within the presence
-- window, still viewers with access).
create or replace function collaboration_watching_json(p_session uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('userId', w.user_id, 'name', collaboration_display_name(w.user_id)) order by w.started_at), '[]'::jsonb)
  from collaboration_watchers w
  join collaboration_sessions s on s.id = w.session_id
  join collaboration_conversations c on c.id = s.conversation_id
  where w.session_id = p_session and w.stopped_at is null and w.connection_id is not null
    and w.last_seen_at > now() - collaboration_presence_window()
    and collaboration_conversation_role(c, w.user_id) = 'viewer';
$$;

-- What a participant's browser sees. Never includes connection ids.
create or replace function collaboration_snapshot(p_session uuid, p_actor uuid, p_connection uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s collaboration_sessions;
  h collaboration_participants;
  g collaboration_participants;
  me collaboration_participants;
  ctl collaboration_participants;
  v_workstream_name text;
  d record;
begin
  select * into s from collaboration_sessions where id = p_session;
  select * into h from collaboration_participants where session_id = s.id and user_id = s.host_id;
  select * into g from collaboration_participants where session_id = s.id and user_id = s.guest_id;
  me := case when p_actor = s.host_id then h else g end;
  ctl := case when s.controller_id = s.host_id then h else g end;
  select * into d from collaboration_deadline(s.id);
  if s.location_workstream_id is not null then
    select name into v_workstream_name from project_workstreams where id = s.location_workstream_id;
  end if;
  return jsonb_build_object(
    'id', s.id,
    'conversationId', s.conversation_id,
    'projectId', s.project_id,
    'projectName', (select name from projects where id = s.project_id),
    'status', s.status,
    'endReason', s.end_reason,
    'myRole', case when p_actor = s.host_id then 'host' else 'guest' end,
    'host', jsonb_build_object('id', s.host_id, 'name', collaboration_display_name(s.host_id),
      'present', coalesce(collaboration_is_present(h), false), 'left', h.left_at is not null,
      'away', collaboration_is_away(h, s.started_at),
      'inactiveSeconds', floor(extract(epoch from now() - collaboration_last_active(h, s.started_at)))::int),
    'guest', jsonb_build_object('id', s.guest_id, 'name', collaboration_display_name(s.guest_id),
      'present', coalesce(collaboration_is_present(g), false), 'left', g.left_at is not null,
      'away', collaboration_is_away(g, s.started_at),
      'inactiveSeconds', floor(extract(epoch from now() - collaboration_last_active(g, s.started_at)))::int),
    'controllerId', s.controller_id,
    'controlGeneration', s.control_generation,
    'stateRevision', s.state_revision,
    'controlRequestedBy', s.control_requested_by,
    'location', jsonb_build_object('workstreamId', s.location_workstream_id, 'workstreamName', v_workstream_name),
    -- This tab is the caller's current tab (and still present).
    'thisTabJoined', coalesce(p_connection is not null and me.connection_id = p_connection and collaboration_is_present(me), false),
    -- The caller is present from some other tab.
    'otherTabActive', me.connection_id is distinct from p_connection and coalesce(collaboration_is_present(me), false),
    'iLeft', me.left_at is not null,
    'viewers', collaboration_viewers_json(s.conversation_id),
    'watching', collaboration_watching_json(s.id),
    -- Seconds until the session ends on its own, and which rule ends it.
    'endsInSeconds', case when s.status = 'active' then greatest(0, floor(extract(epoch from d.ends_at - now())))::int end,
    'endingReason', case when s.status = 'active' then d.reason end,
    -- Someone not in control may take it while the controller is away or
    -- not connected (the host can always take it back).
    'canTakeControl', s.status = 'active' and s.controller_id <> p_actor
      and (collaboration_is_away(ctl, s.started_at) or not coalesce(collaboration_is_present(ctl), false))
  );
end;
$$;

create or replace function collaboration_invitation_dto(i collaboration_invitations)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', i.id,
    'projectId', i.project_id,
    'projectName', (select name from projects where id = i.project_id),
    'conversationId', i.conversation_id,
    'inviterId', i.inviter_id,
    'inviterName', collaboration_display_name(i.inviter_id),
    'inviteeId', i.invitee_id,
    'inviteeName', collaboration_display_name(i.invitee_id),
    'status', case when i.status = 'pending' and i.expires_at <= now() then 'expired' else i.status end,
    'expiresAt', i.expires_at,
    'sessionId', i.session_id
  );
$$;

revoke all on function collaboration_presence_window() from public, anon, authenticated;
revoke all on function collaboration_invitation_lifetime() from public, anon, authenticated;
revoke all on function collaboration_away_after() from public, anon, authenticated;
revoke all on function collaboration_inactive_limit() from public, anon, authenticated;
revoke all on function collaboration_participant_inactive_limit() from public, anon, authenticated;
revoke all on function collaboration_last_active(collaboration_participants, timestamptz) from public, anon, authenticated;
revoke all on function collaboration_is_away(collaboration_participants, timestamptz) from public, anon, authenticated;
revoke all on function collaboration_deadline(uuid) from public, anon, authenticated;
revoke all on function collaboration_max_duration() from public, anon, authenticated;
revoke all on function collaboration_has_access(uuid, uuid) from public, anon, authenticated;
revoke all on function collaboration_display_name(uuid) from public, anon, authenticated;
revoke all on function collaboration_actor() from public, anon, authenticated;
revoke all on function collaboration_writer() from public, anon, authenticated;
revoke all on function collaboration_is_present(collaboration_participants) from public, anon, authenticated;
revoke all on function collaboration_end_session(uuid, text, uuid) from public, anon, authenticated;
revoke all on function collaboration_settle(uuid) from public, anon, authenticated;
revoke all on function collaboration_settle_user(uuid) from public, anon, authenticated;
revoke all on function collaboration_in_live_session(uuid) from public, anon, authenticated;
revoke all on function collaboration_lock(uuid, uuid, uuid) from public, anon, authenticated;
revoke all on function collaboration_log(collaboration_sessions, uuid, text) from public, anon, authenticated;
revoke all on function collaboration_snapshot(uuid, uuid, uuid) from public, anon, authenticated;
revoke all on function collaboration_viewers_json(uuid) from public, anon, authenticated;
revoke all on function collaboration_watching_json(uuid) from public, anon, authenticated;
revoke all on function collaboration_conversation_role(collaboration_conversations, uuid) from public, anon, authenticated;
revoke all on function collaboration_invitation_dto(collaboration_invitations) from public, anon, authenticated;

-- Reads ---------------------------------------------------------------------------

-- Who the caller can invite in this Project: other active members.
create or replace function collaboration_candidates(p_project uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_actor();
begin
  if not collaboration_has_access(p_project, v_actor) then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('userId', m.user_id, 'name', collaboration_display_name(m.user_id), 'role', m.role)
      order by lower(collaboration_display_name(m.user_id)))
    from project_members m join profiles p on p.id = m.user_id
    where m.project_id = p_project and m.status = 'active' and p.is_active and m.user_id <> v_actor
  ), '[]'::jsonb);
end;
$$;

-- The caller's shared conversations (as one of the pair, or a viewer),
-- newest activity first. A conversation disappears from every history
-- while either of the pair lacks access to its Project (fail closed), and
-- from a viewer's while they do; it returns if access does.
create or replace function collaboration_history()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_actor();
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', c.id,
      'projectId', c.project_id,
      'projectName', pr.name,
      'myRole', collaboration_conversation_role(c, v_actor),
      -- For a viewer there's no "other person": the pair is shown instead.
      'otherUserId', case when c.user_a = v_actor then c.user_b when c.user_b = v_actor then c.user_a end,
      'otherName', case
        when c.user_a = v_actor then collaboration_display_name(c.user_b)
        when c.user_b = v_actor then collaboration_display_name(c.user_a)
        else collaboration_display_name(c.user_a) || ' & ' || collaboration_display_name(c.user_b) end,
      'createdAt', c.created_at,
      'lastActivityAt', c.last_activity_at,
      -- Not "live" once past its deadline, even before anyone has settled it.
      'liveSessionId', (select s.id from collaboration_sessions s where s.conversation_id = c.id and s.status = 'active'
                          and (select ends_at from collaboration_deadline(s.id)) > now())
    ) order by c.last_activity_at desc)
    from collaboration_conversations c join projects pr on pr.id = c.project_id
    where collaboration_conversation_role(c, v_actor) is not null
  ), '[]'::jsonb);
end;
$$;

-- One shared conversation's shell: the pair, the Project and its sessions.
create or replace function collaboration_conversation(p_conversation uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_actor();
  c collaboration_conversations;
  v_other uuid;
  v_role text;
begin
  select * into c from collaboration_conversations where id = p_conversation;
  if not found then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  v_role := collaboration_conversation_role(c, v_actor);
  if v_role is null then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  v_other := case when c.user_a = v_actor then c.user_b when c.user_b = v_actor then c.user_a end;
  return jsonb_build_object(
    'id', c.id,
    'projectId', c.project_id,
    'projectName', (select name from projects where id = c.project_id),
    'myRole', v_role,
    'participants', jsonb_build_array(
      jsonb_build_object('userId', c.user_a, 'name', collaboration_display_name(c.user_a)),
      jsonb_build_object('userId', c.user_b, 'name', collaboration_display_name(c.user_b))),
    'viewers', collaboration_viewers_json(c.id),
    'otherUserId', v_other,
    'otherName', case when v_other is null then null else collaboration_display_name(v_other) end,
    'createdAt', c.created_at,
    'lastActivityAt', c.last_activity_at,
    'pendingInvitation', case when v_role = 'participant' then (
      select collaboration_invitation_dto(i) from collaboration_invitations i
      where i.conversation_id = c.id and i.status = 'pending' and i.expires_at > now()
      order by i.created_at desc limit 1
    ) end,
    'sessions', coalesce((
      -- A session past its deadline reads as ended (with the reason it
      -- will be settled with), even before anyone has settled it.
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'hostName', collaboration_display_name(s.host_id),
        'status', case when s.status = 'active' and d.ends_at <= now() then 'ended' else s.status end,
        'endReason', case when s.status = 'active' and d.ends_at <= now() then d.reason else s.end_reason end,
        'startedAt', s.started_at,
        'endedAt', case when s.status = 'active' and d.ends_at <= now() then d.ends_at else s.ended_at end
      ) order by s.started_at desc)
      from collaboration_sessions s cross join lateral collaboration_deadline(s.id) d where s.conversation_id = c.id
    ), '[]'::jsonb)
  );
end;
$$;

-- Polled by the browser (directly against Supabase, not through the app
-- server): the caller's live session, if any, and pending invitations.
-- With the caller's current tab id, also records that tab's presence (and,
-- with p_active, that the person is using it) -- the only write besides
-- settling an overdue session, and only to the caller's own row.
create or replace function collaboration_status(p_connection uuid default null, p_session uuid default null, p_active boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  v_session uuid;
begin
  -- The caller's live session; or, if the tab asks about one that just
  -- ended, that one, so it can say why.
  select s.id into v_session from collaboration_sessions s
    join collaboration_participants p on p.session_id = s.id and p.user_id = v_actor
    where s.status = 'active' order by (p.left_at is null) desc, s.started_at desc limit 1
    for update of s;
  if v_session is not null and collaboration_settle(v_session) and p_session is null then
    p_session := v_session;
  end if;
  if v_session is not null and exists (select 1 from collaboration_sessions where id = v_session and status = 'active') then
    if not collaboration_has_access((select project_id from collaboration_sessions where id = v_session), v_actor) then
      v_session := null;
    elsif p_connection is not null then
      -- p_active: the person used this tab since its last poll.
      update collaboration_participants
        set last_seen_at = now(), last_active_at = case when p_active then now() else last_active_at end
        where session_id = v_session and user_id = v_actor and connection_id = p_connection and left_at is null;
    end if;
  else
    v_session := null;
  end if;
  if v_session is null and p_session is not null then
    -- Only report on an ended session the caller was in and still has access to.
    select s.id into v_session from collaboration_sessions s
      where s.id = p_session and v_actor in (s.host_id, s.guest_id) and collaboration_has_access(s.project_id, v_actor);
  end if;
  return jsonb_build_object(
    'session', case when v_session is null then null else collaboration_snapshot(v_session, v_actor, p_connection) end,
    'incoming', coalesce((
      select jsonb_agg(collaboration_invitation_dto(i) order by i.created_at desc)
      from collaboration_invitations i
      where i.invitee_id = v_actor and i.status = 'pending' and i.expires_at > now()
        and collaboration_has_access(i.project_id, i.inviter_id) and collaboration_has_access(i.project_id, v_actor)
    ), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(collaboration_invitation_dto(i) order by i.created_at desc)
      from collaboration_invitations i
      where i.inviter_id = v_actor and i.status = 'pending' and i.expires_at > now()
    ), '[]'::jsonb),
    -- Live sessions on conversations the caller views, which they could
    -- choose to watch. Read-only: nothing here starts any polling.
    'watchable', coalesce((
      select jsonb_agg(jsonb_build_object(
        'sessionId', s.id, 'conversationId', c.id, 'projectId', c.project_id,
        'projectName', (select name from projects where id = c.project_id),
        'hostName', collaboration_display_name(s.host_id), 'guestName', collaboration_display_name(s.guest_id)
      ) order by s.started_at desc)
      from collaboration_sessions s join collaboration_conversations c on c.id = s.conversation_id
      where s.status = 'active' and collaboration_conversation_role(c, v_actor) = 'viewer'
        and (select ends_at from collaboration_deadline(s.id)) > now()
    ), '[]'::jsonb)
  );
end;
$$;

-- Invitations ---------------------------------------------------------------------

create or replace function collaboration_invite(
  p_project uuid,
  p_invitee uuid,
  p_conversation uuid default null,
  p_created_via text default 'ui',
  p_assistant_conversation uuid default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  c collaboration_conversations;
  i collaboration_invitations;
begin
  if p_invitee is null or p_invitee = v_actor then
    raise exception 'Choose another Project member to invite' using errcode = 'EC001';
  end if;
  if not collaboration_has_access(p_project, v_actor) or not collaboration_has_access(p_project, p_invitee) then
    raise exception 'Both people must be active members of this Project' using errcode = 'EC001';
  end if;
  if p_created_via not in ('ui', 'assistant') then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  if p_assistant_conversation is not null
     and not exists (select 1 from conversations where id = p_assistant_conversation and user_id = v_actor) then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  if p_conversation is not null then
    select * into c from collaboration_conversations where id = p_conversation;
    if not found or c.project_id <> p_project or least(v_actor, p_invitee) <> c.user_a or greatest(v_actor, p_invitee) <> c.user_b then
      raise exception 'Collaboration access denied' using errcode = '42501';
    end if;
    if exists (select 1 from collaboration_sessions where conversation_id = c.id and status = 'active') then
      raise exception 'This conversation already has a live session' using errcode = 'EC001';
    end if;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_actor::text, 1955));
  perform collaboration_settle_user(v_actor);
  if collaboration_in_live_session(v_actor) then
    raise exception 'You are already in a live session -- leave or end it first' using errcode = 'EC001';
  end if;

  -- Re-sending the same invitation returns the pending one.
  select * into i from collaboration_invitations
    where inviter_id = v_actor and invitee_id = p_invitee and project_id = p_project
      and conversation_id is not distinct from p_conversation and status = 'pending' and expires_at > now()
    order by created_at desc limit 1;
  if found then
    return collaboration_invitation_dto(i);
  end if;
  -- Only one pending invitation from the caller at a time.
  update collaboration_invitations set status = 'cancelled', responded_at = now()
    where inviter_id = v_actor and status = 'pending';

  insert into collaboration_invitations(project_id, conversation_id, inviter_id, invitee_id, created_via, assistant_conversation_id, expires_at)
    values (p_project, p_conversation, v_actor, p_invitee, p_created_via, p_assistant_conversation, now() + collaboration_invitation_lifetime())
    returning * into i;
  insert into collaboration_events(invitation_id, conversation_id, actor_id, event)
    values (i.id, p_conversation, v_actor, 'invited');
  return collaboration_invitation_dto(i);
end;
$$;

create or replace function collaboration_cancel_invitation(p_invitation uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  i collaboration_invitations;
begin
  select * into i from collaboration_invitations where id = p_invitation for update;
  if not found or i.inviter_id <> v_actor then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  if i.status = 'pending' then
    update collaboration_invitations set status = 'cancelled', responded_at = now() where id = i.id returning * into i;
    insert into collaboration_events(invitation_id, actor_id, event) values (i.id, v_actor, 'invitation_cancelled');
  end if;
  return collaboration_invitation_dto(i);
end;
$$;

-- Accepting starts the live session with the inviter as host and
-- controller. p_connection joins the accepting tab straight away.
create or replace function collaboration_respond_invitation(p_invitation uuid, p_accept boolean, p_connection uuid default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  i collaboration_invitations;
  c collaboration_conversations;
  s collaboration_sessions;
begin
  select * into i from collaboration_invitations where id = p_invitation for update;
  if not found or i.invitee_id <> v_actor then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  if i.status = 'accepted' and p_accept and i.session_id is not null then
    -- A repeated accept (double click, retry) returns the same session.
    return jsonb_build_object('invitation', collaboration_invitation_dto(i), 'sessionId', i.session_id);
  end if;
  if i.status <> 'pending' or i.expires_at <= now() then
    raise exception 'This invitation is no longer available' using errcode = 'EC001';
  end if;
  if not p_accept then
    update collaboration_invitations set status = 'declined', responded_at = now() where id = i.id returning * into i;
    insert into collaboration_events(invitation_id, actor_id, event) values (i.id, v_actor, 'invitation_declined');
    return jsonb_build_object('invitation', collaboration_invitation_dto(i), 'sessionId', null);
  end if;

  if not collaboration_has_access(i.project_id, i.inviter_id) or not collaboration_has_access(i.project_id, v_actor) then
    raise exception 'Both people must be active members of this Project' using errcode = 'EC001';
  end if;
  -- Lock both people in a fixed order so two crossing accepts serialize.
  perform pg_advisory_xact_lock(hashtextextended(least(i.inviter_id, v_actor)::text, 1955));
  perform pg_advisory_xact_lock(hashtextextended(greatest(i.inviter_id, v_actor)::text, 1955));
  perform collaboration_settle_user(i.inviter_id);
  perform collaboration_settle_user(v_actor);
  if collaboration_in_live_session(v_actor) then
    raise exception 'You are already in a live session -- leave it first' using errcode = 'EC001';
  end if;
  if collaboration_in_live_session(i.inviter_id) then
    raise exception '% is already in another live session', collaboration_display_name(i.inviter_id) using errcode = 'EC001';
  end if;

  if i.conversation_id is not null then
    select * into c from collaboration_conversations where id = i.conversation_id for update;
    if exists (select 1 from collaboration_sessions where conversation_id = c.id and status = 'active') then
      raise exception 'This conversation already has a live session' using errcode = 'EC001';
    end if;
    update collaboration_conversations set last_activity_at = now() where id = c.id;
  else
    insert into collaboration_conversations(project_id, user_a, user_b, created_by)
      values (i.project_id, least(i.inviter_id, v_actor), greatest(i.inviter_id, v_actor), i.inviter_id)
      returning * into c;
  end if;

  insert into collaboration_sessions(conversation_id, project_id, host_id, guest_id, controller_id)
    values (c.id, i.project_id, i.inviter_id, v_actor, i.inviter_id)
    returning * into s;
  insert into collaboration_participants(session_id, user_id, role) values (s.id, i.inviter_id, 'host');
  insert into collaboration_participants(session_id, user_id, role, connection_id, last_seen_at, last_active_at, joined_at)
    values (s.id, v_actor, 'guest', p_connection, case when p_connection is null then null else now() end, now(),
            case when p_connection is null then null else now() end);
  -- Joining a session as one of the pair ends any watching elsewhere.
  update collaboration_watchers set stopped_at = now(), connection_id = null where user_id = v_actor and stopped_at is null;
  update collaboration_invitations set status = 'accepted', responded_at = now(), conversation_id = c.id, session_id = s.id
    where id = i.id returning * into i;
  insert into collaboration_events(invitation_id, session_id, conversation_id, actor_id, event, control_generation)
    values (i.id, s.id, c.id, v_actor, 'invitation_accepted', s.control_generation);
  return jsonb_build_object('invitation', collaboration_invitation_dto(i), 'sessionId', s.id);
end;
$$;

-- Viewers ---------------------------------------------------------------------------

-- Either of the pair adds another active member of the Project as a viewer
-- (at most 20). Re-adding a removed viewer reactivates them.
create or replace function collaboration_add_viewer(p_conversation uuid, p_user uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  c collaboration_conversations;
begin
  select * into c from collaboration_conversations where id = p_conversation for update;
  if not found or collaboration_conversation_role(c, v_actor) is distinct from 'participant' then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  if p_user is null or p_user in (c.user_a, c.user_b) then
    raise exception 'Choose someone other than the two of you' using errcode = 'EC001';
  end if;
  if not collaboration_has_access(c.project_id, p_user) then
    raise exception 'Viewers must be active members of this Project' using errcode = 'EC001';
  end if;
  if not exists (select 1 from collaboration_viewers where conversation_id = c.id and user_id = p_user and status = 'active') then
    if (select count(*) from collaboration_viewers where conversation_id = c.id and status = 'active') >= 20 then
      raise exception 'A conversation can have at most 20 viewers' using errcode = 'EC001';
    end if;
    insert into collaboration_viewers(conversation_id, user_id, added_by)
      values (c.id, p_user, v_actor)
      on conflict (conversation_id, user_id) do update
        set status = 'active', added_by = excluded.added_by, added_at = now(), removed_by = null, removed_at = null;
    insert into collaboration_events(conversation_id, actor_id, subject_id, event) values (c.id, v_actor, p_user, 'viewer_added');
  end if;
  return collaboration_viewers_json(c.id);
end;
$$;

-- Either of the pair removes a viewer, or a viewer removes themselves.
create or replace function collaboration_remove_viewer(p_conversation uuid, p_user uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  c collaboration_conversations;
begin
  select * into c from collaboration_conversations where id = p_conversation for update;
  if not found or (collaboration_conversation_role(c, v_actor) is distinct from 'participant' and v_actor is distinct from p_user) then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  update collaboration_viewers set status = 'removed', removed_by = v_actor, removed_at = now()
    where conversation_id = c.id and user_id = p_user and status = 'active';
  if found then
    insert into collaboration_events(conversation_id, actor_id, subject_id, event) values (c.id, v_actor, p_user, 'viewer_removed');
  end if;
  return collaboration_viewers_json(c.id);
end;
$$;

-- Watching --------------------------------------------------------------------------

-- What a watcher's tab sees: where the session is and who is in it.
-- Ended or overdue reads as ended (watchers never settle a session).
create or replace function collaboration_watch_snapshot(p_session uuid, p_actor uuid, p_connection uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s collaboration_sessions;
  h collaboration_participants;
  g collaboration_participants;
  w collaboration_watchers;
  d record;
  v_workstream_name text;
begin
  select * into s from collaboration_sessions where id = p_session;
  select * into h from collaboration_participants where session_id = s.id and user_id = s.host_id;
  select * into g from collaboration_participants where session_id = s.id and user_id = s.guest_id;
  select * into w from collaboration_watchers where session_id = s.id and user_id = p_actor;
  select * into d from collaboration_deadline(s.id);
  if s.location_workstream_id is not null then
    select name into v_workstream_name from project_workstreams where id = s.location_workstream_id;
  end if;
  return jsonb_build_object(
    'id', s.id,
    'conversationId', s.conversation_id,
    'projectId', s.project_id,
    'projectName', (select name from projects where id = s.project_id),
    'status', case when s.status = 'active' and d.ends_at <= now() then 'ended' else s.status end,
    'endReason', case when s.status = 'active' and d.ends_at <= now() then d.reason else s.end_reason end,
    'host', jsonb_build_object('id', s.host_id, 'name', collaboration_display_name(s.host_id),
      'present', coalesce(collaboration_is_present(h), false), 'away', collaboration_is_away(h, s.started_at), 'left', h.left_at is not null),
    'guest', jsonb_build_object('id', s.guest_id, 'name', collaboration_display_name(s.guest_id),
      'present', coalesce(collaboration_is_present(g), false), 'away', collaboration_is_away(g, s.started_at), 'left', g.left_at is not null),
    'controllerId', s.controller_id,
    'stateRevision', s.state_revision,
    'location', jsonb_build_object('workstreamId', s.location_workstream_id, 'workstreamName', v_workstream_name),
    -- This tab is the caller's watching tab.
    'thisTabWatching', coalesce(p_connection is not null and w.connection_id = p_connection and w.stopped_at is null, false)
  );
end;
$$;
revoke all on function collaboration_watch_snapshot(uuid, uuid, uuid) from public, anon, authenticated;

-- A viewer starts watching a live session in this tab (a later tab takes
-- over from an earlier one). At most 10 people watch at once.
create or replace function collaboration_watch(p_session uuid, p_connection uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
  c collaboration_conversations;
begin
  select * into s from collaboration_sessions where id = p_session;
  if not found or p_connection is null then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  select * into c from collaboration_conversations where id = s.conversation_id;
  if collaboration_conversation_role(c, v_actor) is distinct from 'viewer' then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  if s.status <> 'active' or (select ends_at from collaboration_deadline(s.id)) <= now() then
    raise exception 'This live session has ended' using errcode = 'EC001';
  end if;
  if collaboration_in_live_session(v_actor) then
    raise exception 'You are in a live session yourself -- leave it to watch this one' using errcode = 'EC001';
  end if;
  -- Serializes the watcher limit per session without locking the session row.
  perform pg_advisory_xact_lock(hashtextextended(s.id::text, 2024));
  if not exists (select 1 from collaboration_watchers where session_id = s.id and user_id = v_actor and stopped_at is null)
     and jsonb_array_length(collaboration_watching_json(s.id)) >= 10 then
    raise exception 'Ten people are already watching this session' using errcode = 'EC001';
  end if;
  -- Watching one session at a time.
  update collaboration_watchers set stopped_at = now(), connection_id = null
    where user_id = v_actor and session_id <> s.id and stopped_at is null;
  insert into collaboration_watchers(session_id, user_id, connection_id, last_seen_at)
    values (s.id, v_actor, p_connection, now())
    on conflict (session_id, user_id) do update
      set connection_id = excluded.connection_id, last_seen_at = now(), stopped_at = null,
          started_at = case when collaboration_watchers.stopped_at is null then collaboration_watchers.started_at else now() end;
  insert into collaboration_events(session_id, conversation_id, actor_id, event) values (s.id, c.id, v_actor, 'watching_started');
  return collaboration_watch_snapshot(s.id, v_actor, p_connection);
end;
$$;

-- A watcher's poll: records this tab's presence and returns where the
-- session is. Rechecks that the caller is still a viewer with access.
create or replace function collaboration_watch_status(p_session uuid, p_connection uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
  c collaboration_conversations;
begin
  select * into s from collaboration_sessions where id = p_session;
  if not found then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  select * into c from collaboration_conversations where id = s.conversation_id;
  if collaboration_conversation_role(c, v_actor) is distinct from 'viewer' then
    update collaboration_watchers set stopped_at = now(), connection_id = null where session_id = s.id and user_id = v_actor and stopped_at is null;
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  update collaboration_watchers set last_seen_at = now()
    where session_id = s.id and user_id = v_actor and connection_id = p_connection and stopped_at is null;
  return collaboration_watch_snapshot(s.id, v_actor, p_connection);
end;
$$;

-- Stop watching (the button, or the tab closing). Quiet if not watching.
create or replace function collaboration_stop_watching(p_session uuid, p_connection uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
begin
  update collaboration_watchers set stopped_at = now(), connection_id = null
    where session_id = p_session and user_id = v_actor and connection_id = p_connection and stopped_at is null;
  if found then
    insert into collaboration_events(session_id, actor_id, event) values (p_session, v_actor, 'watching_stopped');
  end if;
end;
$$;

-- Session commands ----------------------------------------------------------------

-- Makes this tab the caller's tab in the session. If another of the
-- caller's tabs is present, refuses unless p_take_over -- two tabs of one
-- account never act as two controllers. A new tab for the controller
-- bumps the control generation, so the old tab's commands fail.
create or replace function collaboration_join(p_session uuid, p_connection uuid, p_take_over boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
  me collaboration_participants;
begin
  if p_connection is null then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  s := collaboration_lock(p_session, null, v_actor);
  select * into me from collaboration_participants where session_id = s.id and user_id = v_actor for update;
  if me.connection_id is distinct from p_connection and coalesce(collaboration_is_present(me), false) and not p_take_over then
    raise exception 'This live session is open in another of your tabs' using errcode = 'EC002';
  end if;
  if me.left_at is not null and exists (
    select 1 from collaboration_sessions o join collaboration_participants op on op.session_id = o.id
    where op.user_id = v_actor and o.status = 'active' and op.left_at is null and o.id <> s.id
  ) then
    raise exception 'You are in another live session -- leave it first' using errcode = 'EC001';
  end if;
  if me.connection_id is distinct from p_connection or me.left_at is not null then
    if s.controller_id = v_actor and me.connection_id is distinct from p_connection then
      update collaboration_sessions set control_generation = control_generation + 1 where id = s.id;
    end if;
    update collaboration_sessions set state_revision = state_revision + 1 where id = s.id returning * into s;
    perform collaboration_log(s, v_actor, case when me.joined_at is null then 'joined' else 'rejoined' end);
  end if;
  update collaboration_participants
    set connection_id = p_connection, last_seen_at = now(), last_active_at = now(), joined_at = coalesce(joined_at, now()), left_at = null
    where session_id = s.id and user_id = v_actor;
  return collaboration_snapshot(s.id, v_actor, p_connection);
end;
$$;

-- The controller moves both browsers: null = the Project page, or one of
-- its workstreams. p_generation is the control generation the tab last saw.
create or replace function collaboration_navigate(p_session uuid, p_connection uuid, p_generation integer, p_workstream uuid default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
begin
  s := collaboration_lock(p_session, p_connection, v_actor);
  if s.controller_id <> v_actor then
    raise exception 'Ask for control before moving the shared view' using errcode = 'EC001';
  end if;
  if p_generation is distinct from s.control_generation then
    raise exception 'Control changed -- the shared view was not moved' using errcode = 'EC003';
  end if;
  if p_workstream is not null and not exists (select 1 from project_workstreams where id = p_workstream and project_id = s.project_id) then
    raise exception 'That workstream is not in this Project' using errcode = 'EC001';
  end if;
  if s.location_workstream_id is distinct from p_workstream then
    update collaboration_sessions set location_workstream_id = p_workstream, state_revision = state_revision + 1 where id = s.id;
  end if;
  return collaboration_snapshot(s.id, v_actor, p_connection);
end;
$$;

create or replace function collaboration_request_control(p_session uuid, p_connection uuid, p_withdraw boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
begin
  s := collaboration_lock(p_session, p_connection, v_actor);
  if p_withdraw then
    if s.control_requested_by = v_actor then
      update collaboration_sessions set control_requested_by = null, control_requested_at = null, state_revision = state_revision + 1
        where id = s.id returning * into s;
      perform collaboration_log(s, v_actor, 'control_request_withdrawn');
    end if;
  else
    if s.controller_id = v_actor then
      raise exception 'You already have control' using errcode = 'EC001';
    end if;
    if s.control_requested_by is distinct from v_actor then
      update collaboration_sessions set control_requested_by = v_actor, control_requested_at = now(), state_revision = state_revision + 1
        where id = s.id returning * into s;
      perform collaboration_log(s, v_actor, 'control_requested');
    end if;
  end if;
  return collaboration_snapshot(s.id, v_actor, p_connection);
end;
$$;

-- The controller grants or declines the pending request. Granting needs
-- the requester present, so control never lands on an absent person.
create or replace function collaboration_answer_control_request(p_session uuid, p_connection uuid, p_generation integer, p_grant boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
  r collaboration_participants;
begin
  s := collaboration_lock(p_session, p_connection, v_actor);
  if s.controller_id <> v_actor then
    raise exception 'Only the person in control can answer a request' using errcode = 'EC001';
  end if;
  if p_generation is distinct from s.control_generation then
    raise exception 'Control changed -- refresh and try again' using errcode = 'EC003';
  end if;
  if s.control_requested_by is null then
    raise exception 'There is no request for control to answer' using errcode = 'EC003';
  end if;
  if p_grant then
    select * into r from collaboration_participants where session_id = s.id and user_id = s.control_requested_by;
    if not coalesce(collaboration_is_present(r), false) or collaboration_is_away(r, s.started_at) then
      raise exception '% is not connected or is away right now', collaboration_display_name(r.user_id) using errcode = 'EC001';
    end if;
    update collaboration_sessions
      set controller_id = control_requested_by, control_requested_by = null, control_requested_at = null,
          control_generation = control_generation + 1, state_revision = state_revision + 1
      where id = s.id returning * into s;
    perform collaboration_log(s, v_actor, 'control_granted');
  else
    update collaboration_sessions set control_requested_by = null, control_requested_at = null, state_revision = state_revision + 1
      where id = s.id returning * into s;
    perform collaboration_log(s, v_actor, 'control_request_declined');
  end if;
  return collaboration_snapshot(s.id, v_actor, p_connection);
end;
$$;

-- The host takes control back at any time; visible and recorded.
create or replace function collaboration_reclaim_control(p_session uuid, p_connection uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
begin
  s := collaboration_lock(p_session, p_connection, v_actor);
  if s.host_id <> v_actor then
    raise exception 'Only the host can take control back' using errcode = 'EC001';
  end if;
  if s.controller_id <> v_actor then
    update collaboration_sessions
      set controller_id = v_actor, control_requested_by = null, control_requested_at = null,
          control_generation = control_generation + 1, state_revision = state_revision + 1
      where id = s.id returning * into s;
    perform collaboration_log(s, v_actor, 'control_reclaimed');
  end if;
  return collaboration_snapshot(s.id, v_actor, p_connection);
end;
$$;

-- Someone not in control takes it while the controller is away or not
-- connected, so one person stepping away can't strand the other. Explicit
-- and recorded; the host can still take control back at any time.
create or replace function collaboration_take_control(p_session uuid, p_connection uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
  ctl collaboration_participants;
begin
  s := collaboration_lock(p_session, p_connection, v_actor);
  if s.controller_id = v_actor then
    raise exception 'You already have control' using errcode = 'EC001';
  end if;
  select * into ctl from collaboration_participants where session_id = s.id and user_id = s.controller_id;
  if not collaboration_is_away(ctl, s.started_at) and coalesce(collaboration_is_present(ctl), false) then
    raise exception '% is active -- ask for control instead', collaboration_display_name(s.controller_id) using errcode = 'EC003';
  end if;
  update collaboration_sessions
    set controller_id = v_actor, control_requested_by = null, control_requested_at = null,
        control_generation = control_generation + 1, state_revision = state_revision + 1
    where id = s.id returning * into s;
  perform collaboration_log(s, v_actor, 'control_taken_while_away');
  return collaboration_snapshot(s.id, v_actor, p_connection);
end;
$$;

-- A tab closing (or the page unloading) says so, so the other person sees
-- "not connected" straight away rather than after the presence window.
-- Only clears presence -- control, and whether the person is in the
-- session, are unchanged; reloading rejoins as the same tab.
create or replace function collaboration_disconnect(p_session uuid, p_connection uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
begin
  update collaboration_participants p set last_seen_at = null
    from collaboration_sessions s
    where p.session_id = p_session and p.user_id = v_actor and p.connection_id = p_connection
      and s.id = p.session_id and s.status = 'active';
end;
$$;

-- Leaving is explicit (closing a tab is a disconnect, not a leave). If the
-- leaver had control and the other person is still in the session, control
-- passes to them -- recorded, never silent. When nobody is left, the
-- session ends. Works from any of the caller's tabs.
create or replace function collaboration_leave(p_session uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
  v_other uuid;
  other collaboration_participants;
begin
  s := collaboration_lock(p_session, null, v_actor);
  v_other := case when v_actor = s.host_id then s.guest_id else s.host_id end;
  select * into other from collaboration_participants where session_id = s.id and user_id = v_other;
  update collaboration_participants set left_at = now(), connection_id = null where session_id = s.id and user_id = v_actor;
  update collaboration_sessions
    set control_requested_by = case when control_requested_by = v_actor then null else control_requested_by end,
        control_requested_at = case when control_requested_by = v_actor then null else control_requested_at end,
        state_revision = state_revision + 1
    where id = s.id returning * into s;
  perform collaboration_log(s, v_actor, 'left');
  if other.left_at is not null then
    perform collaboration_end_session(s.id, 'everyone_left', v_actor);
  elsif s.controller_id = v_actor then
    update collaboration_sessions
      set controller_id = v_other, control_requested_by = null, control_requested_at = null,
          control_generation = control_generation + 1, state_revision = state_revision + 1
      where id = s.id returning * into s;
    perform collaboration_log(s, v_actor, 'control_passed_on_leave');
  end if;
  return collaboration_snapshot(s.id, v_actor, null);
end;
$$;

-- Only the host ends the session. The conversation stays in both histories.
create or replace function collaboration_end(p_session uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
begin
  s := collaboration_lock(p_session, null, v_actor);
  if s.host_id <> v_actor then
    raise exception 'Only the host can end the session' using errcode = 'EC001';
  end if;
  perform collaboration_end_session(s.id, 'ended_by_host', v_actor);
  return collaboration_snapshot(s.id, v_actor, null);
end;
$$;

