-- ==== supabase/migrations/20261024100001_collaboration_shared_editing.sql ====
-- Shared workspace sessions, Phase 2: shared editing on the Project and
-- Workstream pages (docs/dev-request-shared-workspace-sessions.md).
--
-- In a live session, the person in control edits the Project's goal,
-- description (objective) and starter prompt, and a Workstream's summary,
-- as shared drafts the other browser (and any watcher) sees as they type;
-- Save is explicit. Deliverable checkboxes save at once, as set-to-value
-- operations so a retry can't flip one back.
--
-- Authority stays in the database: every draft write and save locks the
-- session row and checks the caller's tab, that they're in control, the
-- control generation, that the field is on the page being shared, and
-- that their own account may edit that field (the same rules as the
-- ordinary forms: goal -- the Project's owner or a platform admin; the
-- rest -- owner, curator or platform admin). Control never borrows anyone
-- else's rights.
--
-- Conflicts: a draft remembers the saved text it started from. Saving
-- succeeds only if the field still holds that text; if someone changed it
-- outside the session meanwhile, the save is refused (EC004) and the
-- person chooses what to do. Saves carry a request id, so a retry returns
-- the first result instead of saving twice. No existing table is altered.
--
-- Nothing here deletes a row: drafts end as saved, discarded or abandoned
-- (when their session ends). Safe to re-run. Requires 20261023100001.

create table if not exists collaboration_drafts (
  session_id uuid not null references collaboration_sessions(id) on delete cascade,
  field text not null check (field in ('project_goal', 'project_objective', 'project_starter_prompt', 'workstream_summary')),
  -- The Project for project_* fields, the workstream for workstream_*.
  target_id uuid not null,
  value text not null default '' check (length(value) <= 20000),
  -- The saved text when the draft was opened (null = the field was empty).
  base_value text,
  editor_id uuid references profiles(id) on delete set null,
  revision integer not null default 1,
  status text not null default 'open' check (status in ('open', 'saved', 'discarded', 'abandoned')),
  opened_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (session_id, field, target_id)
);

-- One row per save request (text fields and checkboxes): makes a retried
-- save return its first result, and records who saved what, when.
create table if not exists collaboration_saves (
  request_id uuid primary key,
  session_id uuid not null references collaboration_sessions(id) on delete cascade,
  actor_id uuid references profiles(id) on delete set null,
  field text not null,
  target_id uuid not null,
  item_index integer,
  created_at timestamptz not null default now()
);

create index if not exists collaboration_saves_session_idx on collaboration_saves(session_id, created_at);

alter table collaboration_drafts enable row level security;
alter table collaboration_saves enable row level security;
revoke all on collaboration_drafts, collaboration_saves from anon, authenticated;

-- Field helpers -------------------------------------------------------------------

-- Who may edit a shared field: the same bar as the ordinary forms.
create or replace function collaboration_can_edit_field(p_project uuid, p_field text, p_user uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select case
    when p_user is null then false
    when p_field = 'project_goal' then can_manage_project(p_project, p_user)
    when p_field in ('project_objective', 'project_starter_prompt', 'workstream_summary', 'workstream_deliverables') then can_curate_project(p_project, p_user)
    else false
  end;
$$;

-- The saved text of a field right now.
create or replace function collaboration_field_value(p_field text, p_target uuid)
returns text
language sql stable security definer set search_path = public as $$
  select case p_field
    when 'project_goal' then (select goal from projects where id = p_target)
    when 'project_objective' then (select objective from projects where id = p_target)
    when 'project_starter_prompt' then (select starter_prompt from projects where id = p_target)
    when 'workstream_summary' then (select summary from project_workstreams where id = p_target)
  end;
$$;

-- The field's target must be what the session is showing: the Project's
-- own fields on the Project page, a workstream's on that workstream's page.
create or replace function collaboration_check_target(s collaboration_sessions, p_field text, p_target uuid)
returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if p_field like 'project\_%' then
    if p_target is distinct from s.project_id or s.location_workstream_id is not null then
      raise exception 'That field isn''t on the page being shared' using errcode = 'EC003';
    end if;
  elsif p_field like 'workstream\_%' then
    if p_target is distinct from s.location_workstream_id then
      raise exception 'That field isn''t on the page being shared' using errcode = 'EC003';
    end if;
  else
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
end;
$$;

-- Locks the session for an edit: the caller's current tab, in control, on
-- the generation they last saw, editing a field on the shared page that
-- their own account may edit.
create or replace function collaboration_lock_for_edit(p_session uuid, p_connection uuid, p_generation integer, p_field text, p_target uuid, p_actor uuid)
returns collaboration_sessions
language plpgsql security definer set search_path = public as $$
declare
  s collaboration_sessions;
begin
  if p_connection is null then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  s := collaboration_lock(p_session, p_connection, p_actor);
  if s.controller_id <> p_actor then
    raise exception 'Ask for control before editing' using errcode = 'EC001';
  end if;
  if p_generation is distinct from s.control_generation then
    raise exception 'Control changed -- nothing was changed' using errcode = 'EC003';
  end if;
  perform collaboration_check_target(s, p_field, p_target);
  if not collaboration_can_edit_field(s.project_id, p_field, p_actor) then
    raise exception 'Your account can''t edit this field' using errcode = 'EC001';
  end if;
  return s;
end;
$$;

-- The shared fields on the page the session is showing: saved value,
-- open draft (if any), and whether p_actor may edit (null actor: a
-- watcher, never). Called from the snapshots.
create or replace function collaboration_fields_json(p_session uuid, p_actor uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s collaboration_sessions;
  v_fields text[];
  v_target uuid;
  v_out jsonb := '[]'::jsonb;
  v_field text;
  v_saved text;
  dr collaboration_drafts;
begin
  select * into s from collaboration_sessions where id = p_session;
  if s.location_workstream_id is null then
    v_fields := array['project_goal', 'project_objective', 'project_starter_prompt'];
    v_target := s.project_id;
  else
    v_fields := array['workstream_summary'];
    v_target := s.location_workstream_id;
  end if;
  foreach v_field in array v_fields loop
    v_saved := collaboration_field_value(v_field, v_target);
    select * into dr from collaboration_drafts where session_id = s.id and field = v_field and target_id = v_target and status = 'open';
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'field', v_field,
      'targetId', v_target,
      'saved', v_saved,
      'canEdit', collaboration_can_edit_field(s.project_id, v_field, p_actor),
      'draft', case when dr.session_id is null then null else jsonb_build_object(
        'value', dr.value,
        'revision', dr.revision,
        'editorId', dr.editor_id,
        'editorName', collaboration_display_name(dr.editor_id),
        'updatedAt', dr.updated_at,
        -- The field was changed outside the session since this draft opened.
        'baseChanged', v_saved is distinct from dr.base_value
      ) end
    ));
  end loop;
  if s.location_workstream_id is not null then
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'field', 'workstream_deliverables',
      'targetId', v_target,
      'deliverables', (select deliverables from project_workstreams where id = v_target),
      'canEdit', collaboration_can_edit_field(s.project_id, 'workstream_deliverables', p_actor)
    ));
  end if;
  return v_out;
end;
$$;

-- Every unsaved draft in the session, wherever it is.
create or replace function collaboration_open_drafts_json(p_session uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'field', d.field, 'targetId', d.target_id,
    'workstreamName', case when d.field like 'workstream\_%' then (select name from project_workstreams where id = d.target_id) end,
    'editorName', collaboration_display_name(d.editor_id)
  ) order by d.opened_at), '[]'::jsonb)
  from collaboration_drafts d where d.session_id = p_session and d.status = 'open';
$$;

revoke all on function collaboration_can_edit_field(uuid, text, uuid) from public, anon, authenticated;
revoke all on function collaboration_field_value(text, uuid) from public, anon, authenticated;
revoke all on function collaboration_check_target(collaboration_sessions, text, uuid) from public, anon, authenticated;
revoke all on function collaboration_lock_for_edit(uuid, uuid, integer, text, uuid, uuid) from public, anon, authenticated;
revoke all on function collaboration_fields_json(uuid, uuid) from public, anon, authenticated;
revoke all on function collaboration_open_drafts_json(uuid) from public, anon, authenticated;

-- Snapshots and ending, extended (otherwise as in 20261023100001) ---------------------

create or replace function collaboration_snapshot(p_session uuid, p_actor uuid, p_connection uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s collaboration_sessions;
  h collaboration_participants;
  g collaboration_participants;
  me collaboration_participants;
  ctl collaboration_participants;
  v_workstream_name text;
  d record;
begin
  select * into s from collaboration_sessions where id = p_session;
  select * into h from collaboration_participants where session_id = s.id and user_id = s.host_id;
  select * into g from collaboration_participants where session_id = s.id and user_id = s.guest_id;
  me := case when p_actor = s.host_id then h else g end;
  ctl := case when s.controller_id = s.host_id then h else g end;
  select * into d from collaboration_deadline(s.id);
  if s.location_workstream_id is not null then
    select name into v_workstream_name from project_workstreams where id = s.location_workstream_id;
  end if;
  return jsonb_build_object(
    'id', s.id,
    'conversationId', s.conversation_id,
    'projectId', s.project_id,
    'projectName', (select name from projects where id = s.project_id),
    'status', s.status,
    'endReason', s.end_reason,
    'myRole', case when p_actor = s.host_id then 'host' else 'guest' end,
    'host', jsonb_build_object('id', s.host_id, 'name', collaboration_display_name(s.host_id),
      'present', coalesce(collaboration_is_present(h), false), 'left', h.left_at is not null,
      'away', collaboration_is_away(h, s.started_at),
      'inactiveSeconds', floor(extract(epoch from now() - collaboration_last_active(h, s.started_at)))::int),
    'guest', jsonb_build_object('id', s.guest_id, 'name', collaboration_display_name(s.guest_id),
      'present', coalesce(collaboration_is_present(g), false), 'left', g.left_at is not null,
      'away', collaboration_is_away(g, s.started_at),
      'inactiveSeconds', floor(extract(epoch from now() - collaboration_last_active(g, s.started_at)))::int),
    'controllerId', s.controller_id,
    'controlGeneration', s.control_generation,
    'stateRevision', s.state_revision,
    'controlRequestedBy', s.control_requested_by,
    'location', jsonb_build_object('workstreamId', s.location_workstream_id, 'workstreamName', v_workstream_name),
    -- This tab is the caller's current tab (and still present).
    'thisTabJoined', coalesce(p_connection is not null and me.connection_id = p_connection and collaboration_is_present(me), false),
    -- The caller is present from some other tab.
    'otherTabActive', me.connection_id is distinct from p_connection and coalesce(collaboration_is_present(me), false),
    'iLeft', me.left_at is not null,
    'viewers', collaboration_viewers_json(s.conversation_id),
    'watching', collaboration_watching_json(s.id),
    -- Phase 2: the shared fields where the session is, and every unsaved
    -- draft in the session (for the bar and the end/leave warnings).
    'fields', collaboration_fields_json(s.id, p_actor),
    'openDrafts', collaboration_open_drafts_json(s.id),
    -- Seconds until the session ends on its own, and which rule ends it.
    'endsInSeconds', case when s.status = 'active' then greatest(0, floor(extract(epoch from d.ends_at - now())))::int end,
    'endingReason', case when s.status = 'active' then d.reason end,
    -- Someone not in control may take it while the controller is away or
    -- not connected (the host can always take it back).
    'canTakeControl', s.status = 'active' and s.controller_id <> p_actor
      and (collaboration_is_away(ctl, s.started_at) or not coalesce(collaboration_is_present(ctl), false))
  );
end;
$$;

create or replace function collaboration_watch_snapshot(p_session uuid, p_actor uuid, p_connection uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s collaboration_sessions;
  h collaboration_participants;
  g collaboration_participants;
  w collaboration_watchers;
  d record;
  v_workstream_name text;
begin
  select * into s from collaboration_sessions where id = p_session;
  select * into h from collaboration_participants where session_id = s.id and user_id = s.host_id;
  select * into g from collaboration_participants where session_id = s.id and user_id = s.guest_id;
  select * into w from collaboration_watchers where session_id = s.id and user_id = p_actor;
  select * into d from collaboration_deadline(s.id);
  if s.location_workstream_id is not null then
    select name into v_workstream_name from project_workstreams where id = s.location_workstream_id;
  end if;
  return jsonb_build_object(
    'id', s.id,
    'conversationId', s.conversation_id,
    'projectId', s.project_id,
    'projectName', (select name from projects where id = s.project_id),
    'status', case when s.status = 'active' and d.ends_at <= now() then 'ended' else s.status end,
    'endReason', case when s.status = 'active' and d.ends_at <= now() then d.reason else s.end_reason end,
    'host', jsonb_build_object('id', s.host_id, 'name', collaboration_display_name(s.host_id),
      'present', coalesce(collaboration_is_present(h), false), 'away', collaboration_is_away(h, s.started_at), 'left', h.left_at is not null),
    'guest', jsonb_build_object('id', s.guest_id, 'name', collaboration_display_name(s.guest_id),
      'present', coalesce(collaboration_is_present(g), false), 'away', collaboration_is_away(g, s.started_at), 'left', g.left_at is not null),
    'controllerId', s.controller_id,
    'stateRevision', s.state_revision,
    'location', jsonb_build_object('workstreamId', s.location_workstream_id, 'workstreamName', v_workstream_name),
    -- Watchers see the shared fields and drafts too, with no edit rights.
    'fields', collaboration_fields_json(s.id, null),
    -- This tab is the caller's watching tab.
    'thisTabWatching', coalesce(p_connection is not null and w.connection_id = p_connection and w.stopped_at is null, false)
  );
end;
$$;

create or replace function collaboration_end_session(p_session uuid, p_reason text, p_actor uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  update collaboration_sessions
    set status = 'ended', end_reason = p_reason, ended_by = p_actor, ended_at = now(),
        control_requested_by = null, control_requested_at = null,
        control_generation = control_generation + 1, state_revision = state_revision + 1
    where id = p_session and status = 'active';
  if found then
    -- Unsaved drafts end with the session: kept, marked abandoned, never saved.
    update collaboration_drafts set status = 'abandoned', updated_at = now() where session_id = p_session and status = 'open';
    update collaboration_conversations set last_activity_at = now()
      where id = (select conversation_id from collaboration_sessions where id = p_session);
    insert into collaboration_events(session_id, actor_id, event, control_generation)
      select id, p_actor, 'ended:' || p_reason, control_generation from collaboration_sessions where id = p_session;
  end if;
end;
$$;

-- Shared editing --------------------------------------------------------------------

-- The controller's latest text for a field (sent as they type). Opening a
-- draft records the field's saved text as its base; p_rebase moves the
-- base to the current saved text (the person chose to keep their draft
-- after a change outside the session).
create or replace function collaboration_set_draft(
  p_session uuid, p_connection uuid, p_generation integer, p_field text, p_target uuid, p_value text, p_rebase boolean default false
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
begin
  s := collaboration_lock_for_edit(p_session, p_connection, p_generation, p_field, p_target, v_actor);
  if p_value is null or length(p_value) > 20000 then
    raise exception 'That text is too long (20,000 characters at most)' using errcode = 'EC001';
  end if;
  insert into collaboration_drafts as d (session_id, field, target_id, value, base_value, editor_id)
    values (s.id, p_field, p_target, p_value, collaboration_field_value(p_field, p_target), v_actor)
    on conflict (session_id, field, target_id) do update
      set value = excluded.value,
          -- A draft reopened after it was saved or discarded starts again
          -- from the current saved text.
          base_value = case when d.status <> 'open' or p_rebase then excluded.base_value else d.base_value end,
          opened_at = case when d.status <> 'open' then now() else d.opened_at end,
          editor_id = excluded.editor_id,
          revision = d.revision + 1,
          status = 'open',
          updated_at = now();
  update collaboration_sessions set state_revision = state_revision + 1 where id = s.id;
  return collaboration_snapshot(s.id, v_actor, p_connection);
end;
$$;

-- The controller drops a draft (Cancel). The saved text is unchanged.
create or replace function collaboration_discard_draft(p_session uuid, p_connection uuid, p_generation integer, p_field text, p_target uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
begin
  s := collaboration_lock_for_edit(p_session, p_connection, p_generation, p_field, p_target, v_actor);
  update collaboration_drafts set status = 'discarded', editor_id = v_actor, updated_at = now()
    where session_id = s.id and field = p_field and target_id = p_target and status = 'open';
  if found then
    update collaboration_sessions set state_revision = state_revision + 1 where id = s.id;
  end if;
  return collaboration_snapshot(s.id, v_actor, p_connection);
end;
$$;

-- Saves the open draft to the Project or workstream -- in the same
-- transaction as the control checks, so a handover can't slip between
-- them. Refused (EC004) if the field changed since the draft opened.
-- Text is trimmed and an empty field saved as empty, as the forms do.
create or replace function collaboration_save_field(
  p_session uuid, p_connection uuid, p_generation integer, p_field text, p_target uuid, p_request uuid
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
  dr collaboration_drafts;
  v_new text;
begin
  if p_request is null then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  -- A retried save returns the session as it is; it never saves twice.
  if exists (select 1 from collaboration_saves where request_id = p_request and session_id = p_session and actor_id = v_actor) then
    return collaboration_snapshot(p_session, v_actor, p_connection);
  end if;
  s := collaboration_lock_for_edit(p_session, p_connection, p_generation, p_field, p_target, v_actor);
  -- Checked again under the lock: the same request sent twice at once.
  if exists (select 1 from collaboration_saves where request_id = p_request) then
    return collaboration_snapshot(s.id, v_actor, p_connection);
  end if;
  select * into dr from collaboration_drafts where session_id = s.id and field = p_field and target_id = p_target and status = 'open' for update;
  if not found then
    raise exception 'There''s no unsaved draft for that field' using errcode = 'EC003';
  end if;
  if collaboration_field_value(p_field, p_target) is distinct from dr.base_value then
    raise exception 'This was changed outside the session since editing began -- review the saved text before saving' using errcode = 'EC004';
  end if;
  v_new := nullif(trim(dr.value), '');
  if p_field = 'project_goal' then
    update projects set goal = v_new where id = p_target;
  elsif p_field = 'project_objective' then
    update projects set objective = v_new where id = p_target;
  elsif p_field = 'project_starter_prompt' then
    update projects set starter_prompt = v_new where id = p_target;
  elsif p_field = 'workstream_summary' then
    update project_workstreams set summary = v_new where id = p_target;
  end if;
  update collaboration_drafts set status = 'saved', editor_id = v_actor, updated_at = now()
    where session_id = s.id and field = p_field and target_id = p_target;
  insert into collaboration_saves(request_id, session_id, actor_id, field, target_id) values (p_request, s.id, v_actor, p_field, p_target);
  update collaboration_sessions set state_revision = state_revision + 1 where id = s.id returning * into s;
  perform collaboration_log(s, v_actor, 'saved:' || p_field);
  return collaboration_snapshot(s.id, v_actor, p_connection);
end;
$$;

-- Sets one deliverable's checkbox to a value (not a toggle, so a retry
-- can't flip it back). p_label is the item's text as the caller saw it;
-- if the list changed underneath (reordered or renamed), it's refused.
create or replace function collaboration_set_deliverable(
  p_session uuid, p_connection uuid, p_generation integer, p_workstream uuid,
  p_index integer, p_label text, p_completed boolean, p_request uuid
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
  v_items jsonb;
begin
  if p_request is null or p_index is null or p_completed is null then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  if exists (select 1 from collaboration_saves where request_id = p_request and session_id = p_session and actor_id = v_actor) then
    return collaboration_snapshot(p_session, v_actor, p_connection);
  end if;
  s := collaboration_lock_for_edit(p_session, p_connection, p_generation, 'workstream_deliverables', p_workstream, v_actor);
  if exists (select 1 from collaboration_saves where request_id = p_request) then
    return collaboration_snapshot(s.id, v_actor, p_connection);
  end if;
  select deliverables into v_items from project_workstreams where id = p_workstream for update;
  if p_index < 0 or p_index >= jsonb_array_length(v_items) or (v_items -> p_index ->> 'label') is distinct from p_label then
    raise exception 'The deliverables changed -- refresh and try again' using errcode = 'EC004';
  end if;
  if (v_items -> p_index ->> 'completed')::boolean is distinct from p_completed then
    update project_workstreams
      set deliverables = jsonb_set(v_items, array[p_index::text, 'completed'], to_jsonb(p_completed))
      where id = p_workstream;
    update collaboration_sessions set state_revision = state_revision + 1 where id = s.id returning * into s;
    perform collaboration_log(s, v_actor, 'saved:workstream_deliverables');
  end if;
  insert into collaboration_saves(request_id, session_id, actor_id, field, target_id, item_index)
    values (p_request, s.id, v_actor, 'workstream_deliverables', p_workstream, p_index);
  return collaboration_snapshot(s.id, v_actor, p_connection);
end;
$$;

revoke all on function collaboration_set_draft(uuid, uuid, integer, text, uuid, text, boolean) from public, anon;
revoke all on function collaboration_discard_draft(uuid, uuid, integer, text, uuid) from public, anon;
revoke all on function collaboration_save_field(uuid, uuid, integer, text, uuid, uuid) from public, anon;
revoke all on function collaboration_set_deliverable(uuid, uuid, integer, uuid, integer, text, boolean, uuid) from public, anon;
grant execute on function collaboration_set_draft(uuid, uuid, integer, text, uuid, text, boolean) to authenticated;
grant execute on function collaboration_discard_draft(uuid, uuid, integer, text, uuid) to authenticated;
grant execute on function collaboration_save_field(uuid, uuid, integer, text, uuid, uuid) to authenticated;
grant execute on function collaboration_set_deliverable(uuid, uuid, integer, uuid, integer, text, boolean, uuid) to authenticated;

-- External MCP read-only guarantee (20261005100001_external_mcp_access.sql),
-- guarded so this migration also applies before that one has run.
do $$
begin
  if to_regprocedure('public.apply_oauth_read_only_policies()') is not null then
    perform apply_oauth_read_only_policies();
  end if;
end;
$$;


-- ==== supabase/migrations/20261025100001_collaboration_shared_chat.sql ====
-- Shared workspace sessions, Phase 3: shared Ember chat
-- (docs/dev-request-shared-workspace-sessions.md).
--
-- A shared conversation gets one ordered chat. In a live session either of
-- the pair asks Ember; each question is an attributed message and a queued
-- turn, answered one at a time in order. The conversation's viewers read
-- the chat (the recap) and post comments; Ember doesn't answer a comment
-- unless one of the pair passes it on, and the answer is then attributed
-- to both.
--
-- Who reads what: everyone who can read the chat -- the pair and its
-- viewers -- is the audience, so Ember may only use evidence (knowledge
-- sources and wiki articles) that every one of them can open. That is
-- checked with the real access rules, not a copy of them:
-- collaboration_common_evidence evaluates the ordinary row-level security
-- of knowledge_sources and wiki_articles as each reader in turn. A reply
-- records the evidence it was built from; a reply is readable only by a
-- reader who can still open all of it (a row-level-security policy on
-- collaboration_messages), so someone who loses access to a source stops
-- seeing answers that drew on it, and a newly added viewer never sees
-- answers built from sources they can't open.
--
-- Turns run in the app server (a Route Handler with the service role):
-- claiming, completing and failing a turn are callable by the service role
-- only, so no browser can write an Ember reply. A claimed turn holds a
-- lease; a run that stops is retried once, then marked failed. A question
-- carries a request id, so a retried send never posts twice, and a
-- completed turn never gets a second reply.
--
-- Nothing here deletes a row: turns end as done, failed or cancelled.
-- No existing table is altered. Safe to re-run. Requires 20261023100001
-- and 20261024100001.

create table if not exists collaboration_messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references collaboration_conversations(id) on delete cascade,
  -- Server order within the conversation.
  seq bigint not null,
  -- message: one of the pair asking Ember; comment: a viewer's comment;
  -- reply: Ember's answer.
  kind text not null check (kind in ('message', 'comment', 'reply')),
  author_id uuid references profiles(id) on delete set null,
  session_id uuid references collaboration_sessions(id) on delete set null,
  content text not null check (char_length(content) between 1 and 20000),
  -- The knowledge sources and wiki articles a reply was built from:
  -- [{"type": "knowledge_source" | "wiki_article", "id": ..., "title": ...}].
  evidence jsonb not null default '[]' check (jsonb_typeof(evidence) = 'array'),
  turn_id uuid,
  request_id uuid unique,
  provider text,
  model text,
  created_at timestamptz not null default now(),
  unique (conversation_id, seq),
  check (kind <> 'reply' or turn_id is not null)
);

create table if not exists collaboration_turns (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references collaboration_conversations(id) on delete cascade,
  session_id uuid not null references collaboration_sessions(id) on delete cascade,
  -- The question or passed-on comment being answered: one turn each.
  prompt_id uuid not null unique references collaboration_messages(id) on delete cascade,
  requested_by uuid not null references profiles(id) on delete cascade,
  status text not null default 'queued' check (status in ('queued', 'running', 'done', 'failed', 'cancelled')),
  lease_id uuid,
  lease_expires_at timestamptz,
  attempts integer not null default 0,
  claimed_by uuid references profiles(id) on delete set null,
  reply_id uuid references collaboration_messages(id) on delete set null,
  error text,
  created_at timestamptz not null default now(),
  started_at timestamptz,
  finished_at timestamptz,
  updated_at timestamptz not null default now()
);

create index if not exists collaboration_turns_open_idx on collaboration_turns(conversation_id, status, created_at);

alter table collaboration_messages enable row level security;
alter table collaboration_turns enable row level security;
revoke all on collaboration_messages, collaboration_turns from anon, authenticated;
-- Messages are read through their row-level-security policy (below), so
-- that the evidence check runs as the reader. Writes go through functions.
grant select on collaboration_messages to authenticated;

-- Limits ----------------------------------------------------------------------------

create or replace function collaboration_chat_max_chars() returns integer
language sql immutable as $$ select 4000 $$;
-- Questions waiting or being answered, per conversation.
create or replace function collaboration_chat_queue_limit() returns integer
language sql immutable as $$ select 3 $$;
create or replace function collaboration_comments_per_hour() returns integer
language sql immutable as $$ select 30 $$;
-- How long a claimed turn may run before another run may take it over.
create or replace function collaboration_turn_lease() returns interval
language sql immutable as $$ select interval '150 seconds' $$;

-- Reading -----------------------------------------------------------------------------

-- The caller may read this conversation (one of the pair, or a viewer,
-- with access).
create or replace function collaboration_is_reader(p_conversation uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select collaboration_conversation_role(c, auth.uid()) is not null
    from collaboration_conversations c where c.id = p_conversation), false);
$$;

-- Whether the current user can open every item of p_evidence, by the
-- ordinary row-level security of the two tables (security invoker: it
-- runs as whoever is asking).
create or replace function collaboration_evidence_visible(p_evidence jsonb)
returns boolean
language sql stable security invoker set search_path = public as $$
  select not exists (
    select 1 from jsonb_array_elements(coalesce(p_evidence, '[]'::jsonb)) e
    where not case e->>'type'
      when 'knowledge_source' then case when (e->>'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then exists (select 1 from knowledge_sources k where k.id = (e->>'id')::uuid) else false end
      when 'wiki_article' then exists (select 1 from wiki_articles w where w.slug = e->>'id')
      else false
    end
  );
$$;

create or replace function collaboration_message_readable(p_conversation uuid, p_evidence jsonb)
returns boolean
language sql stable security invoker set search_path = public as $$
  select collaboration_is_reader(p_conversation) and collaboration_evidence_visible(p_evidence);
$$;

drop policy if exists collaboration_messages_select_readers on collaboration_messages;
create policy collaboration_messages_select_readers on collaboration_messages
  for select to authenticated
  using (collaboration_message_readable(conversation_id, evidence));

-- Everyone who reads the conversation: the pair and its viewers with
-- access. Only one of the pair may ask.
create or replace function collaboration_reader_ids(p_conversation uuid)
returns uuid[]
language plpgsql stable security definer set search_path = public as $$
declare
  c collaboration_conversations;
begin
  select * into c from collaboration_conversations where id = p_conversation;
  if not found or collaboration_conversation_role(c, auth.uid()) is distinct from 'participant' then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  return array[c.user_a, c.user_b] || coalesce((
    select array_agg(v.user_id order by v.user_id) from collaboration_viewers v
    where v.conversation_id = c.id and v.status = 'active' and collaboration_has_access(c.project_id, v.user_id)
  ), '{}');
end;
$$;

-- The items of p_evidence that every reader of the conversation can open.
-- Evaluates the real access rules as each reader: the request's identity
-- (the claims auth.uid() reads) is switched to each reader in turn, for
-- this transaction only, and put back before returning. Called by the app
-- server with the signed-in caller's own credentials, before evidence
-- reaches Ember; the caller must be one of the pair.
create or replace function collaboration_common_evidence(p_conversation uuid, p_evidence jsonb)
returns jsonb
language plpgsql volatile security invoker set search_path = public as $$
declare
  v_readers uuid[];
  v_claims text := current_setting('request.jwt.claims', true);
  v_sub text := current_setting('request.jwt.claim.sub', true);
  v_items jsonb;
  v_reader uuid;
begin
  if (auth.jwt() ->> 'client_id') is not null then
    raise exception 'An external client cannot use shared chat' using errcode = '42501';
  end if;
  v_readers := collaboration_reader_ids(p_conversation);
  if jsonb_typeof(p_evidence) is distinct from 'array' or jsonb_array_length(p_evidence) > 200 then
    raise exception 'Evidence must be a list of at most 200 items' using errcode = 'EC001';
  end if;
  -- Well-formed items, once each.
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_items from (
    select distinct on (e->>'type', e->>'id') e as x from jsonb_array_elements(p_evidence) e
    where e->>'type' in ('knowledge_source', 'wiki_article') and coalesce(e->>'id', '') <> ''
  ) d;
  foreach v_reader in array v_readers loop
    exit when jsonb_array_length(v_items) = 0;
    perform set_config('request.jwt.claims', jsonb_build_object('sub', v_reader, 'role', 'authenticated')::text, true);
    perform set_config('request.jwt.claim.sub', v_reader::text, true);
    select coalesce(jsonb_agg(e), '[]'::jsonb) into v_items
      from jsonb_array_elements(v_items) e where collaboration_evidence_visible(jsonb_build_array(e));
  end loop;
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_sub, ''), true);
  return v_items;
end;
$$;

-- A session in which Ember may answer: live, both of the pair still in it
-- and with access.
create or replace function collaboration_session_live(s collaboration_sessions)
returns boolean
language sql stable security definer set search_path = public as $$
  select s.status = 'active'
    and (select d.ends_at > now() from collaboration_deadline(s.id) d)
    and collaboration_has_access(s.project_id, s.host_id) and collaboration_has_access(s.project_id, s.guest_id)
    and not exists (select 1 from collaboration_participants p where p.session_id = s.id and p.left_at is not null);
$$;

-- The chat's state for the polled snapshots (no content): the client
-- reloads the chat when the version changes, and a participant's browser
-- starts the turn runner when work is waiting and nobody is running it.
create or replace function collaboration_chat_state_json(p_conversation uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'version', coalesce((select max(seq) from collaboration_messages where conversation_id = p_conversation), 0)::text || ':' ||
      coalesce((select floor(extract(epoch from max(updated_at)) * 1000)::bigint from collaboration_turns where conversation_id = p_conversation), 0)::text,
    'waiting', (select count(*) from collaboration_turns where conversation_id = p_conversation and status = 'queued')::int,
    'answering', exists (select 1 from collaboration_turns where conversation_id = p_conversation and status = 'running' and lease_expires_at > now()),
    'needsRunner', exists (select 1 from collaboration_turns where conversation_id = p_conversation and status = 'running' and lease_expires_at <= now())
      or (exists (select 1 from collaboration_turns where conversation_id = p_conversation and status = 'queued')
          and not exists (select 1 from collaboration_turns where conversation_id = p_conversation and status = 'running'))
  );
$$;

revoke all on function collaboration_chat_max_chars() from public, anon, authenticated;
revoke all on function collaboration_chat_queue_limit() from public, anon, authenticated;
revoke all on function collaboration_comments_per_hour() from public, anon, authenticated;
revoke all on function collaboration_turn_lease() from public, anon, authenticated;
revoke all on function collaboration_session_live(collaboration_sessions) from public, anon, authenticated;
revoke all on function collaboration_chat_state_json(uuid) from public, anon, authenticated;
-- Called from the read policy and the evidence check, so callable by
-- signed-in users; each answers only for the caller.
revoke all on function collaboration_is_reader(uuid) from public, anon;
revoke all on function collaboration_evidence_visible(jsonb) from public, anon;
revoke all on function collaboration_message_readable(uuid, jsonb) from public, anon;
revoke all on function collaboration_reader_ids(uuid) from public, anon;
revoke all on function collaboration_common_evidence(uuid, jsonb) from public, anon;
grant execute on function collaboration_is_reader(uuid) to authenticated;
grant execute on function collaboration_evidence_visible(jsonb) to authenticated;
grant execute on function collaboration_message_readable(uuid, jsonb) to authenticated;
grant execute on function collaboration_reader_ids(uuid) to authenticated;
grant execute on function collaboration_common_evidence(uuid, jsonb) to authenticated;

-- The chat without its text: order, kinds, authors, turn states. Every
-- reader gets the whole outline; text comes from collaboration_chat.
create or replace function collaboration_chat_outline(p_conversation uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_actor();
  c collaboration_conversations;
  v_role text;
begin
  select * into c from collaboration_conversations where id = p_conversation;
  v_role := case when found then collaboration_conversation_role(c, v_actor) end;
  if v_role is null then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'conversationId', c.id,
    'projectId', c.project_id,
    'myRole', v_role,
    'liveSessionId', (select s.id from collaboration_sessions s where s.conversation_id = c.id and s.status = 'active'
      order by s.started_at desc limit 1),
    'state', collaboration_chat_state_json(c.id),
    'messages', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', m.id, 'seq', m.seq, 'kind', m.kind, 'authorId', m.author_id,
        'authorName', case when m.author_id is not null then collaboration_display_name(m.author_id) end,
        'createdAt', m.created_at,
        -- A reply: the question it answers.
        'promptId', (select t.prompt_id from collaboration_turns t where t.id = m.turn_id),
        -- A question or comment: its turn, if it has one.
        'turn', (select jsonb_build_object('id', t.id,
            'status', case when t.status = 'queued' and not collaboration_session_live(s) then 'cancelled' else t.status end,
            'requestedById', t.requested_by, 'requestedByName', collaboration_display_name(t.requested_by),
            'replyId', t.reply_id, 'error', t.error)
          from collaboration_turns t join collaboration_sessions s on s.id = t.session_id where t.prompt_id = m.id)
      ) order by m.seq)
      from (select * from collaboration_messages where conversation_id = c.id order by seq desc limit 300) m
    ), '[]'::jsonb)
  );
end;
$$;

-- The chat for the caller: the outline, with each message's text where
-- the caller may read it (the read policy decides, as the caller), and
-- "hidden" where they may not.
create or replace function collaboration_chat(p_conversation uuid)
returns jsonb
language plpgsql stable security invoker set search_path = public as $$
declare
  o jsonb := collaboration_chat_outline(p_conversation);
begin
  return o || jsonb_build_object('messages', coalesce((
    select jsonb_agg(case when x.id is null then m || jsonb_build_object('hidden', true)
                          else m || jsonb_build_object('content', x.content, 'evidence', x.evidence) end
                     order by (m->>'seq')::bigint)
    from jsonb_array_elements(o->'messages') m
    left join collaboration_messages x on x.id = (m->>'id')::uuid
  ), '[]'::jsonb));
end;
$$;

revoke all on function collaboration_chat_outline(uuid) from public, anon;
revoke all on function collaboration_chat(uuid) from public, anon;
grant execute on function collaboration_chat_outline(uuid) to authenticated;
grant execute on function collaboration_chat(uuid) to authenticated;

-- Snapshots, extended with the chat's state (otherwise as in 20261024100001) ----------

create or replace function collaboration_snapshot(p_session uuid, p_actor uuid, p_connection uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s collaboration_sessions;
  h collaboration_participants;
  g collaboration_participants;
  me collaboration_participants;
  ctl collaboration_participants;
  v_workstream_name text;
  d record;
begin
  select * into s from collaboration_sessions where id = p_session;
  select * into h from collaboration_participants where session_id = s.id and user_id = s.host_id;
  select * into g from collaboration_participants where session_id = s.id and user_id = s.guest_id;
  me := case when p_actor = s.host_id then h else g end;
  ctl := case when s.controller_id = s.host_id then h else g end;
  select * into d from collaboration_deadline(s.id);
  if s.location_workstream_id is not null then
    select name into v_workstream_name from project_workstreams where id = s.location_workstream_id;
  end if;
  return jsonb_build_object(
    'id', s.id,
    'conversationId', s.conversation_id,
    'projectId', s.project_id,
    'projectName', (select name from projects where id = s.project_id),
    'status', s.status,
    'endReason', s.end_reason,
    'myRole', case when p_actor = s.host_id then 'host' else 'guest' end,
    'host', jsonb_build_object('id', s.host_id, 'name', collaboration_display_name(s.host_id),
      'present', coalesce(collaboration_is_present(h), false), 'left', h.left_at is not null,
      'away', collaboration_is_away(h, s.started_at),
      'inactiveSeconds', floor(extract(epoch from now() - collaboration_last_active(h, s.started_at)))::int),
    'guest', jsonb_build_object('id', s.guest_id, 'name', collaboration_display_name(s.guest_id),
      'present', coalesce(collaboration_is_present(g), false), 'left', g.left_at is not null,
      'away', collaboration_is_away(g, s.started_at),
      'inactiveSeconds', floor(extract(epoch from now() - collaboration_last_active(g, s.started_at)))::int),
    'controllerId', s.controller_id,
    'controlGeneration', s.control_generation,
    'stateRevision', s.state_revision,
    'controlRequestedBy', s.control_requested_by,
    'location', jsonb_build_object('workstreamId', s.location_workstream_id, 'workstreamName', v_workstream_name),
    -- This tab is the caller's current tab (and still present).
    'thisTabJoined', coalesce(p_connection is not null and me.connection_id = p_connection and collaboration_is_present(me), false),
    -- The caller is present from some other tab.
    'otherTabActive', me.connection_id is distinct from p_connection and coalesce(collaboration_is_present(me), false),
    'iLeft', me.left_at is not null,
    'viewers', collaboration_viewers_json(s.conversation_id),
    'watching', collaboration_watching_json(s.id),
    -- Phase 2: the shared fields where the session is, and every unsaved
    -- draft in the session (for the bar and the end/leave warnings).
    'fields', collaboration_fields_json(s.id, p_actor),
    'openDrafts', collaboration_open_drafts_json(s.id),
    -- Phase 3: the shared chat's state (no content).
    'chat', collaboration_chat_state_json(s.conversation_id),
    -- Seconds until the session ends on its own, and which rule ends it.
    'endsInSeconds', case when s.status = 'active' then greatest(0, floor(extract(epoch from d.ends_at - now())))::int end,
    'endingReason', case when s.status = 'active' then d.reason end,
    -- Someone not in control may take it while the controller is away or
    -- not connected (the host can always take it back).
    'canTakeControl', s.status = 'active' and s.controller_id <> p_actor
      and (collaboration_is_away(ctl, s.started_at) or not coalesce(collaboration_is_present(ctl), false))
  );
end;
$$;

create or replace function collaboration_watch_snapshot(p_session uuid, p_actor uuid, p_connection uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s collaboration_sessions;
  h collaboration_participants;
  g collaboration_participants;
  w collaboration_watchers;
  d record;
  v_workstream_name text;
begin
  select * into s from collaboration_sessions where id = p_session;
  select * into h from collaboration_participants where session_id = s.id and user_id = s.host_id;
  select * into g from collaboration_participants where session_id = s.id and user_id = s.guest_id;
  select * into w from collaboration_watchers where session_id = s.id and user_id = p_actor;
  select * into d from collaboration_deadline(s.id);
  if s.location_workstream_id is not null then
    select name into v_workstream_name from project_workstreams where id = s.location_workstream_id;
  end if;
  return jsonb_build_object(
    'id', s.id,
    'conversationId', s.conversation_id,
    'projectId', s.project_id,
    'projectName', (select name from projects where id = s.project_id),
    'status', case when s.status = 'active' and d.ends_at <= now() then 'ended' else s.status end,
    'endReason', case when s.status = 'active' and d.ends_at <= now() then d.reason else s.end_reason end,
    'host', jsonb_build_object('id', s.host_id, 'name', collaboration_display_name(s.host_id),
      'present', coalesce(collaboration_is_present(h), false), 'away', collaboration_is_away(h, s.started_at), 'left', h.left_at is not null),
    'guest', jsonb_build_object('id', s.guest_id, 'name', collaboration_display_name(s.guest_id),
      'present', coalesce(collaboration_is_present(g), false), 'away', collaboration_is_away(g, s.started_at), 'left', g.left_at is not null),
    'controllerId', s.controller_id,
    'stateRevision', s.state_revision,
    'location', jsonb_build_object('workstreamId', s.location_workstream_id, 'workstreamName', v_workstream_name),
    -- Watchers see the shared fields and drafts too, with no edit rights.
    'fields', collaboration_fields_json(s.id, null),
    -- Phase 3: the shared chat's state (no content).
    'chat', collaboration_chat_state_json(s.conversation_id),
    -- This tab is the caller's watching tab.
    'thisTabWatching', coalesce(p_connection is not null and w.connection_id = p_connection and w.stopped_at is null, false)
  );
end;
$$;

-- Writing -----------------------------------------------------------------------------

create or replace function collaboration_next_seq(p_conversation uuid)
returns bigint
language sql stable security definer set search_path = public as $$
  select coalesce(max(seq), 0) + 1 from collaboration_messages where conversation_id = p_conversation;
$$;

-- Ember answers in a live session with both of the pair in it.
create or replace function collaboration_lock_for_chat(p_session uuid, p_connection uuid, p_actor uuid)
returns collaboration_sessions
language plpgsql security definer set search_path = public as $$
declare
  s collaboration_sessions;
begin
  s := collaboration_lock(p_session, p_connection, p_actor);
  if not collaboration_session_live(s) then
    raise exception 'Ember answers in the shared chat only while you are both in the live session' using errcode = 'EC001';
  end if;
  perform 1 from collaboration_conversations where id = s.conversation_id for update;
  return s;
end;
$$;

create or replace function collaboration_check_queue(p_conversation uuid)
returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if (select count(*) from collaboration_turns where conversation_id = p_conversation and status in ('queued', 'running'))
     >= collaboration_chat_queue_limit() then
    raise exception 'Ember already has % questions waiting -- wait for an answer first', collaboration_chat_queue_limit() using errcode = 'EC001';
  end if;
end;
$$;

revoke all on function collaboration_next_seq(uuid) from public, anon, authenticated;
revoke all on function collaboration_lock_for_chat(uuid, uuid, uuid) from public, anon, authenticated;
revoke all on function collaboration_check_queue(uuid) from public, anon, authenticated;

-- One of the pair asks Ember, from their session tab. A retry with the
-- same request id returns the first result.
create or replace function collaboration_ask_ember(p_session uuid, p_connection uuid, p_content text, p_request uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  v_content text := btrim(coalesce(p_content, ''));
  s collaboration_sessions;
  m collaboration_messages;
  t collaboration_turns;
begin
  if p_request is null then
    raise exception 'A request id is required' using errcode = 'EC001';
  end if;
  s := collaboration_lock_for_chat(p_session, p_connection, v_actor);
  select * into m from collaboration_messages where request_id = p_request;
  if found then
    if m.author_id is distinct from v_actor or m.conversation_id <> s.conversation_id then
      raise exception 'Collaboration access denied' using errcode = '42501';
    end if;
    select * into t from collaboration_turns where prompt_id = m.id;
    return jsonb_build_object('messageId', m.id, 'turnId', t.id);
  end if;
  if v_content = '' or char_length(v_content) > collaboration_chat_max_chars() then
    raise exception 'A message must be 1 to % characters', collaboration_chat_max_chars() using errcode = 'EC001';
  end if;
  perform collaboration_check_queue(s.conversation_id);
  insert into collaboration_messages(conversation_id, seq, kind, author_id, session_id, content, request_id)
    values (s.conversation_id, collaboration_next_seq(s.conversation_id), 'message', v_actor, s.id, v_content, p_request)
    returning * into m;
  insert into collaboration_turns(conversation_id, session_id, prompt_id, requested_by)
    values (s.conversation_id, s.id, m.id, v_actor) returning * into t;
  update collaboration_conversations set last_activity_at = now() where id = s.conversation_id;
  return jsonb_build_object('messageId', m.id, 'turnId', t.id);
end;
$$;

-- A viewer comments. Ember doesn't answer it unless one of the pair
-- passes it on (collaboration_queue_turn). No live session needed.
create or replace function collaboration_post_comment(p_conversation uuid, p_content text, p_request uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  v_content text := btrim(coalesce(p_content, ''));
  c collaboration_conversations;
  m collaboration_messages;
begin
  if p_request is null then
    raise exception 'A request id is required' using errcode = 'EC001';
  end if;
  select * into c from collaboration_conversations where id = p_conversation for update;
  if not found or collaboration_conversation_role(c, v_actor) is distinct from 'viewer' then
    raise exception 'Only the conversation''s viewers post comments' using errcode = '42501';
  end if;
  select * into m from collaboration_messages where request_id = p_request;
  if found then
    if m.author_id is distinct from v_actor or m.conversation_id <> c.id then
      raise exception 'Collaboration access denied' using errcode = '42501';
    end if;
    return jsonb_build_object('messageId', m.id);
  end if;
  if v_content = '' or char_length(v_content) > collaboration_chat_max_chars() then
    raise exception 'A comment must be 1 to % characters', collaboration_chat_max_chars() using errcode = 'EC001';
  end if;
  if (select count(*) from collaboration_messages where author_id = v_actor and kind = 'comment' and created_at > now() - interval '1 hour')
     >= collaboration_comments_per_hour() then
    raise exception 'That''s % comments in the last hour -- try again later', collaboration_comments_per_hour() using errcode = 'EC001';
  end if;
  insert into collaboration_messages(conversation_id, seq, kind, author_id, session_id, content, request_id)
    values (c.id, collaboration_next_seq(c.id), 'comment', v_actor,
      (select s.id from collaboration_sessions s where s.conversation_id = c.id and s.status = 'active' order by s.started_at desc limit 1),
      v_content, p_request)
    returning * into m;
  update collaboration_conversations set last_activity_at = now() where id = c.id;
  return jsonb_build_object('messageId', m.id);
end;
$$;

-- One of the pair passes a comment on to Ember, or asks again after a
-- failed or cancelled answer. Already waiting, answering or answered:
-- returned as it is.
create or replace function collaboration_queue_turn(p_session uuid, p_connection uuid, p_message uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_sessions;
  m collaboration_messages;
  t collaboration_turns;
begin
  s := collaboration_lock_for_chat(p_session, p_connection, v_actor);
  select * into m from collaboration_messages where id = p_message and conversation_id = s.conversation_id;
  if not found or m.kind = 'reply' then
    raise exception 'That isn''t a question or comment in this conversation' using errcode = 'EC001';
  end if;
  select * into t from collaboration_turns where prompt_id = m.id for update;
  if t.id is not null and t.status in ('queued', 'running', 'done') then
    return jsonb_build_object('messageId', m.id, 'turnId', t.id, 'status', t.status);
  end if;
  perform collaboration_check_queue(s.conversation_id);
  if t.id is not null then
    update collaboration_turns
      set status = 'queued', session_id = s.id, requested_by = v_actor, error = null, attempts = 0,
          lease_id = null, lease_expires_at = null, finished_at = null, updated_at = now()
      where id = t.id returning * into t;
  else
    insert into collaboration_turns(conversation_id, session_id, prompt_id, requested_by)
      values (s.conversation_id, s.id, m.id, v_actor) returning * into t;
  end if;
  update collaboration_conversations set last_activity_at = now() where id = s.conversation_id;
  return jsonb_build_object('messageId', m.id, 'turnId', t.id, 'status', t.status);
end;
$$;

revoke all on function collaboration_ask_ember(uuid, uuid, text, uuid) from public, anon;
revoke all on function collaboration_post_comment(uuid, text, uuid) from public, anon;
revoke all on function collaboration_queue_turn(uuid, uuid, uuid) from public, anon;
grant execute on function collaboration_ask_ember(uuid, uuid, text, uuid) to authenticated;
grant execute on function collaboration_post_comment(uuid, text, uuid) to authenticated;
grant execute on function collaboration_queue_turn(uuid, uuid, uuid) to authenticated;

-- Running turns (the app server, service role only) -------------------------------------

-- Takes the next waiting turn for p_actor (one of the pair, checked by the
-- app server's own signed-in call first and again here). One turn runs at
-- a time per conversation. Returns the question and the conversation so
-- far, unfiltered: the app server filters it to common evidence (with
-- collaboration_common_evidence, as the caller) before Ember sees it.
create or replace function collaboration_claim_turn(p_conversation uuid, p_actor uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  c collaboration_conversations;
  t collaboration_turns;
  p collaboration_messages;
  v_lease uuid := gen_random_uuid();
begin
  select * into c from collaboration_conversations where id = p_conversation for update;
  if not found or collaboration_conversation_role(c, p_actor) is distinct from 'participant' then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  -- A run that stopped without finishing: run again once, then failed.
  update collaboration_turns
    set status = case when attempts < 2 then 'queued' else 'failed' end,
        error = case when attempts < 2 then null else 'Ember didn''t finish answering. Ask again.' end,
        finished_at = case when attempts < 2 then null else now() end,
        lease_expires_at = null, updated_at = now()
    where conversation_id = c.id and status = 'running' and lease_expires_at <= now();
  if exists (select 1 from collaboration_turns where conversation_id = c.id and status = 'running') then
    return jsonb_build_object('state', 'busy');
  end if;
  -- Waiting questions from a session that is no longer live aren't answered.
  update collaboration_turns q
    set status = 'cancelled', error = 'The live session ended before Ember answered.', finished_at = now(), updated_at = now()
    from collaboration_sessions s
    where s.id = q.session_id and q.conversation_id = c.id and q.status = 'queued' and not collaboration_session_live(s);
  select * into t from collaboration_turns where conversation_id = c.id and status = 'queued' order by created_at, id limit 1;
  if not found then
    return jsonb_build_object('state', 'idle');
  end if;
  update collaboration_turns
    set status = 'running', lease_id = v_lease, lease_expires_at = now() + collaboration_turn_lease(),
        attempts = attempts + 1, claimed_by = p_actor, started_at = coalesce(started_at, now()), updated_at = now()
    where id = t.id returning * into t;
  select * into p from collaboration_messages where id = t.prompt_id;
  return jsonb_build_object(
    'state', 'claimed',
    'turnId', t.id,
    'leaseId', v_lease,
    'conversationId', c.id,
    'projectId', c.project_id,
    'sessionId', t.session_id,
    'requestedByName', collaboration_display_name(t.requested_by),
    'prompt', jsonb_build_object('id', p.id, 'kind', p.kind, 'content', p.content, 'authorName', collaboration_display_name(p.author_id)),
    -- Earlier questions and passed-on comments, each followed by its reply
    -- (a reply can be posted after later questions were asked); the latest 30.
    'history', coalesce((
      select jsonb_agg(jsonb_build_object('kind', h.kind,
        'authorName', case when h.author_id is not null then collaboration_display_name(h.author_id) end,
        'content', h.content, 'evidence', h.evidence) order by h.ord, h.seq)
      from (
        select m.*, coalesce(pm.seq, m.seq) as ord from collaboration_messages m
        left join collaboration_turns rt on rt.id = m.turn_id
        left join collaboration_messages pm on pm.id = rt.prompt_id
        where m.conversation_id = c.id and coalesce(pm.seq, m.seq) < p.seq
          and (m.kind <> 'comment' or exists (select 1 from collaboration_turns x where x.prompt_id = m.id))
        order by coalesce(pm.seq, m.seq) desc, m.seq desc limit 30
      ) h
    ), '[]'::jsonb)
  );
end;
$$;

-- Records Ember's answer for a claimed turn, once. A repeat with the same
-- lease returns the first result; a turn no longer held by this lease is
-- refused (EC003). p_evidence: everything the answer was built from.
create or replace function collaboration_complete_turn(p_turn uuid, p_lease uuid, p_content text, p_evidence jsonb, p_provider text, p_model text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_conversation uuid;
  t collaboration_turns;
  r collaboration_messages;
begin
  select conversation_id into v_conversation from collaboration_turns where id = p_turn;
  if not found then
    raise exception 'Unknown turn' using errcode = 'EC001';
  end if;
  perform 1 from collaboration_conversations where id = v_conversation for update;
  select * into t from collaboration_turns where id = p_turn for update;
  if t.status = 'done' and t.lease_id = p_lease then
    return jsonb_build_object('status', 'done', 'replyId', t.reply_id);
  end if;
  if t.status <> 'running' or t.lease_id is distinct from p_lease then
    raise exception 'This answer is no longer wanted' using errcode = 'EC003';
  end if;
  if jsonb_typeof(p_evidence) is distinct from 'array' or exists (
    select 1 from jsonb_array_elements(p_evidence) e
    where e->>'type' not in ('knowledge_source', 'wiki_article') or coalesce(e->>'id', '') = ''
  ) then
    raise exception 'Malformed evidence' using errcode = 'EC001';
  end if;
  insert into collaboration_messages(conversation_id, seq, kind, session_id, content, evidence, turn_id, provider, model)
    values (t.conversation_id, collaboration_next_seq(t.conversation_id), 'reply', t.session_id,
      coalesce(nullif(left(btrim(coalesce(p_content, '')), 20000), ''), '(no answer)'), p_evidence, t.id, p_provider, p_model)
    returning * into r;
  update collaboration_turns
    set status = 'done', reply_id = r.id, error = null, lease_expires_at = null, finished_at = now(), updated_at = now()
    where id = t.id;
  update collaboration_conversations set last_activity_at = now() where id = t.conversation_id;
  return jsonb_build_object('status', 'done', 'replyId', r.id);
end;
$$;

-- Records that a claimed turn couldn't be answered (shown to everyone;
-- either of the pair can ask again).
create or replace function collaboration_fail_turn(p_turn uuid, p_lease uuid, p_error text)
returns void
language sql security definer set search_path = public as $$
  update collaboration_turns
    set status = 'failed', error = left(coalesce(nullif(btrim(p_error), ''), 'Ember couldn''t answer.'), 300),
        lease_expires_at = null, finished_at = now(), updated_at = now()
    where id = p_turn and status = 'running' and lease_id = p_lease;
$$;

revoke all on function collaboration_claim_turn(uuid, uuid) from public, anon, authenticated;
revoke all on function collaboration_complete_turn(uuid, uuid, text, jsonb, text, text) from public, anon, authenticated;
revoke all on function collaboration_fail_turn(uuid, uuid, text) from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function collaboration_claim_turn(uuid, uuid) to service_role;
    grant execute on function collaboration_complete_turn(uuid, uuid, text, jsonb, text, text) to service_role;
    grant execute on function collaboration_fail_turn(uuid, uuid, text) to service_role;
  end if;
end;
$$;

-- External MCP read-only guarantee (20261005100001_external_mcp_access.sql),
-- guarded so this migration also applies before that one has run.
do $$
begin
  if to_regprocedure('public.apply_oauth_read_only_policies()') is not null then
    perform apply_oauth_read_only_policies();
  end if;
end;
$$;


-- ==== supabase/migrations/20261026100001_verification_criteria_checks.sql ====
-- Pass criteria as a checklist. A verification method's pass criteria often
-- holds several acceptance criteria (AC1, AC2, ...); the record form lists
-- them and the recorder ticks each one met or not. The ticks are saved with
-- the record, each with the criterion text it was judged against, so the
-- history shows which criteria a result covered. A pass needs every listed
-- criterion met; a fail or conditional pass may leave some unmet. The app
-- splits the criteria from the text (src/lib/projects/criteria.ts); a record
-- without ticks (older records, or a method with one criterion) keeps
-- criteria_checks null.
--
-- Safe to re-run.

alter table solution_verification_records add column if not exists criteria_checks jsonb
  check (criteria_checks is null or jsonb_typeof(criteria_checks) = 'array');

-- The recording function gains p_criteria_checks: drop the old signature so
-- the two don't overload each other.
drop function if exists record_solution_verification(uuid, uuid, text, text, text, date, uuid[], text, text, text, text, text, text, uuid);

create or replace function record_solution_verification(
  p_requirement_id uuid,
  p_method_id uuid,
  p_result text,
  p_environment text,
  p_solution_reference text,
  p_performed_on date,
  p_artifact_ids uuid[],
  p_configuration_reference text default null,
  p_conditions text default null,
  p_rationale text default null,
  p_measured_value text default null,
  p_observations text default null,
  p_defect_reference text default null,
  p_supersedes_id uuid default null,
  p_criteria_checks jsonb default null
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_requirement solution_requirements%rowtype;
  v_method solution_verification_methods%rowtype;
  v_superseded solution_verification_records%rowtype;
  v_artifact_ids uuid[] := array(select distinct a from unnest(coalesce(p_artifact_ids, '{}'::uuid[])) a where a is not null);
  v_artifact_id uuid;
  v_record_id uuid;
  v_check jsonb;
begin
  if v_uid is null then
    raise exception 'record_solution_verification: not signed in';
  end if;

  select * into v_requirement from solution_requirements where id = p_requirement_id;
  if not found or not can_run_project_evals(v_requirement.project_id, v_uid) then
    raise exception 'record_solution_verification: only this Project''s owner, curators and consultants can record verification results';
  end if;
  if v_requirement.status not in ('draft', 'baselined') then
    raise exception 'record_solution_verification: this requirement is closed -- it no longer takes verification results';
  end if;

  select * into v_method from solution_verification_methods where id = p_method_id and requirement_id = p_requirement_id;
  if not found then
    raise exception 'record_solution_verification: choose one of this requirement''s verification methods';
  end if;

  if p_result is null or p_result not in ('pass', 'fail', 'conditional_pass', 'not_run', 'not_applicable') then
    raise exception 'record_solution_verification: unknown result';
  end if;
  if p_result = 'conditional_pass' and length(trim(coalesce(p_conditions, ''))) = 0 then
    raise exception 'record_solution_verification: a conditional pass needs its conditions';
  end if;
  if p_result = 'not_applicable' and length(trim(coalesce(p_rationale, ''))) = 0 then
    raise exception 'record_solution_verification: not applicable needs a rationale';
  end if;
  if p_environment is null or p_environment not in ('lab', 'factory', 'staging', 'site', 'production', 'vendor', 'other') then
    raise exception 'record_solution_verification: choose the environment it was run in';
  end if;
  if length(trim(coalesce(p_solution_reference, ''))) = 0 then
    raise exception 'record_solution_verification: identify the solution state -- build or component versions';
  end if;
  if p_performed_on is null or p_performed_on > current_date + 1 then
    raise exception 'record_solution_verification: the date it was performed can''t be in the future';
  end if;
  if p_result in ('pass', 'conditional_pass') and cardinality(v_artifact_ids) = 0 then
    raise exception 'record_solution_verification: a pass needs at least one evidence artifact -- a narrative assertion alone is not evidence';
  end if;
  if v_method.method = 'operational_measure' and p_result in ('pass', 'fail', 'conditional_pass')
    and length(trim(coalesce(p_measured_value, ''))) = 0 then
    raise exception 'record_solution_verification: an operational measure needs the measured value';
  end if;

  if p_criteria_checks is not null then
    if jsonb_typeof(p_criteria_checks) <> 'array' then
      raise exception 'record_solution_verification: criteria checks must be a list';
    end if;
    for v_check in select value from jsonb_array_elements(p_criteria_checks) loop
      if jsonb_typeof(v_check) <> 'object'
        or coalesce(jsonb_typeof(v_check -> 'criterion'), '') <> 'string'
        or length(trim(v_check ->> 'criterion')) = 0
        or coalesce(jsonb_typeof(v_check -> 'met'), '') <> 'boolean' then
        raise exception 'record_solution_verification: each criteria check needs the criterion and whether it was met';
      end if;
    end loop;
    if p_result = 'pass' and exists (
      select 1 from jsonb_array_elements(p_criteria_checks) c where not (c ->> 'met')::boolean
    ) then
      raise exception 'record_solution_verification: a pass needs every pass criterion met';
    end if;
  end if;

  if p_supersedes_id is not null then
    select * into v_superseded from solution_verification_records where id = p_supersedes_id;
    if not found or v_superseded.requirement_id <> p_requirement_id then
      raise exception 'record_solution_verification: a correction must supersede a record of the same requirement';
    end if;
    if exists (select 1 from solution_verification_records r where r.supersedes_id = p_supersedes_id) then
      raise exception 'record_solution_verification: that record has already been corrected';
    end if;
  end if;

  foreach v_artifact_id in array v_artifact_ids loop
    if not exists (
      select 1 from workstream_artifacts a
      join project_workstreams w on w.id = a.workstream_id
      where a.id = v_artifact_id
        and w.project_id = v_requirement.project_id
        and has_evidence_access('workstream_artifact', a.id, v_uid)
    ) then
      raise exception 'record_solution_verification: evidence must be an artifact in one of this Project''s workstreams that you can see';
    end if;
  end loop;

  insert into solution_verification_records (
    project_id, requirement_id, method_id, method_kind, pass_criteria, threshold, measure_window,
    result, conditions, rationale, measured_value, environment, solution_reference, configuration_reference,
    performed_on, observations, defect_reference, supersedes_id, recorded_by, criteria_checks
  ) values (
    v_requirement.project_id, p_requirement_id, v_method.id, v_method.method, v_method.pass_criteria, v_method.threshold, v_method.measure_window,
    p_result, nullif(trim(p_conditions), ''), nullif(trim(p_rationale), ''), nullif(trim(p_measured_value), ''),
    p_environment, trim(p_solution_reference), nullif(trim(p_configuration_reference), ''),
    p_performed_on, nullif(trim(p_observations), ''), nullif(trim(p_defect_reference), ''), p_supersedes_id, v_uid,
    case when jsonb_array_length(coalesce(p_criteria_checks, '[]'::jsonb)) > 0 then p_criteria_checks end
  )
  returning id into v_record_id;

  insert into solution_verification_evidence (record_id, project_id, workstream_artifact_id)
  select v_record_id, v_requirement.project_id, a from unnest(v_artifact_ids) a;

  return v_record_id;
end;
$$;

revoke execute on function record_solution_verification(uuid, uuid, text, text, text, date, uuid[], text, text, text, text, text, text, uuid, jsonb) from public, anon;
grant execute on function record_solution_verification(uuid, uuid, text, text, text, date, uuid[], text, text, text, text, text, text, uuid, jsonb) to authenticated;


-- ==== supabase/migrations/20261027100001_collaboration_shared_chat_tools.sql ====
-- Shared workspace sessions, Phase 3 completed: the shared chat's summary,
-- and Ember's proposals (docs/dev-request-shared-workspace-sessions.md).
--
-- Summary. Ember sees the latest 30 messages of a shared chat; what is
-- older is kept as a summary. The app server writes it (service role
-- only) from messages every reader can open, and records the evidence it
-- was built from. Like an answer, a summary is readable only by readers
-- who can still open all of that evidence, and Ember stops using one that
-- isn't fully common any more. Each summary is a new row; older ones are
-- kept. Either of the pair can review a summary and publish it as a
-- Project note (with their own note permissions).
--
-- Proposals. Ember's answer can carry proposals -- a Project note to send,
-- or new text for a Project or Workstream field -- stored on the answer, so
-- they are hidden wherever the answer is. Ember never acts: one of the pair
-- sends a note as themselves, and the person in control puts proposed
-- text into the shared draft, which saves under the Phase 2 rules.
-- collaboration_proposal_uses records what happened to each one.
--
-- Wider audiences. A note, or a Project or Workstream field, is read by more
-- people than the conversation. collaboration_evidence_project_visible
-- says whether every active member of the Project can open some evidence
-- (the real access rules, evaluated as each member); the app sends or
-- applies a proposal, or publishes a summary, only when it can. A Project
-- that isn't private takes field text only if it used no evidence at all.
--
-- Additive: adds a column to collaboration_messages (Phase 3's own table),
-- two tables and functions; changes no other table. Nothing is deleted.
-- Safe to re-run. Requires 20261025100001.

alter table collaboration_messages add column if not exists proposals jsonb not null default '[]';
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'collaboration_messages_proposals_array') then
    alter table collaboration_messages add constraint collaboration_messages_proposals_array
      check (jsonb_typeof(proposals) = 'array' and jsonb_array_length(proposals) <= 3);
  end if;
end;
$$;

create table if not exists collaboration_summaries (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references collaboration_conversations(id) on delete cascade,
  -- Covers every message up to this point in reading order (an answer
  -- counts at its question's place).
  upto_ord bigint not null,
  content text not null check (char_length(content) between 1 and 8000),
  evidence jsonb not null default '[]' check (jsonb_typeof(evidence) = 'array'),
  provider text,
  model text,
  published_note_id uuid,
  published_by uuid references profiles(id) on delete set null,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  unique (conversation_id, upto_ord)
);

create table if not exists collaboration_proposal_uses (
  message_id uuid not null references collaboration_messages(id) on delete cascade,
  idx integer not null check (idx between 0 and 2),
  -- sending -> sent | failed (a note); applied (field text put into the
  -- shared draft); dismissed.
  status text not null check (status in ('sending', 'sent', 'failed', 'applied', 'dismissed')),
  by_user uuid references profiles(id) on delete set null,
  result jsonb not null default '{}',
  updated_at timestamptz not null default now(),
  primary key (message_id, idx)
);

alter table collaboration_summaries enable row level security;
alter table collaboration_proposal_uses enable row level security;
revoke all on collaboration_summaries, collaboration_proposal_uses from anon, authenticated;
grant select on collaboration_summaries to authenticated;

drop policy if exists collaboration_summaries_select_readers on collaboration_summaries;
create policy collaboration_summaries_select_readers on collaboration_summaries
  for select to authenticated
  using (collaboration_message_readable(conversation_id, evidence));

-- Audiences ---------------------------------------------------------------------------

-- The Project's active members (actual membership, active accounts), for
-- one of the conversation's pair.
create or replace function collaboration_project_member_ids(p_conversation uuid)
returns uuid[]
language plpgsql stable security definer set search_path = public as $$
declare
  c collaboration_conversations;
begin
  select * into c from collaboration_conversations where id = p_conversation;
  if not found or collaboration_conversation_role(c, auth.uid()) is distinct from 'participant' then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  return coalesce((
    select array_agg(m.user_id order by m.user_id) from project_members m join profiles p on p.id = m.user_id
    where m.project_id = c.project_id and m.status = 'active' and p.is_active
  ), '{}');
end;
$$;

-- Whether the conversation's Project is private (for its readers).
create or replace function collaboration_project_is_private(p_conversation uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select p.visibility = 'private' from collaboration_conversations c join projects p on p.id = c.project_id
    where c.id = p_conversation and collaboration_is_reader(c.id)), false);
$$;

-- Whether every active member of the conversation's Project can open all
-- of p_evidence, by the real access rules evaluated as each member (as in
-- collaboration_common_evidence). For one of the pair; refuses MCP tokens.
-- No evidence: true. p_require_private: also false when the Project isn't
-- private and there is evidence (text shown outside the membership).
create or replace function collaboration_evidence_project_visible(p_conversation uuid, p_evidence jsonb, p_require_private boolean default false)
returns boolean
language plpgsql volatile security invoker set search_path = public as $$
declare
  v_members uuid[];
  v_claims text := current_setting('request.jwt.claims', true);
  v_sub text := current_setting('request.jwt.claim.sub', true);
  v_member uuid;
  v_ok boolean := true;
begin
  if (auth.jwt() ->> 'client_id') is not null then
    raise exception 'An external client cannot use shared chat' using errcode = '42501';
  end if;
  v_members := collaboration_project_member_ids(p_conversation);
  if jsonb_typeof(p_evidence) is distinct from 'array' then
    raise exception 'Evidence must be a list' using errcode = 'EC001';
  end if;
  if jsonb_array_length(p_evidence) = 0 then
    return true;
  end if;
  if p_require_private and not collaboration_project_is_private(p_conversation) then
    return false;
  end if;
  if coalesce(array_length(v_members, 1), 0) > 500 then
    return false;
  end if;
  foreach v_member in array v_members loop
    perform set_config('request.jwt.claims', jsonb_build_object('sub', v_member, 'role', 'authenticated')::text, true);
    perform set_config('request.jwt.claim.sub', v_member::text, true);
    v_ok := collaboration_evidence_visible(p_evidence);
    exit when not v_ok;
  end loop;
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_sub, ''), true);
  return v_ok;
end;
$$;

revoke all on function collaboration_project_member_ids(uuid) from public, anon;
revoke all on function collaboration_project_is_private(uuid) from public, anon;
grant execute on function collaboration_project_is_private(uuid) to authenticated;
revoke all on function collaboration_evidence_project_visible(uuid, jsonb, boolean) from public, anon;
grant execute on function collaboration_project_member_ids(uuid) to authenticated;
grant execute on function collaboration_evidence_project_visible(uuid, jsonb, boolean) to authenticated;

-- Reading -----------------------------------------------------------------------------

-- What happened to the proposals in the conversation (no proposal text).
create or replace function collaboration_proposal_uses_json(p_conversation uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not collaboration_is_reader(p_conversation) then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('messageId', u.message_id, 'index', u.idx, 'status', u.status,
      'byName', case when u.by_user is not null then collaboration_display_name(u.by_user) end, 'result', u.result))
    from collaboration_proposal_uses u join collaboration_messages m on m.id = u.message_id
    where m.conversation_id = p_conversation
  ), '[]'::jsonb);
end;
$$;

-- How far the latest summary reaches (whether or not the caller may read it).
create or replace function collaboration_latest_summary_ord(p_conversation uuid)
returns bigint
language sql stable security definer set search_path = public as $$
  select max(upto_ord) from collaboration_summaries where conversation_id = p_conversation and collaboration_is_reader(p_conversation);
$$;

revoke all on function collaboration_proposal_uses_json(uuid) from public, anon;
revoke all on function collaboration_latest_summary_ord(uuid) from public, anon;
grant execute on function collaboration_proposal_uses_json(uuid) to authenticated;
grant execute on function collaboration_latest_summary_ord(uuid) to authenticated;

-- The chat for the caller (as in 20261025100001), now with each readable
-- answer's proposals, what became of them, and the latest summary the
-- caller may read (or that one exists that they may not).
create or replace function collaboration_chat(p_conversation uuid)
returns jsonb
language plpgsql stable security invoker set search_path = public as $$
declare
  o jsonb := collaboration_chat_outline(p_conversation);
  v_latest bigint := collaboration_latest_summary_ord(p_conversation);
begin
  return o || jsonb_build_object(
    'messages', coalesce((
      select jsonb_agg(case when x.id is null then m || jsonb_build_object('hidden', true)
                            else m || jsonb_build_object('content', x.content, 'evidence', x.evidence, 'proposals', x.proposals) end
                       order by (m->>'seq')::bigint)
      from jsonb_array_elements(o->'messages') m
      left join collaboration_messages x on x.id = (m->>'id')::uuid
    ), '[]'::jsonb),
    'proposalUses', collaboration_proposal_uses_json(p_conversation),
    -- Read through the summaries' own policy: null if the caller may not
    -- read the latest one.
    'summary', (
      select jsonb_build_object('id', s.id, 'uptoOrd', s.upto_ord, 'content', s.content, 'evidence', s.evidence,
        'createdAt', s.created_at, 'publishedNoteId', s.published_note_id, 'publishedAt', s.published_at)
      from collaboration_summaries s where s.conversation_id = p_conversation and s.upto_ord = v_latest
    ),
    'summaryHidden', v_latest is not null and not exists (
      select 1 from collaboration_summaries s where s.conversation_id = p_conversation and s.upto_ord = v_latest)
  );
end;
$$;

-- The chat's polled state (as in 20261025100001), whose version now also
-- changes when a proposal is used or a summary is written, so the others'
-- chats reload.
create or replace function collaboration_chat_state_json(p_conversation uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'version', coalesce((select max(seq) from collaboration_messages where conversation_id = p_conversation), 0)::text || ':' ||
      coalesce((select floor(extract(epoch from max(updated_at)) * 1000)::bigint from collaboration_turns where conversation_id = p_conversation), 0)::text || ':' ||
      coalesce((select floor(extract(epoch from max(u.updated_at)) * 1000)::bigint from collaboration_proposal_uses u
        join collaboration_messages m on m.id = u.message_id where m.conversation_id = p_conversation), 0)::text || ':' ||
      coalesce((select floor(extract(epoch from max(coalesce(published_at, created_at))) * 1000)::bigint from collaboration_summaries
        where conversation_id = p_conversation), 0)::text,
    'waiting', (select count(*) from collaboration_turns where conversation_id = p_conversation and status = 'queued')::int,
    'answering', exists (select 1 from collaboration_turns where conversation_id = p_conversation and status = 'running' and lease_expires_at > now()),
    'needsRunner', exists (select 1 from collaboration_turns where conversation_id = p_conversation and status = 'running' and lease_expires_at <= now())
      or (exists (select 1 from collaboration_turns where conversation_id = p_conversation and status = 'queued')
          and not exists (select 1 from collaboration_turns where conversation_id = p_conversation and status = 'running'))
  );
$$;

-- Proposals ---------------------------------------------------------------------------

-- One of the pair records what they did with a proposal: sending (a note,
-- before sending it), sent or failed (after), applied (field text put into
-- the shared draft), dismissed. A sent note can't be sent again; a note
-- being sent by someone else can't be taken over.
create or replace function collaboration_update_proposal(p_message uuid, p_index integer, p_status text, p_result jsonb default '{}')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  m collaboration_messages;
  c collaboration_conversations;
  u collaboration_proposal_uses;
  v_kind text;
begin
  select * into m from collaboration_messages where id = p_message;
  if found then
    select * into c from collaboration_conversations where id = m.conversation_id for update;
  end if;
  if not found or collaboration_conversation_role(c, v_actor) is distinct from 'participant' then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  v_kind := m.proposals -> p_index ->> 'kind';
  if m.kind <> 'reply' or v_kind is null then
    raise exception 'That proposal doesn''t exist' using errcode = 'EC001';
  end if;
  if p_status not in ('sending', 'sent', 'failed', 'applied', 'dismissed') then
    raise exception 'Unknown proposal status' using errcode = 'EC001';
  end if;
  if (v_kind = 'note' and p_status not in ('sending', 'sent', 'failed', 'dismissed'))
     or (v_kind = 'field' and p_status not in ('applied', 'dismissed')) then
    raise exception 'That doesn''t apply to this proposal' using errcode = 'EC001';
  end if;
  select * into u from collaboration_proposal_uses where message_id = m.id and idx = p_index for update;
  if u.message_id is not null then
    if u.status = 'sent' then
      raise exception 'That note was already sent' using errcode = 'EC004';
    end if;
    if u.status = 'sending' and (p_status not in ('sent', 'failed') or u.by_user is distinct from v_actor) then
      raise exception 'Someone is sending that note right now' using errcode = 'EC004';
    end if;
  end if;
  if p_status in ('sent', 'failed') and (u.status is distinct from 'sending' or u.by_user is distinct from v_actor) then
    raise exception 'Start sending the note first' using errcode = 'EC001';
  end if;
  insert into collaboration_proposal_uses(message_id, idx, status, by_user, result, updated_at)
    values (m.id, p_index, p_status, v_actor, coalesce(p_result, '{}'), now())
    on conflict (message_id, idx) do update set status = excluded.status, by_user = excluded.by_user, result = excluded.result, updated_at = now();
  return jsonb_build_object('messageId', m.id, 'index', p_index, 'status', p_status);
end;
$$;

-- One of the pair records that they published a summary as a Project note.
create or replace function collaboration_mark_summary_published(p_summary uuid, p_note uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_actor uuid := collaboration_writer();
  s collaboration_summaries;
  c collaboration_conversations;
begin
  select * into s from collaboration_summaries where id = p_summary for update;
  if found then
    select * into c from collaboration_conversations where id = s.conversation_id;
  end if;
  if not found or collaboration_conversation_role(c, v_actor) is distinct from 'participant' then
    raise exception 'Collaboration access denied' using errcode = '42501';
  end if;
  if not exists (select 1 from project_notes where id = p_note and project_id = c.project_id and author_id = v_actor) then
    raise exception 'That note isn''t yours in this Project' using errcode = 'EC001';
  end if;
  update collaboration_summaries set published_note_id = p_note, published_by = v_actor, published_at = now() where id = s.id;
end;
$$;

revoke all on function collaboration_update_proposal(uuid, integer, text, jsonb) from public, anon;
revoke all on function collaboration_mark_summary_published(uuid, uuid) from public, anon;
grant execute on function collaboration_update_proposal(uuid, integer, text, jsonb) to authenticated;
grant execute on function collaboration_mark_summary_published(uuid, uuid) to authenticated;

-- Running turns (the app server, service role only) -------------------------------------

-- For a claimed turn: the latest summary, and the older messages it
-- doesn't cover yet (outside the latest 30 Ember sees; at most 150, oldest
-- first), so the app server can write a new summary.
create or replace function collaboration_turn_context(p_turn uuid, p_lease uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  t collaboration_turns;
  p collaboration_messages;
  s collaboration_summaries;
begin
  select * into t from collaboration_turns where id = p_turn;
  if not found or t.lease_id is distinct from p_lease or t.status not in ('running', 'done') then
    raise exception 'This answer is no longer wanted' using errcode = 'EC003';
  end if;
  select * into p from collaboration_messages where id = t.prompt_id;
  select * into s from collaboration_summaries where conversation_id = t.conversation_id order by upto_ord desc limit 1;
  return jsonb_build_object(
    'summary', case when s.id is not null then jsonb_build_object('id', s.id, 'uptoOrd', s.upto_ord, 'content', s.content, 'evidence', s.evidence) end,
    'unsummarized', coalesce((
      with eligible as (
        -- Earlier messages Ember may see, in reading order (as
        -- collaboration_claim_turn picks them).
        select m.kind, m.author_id, m.content, m.evidence, coalesce(pm.seq, m.seq) as ord, m.seq
        from collaboration_messages m
        left join collaboration_turns rt on rt.id = m.turn_id
        left join collaboration_messages pm on pm.id = rt.prompt_id
        where m.conversation_id = t.conversation_id and coalesce(pm.seq, m.seq) < p.seq
          and (m.kind <> 'comment' or exists (select 1 from collaboration_turns x where x.prompt_id = m.id))
      ), recent as (
        select ord, seq from eligible order by ord desc, seq desc limit 30
      ), older as (
        select e.* from eligible e
        where not exists (select 1 from recent r where r.ord = e.ord and r.seq = e.seq)
          and e.ord > coalesce(s.upto_ord, 0)
        order by e.ord, e.seq limit 150
      )
      select jsonb_agg(jsonb_build_object('kind', o.kind, 'ord', o.ord,
        'authorName', case when o.author_id is not null then collaboration_display_name(o.author_id) end,
        'content', o.content, 'evidence', o.evidence) order by o.ord, o.seq)
      from older o
    ), '[]'::jsonb)
  );
end;
$$;

-- Records a new summary covering everything up to p_upto_ord. Ignored
-- (returns null) if a summary already covers that far.
create or replace function collaboration_record_summary(p_conversation uuid, p_upto_ord bigint, p_content text, p_evidence jsonb, p_provider text, p_model text)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
begin
  perform 1 from collaboration_conversations where id = p_conversation for update;
  if not found then
    raise exception 'Unknown conversation' using errcode = 'EC001';
  end if;
  if jsonb_typeof(p_evidence) is distinct from 'array' or exists (
    select 1 from jsonb_array_elements(p_evidence) e
    where e->>'type' not in ('knowledge_source', 'wiki_article') or coalesce(e->>'id', '') = ''
  ) then
    raise exception 'Malformed evidence' using errcode = 'EC001';
  end if;
  if exists (select 1 from collaboration_summaries where conversation_id = p_conversation and upto_ord >= p_upto_ord) then
    return null;
  end if;
  insert into collaboration_summaries(conversation_id, upto_ord, content, evidence, provider, model)
    values (p_conversation, p_upto_ord, left(btrim(p_content), 8000), p_evidence, p_provider, p_model)
    returning id into v_id;
  return v_id;
end;
$$;

-- Attaches Ember's proposals to its answer, once, right after the answer
-- is recorded with the same lease. At most 3; each a note or field text.
create or replace function collaboration_set_reply_proposals(p_turn uuid, p_lease uuid, p_proposals jsonb)
returns void
language plpgsql security definer set search_path = public as $$
declare
  t collaboration_turns;
begin
  select * into t from collaboration_turns where id = p_turn for update;
  if not found or t.status <> 'done' or t.lease_id is distinct from p_lease or t.reply_id is null then
    raise exception 'This answer is no longer wanted' using errcode = 'EC003';
  end if;
  if jsonb_typeof(p_proposals) is distinct from 'array' or jsonb_array_length(p_proposals) > 3 or exists (
    select 1 from jsonb_array_elements(p_proposals) e where e->>'kind' not in ('note', 'field')
  ) then
    raise exception 'Malformed proposals' using errcode = 'EC001';
  end if;
  update collaboration_messages set proposals = p_proposals
    where id = t.reply_id and proposals = '[]'::jsonb;
end;
$$;

revoke all on function collaboration_turn_context(uuid, uuid) from public, anon, authenticated;
revoke all on function collaboration_record_summary(uuid, bigint, text, jsonb, text, text) from public, anon, authenticated;
revoke all on function collaboration_set_reply_proposals(uuid, uuid, jsonb) from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function collaboration_turn_context(uuid, uuid) to service_role;
    grant execute on function collaboration_record_summary(uuid, bigint, text, jsonb, text, text) to service_role;
    grant execute on function collaboration_set_reply_proposals(uuid, uuid, jsonb) to service_role;
  end if;
end;
$$;

